-- ════════════════════════════════════════════════════════
-- 269 — Vague 2, lot 8 : sept fiches « graine » et homonymes
--       (Partagás USA, Romeo y Julieta USA, Dannemann, Te Amo, Tabacalera,
--       General Cigar, Villiger)
-- ────────────────────────────────────────────────────────
-- POURQUOI. Ces fiches de mars 2026 portaient une prose romancée, des sources réduites
-- au domaine et, pour trois d'entre elles, un pays de classement qui ne disait pas où le
-- cigare est roulé aujourd'hui. Chacune a été relue le 21 octobre 2026, page par page
-- (pages des maisons, presse du métier datée, Wikipédia, détaillants cités comme tels).
-- Les corrections ne reposent que sur des pages lues, citées dans `source` ; tout ce qui
-- n'a pas de page est retiré, jamais remplacé par une supposition ; les divergences sont
-- écrites, non tranchées. Aucun rang, aucun nom de revue à notes, aucune revendication de
-- « premier » ou de « plus grand », même attribuée. Les lignes dont aucune page ne dit
-- qu'elles sont roulées à la main restent hors gamme.
--
-- ── CLASSEMENT (country_id) ─────────────────────────────────────
-- Partagás USA        : États-Unis → République dominicaine (General Cigar Dominicana,
--                       Santiago de los Caballeros).
-- Romeo y Julieta USA : États-Unis → République dominicaine ; roulage en plusieurs pays
--                       (150th Anniversary en République dominicaine, Reserve au Honduras,
--                       1875 Nicaragua au Nicaragua) : divergence écrite, arbitrage du
--                       21 octobre 2026.
-- General Cigar       : États-Unis → République dominicaine (Macanudo) ; Flathead roulée à
--                       Estelí : aucune page ne donne la répartition, arbitrage du
--                       21 octobre 2026.
-- Dannemann (Brésil), Te Amo (Mexique), Tabacalera (Philippines), Villiger (Nicaragua) :
-- classement inchangé, confirmé par page.
--
-- ── FAUX, RETIRÉ, AJOUTÉ ───────────────────────────────────────
-- PARTAGÁS USA : « marque la plus vendue depuis trois décennies » et « 1845 la plus
-- ambitieuse » retirés ; Serie D USA retirée (aucune page pour la version américaine) ;
-- cape de la 1845 contredite par la presse du métier ; Ramón Cifuentes sans page retiré.
-- ROMEO Y JULIETA USA : 1875 (cape d'Indonésie), Reserve (roulée au Honduras, cape du
-- Nicaragua), 150th Anniversary et 1875 Nicaragua ajoutées ; La Gloria Cubana d'Estelí,
-- 1969 et accords sans page retirés ; 1875 et Reserve Maduro hors gamme (main non établie).
-- DANNEMANN : fondation 1872 (maison) ou 1873 (Wikipédia) en divergence ; statue, esclavage,
-- Sumatra, « quatre générations » et formule sur la machine retirés ; fusion de 1922 et
-- rachat de 1988 ajoutés avec leur page.
-- TE AMO : « à Altadis depuis 2000 » infirmé (Altadis U.S.A. aux États-Unis, les Turrent
-- ailleurs) ; 1966 (Turrent) contre 1963 en divergence ; prix et détails sans page retirés.
-- TABACALERA : récit des manufactures privées faux ; fondation 1881 (11 ou 26 novembre) et
-- monopole (1780 ou 1782) en divergence ; lignes actuelles de la maison (1881, Don Juan
-- Urquijo) ; Tabacalera Premium et récits sans page retirés.
-- GENERAL CIGAR : Tampa et Ybor City sans page retirés ; Philip Morris infirmé (Swedish Match,
-- puis STG depuis 2010) ; Macanudo de 1968-69 ; « assemblage jamaïcain » retiré (Jamaïque
-- fermée en 2000).
-- VILLIGER : histoire refaite sur la page de la maison ; Premium No. 6, Export et cigarillos
-- (machine) hors gamme et leurs accords retirés ; usine d'Estelí ouverte en 2021.
--
-- CE QUI RESTE OUVERT. Aucune page de la maison lue pour General Cigar, Macanudo et
-- Partagás USA (sites illisibles) ; fabrique actuelle de Te Amo (page de 2009 seulement) et
-- de Tabacalera (page de 2011) ; clôture effective de la vente de Tabacalera USA à Gemstone ;
-- nom de la ligne de São Félix pour Dannemann ; année de Havana Club (Villiger). La fiche
-- La Flor de la Isabela, devenue sans objet (marque phare rebaptisée Tabacalera), est traitée
-- à part (migration 270).
--

-- ── Partagás USA ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('La situation de Partagás aux États-Unis illustre le même phénomène juridique que Cohiba USA : l''embargo américain contre Cuba créa un vide de propriété intellectuelle que General Cigar occupa rapidement et légalement.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'La situation de Partagás aux États-Unis illustre le même phénomène juridique que Cohiba USA : l''embargo américain contre Cuba créa un vide de propriété intellectuelle que General Cigar occupa rapidement et légalement.', 'Partagás est un nom porté par deux marques distinctes : le Partagás cubain de Habanos S.A., roulé à La Havane, et le Partagás des États-Unis, sans tabac cubain, que cet atlas classe en République dominicaine, là où il est roulé. Les deux ne partagent que le nom, l''année 1845 de la fondation havanaise et un décor de bague rouge et or.'), `history`),
  `history_en` = IF(LOCATE(CAST('The American Partagás situation illustrates the same legal phenomenon as Cohiba USA: the American embargo against Cuba created an intellectual property vacuum that General Cigar quickly and legally occupied.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The American Partagás situation illustrates the same legal phenomenon as Cohiba USA: the American embargo against Cuba created an intellectual property vacuum that General Cigar quickly and legally occupied.', 'Partagás is a name borne by two distinct brands: the Cuban Partagás of Habanos S.A., rolled in Havana, and the Partagás of the United States, with no Cuban tobacco, which this atlas files under the Dominican Republic, where it is rolled. The two share only the name, the year 1845 of the Havana foundation and a red-and-gold band design.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La situación de Partagás en Estados Unidos ilustra el mismo fenómeno jurídico que Cohiba USA: el embargo estadounidense contra Cuba creó un vacío de propiedad intelectual que General Cigar ocupó con rapidez y legalidad.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La situación de Partagás en Estados Unidos ilustra el mismo fenómeno jurídico que Cohiba USA: el embargo estadounidense contra Cuba creó un vacío de propiedad intelectual que General Cigar ocupó con rapidez y legalidad.', 'Partagás es un nombre que llevan dos marcas distintas: el Partagás cubano de Habanos S.A., torcido en La Habana, y el Partagás de Estados Unidos, sin tabaco cubano, que este atlas clasifica en la República Dominicana, donde se tuerce. Las dos comparten solo el nombre, el año 1845 de la fundación habanera y un diseño de vitola roja y dorada.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die Lage von Partagás in den Vereinigten Staaten veranschaulicht dasselbe rechtliche Phänomen wie Cohiba USA: Das amerikanische Embargo gegen Kuba schuf eine Lücke im geistigen Eigentum, die General Cigar rasch und legal besetzte.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die Lage von Partagás in den Vereinigten Staaten veranschaulicht dasselbe rechtliche Phänomen wie Cohiba USA: Das amerikanische Embargo gegen Kuba schuf eine Lücke im geistigen Eigentum, die General Cigar rasch und legal besetzte.', 'Partagás ist ein Name, den zwei verschiedene Marken tragen: das kubanische Partagás von Habanos S.A., in Havanna gerollt, und das Partagás der Vereinigten Staaten, ohne kubanischen Tabak, das dieser Atlas unter der Dominikanischen Republik einordnet, wo es gerollt wird. Beide teilen nur den Namen, das Jahr 1845 der Havanna-Gründung und ein rot-goldenes Bandmotiv.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('Partagás 在美国的处境，说明的是与 Cohiba USA 相同的法律现象：美国对古巴的禁运造成了知识产权真空，而 General Cigar 迅速且合法地填补了它。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, 'Partagás 在美国的处境，说明的是与 Cohiba USA 相同的法律现象：美国对古巴的禁运造成了知识产权真空，而 General Cigar 迅速且合法地填补了它。', 'Partagás 是两个不同品牌共用的名字：一是 Habanos S.A. 旗下的古巴 Partagás，在哈瓦那手工卷制；二是美国的 Partagás，不含古巴烟叶，本图鉴将其归入多米尼加共和国，因为它在那里卷制。两者只共享名字、哈瓦那创立的 1845年，以及红金相间的烟标设计。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('يوضّح وضع Partagás في الولايات المتحدة الظاهرة القانونية نفسها التي عرفتها Cohiba USA: فالحظر الأمريكي على كوبا خلق فراغاً في الملكية الفكرية شغلته General Cigar سريعاً وبصورة قانونية.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'يوضّح وضع Partagás في الولايات المتحدة الظاهرة القانونية نفسها التي عرفتها Cohiba USA: فالحظر الأمريكي على كوبا خلق فراغاً في الملكية الفكرية شغلته General Cigar سريعاً وبصورة قانونية.', 'Partagás اسم تحمله علامتان مختلفتان: Partagás الكوبية التابعة لـ Habanos S.A. وتُلَفّ في هافانا، وPartagás الخاصة بالولايات المتحدة، بلا تبغ كوبي، وهي التي يصنّفها هذا الأطلس ضمن جمهورية الدومينيكان لأنها تُلَفّ هناك. ولا يجمع بينهما إلا الاسم وسنة 1845 لتأسيس الدار في هافانا وتصميم خاتم أحمر وذهبي.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Partagás USA';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('General Cigar détient les droits sur la marque Partagás aux États-Unis, indépendamment du Partagás cubain de Habanos S.A. La version américaine est fabriquée en République Dominicaine depuis les années 1980, utilisant des tabacs dominicains et mexicains dans un profil intentionnellement évocateur — mais distinct — de l''original havanais.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'General Cigar détient les droits sur la marque Partagás aux États-Unis, indépendamment du Partagás cubain de Habanos S.A. La version américaine est fabriquée en République Dominicaine depuis les années 1980, utilisant des tabacs dominicains et mexicains dans un profil intentionnellement évocateur — mais distinct — de l''original havanais.', 'General Cigar a la marque aux États-Unis depuis 1978 (Wikipédia) ; la production a commencé en Jamaïque, puis a gagné l''usine de Santiago de los Caballeros, en République dominicaine, un an plus tard (Wikipédia ; presse du métier, hiver 1995-1996). En 1995, l''usine de la zone franche comptait environ 600 employés, dont 200 rouleurs. General Cigar appartient à Scandinavian Tobacco Group (STG) ; la bague porte « 1845 » à la place de « Habana ».'), `history`),
  `history_en` = IF(LOCATE(CAST('General Cigar holds the Partagás trademark rights in the United States, independently of the Cuban Partagás owned by Habanos S.A. The American version has been manufactured in the Dominican Republic since the 1980s, using Dominican and Mexican tobaccos in an intentionally evocative — yet distinct — profile from the original Havana house.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'General Cigar holds the Partagás trademark rights in the United States, independently of the Cuban Partagás owned by Habanos S.A. The American version has been manufactured in the Dominican Republic since the 1980s, using Dominican and Mexican tobaccos in an intentionally evocative — yet distinct — profile from the original Havana house.', 'General Cigar has held the brand in the United States since 1978 (Wikipedia); production began in Jamaica, then moved a year later to the factory in Santiago de los Caballeros, in the Dominican Republic (Wikipedia; trade press, winter 1995-1996). In 1995 the free-zone factory had about 600 employees, 200 of them rollers. General Cigar belongs to Scandinavian Tobacco Group (STG); the band reads "1845" in place of "Habana".'), `history_en`),
  `history_es` = IF(LOCATE(CAST('General Cigar posee los derechos de la marca Partagás en Estados Unidos, con independencia del Partagás cubano de Habanos S.A. La versión estadounidense se fabrica en la República Dominicana desde los años ochenta, con tabacos dominicanos y mexicanos en un perfil deliberadamente evocador —pero distinto— del original habanero.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'General Cigar posee los derechos de la marca Partagás en Estados Unidos, con independencia del Partagás cubano de Habanos S.A. La versión estadounidense se fabrica en la República Dominicana desde los años ochenta, con tabacos dominicanos y mexicanos en un perfil deliberadamente evocador —pero distinto— del original habanero.', 'General Cigar posee la marca en Estados Unidos desde 1978 (Wikipedia); la producción empezó en Jamaica y un año después pasó a la fábrica de Santiago de los Caballeros, en la República Dominicana (Wikipedia; prensa del sector, invierno de 1995-1996). En 1995, la fábrica de la zona franca contaba con unos 600 empleados, 200 de ellos torcedores. General Cigar pertenece a Scandinavian Tobacco Group (STG); la vitola lleva «1845» en lugar de «Habana».'), `history_es`),
  `history_de` = IF(LOCATE(CAST('General Cigar hält die Rechte an der Marke Partagás in den Vereinigten Staaten, unabhängig vom kubanischen Partagás der Habanos S.A. Die amerikanische Version wird seit den 1980er Jahren in der Dominikanischen Republik hergestellt, aus dominikanischen und mexikanischen Tabaken, in einem Profil, das das havannesische Original bewusst anklingen lässt — und sich doch davon unterscheidet.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'General Cigar hält die Rechte an der Marke Partagás in den Vereinigten Staaten, unabhängig vom kubanischen Partagás der Habanos S.A. Die amerikanische Version wird seit den 1980er Jahren in der Dominikanischen Republik hergestellt, aus dominikanischen und mexikanischen Tabaken, in einem Profil, das das havannesische Original bewusst anklingen lässt — und sich doch davon unterscheidet.', 'General Cigar hält die Marke in den Vereinigten Staaten seit 1978 (Wikipedia); die Produktion begann in Jamaika und wechselte ein Jahr später in die Fabrik in Santiago de los Caballeros in der Dominikanischen Republik (Wikipedia; Fachpresse, Winter 1995-1996). 1995 zählte die Fabrik in der Freizone etwa 600 Beschäftigte, davon 200 Roller. General Cigar gehört zu Scandinavian Tobacco Group (STG); das Band trägt „1845“ statt „Habana“.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('General Cigar 拥有 Partagás 商标在美国的权利，与 Habanos S.A. 旗下的古巴 Partagás 互不相干。美国版自 1980 年代起在多米尼加共和国生产，采用多米尼加与墨西哥烟叶，风格刻意让人联想到哈瓦那原版，却又与之不同。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, 'General Cigar 拥有 Partagás 商标在美国的权利，与 Habanos S.A. 旗下的古巴 Partagás 互不相干。美国版自 1980 年代起在多米尼加共和国生产，采用多米尼加与墨西哥烟叶，风格刻意让人联想到哈瓦那原版，却又与之不同。', 'General Cigar 自 1978年起在美国持有该品牌（维基百科）；生产最初在牙买加，一年后转到多米尼加共和国圣地亚哥-德洛斯卡瓦列罗斯的工厂（维基百科；行业媒体，1995—1996年冬季）。1995年，自由区的这家工厂约有 600 名员工，其中 200 名是卷烟师。General Cigar 隶属于 Scandinavian Tobacco Group（STG）；烟标上印的是“1845”，而不是“Habana”。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('تملك General Cigar حقوق علامة Partagás في الولايات المتحدة، بمعزل عن Partagás الكوبية التابعة لـ Habanos S.A. وتُصنع النسخة الأمريكية في جمهورية الدومينيكان منذ الثمانينيات، من تبغ دومينيكي ومكسيكي، بطابع يستحضر الأصل الهافاني عن قصد — ويظل مختلفاً عنه.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'تملك General Cigar حقوق علامة Partagás في الولايات المتحدة، بمعزل عن Partagás الكوبية التابعة لـ Habanos S.A. وتُصنع النسخة الأمريكية في جمهورية الدومينيكان منذ الثمانينيات، من تبغ دومينيكي ومكسيكي، بطابع يستحضر الأصل الهافاني عن قصد — ويظل مختلفاً عنه.', 'تملك General Cigar العلامة في الولايات المتحدة منذ 1978 (ويكيبيديا)؛ وبدأ الإنتاج في جامايكا، ثم انتقل بعد عام إلى مصنع سانتياغو دي لوس كاباليروس في جمهورية الدومينيكان (ويكيبيديا؛ صحافة المهنة، شتاء 1995-1996). وفي 1995 كان في مصنع المنطقة الحرة نحو 600 موظف، منهم 200 لفّاف. وتتبع General Cigar مجموعة Scandinavian Tobacco Group (STG)؛ ويحمل الخاتم «1845» بدل «Habana».'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Partagás USA';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('L''impact commercial de cette version américaine est substantiel : Partagás est l''une des marques premium les plus vendues aux États-Unis depuis trois décennies. La fidélité de consommateurs qui ne peuvent accéder au Partagás cubain — et qui ont développé leur palais sur la version dominicaine — crée une base d''acheteurs récurrents solide.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'L''impact commercial de cette version américaine est substantiel : Partagás est l''une des marques premium les plus vendues aux États-Unis depuis trois décennies. La fidélité de consommateurs qui ne peuvent accéder au Partagás cubain — et qui ont développé leur palais sur la version dominicaine — crée une base d''acheteurs récurrents solide.', 'La presse du métier relevait en 1995 environ huit millions de Partagás par an sortis de cet atelier. Ce Partagás s''est installé comme la version que l''amateur américain, privé du cubain par l''embargo, trouve sur son marché.'), `history`),
  `history_en` = IF(LOCATE(CAST('The commercial impact of this American version is substantial: Partagás is one of the best-selling premium brands in the United States over three decades. The loyalty of consumers who cannot access the Cuban Partagás — and who developed their palates on the Dominican version — creates a solid base of recurring buyers.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The commercial impact of this American version is substantial: Partagás is one of the best-selling premium brands in the United States over three decades. The loyalty of consumers who cannot access the Cuban Partagás — and who developed their palates on the Dominican version — creates a solid base of recurring buyers.', 'In 1995 the trade press noted about eight million Partagás a year coming out of this factory. This Partagás has established itself as the version that the American smoker, deprived of the Cuban by the embargo, finds on his market.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('El impacto comercial de esta versión estadounidense es notable: Partagás figura desde hace tres décadas entre las marcas premium más vendidas en Estados Unidos. La fidelidad de unos consumidores que no pueden acceder al Partagás cubano —y que han formado su paladar con la versión dominicana— sostiene una base sólida de compradores recurrentes.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'El impacto comercial de esta versión estadounidense es notable: Partagás figura desde hace tres décadas entre las marcas premium más vendidas en Estados Unidos. La fidelidad de unos consumidores que no pueden acceder al Partagás cubano —y que han formado su paladar con la versión dominicana— sostiene una base sólida de compradores recurrentes.', 'La prensa del sector contabilizaba en 1995 unos ocho millones de Partagás al año salidos de esta fábrica. Este Partagás se ha asentado como la versión que el aficionado estadounidense, privado del cubano por el embargo, encuentra en su mercado.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Der kommerzielle Erfolg dieser amerikanischen Version ist beträchtlich: Partagás gehört seit drei Jahrzehnten zu den meistverkauften Premiummarken der Vereinigten Staaten. Die Treue von Verbrauchern, die keinen Zugang zum kubanischen Partagás haben und ihren Gaumen an der dominikanischen Version geschult haben, trägt einen soliden Stamm an Wiederkäufern.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Der kommerzielle Erfolg dieser amerikanischen Version ist beträchtlich: Partagás gehört seit drei Jahrzehnten zu den meistverkauften Premiummarken der Vereinigten Staaten. Die Treue von Verbrauchern, die keinen Zugang zum kubanischen Partagás haben und ihren Gaumen an der dominikanischen Version geschult haben, trägt einen soliden Stamm an Wiederkäufern.', 'Die Fachpresse verzeichnete 1995 etwa acht Millionen Partagás pro Jahr aus dieser Fabrik. Dieses Partagás hat sich als die Version etabliert, die der amerikanische Liebhaber, dem das Embargo das kubanische vorenthält, auf seinem Markt findet.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('这一美国版的商业影响相当可观：三十年来，Partagás 一直是美国销量最高的高端品牌之一。那些无缘古巴 Partagás、并以多米尼加版养成味觉的消费者，形成了稳固的回头客基础。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '这一美国版的商业影响相当可观：三十年来，Partagás 一直是美国销量最高的高端品牌之一。那些无缘古巴 Partagás、并以多米尼加版养成味觉的消费者，形成了稳固的回头客基础。', '行业媒体在 1995年记录到，这家工厂每年出产约八百万支 Partagás。这款 Partagás 已成为美国爱好者的选择：他们因禁运而买不到古巴版，只能在自己的市场上找到它。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('وأثر هذه النسخة الأمريكية تجارياً كبير: فـ Partagás من أكثر العلامات الفاخرة مبيعاً في الولايات المتحدة منذ ثلاثة عقود. ووفاء مستهلكين لا سبيل لهم إلى Partagás الكوبية، وقد تربّت أذواقهم على النسخة الدومينيكية، يصنع قاعدة متينة من المشترين الدائمين.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'وأثر هذه النسخة الأمريكية تجارياً كبير: فـ Partagás من أكثر العلامات الفاخرة مبيعاً في الولايات المتحدة منذ ثلاثة عقود. ووفاء مستهلكين لا سبيل لهم إلى Partagás الكوبية، وقد تربّت أذواقهم على النسخة الدومينيكية، يصنع قاعدة متينة من المشترين الدائمين.', 'سجّلت صحافة المهنة في 1995 نحو ثمانية ملايين سيجار Partagás في العام يخرج من هذا المصنع. وقد استقرت هذه Partagás بوصفها النسخة التي يجدها الهاوي الأمريكي في سوقه، وقد حرمه الحظر من الكوبية.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Partagás USA';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('La gamme 1845, lancée pour commémorer l''année de fondation de la maison havanaise originale, est la proposition la plus ambitieuse de la version américaine : un assemblage à dominante San Andrés du Mexique qui cherche explicitement à reproduire l''intensité terreuse du Partagás cubain. Certains amateurs américains le préfèrent à l''original pour sa régularité ; d''autres le trouvent trop linéaire. Les deux positions sont défendables et reflètent simplement des préférences différentes de style.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'La gamme 1845, lancée pour commémorer l''année de fondation de la maison havanaise originale, est la proposition la plus ambitieuse de la version américaine : un assemblage à dominante San Andrés du Mexique qui cherche explicitement à reproduire l''intensité terreuse du Partagás cubain. Certains amateurs américains le préfèrent à l''original pour sa régularité ; d''autres le trouvent trop linéaire. Les deux positions sont défendables et reflètent simplement des préférences différentes de style.', 'Parmi les lignes actuelles, la presse du métier cite la 1845, lancée en 2012 avec une cape Habano d''Équateur, comme une rupture avec les Partagás à cape Cameroun, et la Black Label, à cape Connecticut Broadleaf maduro selon les détaillants. En 2015, l''Aniversario 170 est sortie avec une cape Cameroun cultivée au soleil (revue du 20 novembre 2015). En 2025, STG a confié une édition, la Y Nada Más Santiago, à Tabacalera William Ventura à Tamboril, près de Santiago (titre vu).'), `history`),
  `history_en` = IF(LOCATE(CAST('The 1845 range, launched to commemorate the founding year of the original Havana house, is the most ambitious proposition of the American version: a Mexican San Andrés-dominant blend that explicitly seeks to reproduce the earthy intensity of the Cuban Partagás. Some American enthusiasts prefer it to the original for its consistency; others find it too linear in its intensity. Both positions are defensible and simply reflect different stylistic preferences.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The 1845 range, launched to commemorate the founding year of the original Havana house, is the most ambitious proposition of the American version: a Mexican San Andrés-dominant blend that explicitly seeks to reproduce the earthy intensity of the Cuban Partagás. Some American enthusiasts prefer it to the original for its consistency; others find it too linear in its intensity. Both positions are defensible and simply reflect different stylistic preferences.', 'Among the current lines, the trade press cites the 1845, launched in 2012 with an Ecuadorian Habano wrapper, as a break from the Cameroon-wrapped Partagás, and the Black Label, with a Connecticut Broadleaf maduro wrapper according to retailers. In 2015 the Aniversario 170 came out with a sun-grown Cameroon wrapper (issue of 20 November 2015). In 2025 STG entrusted one edition, the Y Nada Más Santiago, to Tabacalera William Ventura in Tamboril, near Santiago (headline seen).'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La gama 1845, lanzada para conmemorar el año de fundación de la casa habanera original, es la propuesta más ambiciosa de la versión estadounidense: una ligada de predominio mexicano San Andrés que busca explícitamente reproducir la intensidad terrosa del Partagás cubano. Algunos aficionados estadounidenses la prefieren al original por su regularidad; otros la encuentran demasiado lineal. Ambas posturas son defendibles y solo reflejan preferencias de estilo distintas.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La gama 1845, lanzada para conmemorar el año de fundación de la casa habanera original, es la propuesta más ambiciosa de la versión estadounidense: una ligada de predominio mexicano San Andrés que busca explícitamente reproducir la intensidad terrosa del Partagás cubano. Algunos aficionados estadounidenses la prefieren al original por su regularidad; otros la encuentran demasiado lineal. Ambas posturas son defendibles y solo reflejan preferencias de estilo distintas.', 'Entre las líneas actuales, la prensa del sector cita la 1845, lanzada en 2012 con capa Habano de Ecuador, como una ruptura con los Partagás de capa Camerún, y la Black Label, de capa Connecticut Broadleaf maduro según los minoristas. En 2015 salió el Aniversario 170 con una capa Camerún cultivada al sol (número del 20 de noviembre de 2015). En 2025, STG encargó una edición, la Y Nada Más Santiago, a Tabacalera William Ventura, en Tamboril, cerca de Santiago (titular visto).'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die Linie 1845, benannt nach dem Gründungsjahr des ursprünglichen Havanna-Hauses, ist der ehrgeizigste Vorschlag der amerikanischen Version: eine Mischung mit Übergewicht des mexikanischen San Andrés, die ausdrücklich die erdige Intensität des kubanischen Partagás nachbilden will. Manche amerikanischen Liebhaber ziehen sie wegen ihrer Gleichmäßigkeit dem Original vor, andere finden sie zu geradlinig. Beide Haltungen lassen sich vertreten und spiegeln schlicht unterschiedliche Stilvorlieben.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die Linie 1845, benannt nach dem Gründungsjahr des ursprünglichen Havanna-Hauses, ist der ehrgeizigste Vorschlag der amerikanischen Version: eine Mischung mit Übergewicht des mexikanischen San Andrés, die ausdrücklich die erdige Intensität des kubanischen Partagás nachbilden will. Manche amerikanischen Liebhaber ziehen sie wegen ihrer Gleichmäßigkeit dem Original vor, andere finden sie zu geradlinig. Beide Haltungen lassen sich vertreten und spiegeln schlicht unterschiedliche Stilvorlieben.', 'Unter den aktuellen Linien nennt die Fachpresse die 1845, 2012 mit einem Habano-Deckblatt aus Ecuador eingeführt, als Bruch mit den Partagás mit Kamerun-Deckblatt, sowie die Black Label mit Connecticut-Broadleaf-Maduro-Deckblatt laut Händlern. 2015 erschien die Aniversario 170 mit einem sonnengewachsenen Kamerun-Deckblatt (Ausgabe vom 20. November 2015). 2025 vertraute STG eine Edition, die Y Nada Más Santiago, Tabacalera William Ventura in Tamboril bei Santiago an (Titel gesehen).'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('为纪念哈瓦那原厂创立年份而推出的 1845 系列，是美国版最具野心的作品：以墨西哥 San Andrés 为主的配方，明确追求还原古巴 Partagás 的厚土强度。一些美国爱好者因其稳定而更偏爱它，另一些人则嫌其过于平直。两种看法都站得住脚，不过是风格偏好不同而已。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '为纪念哈瓦那原厂创立年份而推出的 1845 系列，是美国版最具野心的作品：以墨西哥 San Andrés 为主的配方，明确追求还原古巴 Partagás 的厚土强度。一些美国爱好者因其稳定而更偏爱它，另一些人则嫌其过于平直。两种看法都站得住脚，不过是风格偏好不同而已。', '在现行系列中，行业媒体提到 1845，2012年推出，采用厄瓜多尔 Habano 茄衣，与喀麦隆茄衣的 Partagás 形成断裂；还有 Black Label，据零售商称采用 Connecticut Broadleaf 马杜罗茄衣。2015年，Aniversario 170 问世，采用日晒栽培的喀麦隆茄衣（2015年11月20日一期）。2025年，STG 把一款版本 Y Nada Más Santiago 交给圣地亚哥附近塔姆沃里尔的 Tabacalera William Ventura（仅见标题）。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('أما تشكيلة 1845، التي أُطلقت إحياءً لسنة تأسيس الدار الهافانية الأصلية، فهي أطمح ما تقدّمه النسخة الأمريكية: خلطة يغلب عليها San Andrés المكسيكي وتسعى صراحةً إلى استعادة الشدّة الترابية لـ Partagás الكوبية. بعض الهواة الأمريكيين يفضّلونها على الأصل لانتظامها، وبعضهم يجدها خطّية أكثر مما ينبغي. والموقفان معاً وجيهان، ولا يعكسان سوى اختلاف في تفضيلات الأسلوب.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'أما تشكيلة 1845، التي أُطلقت إحياءً لسنة تأسيس الدار الهافانية الأصلية، فهي أطمح ما تقدّمه النسخة الأمريكية: خلطة يغلب عليها San Andrés المكسيكي وتسعى صراحةً إلى استعادة الشدّة الترابية لـ Partagás الكوبية. بعض الهواة الأمريكيين يفضّلونها على الأصل لانتظامها، وبعضهم يجدها خطّية أكثر مما ينبغي. والموقفان معاً وجيهان، ولا يعكسان سوى اختلاف في تفضيلات الأسلوب.', 'من بين التشكيلات الحالية تذكر صحافة المهنة 1845، التي أُطلقت في 2012 بغلاف Habano من الإكوادور، بوصفها قطيعة مع Partagás ذات الغلاف الكاميروني، وتذكر Black Label بغلاف Connecticut Broadleaf مادورو بحسب تجار التجزئة. وفي 2015 صدرت Aniversario 170 بغلاف كاميروني مزروع تحت الشمس (عدد 20 نوفمبر 2015). وفي 2025 أسندت STG إصداراً هو Y Nada Más Santiago إلى Tabacalera William Ventura في تامبوريل قرب سانتياغو (العنوان فقط مطّلع عليه).'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Partagás USA';

UPDATE `brands` SET
  `country_id` = 'dominican',
  `limited_eds` = '["Partagás Aniversario 170 (2015)","Partagás 1845 Heritage (titre vu)"]',
  `founded` = '1978 — États-Unis (General Cigar)',
  `factory` = 'General Cigar Dominicana, Santiago de los Caballeros, République dominicaine (groupe STG)',
  `gamme` = '[{"name":"Partagás 1845","color":"#3D1A00","story":"Ligne lancée en 2012 selon la presse du métier : cape Habano d''Équateur, liant Connecticut, profil plein de saveur et de corps moyen, café et cacao, entre la ligne jaune et la Black Label. Faite à Santiago.","wrapper":"Habano d''Équateur","force":"Medium"},{"name":"Partagás Black Label","color":"#1A1A1A","story":"Ligne maduro : cape Connecticut Broadleaf, liant dominicain, ligero nicaraguayen et piloto cubano dominicain selon un détaillant ; faite main en République dominicaine. Chocolat, café, notes de noix.","wrapper":"Connecticut Broadleaf maduro","force":"Full"}]',
  `gamme_en` = '[{"name":"Partagás 1845","color":"#3D1A00","story":"Line launched in 2012 according to the trade press: Ecuadorian Habano wrapper, Connecticut binder, a full-flavoured, medium-bodied profile, coffee and cocoa, between the yellow line and the Black Label. Made in Santiago.","wrapper":"Ecuadorian Habano","force":"Medium"},{"name":"Partagás Black Label","color":"#1A1A1A","story":"Maduro line: Connecticut Broadleaf wrapper, Dominican binder, Nicaraguan ligero and Dominican piloto cubano according to a retailer; handmade in the Dominican Republic. Chocolate, coffee, nutty notes.","wrapper":"Connecticut Broadleaf maduro","force":"Full"}]',
  `gamme_es` = '[{"name":"Partagás 1845","color":"#3D1A00","story":"Línea lanzada en 2012 según la prensa del sector: capa Habano de Ecuador, capote Connecticut, perfil lleno de sabor y de cuerpo medio, café y cacao, entre la línea amarilla y la Black Label. Hecha en Santiago.","wrapper":"Habano de Ecuador","force":"Medium"},{"name":"Partagás Black Label","color":"#1A1A1A","story":"Línea maduro: capa Connecticut Broadleaf, capote dominicano, ligero nicaragüense y piloto cubano dominicano según un minorista; hecha a mano en la República Dominicana. Chocolate, café, notas de nuez.","wrapper":"Connecticut Broadleaf maduro","force":"Full"}]',
  `gamme_de` = '[{"name":"Partagás 1845","color":"#3D1A00","story":"Linie, 2012 eingeführt laut Fachpresse: Habano-Deckblatt aus Ecuador, Connecticut-Umblatt, geschmacksreiches Profil mit mittlerer Stärke, Kaffee und Kakao, zwischen der gelben Linie und der Black Label. In Santiago gefertigt.","wrapper":"Habano aus Ecuador","force":"Medium"},{"name":"Partagás Black Label","color":"#1A1A1A","story":"Maduro-Linie: Connecticut-Broadleaf-Deckblatt, dominikanisches Umblatt, nicaraguanisches Ligero und dominikanischer Piloto cubano laut einem Händler; handgefertigt in der Dominikanischen Republik. Schokolade, Kaffee, Nussnoten.","wrapper":"Connecticut Broadleaf Maduro","force":"Full"}]',
  `gamme_zh` = '[{"name":"Partagás 1845","color":"#3D1A00","story":"据行业媒体，该系列 2012年推出：厄瓜多尔 Habano 茄衣，Connecticut 茄套，风味饱满、浓度中等，带咖啡与可可，位于黄线系列与 Black Label 之间。在圣地亚哥制作。","wrapper":"厄瓜多尔 Habano","force":"Medium"},{"name":"Partagás Black Label","color":"#1A1A1A","story":"马杜罗系列：Connecticut Broadleaf 茄衣，多米尼加茄套，据一家零售商称，茄芯含尼加拉瓜 ligero 与多米尼加产 piloto cubano；在多米尼加共和国手工制作。巧克力、咖啡、坚果气息。","wrapper":"Connecticut Broadleaf 马杜罗","force":"Full"}]',
  `gamme_ar` = '[{"name":"Partagás 1845","color":"#3D1A00","story":"تشكيلة أُطلقت في 2012 بحسب صحافة المهنة: غلاف Habano من الإكوادور، وربّاط Connecticut، وطابع غني بالنكهة متوسط الجسم، قهوة وكاكاو، بين الخط الأصفر وBlack Label. صُنعت في سانتياغو.","wrapper":"Habano من الإكوادور","force":"Medium"},{"name":"Partagás Black Label","color":"#1A1A1A","story":"تشكيلة مادورو: غلاف Connecticut Broadleaf، وربّاط دومينيكي، وligero نيكاراغوي وpiloto cubano دومينيكي بحسب تاجر تجزئة؛ مصنوعة يدوياً في جمهورية الدومينيكان. شوكولاتة وقهوة ولمسات من المكسرات.","wrapper":"Connecticut Broadleaf مادورو","force":"Full"}]',
  `celebrities` = '[]',
  `celebrities_en` = '[]',
  `celebrities_es` = '[]',
  `celebrities_de` = '[]',
  `celebrities_zh` = '[]',
  `celebrities_ar` = '[]',
  `source` = IF(LOCATE(CAST('generalcigar.com, cigaraficionado.com et en.wikipedia.org (la version non cubaine du nom, faite par General Cigar à Santiago)' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, 'generalcigar.com, cigaraficionado.com et en.wikipedia.org (la version non cubaine du nom, faite par General Cigar à Santiago)', 'en.wikipedia.org « Partagás (cigar brand) » (General Cigar, marque de 1978, Jamaïque puis Santiago, bague 1845 ; division de STG) ; en.wikipedia.org « General Cigar Company » (Swedish Match 2005, STG 2010, 2016 ; Forged Cigar Company, janvier 2021) ; cigaraficionado.com « The Partagas Family » (hiver 1995/96 : General Cigar Dominicana, zone franche de Santiago, 8 millions de Partagás par an) ; cigardojo.com « Partagas Aniversario 170 » (20 novembre 2015 : cape Cameroun, General Cigar Dominicana) ; cigaraficionado.com « General adds new sizes to Partagas 1845 » (titre vu : ligne 1845, 2012) ; NeptuneCigar.com « Partagas Black Label Clasico » (détaillant : cape Connecticut Broadleaf maduro) ; halfwheel.com « STG turns to Tabacalera William Ventura for Partagas Y Nada Más Santiago » (titre vu, 2025)'), `source`),
  `updated_at` = NOW()
 WHERE `name` = 'Partagás USA';

-- ── Romeo y Julieta USA ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('La version américaine de Romeo y Julieta partage avec Cohiba USA et Partagás USA la même genèse juridique : l''embargo américain contre Cuba ouvrit la voie à l''enregistrement de la marque sur le sol américain par des entités distinctes de la maison havanaise originale.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'La version américaine de Romeo y Julieta partage avec Cohiba USA et Partagás USA la même genèse juridique : l''embargo américain contre Cuba ouvrit la voie à l''enregistrement de la marque sur le sol américain par des entités distinctes de la maison havanaise originale.', 'Romeo y Julieta est une marque de 1875 ; la page d''Altadis U.S.A. la dit établie cette année-là, et Wikipédia nomme Inocencio Alvarez et Manin García. Après la révolution cubaine et la nationalisation, la marque a été déplacée à La Romana, en République dominicaine, selon Wikipédia ; la version vendue aux États-Unis y est gérée par Altadis U.S.A. Elle n''est pas la même marque que Romeo y Julieta de Cuba, distribué par Habanos S.A. : le nom est commun, les tabacs et les fabriques diffèrent.'), `history`),
  `history_en` = IF(LOCATE(CAST('The American Romeo y Julieta shares with Cohiba USA and Partagás USA the same legal genesis: the American embargo against Cuba opened the way for trademark registration on American soil by entities entirely distinct from the original Havana house.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The American Romeo y Julieta shares with Cohiba USA and Partagás USA the same legal genesis: the American embargo against Cuba opened the way for trademark registration on American soil by entities entirely distinct from the original Havana house.', 'Romeo y Julieta is a brand of 1875; the Altadis U.S.A. page says it was established that year, and Wikipedia names Inocencio Alvarez and Manin García. After the Cuban Revolution and the nationalisation, the brand was moved to La Romana, in the Dominican Republic, according to Wikipedia; the version sold in the United States is managed there by Altadis U.S.A. It is not the same brand as the Romeo y Julieta of Cuba, distributed by Habanos S.A.: the name is shared, the tobaccos and the factories differ.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La versión estadounidense de Romeo y Julieta comparte con Cohiba USA y Partagás USA la misma génesis jurídica: el embargo estadounidense contra Cuba abrió la vía al registro de la marca en suelo estadounidense por entidades ajenas a la casa habanera original.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La versión estadounidense de Romeo y Julieta comparte con Cohiba USA y Partagás USA la misma génesis jurídica: el embargo estadounidense contra Cuba abrió la vía al registro de la marca en suelo estadounidense por entidades ajenas a la casa habanera original.', 'Romeo y Julieta es una marca de 1875; la página de Altadis U.S.A. la da por establecida ese año, y Wikipedia nombra a Inocencio Alvarez y Manin García. Tras la revolución cubana y la nacionalización, la marca se trasladó a La Romana, en la República Dominicana, según Wikipedia; la versión que se vende en Estados Unidos la gestiona allí Altadis U.S.A. No es la misma marca que el Romeo y Julieta de Cuba, distribuido por Habanos S.A.: el nombre es común, los tabacos y las fábricas difieren.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die amerikanische Version von Romeo y Julieta teilt mit Cohiba USA und Partagás USA denselben rechtlichen Ursprung: Das amerikanische Embargo gegen Kuba ebnete den Weg dafür, dass die Marke auf amerikanischem Boden von Gesellschaften eingetragen wurde, die mit dem ursprünglichen Havanna-Haus nichts zu tun hatten.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die amerikanische Version von Romeo y Julieta teilt mit Cohiba USA und Partagás USA denselben rechtlichen Ursprung: Das amerikanische Embargo gegen Kuba ebnete den Weg dafür, dass die Marke auf amerikanischem Boden von Gesellschaften eingetragen wurde, die mit dem ursprünglichen Havanna-Haus nichts zu tun hatten.', 'Romeo y Julieta ist eine Marke von 1875; die Seite von Altadis U.S.A. nennt sie in jenem Jahr gegründet, und Wikipedia nennt Inocencio Alvarez und Manin García. Nach der kubanischen Revolution und der Verstaatlichung wurde die Marke laut Wikipedia nach La Romana in der Dominikanischen Republik verlegt; die in den Vereinigten Staaten verkaufte Version wird dort von Altadis U.S.A. geführt. Sie ist nicht dieselbe Marke wie das Romeo y Julieta aus Kuba, das von Habanos S.A. vertrieben wird: Der Name ist gemeinsam, Tabake und Fabriken unterscheiden sich.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('Romeo y Julieta 的美国版与 Cohiba USA、Partagás USA 有着相同的法律出身：美国对古巴的禁运，为哈瓦那原厂之外的公司在美国境内注册该商标打开了通路。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, 'Romeo y Julieta 的美国版与 Cohiba USA、Partagás USA 有着相同的法律出身：美国对古巴的禁运，为哈瓦那原厂之外的公司在美国境内注册该商标打开了通路。', 'Romeo y Julieta 是 1875年的品牌；Altadis U.S.A. 的页面称其创立于当年，维基百科则提到 Inocencio Alvarez 与 Manin García。据维基百科，古巴革命与国有化之后，品牌迁到了多米尼加共和国的拉罗马纳；在美国销售的版本由 Altadis U.S.A. 在那里管理。它与由 Habanos S.A. 发行的古巴 Romeo y Julieta 不是同一个品牌：名字相同，烟叶与工厂不同。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('تشترك النسخة الأمريكية من Romeo y Julieta مع Cohiba USA وPartagás USA في المنشأ القانوني نفسه: فالحظر الأمريكي على كوبا فتح الطريق أمام تسجيل العلامة على الأراضي الأمريكية من قِبل كيانات لا صلة لها بالدار الهافانية الأصلية.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'تشترك النسخة الأمريكية من Romeo y Julieta مع Cohiba USA وPartagás USA في المنشأ القانوني نفسه: فالحظر الأمريكي على كوبا فتح الطريق أمام تسجيل العلامة على الأراضي الأمريكية من قِبل كيانات لا صلة لها بالدار الهافانية الأصلية.', 'Romeo y Julieta علامة تعود إلى 1875؛ وتذكر صفحة Altadis U.S.A. أنها تأسست في تلك السنة، وتسمّي ويكيبيديا Inocencio Alvarez وManin García. وبعد الثورة الكوبية والتأميم نُقلت العلامة إلى لا رومانا في جمهورية الدومينيكان بحسب ويكيبيديا؛ والنسخة المباعة في الولايات المتحدة تديرها هناك Altadis U.S.A. وهي ليست العلامة نفسها مثل Romeo y Julieta الكوبية التي توزّعها Habanos S.A.: فالاسم مشترك، أما التبغ والمصانع فمختلفة.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Romeo y Julieta USA';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Altadis USA — passée d''Imperial Brands à Gemstone Investment Holding en octobre 2020 — détient les droits américains de Romeo y Julieta et produit la gamme en République Dominicaine. La marque américaine a su créer sa propre identité sans chercher à reproduire exactement le profil cubain — un choix stratégique judicieux qui lui a évité les comparaisons défavorables inévitables.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Altadis USA — passée d''Imperial Brands à Gemstone Investment Holding en octobre 2020 — détient les droits américains de Romeo y Julieta et produit la gamme en République Dominicaine. La marque américaine a su créer sa propre identité sans chercher à reproduire exactement le profil cubain — un choix stratégique judicieux qui lui a évité les comparaisons défavorables inévitables.', 'Altadis U.S.A. détient la marque aux États-Unis (presse du métier, 3 février 2025). Elle fait partie de Tabacalera USA, que Imperial Brands a cédée à Gemstone Investment Holding (clôture prévue le 29 octobre 2020, Cigar Coop) ; l''usine Tabacalera de García, en République dominicaine, était comprise dans la vente du reste du monde à Allied Cigar Corporation. La gamme américaine n''a donc plus une origine unique : la page de la maison (altadisusa.com, octobre 2026) liste des lignes de République dominicaine, du Honduras et du Nicaragua.'), `history`),
  `history_en` = IF(LOCATE(CAST('Altadis USA — sold by Imperial Brands to Gemstone Investment Holding in October 2020 — holds the American rights to Romeo y Julieta and produces the range in the Dominican Republic. The American brand has succeeded in creating its own identity without trying to exactly reproduce the Cuban profile — a judicious strategic choice that spared it the inevitable unfavorable comparisons.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'Altadis USA — sold by Imperial Brands to Gemstone Investment Holding in October 2020 — holds the American rights to Romeo y Julieta and produces the range in the Dominican Republic. The American brand has succeeded in creating its own identity without trying to exactly reproduce the Cuban profile — a judicious strategic choice that spared it the inevitable unfavorable comparisons.', 'Altadis U.S.A. holds the brand in the United States (trade press, 3 February 2025). It is part of Tabacalera USA, which Imperial Brands sold to Gemstone Investment Holding (closing expected on 29 October 2020, Cigar Coop); the Tabacalera de García factory in the Dominican Republic was included in the sale of the rest of the world to Allied Cigar Corporation. The American range therefore no longer has a single origin: the house''s page (altadisusa.com, October 2026) lists lines from the Dominican Republic, Honduras and Nicaragua.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Altadis USA —vendida por Imperial Brands a Gemstone Investment Holding en octubre de 2020— posee los derechos estadounidenses de Romeo y Julieta y produce la gama en la República Dominicana. La marca estadounidense ha sabido crear su propia identidad sin pretender reproducir exactamente el perfil cubano: una decisión estratégica acertada que le ha ahorrado las inevitables comparaciones desfavorables.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Altadis USA —vendida por Imperial Brands a Gemstone Investment Holding en octubre de 2020— posee los derechos estadounidenses de Romeo y Julieta y produce la gama en la República Dominicana. La marca estadounidense ha sabido crear su propia identidad sin pretender reproducir exactamente el perfil cubano: una decisión estratégica acertada que le ha ahorrado las inevitables comparaciones desfavorables.', 'Altadis U.S.A. posee la marca en Estados Unidos (prensa del sector, 3 de febrero de 2025). Forma parte de Tabacalera USA, que Imperial Brands vendió a Gemstone Investment Holding (cierre previsto el 29 de octubre de 2020, Cigar Coop); la fábrica Tabacalera de García, en la República Dominicana, estaba incluida en la venta del resto del mundo a Allied Cigar Corporation. La gama estadounidense ya no tiene, pues, un origen único: la página de la casa (altadisusa.com, octubre de 2026) enumera líneas de la República Dominicana, de Honduras y de Nicaragua.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Altadis USA — im Oktober 2020 von Imperial Brands an Gemstone Investment Holding verkauft — hält die amerikanischen Rechte an Romeo y Julieta und fertigt die Linie in der Dominikanischen Republik. Die amerikanische Marke hat es verstanden, eine eigene Identität zu entwickeln, statt das kubanische Profil genau nachbilden zu wollen — eine kluge strategische Entscheidung, die ihr die unvermeidlichen ungünstigen Vergleiche ersparte.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Altadis USA — im Oktober 2020 von Imperial Brands an Gemstone Investment Holding verkauft — hält die amerikanischen Rechte an Romeo y Julieta und fertigt die Linie in der Dominikanischen Republik. Die amerikanische Marke hat es verstanden, eine eigene Identität zu entwickeln, statt das kubanische Profil genau nachbilden zu wollen — eine kluge strategische Entscheidung, die ihr die unvermeidlichen ungünstigen Vergleiche ersparte.', 'Altadis U.S.A. hält die Marke in den Vereinigten Staaten (Fachpresse, 3. Februar 2025). Sie gehört zu Tabacalera USA, die Imperial Brands an Gemstone Investment Holding verkauft hat (Abschluss für den 29. Oktober 2020 vorgesehen, Cigar Coop); die Fabrik Tabacalera de García in der Dominikanischen Republik war im Verkauf des Rests der Welt an Allied Cigar Corporation enthalten. Die amerikanische Linie hat daher keinen einheitlichen Ursprung mehr: Die Seite des Hauses (altadisusa.com, Oktober 2026) führt Linien aus der Dominikanischen Republik, aus Honduras und aus Nicaragua auf.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('Altadis USA（2020 年 10 月由 Imperial Brands 售予 Gemstone Investment Holding）持有 Romeo y Julieta 的美国权利，并在多米尼加共和国生产该系列。这个美国品牌懂得建立自己的身份，而不去精确复刻古巴风格——这一策略选择颇为明智，替它免去了必然不利的比较。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, 'Altadis USA（2020 年 10 月由 Imperial Brands 售予 Gemstone Investment Holding）持有 Romeo y Julieta 的美国权利，并在多米尼加共和国生产该系列。这个美国品牌懂得建立自己的身份，而不去精确复刻古巴风格——这一策略选择颇为明智，替它免去了必然不利的比较。', 'Altadis U.S.A. 在美国持有该品牌（行业媒体，2025年2月3日）。它隶属于 Tabacalera USA，后者已由 Imperial Brands 售予 Gemstone Investment Holding（预计 2020年10月29日完成交割，Cigar Coop）；多米尼加共和国的 Tabacalera de García 工厂包含在向 Allied Cigar Corporation 出售世界其他地区业务的交易中。因此美国的系列已不再只有单一产地：该公司页面（altadisusa.com，2026年10月）列出了来自多米尼加共和国、洪都拉斯与尼加拉瓜的系列。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('تملك Altadis USA — التي باعتها Imperial Brands إلى Gemstone Investment Holding في أكتوبر 2020 — الحقوق الأمريكية لـ Romeo y Julieta وتنتج التشكيلة في جمهورية الدومينيكان. وقد أحسنت العلامة الأمريكية بناء هوية خاصة بها بدل السعي إلى استنساخ الطابع الكوبي حرفياً — وهو خيار استراتيجي صائب جنّبها المقارنات غير المواتية الحتمية.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'تملك Altadis USA — التي باعتها Imperial Brands إلى Gemstone Investment Holding في أكتوبر 2020 — الحقوق الأمريكية لـ Romeo y Julieta وتنتج التشكيلة في جمهورية الدومينيكان. وقد أحسنت العلامة الأمريكية بناء هوية خاصة بها بدل السعي إلى استنساخ الطابع الكوبي حرفياً — وهو خيار استراتيجي صائب جنّبها المقارنات غير المواتية الحتمية.', 'تملك Altadis U.S.A. العلامة في الولايات المتحدة (صحافة المهنة، 3 فبراير 2025). وهي جزء من Tabacalera USA التي باعتها Imperial Brands إلى Gemstone Investment Holding (إغلاق الصفقة مقرر في 29 أكتوبر 2020، Cigar Coop)؛ وكان مصنع Tabacalera de García في جمهورية الدومينيكان داخلاً في بيع بقية العالم إلى Allied Cigar Corporation. فلم يعد للتشكيلة الأمريكية أصل واحد: إذ تسرد صفحة الدار (altadisusa.com، أكتوبر 2026) تشكيلات من جمهورية الدومينيكان وهندوراس ونيكاراغوا.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Romeo y Julieta USA';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('La gamme 1875 — nombre rappelant l''année de fondation de la maison havanaise — est construite autour de tabacs dominicains et équatoriens avec des appoints nicaraguayens. Son profil plus doux et plus crémeux que la version cubaine reflète les préférences du marché américain large, et lui a permis d''atteindre des volumes que le cubain n''approchera jamais.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'La gamme 1875 — nombre rappelant l''année de fondation de la maison havanaise — est construite autour de tabacs dominicains et équatoriens avec des appoints nicaraguayens. Son profil plus doux et plus crémeux que la version cubaine reflète les préférences du marché américain large, et lui a permis d''atteindre des volumes que le cubain n''approchera jamais.', 'La Reserve est roulée à la main au Honduras, à La Flor de Copán (cape et liant nicaraguayens, tripe de Honduras et du Nicaragua) ; la 1875 Nicaragua est un puro nicaraguayen fait à la main par Plasencia ; la 150th Anniversary de 2025 est faite à Tabacalera de García. La page de la maison ne dit pas que la 1875 (cape Indonesian Shade Grown) ni la 1875 Reserve Maduro (cape Connecticut Broadleaf) sont roulées à la main ; elles ne figurent pas dans la gamme.'), `history`),
  `history_en` = IF(LOCATE(CAST('The 1875 range — the number recalling the founding year of the original Havana house — is built around Dominican and Ecuadorian tobaccos with Nicaraguan contributions. Its softer, creamier profile than the Cuban version reflects the preferences of the broad American market, allowing it to reach volumes the Cuban brand will never approach.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The 1875 range — the number recalling the founding year of the original Havana house — is built around Dominican and Ecuadorian tobaccos with Nicaraguan contributions. Its softer, creamier profile than the Cuban version reflects the preferences of the broad American market, allowing it to reach volumes the Cuban brand will never approach.', 'The Reserve is handrolled in Honduras, at La Flor de Copán (Nicaraguan wrapper and binder, filler from Honduras and Nicaragua); the 1875 Nicaragua is a Nicaraguan puro handmade by Plasencia; the 150th Anniversary of 2025 is made at Tabacalera de García. The house''s page does not say that the 1875 (Indonesian Shade Grown wrapper) or the 1875 Reserve Maduro (Connecticut Broadleaf wrapper) are handrolled; they are not in the range.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La gama 1875 —cifra que recuerda el año de fundación de la casa habanera— se construye sobre tabacos dominicanos y ecuatorianos con aportes nicaragüenses. Su perfil, más suave y cremoso que el de la versión cubana, refleja las preferencias del gran mercado estadounidense y le ha permitido alcanzar volúmenes que el cubano nunca rozará.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La gama 1875 —cifra que recuerda el año de fundación de la casa habanera— se construye sobre tabacos dominicanos y ecuatorianos con aportes nicaragüenses. Su perfil, más suave y cremoso que el de la versión cubana, refleja las preferencias del gran mercado estadounidense y le ha permitido alcanzar volúmenes que el cubano nunca rozará.', 'La Reserve se tuerce a mano en Honduras, en La Flor de Copán (capa y capote nicaragüenses, tripa de Honduras y de Nicaragua); la 1875 Nicaragua es un puro nicaragüense hecho a mano por Plasencia; la 150th Anniversary de 2025 se hace en Tabacalera de García. La página de la casa no dice que la 1875 (capa Indonesian Shade Grown) ni la 1875 Reserve Maduro (capa Connecticut Broadleaf) se tuerzan a mano; no figuran en la gama.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die Linie 1875 — die Zahl erinnert an das Gründungsjahr des Havanna-Hauses — beruht auf dominikanischen und ecuadorianischen Tabaken mit nicaraguanischen Zugaben. Ihr milderes, cremigeres Profil gegenüber der kubanischen Version entspricht dem Geschmack des breiten amerikanischen Marktes und hat ihr Stückzahlen verschafft, an die die kubanische nie herankommen wird.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die Linie 1875 — die Zahl erinnert an das Gründungsjahr des Havanna-Hauses — beruht auf dominikanischen und ecuadorianischen Tabaken mit nicaraguanischen Zugaben. Ihr milderes, cremigeres Profil gegenüber der kubanischen Version entspricht dem Geschmack des breiten amerikanischen Marktes und hat ihr Stückzahlen verschafft, an die die kubanische nie herankommen wird.', 'Die Reserve wird in Honduras bei La Flor de Copán von Hand gerollt (Deckblatt und Umblatt aus Nicaragua, Einlage aus Honduras und Nicaragua); die 1875 Nicaragua ist ein nicaraguanischer Puro, von Plasencia handgefertigt; die 150th Anniversary von 2025 wird bei Tabacalera de García gefertigt. Die Seite des Hauses sagt nicht, dass die 1875 (Deckblatt Indonesian Shade Grown) oder die 1875 Reserve Maduro (Deckblatt Connecticut Broadleaf) von Hand gerollt sind; sie gehören nicht zur Linie.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('1875 系列——数字取自哈瓦那老厂的创立年份——以多米尼加与厄瓜多尔烟叶为骨，辅以尼加拉瓜烟叶。它比古巴版更柔和、更奶润的风格契合美国大众市场的偏好，也让它达到了古巴版永远无法接近的产量。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '1875 系列——数字取自哈瓦那老厂的创立年份——以多米尼加与厄瓜多尔烟叶为骨，辅以尼加拉瓜烟叶。它比古巴版更柔和、更奶润的风格契合美国大众市场的偏好，也让它达到了古巴版永远无法接近的产量。', 'Reserve 在洪都拉斯的 La Flor de Copán 手工卷制（茄衣与茄套来自尼加拉瓜，茄芯来自洪都拉斯与尼加拉瓜）；1875 Nicaragua 是由 Plasencia 手工制作的尼加拉瓜纯种雪茄；2025年的 150th Anniversary 在 Tabacalera de García 制作。该公司页面没有说 1875（Indonesian Shade Grown 茄衣）或 1875 Reserve Maduro（Connecticut Broadleaf 茄衣）是手工卷制；它们不在系列之列。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('أما تشكيلة 1875 — والرقم يذكّر بسنة تأسيس الدار الهافانية — فمبنية على تبغ دومينيكي وإكوادوري مع إضافات نيكاراغوية. وطابعها الأنعم والأكثر كريمية من النسخة الكوبية يعكس أذواق السوق الأمريكية الواسعة، وأتاح لها أحجاماً لن تقترب منها الكوبية أبداً.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'أما تشكيلة 1875 — والرقم يذكّر بسنة تأسيس الدار الهافانية — فمبنية على تبغ دومينيكي وإكوادوري مع إضافات نيكاراغوية. وطابعها الأنعم والأكثر كريمية من النسخة الكوبية يعكس أذواق السوق الأمريكية الواسعة، وأتاح لها أحجاماً لن تقترب منها الكوبية أبداً.', 'تُلَفّ Reserve يدوياً في هندوراس، في La Flor de Copán (الغلاف والربّاط نيكاراغويان، والحشوة من هندوراس ونيكاراغوا)؛ أما 1875 Nicaragua فسيجار puro نيكاراغوي صنعته Plasencia يدوياً؛ وتُصنع 150th Anniversary لسنة 2025 في Tabacalera de García. ولا تقول صفحة الدار إن 1875 (غلاف Indonesian Shade Grown) ولا 1875 Reserve Maduro (غلاف Connecticut Broadleaf) تُلَفّان يدوياً؛ فهما ليستا في التشكيلة.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Romeo y Julieta USA';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST(CONCAT('', CHAR(13), '
', CHAR(13), '
Le Reserve Maduro est l''interprétation la plus ambitieuse de la marque américaine. Sous une cape Connecticut Broadleaf fermentée deux ans, il développe chocolat au lait et café torréfié — c''est la gamme par laquelle la marque américaine a trouvé son public. Plusieurs amateurs sérieux estiment qu''il mérite d''être évalué indépendamment de son homonyme cubain — non comme substitut, mais comme expression d''une esthétique distincte.') AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, CONCAT('', CHAR(13), '
', CHAR(13), '
Le Reserve Maduro est l''interprétation la plus ambitieuse de la marque américaine. Sous une cape Connecticut Broadleaf fermentée deux ans, il développe chocolat au lait et café torréfié — c''est la gamme par laquelle la marque américaine a trouvé son public. Plusieurs amateurs sérieux estiment qu''il mérite d''être évalué indépendamment de son homonyme cubain — non comme substitut, mais comme expression d''une esthétique distincte.'), ''), `history`),
  `history_en` = IF(LOCATE(CAST(CONCAT('', CHAR(13), '
', CHAR(13), '
The Reserve Maduro is the most ambitious interpretation of the American brand. Under a Connecticut Broadleaf wrapper fermented for two years, it develops milk chocolate and roasted coffee — the range through which the American brand found its audience. Several serious enthusiasts argue it deserves to be evaluated independently of its Cuban namesake — not as a substitute, but as an expression of a distinct aesthetic.') AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, CONCAT('', CHAR(13), '
', CHAR(13), '
The Reserve Maduro is the most ambitious interpretation of the American brand. Under a Connecticut Broadleaf wrapper fermented for two years, it develops milk chocolate and roasted coffee — the range through which the American brand found its audience. Several serious enthusiasts argue it deserves to be evaluated independently of its Cuban namesake — not as a substitute, but as an expression of a distinct aesthetic.'), ''), `history_en`),
  `history_es` = IF(LOCATE(CAST('

El Reserve Maduro es la interpretación más ambiciosa de la marca estadounidense. Bajo una capa Connecticut Broadleaf fermentada dos años, despliega chocolate con leche y café tostado: es la gama con la que la marca estadounidense encontró su público. Varios aficionados serios sostienen que merece juzgarse al margen de su homónimo cubano: no como sustituto, sino como expresión de una estética propia.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, '

El Reserve Maduro es la interpretación más ambiciosa de la marca estadounidense. Bajo una capa Connecticut Broadleaf fermentada dos años, despliega chocolate con leche y café tostado: es la gama con la que la marca estadounidense encontró su público. Varios aficionados serios sostienen que merece juzgarse al margen de su homónimo cubano: no como sustituto, sino como expresión de una estética propia.', ''), `history_es`),
  `history_de` = IF(LOCATE(CAST('

Der Reserve Maduro ist die ehrgeizigste Auslegung der amerikanischen Marke. Unter einem zwei Jahre fermentierten Connecticut-Broadleaf-Deckblatt entfaltet er Milchschokolade und Röstkaffee — die Linie, mit der die amerikanische Marke ihr Publikum fand. Manche ernsthaften Liebhaber finden, er verdiene eine Beurteilung unabhängig von seinem kubanischen Namensvetter — nicht als Ersatz, sondern als Ausdruck einer eigenen Ästhetik.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, '

Der Reserve Maduro ist die ehrgeizigste Auslegung der amerikanischen Marke. Unter einem zwei Jahre fermentierten Connecticut-Broadleaf-Deckblatt entfaltet er Milchschokolade und Röstkaffee — die Linie, mit der die amerikanische Marke ihr Publikum fand. Manche ernsthaften Liebhaber finden, er verdiene eine Beurteilung unabhängig von seinem kubanischen Namensvetter — nicht als Ersatz, sondern als Ausdruck einer eigenen Ästhetik.', ''), `history_de`),
  `history_zh` = IF(LOCATE(CAST('

Reserve Maduro 是这个美国品牌最具野心的诠释。茄衣是陈化两年的 Connecticut Broadleaf，展现牛奶巧克力与烘焙咖啡的气息——这个美国品牌正是靠这个系列找到了自己的读者。不少认真的爱好者认为，应当撇开它的古巴同名者来评价它——不是作为替代品，而是作为另一种审美的表达。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '

Reserve Maduro 是这个美国品牌最具野心的诠释。茄衣是陈化两年的 Connecticut Broadleaf，展现牛奶巧克力与烘焙咖啡的气息——这个美国品牌正是靠这个系列找到了自己的读者。不少认真的爱好者认为，应当撇开它的古巴同名者来评价它——不是作为替代品，而是作为另一种审美的表达。', ''), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('

و Reserve Maduro هو أطمح تفسير قدّمته العلامة الأمريكية. فبغلاف Connecticut Broadleaf مخمَّر سنتين، يطوّر نكهات الشوكولاتة بالحليب والقهوة المحمّصة — وهي المجموعة التي وجدت بها العلامة الأمريكية جمهورها. ويرى عدد من الهواة الجادّين أنه يستحق التقييم بمعزل عن نظيره الكوبي في الاسم — لا بوصفه بديلاً، بل تعبيراً عن جماليات مستقلة.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, '

و Reserve Maduro هو أطمح تفسير قدّمته العلامة الأمريكية. فبغلاف Connecticut Broadleaf مخمَّر سنتين، يطوّر نكهات الشوكولاتة بالحليب والقهوة المحمّصة — وهي المجموعة التي وجدت بها العلامة الأمريكية جمهورها. ويرى عدد من الهواة الجادّين أنه يستحق التقييم بمعزل عن نظيره الكوبي في الاسم — لا بوصفه بديلاً، بل تعبيراً عن جماليات مستقلة.', ''), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Romeo y Julieta USA';

UPDATE `brands` SET
  `country_id` = 'dominican',
  `limited_eds` = '["Romeo y Julieta 1875 Vintage Lote (2024)"]',
  `founded` = '1875 (marque) ; version Altadis U.S.A.',
  `factory` = 'Tabacalera de García, La Romana (Rép. dominicaine) : 150th Anniversary ; La Flor de Copán (Honduras) : Reserve ; Plasencia, Estelí (Nicaragua) : 1875 Nicaragua (pages Altadis U.S.A., octobre 2026)',
  `gamme` = '[{"name":"Romeo y Julieta Reserve","color":"#5C1A1A","story":"Ligne de la maison (altadisusa.com, octobre 2026) : roulée à la main au Honduras, à La Flor de Copán. Cape et liant nicaraguayens, tripe de Honduras et du Nicaragua ; la maison la dit full-bodied. Formats : Corona 45x5 5/8, Belicoso 52x6 1/8, Robusto 54x5, Churchill 54x7, Toro 56x6, avec des tubes.","wrapper":"Nicaragua","force":null},{"name":"Romeo y Julieta 1875 Nicaragua","color":"#6b3a1f","force":null,"wrapper":"Nicaragua","vitolas":[],"story":"Puro nicaraguayen fait à la main par Plasencia Cigars S.A. au Nicaragua, selon la page de la maison (altadisusa.com, octobre 2026), qui le dit robuste. Formats : Toro 52x6, Piramide 52x6 1/8, Bully Grande 54x5."},{"name":"Romeo y Julieta 150th Anniversary","color":"#8b5a2b","force":null,"wrapper":"Sumatra d''Équateur","vitolas":[],"story":"Sortie de 2025 pour les 150 ans de la marque, faite à Tabacalera de García, en République dominicaine. Cape Sumatra d''Équateur cultivée et fermentée par A.J. Fernández, liant San Andrés de la famille Turrent, tripes du Pérou, du Honduras et dominicaine (presse du métier, 3 février 2025 ; altadisusa.com, octobre 2026)."}]',
  `gamme_en` = '[{"name":"Romeo y Julieta Reserve","color":"#5C1A1A","story":"House line (altadisusa.com, October 2026): handrolled in Honduras, at La Flor de Copán. Nicaraguan wrapper and binder, filler from Honduras and Nicaragua; the house calls it full-bodied. Sizes: Corona 45x5 5/8, Belicoso 52x6 1/8, Robusto 54x5, Churchill 54x7, Toro 56x6, with tubes.","wrapper":"Nicaragua","force":null},{"name":"Romeo y Julieta 1875 Nicaragua","color":"#6b3a1f","force":null,"wrapper":"Nicaragua","vitolas":[],"story":"Nicaraguan puro handmade by Plasencia Cigars S.A. in Nicaragua, according to the house''s page (altadisusa.com, October 2026), which calls it robust. Sizes: Toro 52x6, Piramide 52x6 1/8, Bully Grande 54x5."},{"name":"Romeo y Julieta 150th Anniversary","color":"#8b5a2b","force":null,"wrapper":"Ecuadorian Sumatra","vitolas":[],"story":"Released in 2025 for the brand''s 150 years, made at Tabacalera de García, in the Dominican Republic. Ecuadorian Sumatra wrapper grown and fermented by A.J. Fernández, San Andrés binder from the Turrent family, filler from Peru, Honduras and the Dominican Republic (trade press, 3 February 2025; altadisusa.com, October 2026)."}]',
  `gamme_es` = '[{"name":"Romeo y Julieta Reserve","color":"#5C1A1A","story":"Línea de la casa (altadisusa.com, octubre de 2026): torcida a mano en Honduras, en La Flor de Copán. Capa y capote nicaragüenses, tripa de Honduras y de Nicaragua; la casa la califica de cuerpo pleno. Formatos: Corona 45x5 5/8, Belicoso 52x6 1/8, Robusto 54x5, Churchill 54x7, Toro 56x6, con tubos.","wrapper":"Nicaragua","force":null},{"name":"Romeo y Julieta 1875 Nicaragua","color":"#6b3a1f","force":null,"wrapper":"Nicaragua","vitolas":[],"story":"Puro nicaragüense hecho a mano por Plasencia Cigars S.A. en Nicaragua, según la página de la casa (altadisusa.com, octubre de 2026), que lo califica de robusto. Formatos: Toro 52x6, Piramide 52x6 1/8, Bully Grande 54x5."},{"name":"Romeo y Julieta 150th Anniversary","color":"#8b5a2b","force":null,"wrapper":"Sumatra de Ecuador","vitolas":[],"story":"Lanzamiento de 2025 por los 150 años de la marca, hecho en Tabacalera de García, en la República Dominicana. Capa Sumatra de Ecuador cultivada y fermentada por A.J. Fernández, capote San Andrés de la familia Turrent, tripas de Perú, de Honduras y dominicana (prensa del sector, 3 de febrero de 2025; altadisusa.com, octubre de 2026)."}]',
  `gamme_de` = '[{"name":"Romeo y Julieta Reserve","color":"#5C1A1A","story":"Linie des Hauses (altadisusa.com, Oktober 2026): von Hand gerollt in Honduras, bei La Flor de Copán. Deckblatt und Umblatt aus Nicaragua, Einlage aus Honduras und Nicaragua; das Haus nennt sie vollmundig. Formate: Corona 45x5 5/8, Belicoso 52x6 1/8, Robusto 54x5, Churchill 54x7, Toro 56x6, mit Röhrchen.","wrapper":"Nicaragua","force":null},{"name":"Romeo y Julieta 1875 Nicaragua","color":"#6b3a1f","force":null,"wrapper":"Nicaragua","vitolas":[],"story":"Nicaraguanischer Puro, von Plasencia Cigars S.A. in Nicaragua handgefertigt, laut der Seite des Hauses (altadisusa.com, Oktober 2026), die ihn kräftig nennt. Formate: Toro 52x6, Piramide 52x6 1/8, Bully Grande 54x5."},{"name":"Romeo y Julieta 150th Anniversary","color":"#8b5a2b","force":null,"wrapper":"Sumatra aus Ecuador","vitolas":[],"story":"Ausgabe von 2025 zum 150-jährigen Bestehen der Marke, gefertigt bei Tabacalera de García in der Dominikanischen Republik. Sumatra-Deckblatt aus Ecuador, von A.J. Fernández angebaut und fermentiert, San-Andrés-Umblatt der Familie Turrent, Einlagen aus Peru, Honduras und der Dominikanischen Republik (Fachpresse, 3. Februar 2025; altadisusa.com, Oktober 2026)."}]',
  `gamme_zh` = '[{"name":"Romeo y Julieta Reserve","color":"#5C1A1A","story":"公司系列（altadisusa.com，2026年10月）：在洪都拉斯的 La Flor de Copán 手工卷制。茄衣与茄套来自尼加拉瓜，茄芯来自洪都拉斯与尼加拉瓜；公司称其酒体饱满。规格：Corona 45x5 5/8、Belicoso 52x6 1/8、Robusto 54x5、Churchill 54x7、Toro 56x6，另有烟管装。","wrapper":"尼加拉瓜","force":null},{"name":"Romeo y Julieta 1875 Nicaragua","color":"#6b3a1f","force":null,"wrapper":"尼加拉瓜","vitolas":[],"story":"据公司页面（altadisusa.com，2026年10月），这是由 Plasencia Cigars S.A. 在尼加拉瓜手工制作的尼加拉瓜纯种雪茄，页面称其浓壮。规格：Toro 52x6、Piramide 52x6 1/8、Bully Grande 54x5。"},{"name":"Romeo y Julieta 150th Anniversary","color":"#8b5a2b","force":null,"wrapper":"厄瓜多尔 Sumatra","vitolas":[],"story":"2025年为纪念品牌 150 周年而推出，在多米尼加共和国的 Tabacalera de García 制作。茄衣为厄瓜多尔 Sumatra，由 A.J. Fernández 种植并发酵；茄套为 Turrent 家族的 San Andrés；茄芯来自秘鲁、洪都拉斯与多米尼加（行业媒体，2025年2月3日；altadisusa.com，2026年10月）。"}]',
  `gamme_ar` = '[{"name":"Romeo y Julieta Reserve","color":"#5C1A1A","story":"تشكيلة الدار (altadisusa.com، أكتوبر 2026): تُلَفّ يدوياً في هندوراس، في La Flor de Copán. الغلاف والربّاط نيكاراغويان، والحشوة من هندوراس ونيكاراغوا؛ وتصفها الدار بأنها كاملة الجسم. المقاسات: Corona 45x5 5/8 وBelicoso 52x6 1/8 وRobusto 54x5 وChurchill 54x7 وToro 56x6، مع أنابيب.","wrapper":"نيكاراغوا","force":null},{"name":"Romeo y Julieta 1875 Nicaragua","color":"#6b3a1f","force":null,"wrapper":"نيكاراغوا","vitolas":[],"story":"سيجار puro نيكاراغوي صنعته Plasencia Cigars S.A. يدوياً في نيكاراغوا، بحسب صفحة الدار (altadisusa.com، أكتوبر 2026) التي تصفه بأنه قوي البنية. المقاسات: Toro 52x6 وPiramide 52x6 1/8 وBully Grande 54x5."},{"name":"Romeo y Julieta 150th Anniversary","color":"#8b5a2b","force":null,"wrapper":"Sumatra من الإكوادور","vitolas":[],"story":"صدرت في 2025 بمناسبة مرور 150 عاماً على العلامة، وصُنعت في Tabacalera de García بجمهورية الدومينيكان. غلاف Sumatra من الإكوادور زرعته وخمّرته A.J. Fernández، وربّاط San Andrés من عائلة Turrent، وحشوات من بيرو وهندوراس وجمهورية الدومينيكان (صحافة المهنة، 3 فبراير 2025؛ altadisusa.com، أكتوبر 2026)."}]',
  `celebrities` = '[]',
  `celebrities_en` = '[]',
  `celebrities_es` = '[]',
  `celebrities_de` = '[]',
  `celebrities_zh` = '[]',
  `celebrities_ar` = '[]',
  `pairings` = '[]',
  `pairings_en` = '[]',
  `pairings_es` = '[]',
  `pairings_de` = '[]',
  `pairings_zh` = '[]',
  `pairings_ar` = '[]',
  `source` = IF(LOCATE(CAST('altadisusa.com et cigaraficionado.com (la version américaine, chez Altadis ; Tabacalera de García à La Romana)' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, 'altadisusa.com et cigaraficionado.com (la version américaine, chez Altadis ; Tabacalera de García à La Romana)', 'altadisusa.com « Romeo y Julieta » et pages de lignes Reserve, 1875, 1875 Reserve Maduro, 1875 Nicaragua (octobre 2026 : origines, capes, Honduras, Nicaragua, République dominicaine) ; cigaraficionado.com « Altadis launching Romeo y Julieta 150th anniversary cigar » (3 février 2025 : Tabacalera de García, marque américaine à Altadis U.S.A.) ; cigarslover.com « Romeo y Julieta celebrates 150 years » (18 février 2025) ; cigar-coop.com « Completion of sale of Imperial Brands premium cigar division… » (28 septembre 2020 : Gemstone, Allied Cigar) et « Altadis USA debuts Romeo y Julieta 1875 Vintage Lote at PCA 2024 » (10 avril 2024) ; en.wikipedia.org « Romeo y Julieta (cigar) » (1875, La Romana, Altadis U.S.A.)'), `source`),
  `updated_at` = NOW()
 WHERE `name` = 'Romeo y Julieta USA';

-- ── Dannemann ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Gerhard Dannemann arriva au Brésil en 1873, à vingt-trois ans, parmi des milliers d''immigrants allemands installés dans les États du sud au cours du XIXe siècle. À la différence de la plupart, venus pour l''agriculture ou la petite industrie, Dannemann visait le tabac : il en connaissait le commerce par ses origines allemandes, et celui qu''il découvrit dans le bassin du Recôncavo, à Bahia, ne ressemblait à rien de ce qu''il attendait.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Gerhard Dannemann arriva au Brésil en 1873, à vingt-trois ans, parmi des milliers d''immigrants allemands installés dans les États du sud au cours du XIXe siècle. À la différence de la plupart, venus pour l''agriculture ou la petite industrie, Dannemann visait le tabac : il en connaissait le commerce par ses origines allemandes, et celui qu''il découvrit dans le bassin du Recôncavo, à Bahia, ne ressemblait à rien de ce qu''il attendait.', 'Dannemann naît à São Félix da Cachoeira, dans le Recôncavo de Bahia, au Brésil, avec Gerhard (devenu Geraldo) Dannemann, immigrant allemand. La date de la fabrique diverge : 1872 selon la maison (dannemann-group.com, qui la nomme sa fabrique de longfillers), 1873 selon Wikipédia, qui lui compte six employés au départ. Les deux versions sont données, non tranchées.'), `history`),
  `history_en` = IF(LOCATE(CAST('Gerhard Dannemann arrived in Brazil in 1873 at the age of 23, one of thousands of German immigrants who had settled in the southern Brazilian states during the nineteenth century. Unlike most who came for agriculture or light industry, Dannemann was drawn specifically to tobacco — he had knowledge of the trade from his German background, and the tobacco he encountered in Bahia''s Recôncavo basin was unlike anything he had expected.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'Gerhard Dannemann arrived in Brazil in 1873 at the age of 23, one of thousands of German immigrants who had settled in the southern Brazilian states during the nineteenth century. Unlike most who came for agriculture or light industry, Dannemann was drawn specifically to tobacco — he had knowledge of the trade from his German background, and the tobacco he encountered in Bahia''s Recôncavo basin was unlike anything he had expected.', 'Dannemann was born in São Félix da Cachoeira, in the Recôncavo of Bahia, Brazil, with Gerhard (later Geraldo) Dannemann, a German immigrant. The date of the factory diverges: 1872 according to the house (dannemann-group.com, which calls it its long filler factory), 1873 according to Wikipedia, which gives it six employees at the start. Both versions are given, neither settled.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Gerhard Dannemann llegó a Brasil en 1873, a los veintitrés años, entre miles de inmigrantes alemanes instalados en los estados del sur a lo largo del siglo XIX. A diferencia de la mayoría, venidos para la agricultura o la pequeña industria, Dannemann apuntaba al tabaco: conocía su comercio por sus orígenes alemanes, y el que descubrió en la cuenca del Recôncavo, en Bahía, no se parecía a nada de lo que esperaba.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Gerhard Dannemann llegó a Brasil en 1873, a los veintitrés años, entre miles de inmigrantes alemanes instalados en los estados del sur a lo largo del siglo XIX. A diferencia de la mayoría, venidos para la agricultura o la pequeña industria, Dannemann apuntaba al tabaco: conocía su comercio por sus orígenes alemanes, y el que descubrió en la cuenca del Recôncavo, en Bahía, no se parecía a nada de lo que esperaba.', 'Dannemann nace en São Félix da Cachoeira, en el Recôncavo de Bahía, en Brasil, con Gerhard (llamado luego Geraldo) Dannemann, inmigrante alemán. La fecha de la fábrica diverge: 1872 según la casa (dannemann-group.com, que la nombra su fábrica de puros de tripa larga), 1873 según Wikipedia, que le cuenta seis empleados al comienzo. Se dan las dos versiones, sin zanjar.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Gerhard Dannemann kam 1873 mit dreiundzwanzig Jahren nach Brasilien, unter Tausenden deutscher Einwanderer, die sich im Lauf des 19. Jahrhunderts in den südlichen Staaten niederließen. Anders als die meisten, die für die Landwirtschaft oder das Kleingewerbe kamen, zielte Dannemann auf den Tabak: Er kannte dessen Handel aus seiner deutschen Herkunft, und was er im Becken des Recôncavo in Bahia vorfand, glich nichts von dem, was er erwartet hatte.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Gerhard Dannemann kam 1873 mit dreiundzwanzig Jahren nach Brasilien, unter Tausenden deutscher Einwanderer, die sich im Lauf des 19. Jahrhunderts in den südlichen Staaten niederließen. Anders als die meisten, die für die Landwirtschaft oder das Kleingewerbe kamen, zielte Dannemann auf den Tabak: Er kannte dessen Handel aus seiner deutschen Herkunft, und was er im Becken des Recôncavo in Bahia vorfand, glich nichts von dem, was er erwartet hatte.', 'Dannemann entsteht in São Félix da Cachoeira, im Recôncavo von Bahia in Brasilien, mit Gerhard (später Geraldo) Dannemann, einem deutschen Einwanderer. Das Datum der Fabrik weicht ab: 1872 laut dem Haus (dannemann-group.com, das sie seine Longfiller-Fabrik nennt), 1873 laut Wikipedia, das ihr zu Beginn sechs Beschäftigte zuschreibt. Beide Fassungen werden genannt, nicht entschieden.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('1873年，二十三岁的格哈德·丹尼曼来到巴西，与19世纪里成千上万定居南部各州的德国移民同行。与多数为农业或小工业而来的人不同，丹尼曼冲着烟草：凭德国出身，他懂这门生意；而他在巴伊亚的雷孔卡沃盆地所见到的烟草，与他预想的毫无相似之处。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '1873年，二十三岁的格哈德·丹尼曼来到巴西，与19世纪里成千上万定居南部各州的德国移民同行。与多数为农业或小工业而来的人不同，丹尼曼冲着烟草：凭德国出身，他懂这门生意；而他在巴伊亚的雷孔卡沃盆地所见到的烟草，与他预想的毫无相似之处。', 'Dannemann 诞生于巴西巴伊亚雷孔卡沃的圣费利克斯-达卡绍埃拉，创办人是德国移民 Gerhard（后来称 Geraldo）Dannemann。工厂的创办日期存在分歧：公司称为1872年（dannemann-group.com，称其为公司的长填料工厂），Wikipedia 则称为1873年，并说开办时有六名员工。两种说法都列出，不作定论。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('وصل غيرهارد دانيمان إلى البرازيل عام 1873، في الثالثة والعشرين، بين آلاف المهاجرين الألمان الذين استقرّوا في الولايات الجنوبية خلال القرن التاسع عشر. وخلافًا لمعظمهم، ممن جاؤوا للزراعة أو للصناعة الصغيرة، كان دانيمان يقصد التبغ: عرف تجارته من أصوله الألمانية، لكنّ ما اكتشفه في حوض ريكونكافو بولاية باهيا لم يشبه شيئًا مما توقّعه.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'وصل غيرهارد دانيمان إلى البرازيل عام 1873، في الثالثة والعشرين، بين آلاف المهاجرين الألمان الذين استقرّوا في الولايات الجنوبية خلال القرن التاسع عشر. وخلافًا لمعظمهم، ممن جاؤوا للزراعة أو للصناعة الصغيرة، كان دانيمان يقصد التبغ: عرف تجارته من أصوله الألمانية، لكنّ ما اكتشفه في حوض ريكونكافو بولاية باهيا لم يشبه شيئًا مما توقّعه.', 'تنشأ Dannemann في ساو فيليكس دا كاشويرا، في ريكونكافو بولاية باهيا بالبرازيل، مع غيرهارد (الذي صار يُدعى جيرالدو) دانيمان، وهو مهاجر ألماني. وتاريخ المصنع مختلف عليه: سنة 1872 بحسب الدار (dannemann-group.com، التي تسمّيه مصنعها للسيجار بحشوة طويلة)، وسنة 1873 بحسب Wikipedia، التي تنسب إليه ستة عاملين في البداية. وتُعرض الروايتان دون ترجيح.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Dannemann';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Le tabac bahianais se cultive dans les vallées fertiles au sud du Rio Paraguaçu depuis le XVIIe siècle — d''abord par le travail d''esclaves africains, sous administration coloniale portugaise. Le sol y est sombre, alluvial, enrichi par des siècles de crues et de dépôts, et il donne une feuille d''une douceur naturelle qui n''a rien du caractère abrupt du tabac cubain ni de l''intensité poivrée du nicaraguayen. Elle est plus proche d''un bon Sumatra indonésien que d''aucune variété caribéenne : souple, légèrement épicée, avec une finale de noix de cajou et de miel qui la destine aux petits formats accessibles.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Le tabac bahianais se cultive dans les vallées fertiles au sud du Rio Paraguaçu depuis le XVIIe siècle — d''abord par le travail d''esclaves africains, sous administration coloniale portugaise. Le sol y est sombre, alluvial, enrichi par des siècles de crues et de dépôts, et il donne une feuille d''une douceur naturelle qui n''a rien du caractère abrupt du tabac cubain ni de l''intensité poivrée du nicaraguayen. Elle est plus proche d''un bon Sumatra indonésien que d''aucune variété caribéenne : souple, légèrement épicée, avec une finale de noix de cajou et de miel qui la destine aux petits formats accessibles.', 'Le tabac vient de la région de Mata Fina, à Bahia : selon la maison, plus de 200 fermes partenaires y cultivent la tripe, et la ferme Fazenda San Antônio, de 1 000 hectares, fournit toutes les capes des gammes de cigares premium. Les balles de tabac y vieillissent avant la fabrication.'), `history`),
  `history_en` = IF(LOCATE(CAST('Bahian tobacco has been cultivated in the fertile valleys south of the Rio Paraguaçu since the seventeenth century, originally by enslaved African labor under Portuguese colonial administration. The soil there — dark, alluvial, rich in organic matter from centuries of flooding and deposit — produces a leaf of natural softness and mild sweetness that bears no resemblance to the aggressive character of Cuban tobacco or the peppery intensity of Nicaraguan. It is closer in profile to good Indonesian Sumatra than to any Caribbean variety: gentle, slightly spiced, with a finish of cashew and honey that makes it uniquely suitable for accessible cigar formats.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'Bahian tobacco has been cultivated in the fertile valleys south of the Rio Paraguaçu since the seventeenth century, originally by enslaved African labor under Portuguese colonial administration. The soil there — dark, alluvial, rich in organic matter from centuries of flooding and deposit — produces a leaf of natural softness and mild sweetness that bears no resemblance to the aggressive character of Cuban tobacco or the peppery intensity of Nicaraguan. It is closer in profile to good Indonesian Sumatra than to any Caribbean variety: gentle, slightly spiced, with a finish of cashew and honey that makes it uniquely suitable for accessible cigar formats.', 'The tobacco comes from the Mata Fina region in Bahia: according to the house, more than 200 partner farms grow the filler there, and the 1,000-hectare Fazenda San Antônio farm supplies all the wrappers of the premium cigar ranges. The tobacco bales age there before manufacture.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('El tabaco bahiano se cultiva en los valles fértiles al sur del Río Paraguaçu desde el siglo XVII —primero mediante el trabajo de esclavos africanos, bajo administración colonial portuguesa. El suelo es allí oscuro, aluvial, enriquecido por siglos de crecidas y de depósitos, y da una hoja de una dulzura natural que nada tiene del carácter abrupto del tabaco cubano ni de la intensidad apimentada del nicaragüense. Está más cerca de un buen Sumatra indonesio que de ninguna variedad caribeña: flexible, ligeramente especiada, con un final de anacardo y de miel que la destina a los formatos pequeños y accesibles.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'El tabaco bahiano se cultiva en los valles fértiles al sur del Río Paraguaçu desde el siglo XVII —primero mediante el trabajo de esclavos africanos, bajo administración colonial portuguesa. El suelo es allí oscuro, aluvial, enriquecido por siglos de crecidas y de depósitos, y da una hoja de una dulzura natural que nada tiene del carácter abrupto del tabaco cubano ni de la intensidad apimentada del nicaragüense. Está más cerca de un buen Sumatra indonesio que de ninguna variedad caribeña: flexible, ligeramente especiada, con un final de anacardo y de miel que la destina a los formatos pequeños y accesibles.', 'El tabaco viene de la región de Mata Fina, en Bahía: según la casa, más de 200 fincas asociadas cultivan allí la tripa, y la finca Fazenda San Antônio, de 1000 hectáreas, suministra todas las capas de las gamas de puros premium. Las pacas de tabaco envejecen allí antes de la fabricación.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Der bahianische Tabak wird in den fruchtbaren Tälern südlich des Rio Paraguaçu seit dem 17. Jahrhundert angebaut — zuerst durch die Arbeit afrikanischer Sklaven, unter portugiesischer Kolonialverwaltung. Der Boden ist dort dunkel, angeschwemmt, von Jahrhunderten der Überflutungen und Ablagerungen angereichert, und er gibt ein Blatt von natürlicher Milde, das nichts vom schroffen Wesen des kubanischen Tabaks und nichts von der pfeffrigen Intensität des nicaraguanischen hat. Es steht einem guten indonesischen Sumatra näher als irgendeiner karibischen Sorte: geschmeidig, leicht gewürzt, mit einem Abgang aus Cashew und Honig, der es für die kleinen, zugänglichen Formate bestimmt.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Der bahianische Tabak wird in den fruchtbaren Tälern südlich des Rio Paraguaçu seit dem 17. Jahrhundert angebaut — zuerst durch die Arbeit afrikanischer Sklaven, unter portugiesischer Kolonialverwaltung. Der Boden ist dort dunkel, angeschwemmt, von Jahrhunderten der Überflutungen und Ablagerungen angereichert, und er gibt ein Blatt von natürlicher Milde, das nichts vom schroffen Wesen des kubanischen Tabaks und nichts von der pfeffrigen Intensität des nicaraguanischen hat. Es steht einem guten indonesischen Sumatra näher als irgendeiner karibischen Sorte: geschmeidig, leicht gewürzt, mit einem Abgang aus Cashew und Honig, der es für die kleinen, zugänglichen Formate bestimmt.', 'Der Tabak stammt aus der Region Mata Fina in Bahia: Laut dem Haus bauen dort mehr als 200 Partnerfarmen die Einlage an, und die 1000 Hektar große Farm Fazenda San Antônio liefert alle Deckblätter der Premium-Zigarrenlinien. Die Tabakballen reifen dort vor der Herstellung.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('巴伊亚烟草自17世纪起就种在帕拉瓜苏河以南的肥沃谷地里——起初依靠非洲奴隶的劳动，处在葡萄牙殖民当局的管理之下。那里的土壤深色、冲积而成，由数百年的泛滥与沉积淤积得深厚，长出的叶子带着一种天然的柔和，既没有古巴烟草的硬朗，也没有尼加拉瓜烟草的胡椒式强度。它更接近一片好的印尼苏门答腊叶，而不像任何加勒比品种：柔韧、微带香料，收尾是腰果与蜂蜜，正合适做小而可及的规格。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '巴伊亚烟草自17世纪起就种在帕拉瓜苏河以南的肥沃谷地里——起初依靠非洲奴隶的劳动，处在葡萄牙殖民当局的管理之下。那里的土壤深色、冲积而成，由数百年的泛滥与沉积淤积得深厚，长出的叶子带着一种天然的柔和，既没有古巴烟草的硬朗，也没有尼加拉瓜烟草的胡椒式强度。它更接近一片好的印尼苏门答腊叶，而不像任何加勒比品种：柔韧、微带香料，收尾是腰果与蜂蜜，正合适做小而可及的规格。', '烟草产自巴伊亚的 Mata Fina 地区：公司称，那里有200多家合作农场种植茄芯烟叶，面积1000公顷的 Fazenda San Antônio 农场供应高端雪茄系列的全部茄衣。烟叶包在那里陈放，然后才进入生产。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('يُزرع تبغ باهيا في الوديان الخصبة جنوب نهر باراغواسو منذ القرن السابع عشر — بعمل العبيد الأفارقة في البداية، تحت الإدارة الاستعمارية البرتغالية. والتربة هناك داكنة، غرينية، أغنتها قرون من الفيضانات والرواسب، وهي تعطي ورقة ذات لطف طبيعي لا شيء فيه من حدّة التبغ الكوبي ولا من شدّة النيكاراغوي الفلفلية. إنها أقرب إلى سومطرة إندونيسية جيدة منها إلى أي صنف كاريبي: ليّنة، متبّلة قليلًا، بنهاية من الكاجو والعسل تجعلها للقياسات الصغيرة الميسورة.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'يُزرع تبغ باهيا في الوديان الخصبة جنوب نهر باراغواسو منذ القرن السابع عشر — بعمل العبيد الأفارقة في البداية، تحت الإدارة الاستعمارية البرتغالية. والتربة هناك داكنة، غرينية، أغنتها قرون من الفيضانات والرواسب، وهي تعطي ورقة ذات لطف طبيعي لا شيء فيه من حدّة التبغ الكوبي ولا من شدّة النيكاراغوي الفلفلية. إنها أقرب إلى سومطرة إندونيسية جيدة منها إلى أي صنف كاريبي: ليّنة، متبّلة قليلًا، بنهاية من الكاجو والعسل تجعلها للقياسات الصغيرة الميسورة.', 'يأتي التبغ من منطقة Mata Fina في باهيا: تقول الدار إنّ ما يزيد على 200 مزرعة شريكة تزرع فيها الحشوة، وإنّ مزرعة Fazenda San Antônio، ومساحتها 1000 هكتار، تمدّ بجميع الأغلفة الخارجية لسلاسل السيجار الفاخرة. وتُعتَّق بالات التبغ هناك قبل التصنيع.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Dannemann';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Dannemann comprit le potentiel commercial de ce tabac pour le marché européen, à un moment où la classe moyenne allemande prenait goût aux petits cigares et aux cigarillos comme habitude quotidienne abordable. Il fonda sa manufacture à São Félix da Cachoeira — bourg colonial situé sur l''autre rive du Rio Paraguaçu, face au marché plus important de Cachoeira — et consacra sa première décennie à établir à la fois son approvisionnement et ses réseaux de distribution européens.

' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Dannemann comprit le potentiel commercial de ce tabac pour le marché européen, à un moment où la classe moyenne allemande prenait goût aux petits cigares et aux cigarillos comme habitude quotidienne abordable. Il fonda sa manufacture à São Félix da Cachoeira — bourg colonial situé sur l''autre rive du Rio Paraguaçu, face au marché plus important de Cachoeira — et consacra sa première décennie à établir à la fois son approvisionnement et ses réseaux de distribution européens.

', ''), `history`),
  `history_en` = IF(LOCATE(CAST(CONCAT('Dannemann recognized the commercial potential of Bahian tobacco for the European market at a moment when the German middle class was developing a taste for small cigars and cigarillos as an affordable daily habit. He founded his factory in São Félix da Cachoeira — a colonial town directly across the Rio Paraguaçu from the larger market of Cachoeira — and spent his first decade establishing both his tobacco sourcing and his European distribution relationships.', CHAR(13), '
', CHAR(13), '
') AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, CONCAT('Dannemann recognized the commercial potential of Bahian tobacco for the European market at a moment when the German middle class was developing a taste for small cigars and cigarillos as an affordable daily habit. He founded his factory in São Félix da Cachoeira — a colonial town directly across the Rio Paraguaçu from the larger market of Cachoeira — and spent his first decade establishing both his tobacco sourcing and his European distribution relationships.', CHAR(13), '
', CHAR(13), '
'), ''), `history_en`),
  `history_es` = IF(LOCATE(CAST('Dannemann comprendió el potencial comercial de ese tabaco para el mercado europeo, en un momento en que la clase media alemana tomaba gusto a los cigarros pequeños y a los cigarrillos puros como hábito cotidiano asequible. Fundó su manufactura en São Félix da Cachoeira —villa colonial situada en la otra orilla del Río Paraguaçu, frente al mercado más importante de Cachoeira— y dedicó su primera década a establecer a la vez su abastecimiento y sus redes de distribución europeas.

' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Dannemann comprendió el potencial comercial de ese tabaco para el mercado europeo, en un momento en que la clase media alemana tomaba gusto a los cigarros pequeños y a los cigarrillos puros como hábito cotidiano asequible. Fundó su manufactura en São Félix da Cachoeira —villa colonial situada en la otra orilla del Río Paraguaçu, frente al mercado más importante de Cachoeira— y dedicó su primera década a establecer a la vez su abastecimiento y sus redes de distribución europeas.

', ''), `history_es`),
  `history_de` = IF(LOCATE(CAST('Dannemann erkannte das kaufmännische Vermögen dieses Tabaks für den europäischen Markt, zu einer Zeit, als die deutsche Mittelschicht Gefallen an kleinen Zigarren und Zigarillos als erschwinglicher täglicher Gewohnheit fand. Er gründete seine Manufaktur in São Félix da Cachoeira — einem Kolonialstädtchen am anderen Ufer des Rio Paraguaçu, gegenüber dem größeren Markt von Cachoeira — und verwandte sein erstes Jahrzehnt darauf, zugleich seine Beschaffung und seine europäischen Vertriebsnetze aufzubauen.

' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Dannemann erkannte das kaufmännische Vermögen dieses Tabaks für den europäischen Markt, zu einer Zeit, als die deutsche Mittelschicht Gefallen an kleinen Zigarren und Zigarillos als erschwinglicher täglicher Gewohnheit fand. Er gründete seine Manufaktur in São Félix da Cachoeira — einem Kolonialstädtchen am anderen Ufer des Rio Paraguaçu, gegenüber dem größeren Markt von Cachoeira — und verwandte sein erstes Jahrzehnt darauf, zugleich seine Beschaffung und seine europäischen Vertriebsnetze aufzubauen.

', ''), `history_de`),
  `history_zh` = IF(LOCATE(CAST('丹尼曼看出了这种烟草对欧洲市场的商业潜力：那时德国中产阶级正开始把小雪茄与迷你雪茄当作负担得起的日常习惯。他在圣费利克斯-达卡绍埃拉建起工厂——那是帕拉瓜苏河对岸的一座殖民时期小镇，隔水面对更大的市镇卡绍埃拉——并把最初十年用在同时建立货源与欧洲的分销网络上。

' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '丹尼曼看出了这种烟草对欧洲市场的商业潜力：那时德国中产阶级正开始把小雪茄与迷你雪茄当作负担得起的日常习惯。他在圣费利克斯-达卡绍埃拉建起工厂——那是帕拉瓜苏河对岸的一座殖民时期小镇，隔水面对更大的市镇卡绍埃拉——并把最初十年用在同时建立货源与欧洲的分销网络上。

', ''), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('أدرك دانيمان ما لهذا التبغ من إمكان تجاري في السوق الأوروبية، في لحظة كانت فيها الطبقة الوسطى الألمانية تستطيب السيجار الصغير والسيجارلّو عادةً يومية في المتناول. فأسّس مصنعه في ساو فيليكس دا كاشويرا — بلدة استعمارية على الضفة الأخرى من نهر باراغواسو، قبالة سوق كاشويرا الأكبر — وكرّس عقده الأول لبناء تزوّده وشبكات توزيعه الأوروبية معًا.

' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'أدرك دانيمان ما لهذا التبغ من إمكان تجاري في السوق الأوروبية، في لحظة كانت فيها الطبقة الوسطى الألمانية تستطيب السيجار الصغير والسيجارلّو عادةً يومية في المتناول. فأسّس مصنعه في ساو فيليكس دا كاشويرا — بلدة استعمارية على الضفة الأخرى من نهر باراغواسو، قبالة سوق كاشويرا الأكبر — وكرّس عقده الأول لبناء تزوّده وشبكات توزيعه الأوروبية معًا.

', ''), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Dannemann';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('L''entreprise est restée à São Félix pendant cent cinquante ans. L''entrepôt colonial que Dannemann fit convertir en 1873 a été agrandi et modernisé, jamais déplacé. La maison demeura dans la famille pendant quatre générations avant que le groupe suisse Burger Söhne ne rachète Dannemann GmbH, en 1988 — mais le lieu de production, l''approvisionnement auprès des fermes bahianaises voisines et la proposition même du produit n''ont pas bougé. Peu de produits de consommation soignés peuvent en dire autant sur un siècle et demi.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'L''entreprise est restée à São Félix pendant cent cinquante ans. L''entrepôt colonial que Dannemann fit convertir en 1873 a été agrandi et modernisé, jamais déplacé. La maison demeura dans la famille pendant quatre générations avant que le groupe suisse Burger Söhne ne rachète Dannemann GmbH, en 1988 — mais le lieu de production, l''approvisionnement auprès des fermes bahianaises voisines et la proposition même du produit n''ont pas bougé. Peu de produits de consommation soignés peuvent en dire autant sur un siècle et demi.', 'Selon Wikipédia, Dannemann fusionne en 1922 avec la maison Stender pour former la Companhia de Charutos Dannemann ; pendant la guerre, l''affaire brésilienne est expropriée et gérée par le Banco do Brasil ; en 1988, le groupe suisse Burger rachète les droits de marque allemands et reprend Dannemann GmbH, à Lübbecke. En octobre 2026, le groupe DANNEMANN se dit familial et suisse, holding à Rotkreuz, et compte dix sites de production ; la fabrique de São Félix, qu''il nomme Terra Dannemann, est toujours en activité.'), `history`),
  `history_en` = IF(LOCATE(CAST('The operation has remained in São Félix for 150 years. The colonial warehouse that Dannemann converted in 1873 has been expanded and updated but never relocated. The company passed through the Dannemann family for four generations before the Swiss group Burger Söhne bought Dannemann GmbH, in 1988 — but the production location, the tobacco sourcing from surrounding Bahian farms, and the fundamental proposition of the product have remained constant. Dannemann cigarillos are one of the few luxury consumer products whose manufacturing context has genuinely not moved in a century and a half.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The operation has remained in São Félix for 150 years. The colonial warehouse that Dannemann converted in 1873 has been expanded and updated but never relocated. The company passed through the Dannemann family for four generations before the Swiss group Burger Söhne bought Dannemann GmbH, in 1988 — but the production location, the tobacco sourcing from surrounding Bahian farms, and the fundamental proposition of the product have remained constant. Dannemann cigarillos are one of the few luxury consumer products whose manufacturing context has genuinely not moved in a century and a half.', 'According to Wikipedia, Dannemann merged in 1922 with the Stender company to form the Companhia de Charutos Dannemann; during the war, the Brazilian business was expropriated and run by the Banco do Brasil; in 1988, the Swiss Burger group bought the German trademark rights and took over Dannemann GmbH, in Lübbecke. In October 2026, the DANNEMANN group describes itself as family-owned and Swiss, a holding company in Rotkreuz, and counts ten production sites; the São Félix factory, which it calls Terra Dannemann, is still in operation.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La empresa ha permanecido en São Félix ciento cincuenta años. El almacén colonial que Dannemann hizo convertir en 1873 ha sido ampliado y modernizado, nunca desplazado. La casa siguió en la familia durante cuatro generaciones antes de que el grupo suizo Burger Söhne comprara Dannemann GmbH, en 1988 —pero el lugar de producción, el abastecimiento en las fincas bahianas vecinas y la propuesta misma del producto no se han movido. Pocos productos de consumo cuidados pueden decir otro tanto a lo largo de siglo y medio.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La empresa ha permanecido en São Félix ciento cincuenta años. El almacén colonial que Dannemann hizo convertir en 1873 ha sido ampliado y modernizado, nunca desplazado. La casa siguió en la familia durante cuatro generaciones antes de que el grupo suizo Burger Söhne comprara Dannemann GmbH, en 1988 —pero el lugar de producción, el abastecimiento en las fincas bahianas vecinas y la propuesta misma del producto no se han movido. Pocos productos de consumo cuidados pueden decir otro tanto a lo largo de siglo y medio.', 'Según Wikipedia, Dannemann se fusiona en 1922 con la casa Stender para formar la Companhia de Charutos Dannemann; durante la guerra, el negocio brasileño es expropiado y gestionado por el Banco do Brasil; en 1988, el grupo suizo Burger compra los derechos de marca alemanes y asume Dannemann GmbH, en Lübbecke. En octubre de 2026, el grupo DANNEMANN se dice familiar y suizo, con holding en Rotkreuz, y cuenta diez centros de producción; la fábrica de São Félix, que llama Terra Dannemann, sigue en actividad.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Das Unternehmen ist seit hundertfünfzig Jahren in São Félix geblieben. Das koloniale Lagerhaus, das Dannemann 1873 umbauen ließ, wurde erweitert und erneuert, nie verlegt. Das Haus blieb vier Generationen lang in der Familie, ehe die Schweizer Gruppe Burger Söhne 1988 die Dannemann GmbH übernahm — doch der Produktionsort, die Versorgung von den benachbarten bahianischen Farmen und der Vorschlag des Erzeugnisses selbst haben sich nicht bewegt. Wenige sorgfältige Konsumgüter können über anderthalb Jahrhunderte dasselbe von sich sagen.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Das Unternehmen ist seit hundertfünfzig Jahren in São Félix geblieben. Das koloniale Lagerhaus, das Dannemann 1873 umbauen ließ, wurde erweitert und erneuert, nie verlegt. Das Haus blieb vier Generationen lang in der Familie, ehe die Schweizer Gruppe Burger Söhne 1988 die Dannemann GmbH übernahm — doch der Produktionsort, die Versorgung von den benachbarten bahianischen Farmen und der Vorschlag des Erzeugnisses selbst haben sich nicht bewegt. Wenige sorgfältige Konsumgüter können über anderthalb Jahrhunderte dasselbe von sich sagen.', 'Laut Wikipedia fusioniert Dannemann 1922 mit dem Haus Stender zur Companhia de Charutos Dannemann; im Krieg wird das brasilianische Geschäft enteignet und vom Banco do Brasil verwaltet; 1988 kauft die Schweizer Gruppe Burger die deutschen Markenrechte und übernimmt die Dannemann GmbH in Lübbecke. Im Oktober 2026 bezeichnet sich die Gruppe DANNEMANN als Familienunternehmen und schweizerisch, mit Holding in Rotkreuz, und zählt zehn Produktionsstandorte; die Fabrik in São Félix, die sie Terra Dannemann nennt, ist weiterhin in Betrieb.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('这家企业在圣费利克斯待了一百五十年。丹尼曼1873年改建的那座殖民时期仓库，被扩建过、现代化过，却从未搬迁。在瑞士的 Burger Söhne 集团于 1988 年收购德国的 Dannemann GmbH 之前，这个字号在家族手里传了四代——但生产的地点、来自邻近巴伊亚农场的供应，以及产品本身的主张，都没有动过。在一个半世纪的跨度上，能这样说的讲究消费品并不多。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '这家企业在圣费利克斯待了一百五十年。丹尼曼1873年改建的那座殖民时期仓库，被扩建过、现代化过，却从未搬迁。在瑞士的 Burger Söhne 集团于 1988 年收购德国的 Dannemann GmbH 之前，这个字号在家族手里传了四代——但生产的地点、来自邻近巴伊亚农场的供应，以及产品本身的主张，都没有动过。在一个半世纪的跨度上，能这样说的讲究消费品并不多。', '据 Wikipedia 记载，Dannemann 于1922年与 Stender 公司合并，组成 Companhia de Charutos Dannemann；战争期间，巴西的业务被征收，由 Banco do Brasil 管理；1988年，瑞士的 Burger 集团收购德国的商标权，并接手位于 Lübbecke 的 Dannemann GmbH。2026年10月，DANNEMANN 集团自称为家族企业、瑞士集团，控股公司设在 Rotkreuz，拥有十个生产基地；其位于圣费利克斯的工厂被集团称作 Terra Dannemann，仍在运营。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('بقيت الشركة في ساو فيليكس مئة وخمسين عامًا. أما المستودع الاستعماري الذي حوّله دانيمان عام 1873 فقد وُسّع وحُدِّث، ولم يُنقَل قطّ. وظلّت الدار في العائلة أربعة أجيال قبل أن تشتري المجموعة السويسرية «بورغر زونه» شركة دانيمان الألمانية عام 1988 — غير أنّ مكان الإنتاج، والتزوّد من المزارع الباهية المجاورة، وطرح المنتج نفسه، لم تتزحزح. وقليل من منتجات الاستهلاك المتقنة يمكنه قول مثل ذلك على امتداد قرن ونصف.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'بقيت الشركة في ساو فيليكس مئة وخمسين عامًا. أما المستودع الاستعماري الذي حوّله دانيمان عام 1873 فقد وُسّع وحُدِّث، ولم يُنقَل قطّ. وظلّت الدار في العائلة أربعة أجيال قبل أن تشتري المجموعة السويسرية «بورغر زونه» شركة دانيمان الألمانية عام 1988 — غير أنّ مكان الإنتاج، والتزوّد من المزارع الباهية المجاورة، وطرح المنتج نفسه، لم تتزحزح. وقليل من منتجات الاستهلاك المتقنة يمكنه قول مثل ذلك على امتداد قرن ونصف.', 'تذكر Wikipedia أنّ Dannemann اندمجت سنة 1922 مع دار Stender لتشكّل Companhia de Charutos Dannemann؛ وفي أثناء الحرب صودر النشاط البرازيلي وأدارته Banco do Brasil؛ وفي سنة 1988 اشترت المجموعة السويسرية Burger حقوق العلامة الألمانية وتولّت Dannemann GmbH في لوبكه. وفي أكتوبر 2026 تصف مجموعة DANNEMANN نفسها بأنها عائلية وسويسرية، شركتها القابضة في Rotkreuz، وتعدّ عشرة مواقع إنتاج؛ ومصنع ساو فيليكس، الذي تسمّيه Terra Dannemann، لا يزال عاملًا.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Dannemann';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Une précision décide de la place de cette maison dans cet atlas. Le groupe fait aussi des cigarillos — mais pas ici : ceux-là sortent de Lübbecke, en Allemagne, et des ateliers suisses de Brissago et Reinach. São Félix est la fabrique de longfillers, où des charuteiras roulent à la main. L''atlas ne porte que ce qui sort de São Félix.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Une précision décide de la place de cette maison dans cet atlas. Le groupe fait aussi des cigarillos — mais pas ici : ceux-là sortent de Lübbecke, en Allemagne, et des ateliers suisses de Brissago et Reinach. São Félix est la fabrique de longfillers, où des charuteiras roulent à la main. L''atlas ne porte que ce qui sort de São Félix.', 'Ce qui place cette maison au Brésil est le lieu de roulage. La marque Dannemann vendue en Europe, des cigarillos et des cigares short filler, est décrite par la maison comme cultivée au Brésil mais fabriquée en Europe ; Lübbecke produit surtout des cigarillos, Reinach des mélanges et des cigarillos, Brissago des cigares spéciaux. Les marques Moods et Al Capone du même groupe sont d''autres marques ; les Al Capone roulés à la main à Danlí, au Honduras, ne sont pas ceux-ci. Seuls les longfillers roulés à São Félix entrent ici.'), `history`),
  `history_en` = IF(LOCATE(CAST('One detail settles this house''s place in this atlas. The group also makes cigarillos — but not here: those come out of Lübbecke, in Germany, and the Swiss workshops at Brissago and Reinach. São Félix is the long filler factory, where charuteiras roll by hand. This atlas holds only what comes out of São Félix.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'One detail settles this house''s place in this atlas. The group also makes cigarillos — but not here: those come out of Lübbecke, in Germany, and the Swiss workshops at Brissago and Reinach. São Félix is the long filler factory, where charuteiras roll by hand. This atlas holds only what comes out of São Félix.', 'What places this house in Brazil is the place where the cigars are rolled. The Dannemann brand sold in Europe, cigarillos and short filler cigars, is described by the house as grown in Brazil but made in Europe; Lübbecke mainly produces cigarillos, Reinach blends and cigarillos, Brissago special cigars. The Moods and Al Capone brands of the same group are other brands; the Al Capone hand-rolled in Danlí, Honduras, are not these. Only the long fillers hand-rolled at São Félix are included here.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Una precisión decide el lugar de esta casa en este atlas. El grupo hace también cigarritos, pero no aquí: esos salen de Lübbecke, en Alemania, y de los talleres suizos de Brissago y Reinach. São Félix es la fábrica de tripa larga, donde las charuteiras lían a mano. Este atlas solo recoge lo que sale de São Félix.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Una precisión decide el lugar de esta casa en este atlas. El grupo hace también cigarritos, pero no aquí: esos salen de Lübbecke, en Alemania, y de los talleres suizos de Brissago y Reinach. São Félix es la fábrica de tripa larga, donde las charuteiras lían a mano. Este atlas solo recoge lo que sale de São Félix.', 'Lo que sitúa a esta casa en Brasil es el lugar de liado. La marca Dannemann vendida en Europa, cigarritos y puros de tripa corta, la describe la casa como cultivada en Brasil pero fabricada en Europa; Lübbecke produce sobre todo cigarritos, Reinach mezclas y cigarritos, Brissago puros especiales. Las marcas Moods y Al Capone del mismo grupo son otras marcas; los Al Capone liados a mano en Danlí, en Honduras, no son estos. Aquí solo entran los puros de tripa larga liados en São Félix.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Eine Präzisierung entscheidet über den Platz dieses Hauses in diesem Atlas. Die Gruppe stellt auch Zigarillos her — aber nicht hier: Die kommen aus Lübbecke in Deutschland und aus den Schweizer Werkstätten in Brissago und Reinach. São Félix ist die Longfiller-Fabrik, in der Charuteiras von Hand rollen. Dieser Atlas führt nur, was aus São Félix kommt.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Eine Präzisierung entscheidet über den Platz dieses Hauses in diesem Atlas. Die Gruppe stellt auch Zigarillos her — aber nicht hier: Die kommen aus Lübbecke in Deutschland und aus den Schweizer Werkstätten in Brissago und Reinach. São Félix ist die Longfiller-Fabrik, in der Charuteiras von Hand rollen. Dieser Atlas führt nur, was aus São Félix kommt.', 'Was dieses Haus in Brasilien verortet, ist der Ort des Rollens. Die in Europa verkaufte Marke Dannemann, Zigarillos und Zigarren mit kurzer Einlage, beschreibt das Haus als in Brasilien angebaut, aber in Europa hergestellt; Lübbecke produziert vor allem Zigarillos, Reinach Mischungen und Zigarillos, Brissago Spezialzigarren. Die Marken Moods und Al Capone derselben Gruppe sind andere Marken; die in Danlí in Honduras von Hand gerollten Al Capone sind nicht diese. Nur die in São Félix von Hand gerollten Longfiller kommen hier vor.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('有一点决定了这家在本图集中的位置。集团也生产小雪茄——但不在这里：那些出自德国的吕贝克，以及瑞士布里萨戈与赖纳赫的工坊。圣费利克斯是长填料工厂，由被称作 charuteiras 的女卷烟师手工卷制。本图集只收录出自圣费利克斯的产品。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '有一点决定了这家在本图集中的位置。集团也生产小雪茄——但不在这里：那些出自德国的吕贝克，以及瑞士布里萨戈与赖纳赫的工坊。圣费利克斯是长填料工厂，由被称作 charuteiras 的女卷烟师手工卷制。本图集只收录出自圣费利克斯的产品。', '这家公司之所以归在巴西，是因为卷制地点在这里。Dannemann 品牌在欧洲销售的是小雪茄和短填料雪茄，公司称其烟草种在巴西、制造在欧洲；Lübbecke 主要生产小雪茄，Reinach 生产混合烟丝和小雪茄，Brissago 生产特色雪茄。同一集团的 Moods 和 Al Capone 是另外的品牌；在洪都拉斯 Danlí 手工卷制的 Al Capone 不是这些。这里只收录在圣费利克斯手工卷制的长填料雪茄。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('ثمّة تفصيل يحسم مكانة هذه الدار في هذا الأطلس. فالمجموعة تصنع أيضًا سيجارات صغيرة — لكن ليس هنا: تلك تخرج من لوبكه في ألمانيا، ومن الورشتين السويسريتين في بريساغو ورايناخ. أمّا ساو فيليكس فهي مصنع الحشوة الطويلة، حيث تلفّ الـ«تشاروتيراس» باليد. ولا يضمّ هذا الأطلس إلا ما يخرج من ساو فيليكس.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'ثمّة تفصيل يحسم مكانة هذه الدار في هذا الأطلس. فالمجموعة تصنع أيضًا سيجارات صغيرة — لكن ليس هنا: تلك تخرج من لوبكه في ألمانيا، ومن الورشتين السويسريتين في بريساغو ورايناخ. أمّا ساو فيليكس فهي مصنع الحشوة الطويلة، حيث تلفّ الـ«تشاروتيراس» باليد. ولا يضمّ هذا الأطلس إلا ما يخرج من ساو فيليكس.', 'ما يضع هذه الدار في البرازيل هو مكان اللفّ. فعلامة Dannemann المباعة في أوروبا، وهي سيجارات صغيرة (سيجارلّو) وسيجار بحشوة قصيرة، تصفها الدار بأنها مزروعة في البرازيل ومصنوعة في أوروبا؛ وتنتج لوبكه في الغالب السيجارلّو، وتنتج رايناخ خلطات وسيجارلّو، وتنتج بريساغو سيجارًا خاصًا. وعلامتا Moods وAl Capone من المجموعة نفسها علامتان أخريان؛ وسيجار Al Capone المفتول يدويًا في دانلي بهندوراس ليس هذا. ولا يدخل هنا إلا ما لُفّ باليد من سيجار بحشوة طويلة في ساو فيليكس.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Dannemann';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('La presse économique de 2012 comptait vingt personnes au Centro Dannemann de São Félix, à la fois fabrique et centre culturel tourné vers les visiteurs, et notait que le premier revenu du groupe suisse à Bahia venait de Danco, son usine de traitement de feuilles, non des cigares. Un reportage de 2017 date le bâtiment du Centro de 1892 — la maison, elle, de 1873. En 2026, l''Apcab, l''association des producteurs artisanaux, compte quatre fabricants pour l''essentiel du segment ; la fiche ne sait pas si Dannemann en est.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'La presse économique de 2012 comptait vingt personnes au Centro Dannemann de São Félix, à la fois fabrique et centre culturel tourné vers les visiteurs, et notait que le premier revenu du groupe suisse à Bahia venait de Danco, son usine de traitement de feuilles, non des cigares. Un reportage de 2017 date le bâtiment du Centro de 1892 — la maison, elle, de 1873. En 2026, l''Apcab, l''association des producteurs artisanaux, compte quatre fabricants pour l''essentiel du segment ; la fiche ne sait pas si Dannemann en est.', 'Le Centro Cultural Dannemann occupe l''ancien bâtiment colonial de la fabrique, à São Félix. Selon la presse économique de 2012, vingt personnes y travaillaient et le premier revenu du groupe à Bahia venait de Danco, son usine de traitement de feuilles ; un reportage de 2017 date le bâtiment de 1892. Une ligne premium, Elementum, qui porte l''année de récolte, a été présentée au Festival Origem du Recôncavo (Brazil Journal, 4 octobre 2020) ; la page ne dit pas qui la fabrique.'), `history`),
  `history_en` = IF(LOCATE(CAST('The business press of 2012 counted twenty people at the Centro Dannemann in São Félix, both factory and cultural centre turned toward visitors, and noted that the Swiss group''s first income in Bahia came from Danco, its leaf-processing plant, not from cigars. A 2017 report dates the Centro''s building to 1892 — the house itself to 1873. In 2026 Apcab, the artisanal producers'' association, counts four manufacturers for the bulk of the segment; the entry does not know whether Dannemann is one of them.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The business press of 2012 counted twenty people at the Centro Dannemann in São Félix, both factory and cultural centre turned toward visitors, and noted that the Swiss group''s first income in Bahia came from Danco, its leaf-processing plant, not from cigars. A 2017 report dates the Centro''s building to 1892 — the house itself to 1873. In 2026 Apcab, the artisanal producers'' association, counts four manufacturers for the bulk of the segment; the entry does not know whether Dannemann is one of them.', 'The Centro Cultural Dannemann occupies the former colonial building of the factory, in São Félix. According to the business press of 2012, twenty people worked there and the group''s first income in Bahia came from Danco, its leaf-processing plant; a 2017 report dates the building to 1892. A premium line, Elementum, which carries the harvest year, was presented at the Festival Origem of the Recôncavo (Brazil Journal, 4 October 2020); the page does not say who makes it.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La prensa económica de 2012 contaba veinte personas en el Centro Dannemann de São Félix, a la vez fábrica y centro cultural vuelto hacia los visitantes, y anotaba que el primer ingreso del grupo suizo en Bahía venía de Danco, su planta de procesado de hojas, no de los puros. Un reportaje de 2017 fecha el edificio del Centro en 1892 — la casa, en 1873. En 2026 la Apcab, la asociación de productores artesanales, cuenta cuatro fabricantes para lo esencial del segmento; la ficha no sabe si Dannemann es uno de ellos.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La prensa económica de 2012 contaba veinte personas en el Centro Dannemann de São Félix, a la vez fábrica y centro cultural vuelto hacia los visitantes, y anotaba que el primer ingreso del grupo suizo en Bahía venía de Danco, su planta de procesado de hojas, no de los puros. Un reportaje de 2017 fecha el edificio del Centro en 1892 — la casa, en 1873. En 2026 la Apcab, la asociación de productores artesanales, cuenta cuatro fabricantes para lo esencial del segmento; la ficha no sabe si Dannemann es uno de ellos.', 'El Centro Cultural Dannemann ocupa el antiguo edificio colonial de la fábrica, en São Félix. Según la prensa económica de 2012, trabajaban allí veinte personas y el primer ingreso del grupo en Bahía venía de Danco, su planta de procesado de hojas; un reportaje de 2017 fecha el edificio en 1892. Una línea premium, Elementum, que lleva el año de cosecha, se presentó en el Festival Origem del Recôncavo (Brazil Journal, 4 de octubre de 2020); la página no dice quién la fabrica.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die Wirtschaftspresse von 2012 zählte zwanzig Menschen im Centro Dannemann in São Félix, zugleich Fabrik und den Besuchern zugewandtes Kulturzentrum, und vermerkte, dass die ersten Einnahmen der Schweizer Gruppe in Bahia von Danco kamen, ihrem Blattverarbeitungswerk, nicht von Zigarren. Eine Reportage von 2017 datiert das Gebäude des Centro auf 1892 — das Haus selbst auf 1873. 2026 zählt die Apcab, der Verband der handwerklichen Hersteller, vier Fabrikanten für den Großteil des Segments; der Eintrag weiß nicht, ob Dannemann dazugehört.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die Wirtschaftspresse von 2012 zählte zwanzig Menschen im Centro Dannemann in São Félix, zugleich Fabrik und den Besuchern zugewandtes Kulturzentrum, und vermerkte, dass die ersten Einnahmen der Schweizer Gruppe in Bahia von Danco kamen, ihrem Blattverarbeitungswerk, nicht von Zigarren. Eine Reportage von 2017 datiert das Gebäude des Centro auf 1892 — das Haus selbst auf 1873. 2026 zählt die Apcab, der Verband der handwerklichen Hersteller, vier Fabrikanten für den Großteil des Segments; der Eintrag weiß nicht, ob Dannemann dazugehört.', 'Das Centro Cultural Dannemann belegt das ehemalige Kolonialgebäude der Fabrik in São Félix. Laut der Wirtschaftspresse von 2012 arbeiteten dort zwanzig Menschen, und die ersten Einnahmen der Gruppe in Bahia kamen von Danco, ihrem Blattverarbeitungswerk; eine Reportage von 2017 datiert das Gebäude auf 1892. Eine Premium-Linie, Elementum, die das Erntejahr trägt, wurde auf dem Festival Origem des Recôncavo vorgestellt (Brazil Journal, 4. Oktober 2020); die Seite sagt nicht, wer sie herstellt.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('2012年的经济媒体数到圣费利克斯的 Centro Dannemann 有二十人，既是工厂也是面向访客的文化中心，并指出瑞士集团在巴伊亚的第一大收入来自其烟叶加工厂 Danco，而非雪茄。2017年一篇报道把 Centro 的建筑定在1892年——公司本身则是1873年。2026年，手工生产者协会 Apcab 认定四家制造商占该领域主要份额；词条不知道 Dannemann 是否在其中。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '2012年的经济媒体数到圣费利克斯的 Centro Dannemann 有二十人，既是工厂也是面向访客的文化中心，并指出瑞士集团在巴伊亚的第一大收入来自其烟叶加工厂 Danco，而非雪茄。2017年一篇报道把 Centro 的建筑定在1892年——公司本身则是1873年。2026年，手工生产者协会 Apcab 认定四家制造商占该领域主要份额；词条不知道 Dannemann 是否在其中。', 'Centro Cultural Dannemann 占用工厂在圣费利克斯的旧殖民时期建筑。据2012年的经济媒体报道，那里有二十人工作，集团在巴伊亚的头一笔收入来自其烟叶加工厂 Danco；2017年的一篇报道把该建筑的年代定在1892年。一条标有收获年份的高端系列 Elementum，曾在雷孔卡沃的 Festival Origem 上亮相（Brazil Journal，2020年10月4日）；该页面没有说明由谁制造。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('عدّت الصحافة الاقتصادية سنة 2012 عشرين شخصًا في Centro Dannemann في ساو فيليكس، وهو مصنع ومركز ثقافي موجّه للزوّار في آن، ولاحظت أنّ الدخل الأوّل للمجموعة السويسرية في باهيا يأتي من Danco، معملها لمعالجة الأوراق، لا من السيجار. ويؤرّخ تحقيق سنة 2017 مبنى المركز بسنة 1892 — أمّا الدار فبسنة 1873. وسنة 2026 تعدّ Apcab، جمعية المنتجين الحرفيين، أربعة صانعين لمعظم القطاع؛ ولا تعرف البطاقة إن كانت Dannemann منهم.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'عدّت الصحافة الاقتصادية سنة 2012 عشرين شخصًا في Centro Dannemann في ساو فيليكس، وهو مصنع ومركز ثقافي موجّه للزوّار في آن، ولاحظت أنّ الدخل الأوّل للمجموعة السويسرية في باهيا يأتي من Danco، معملها لمعالجة الأوراق، لا من السيجار. ويؤرّخ تحقيق سنة 2017 مبنى المركز بسنة 1892 — أمّا الدار فبسنة 1873. وسنة 2026 تعدّ Apcab، جمعية المنتجين الحرفيين، أربعة صانعين لمعظم القطاع؛ ولا تعرف البطاقة إن كانت Dannemann منهم.', 'يشغل Centro Cultural Dannemann المبنى الاستعماري القديم للمصنع في ساو فيليكس. وبحسب الصحافة الاقتصادية سنة 2012 كان يعمل فيه عشرون شخصًا، وكان الدخل الأوّل للمجموعة في باهيا يأتي من Danco، معملها لمعالجة الأوراق؛ ويؤرّخ تحقيق سنة 2017 المبنى بسنة 1892. وقُدِّم خط فاخر هو Elementum، يحمل سنة الحصاد، في Festival Origem في ريكونكافو (Brazil Journal، 4 أكتوبر 2020)؛ ولا تذكر الصفحة من يصنعه.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Dannemann';

UPDATE `brands` SET
  `country_id` = 'brazil',
  `limited_eds` = '[]',
  `founded` = '1872 (maison) ou 1873 (Wikipédia) — São Félix',
  `factory` = 'Terra Dannemann, São Félix da Cachoeira, Bahia, Brésil — première fabrique de longfillers du groupe, en activité en octobre 2026',
  `gamme` = '[{"name":"Dannemann Premium","color":"#8B5A2B","force":null,"story":"Longfillers roulés à la main par les rouleurs de la fabrique de São Félix (Terra Dannemann, Bahia), selon la maison. Le nom de cette ligne, ses formats et ses notes ne figurent sur aucune page lue ; ils sont retirés.","vitolas":["Robusto","Toro"],"wrapper":"Bahia (Fazenda San Antônio)"}]',
  `gamme_en` = '[{"name":"Dannemann Premium","color":"#8B5A2B","force":null,"story":"Long fillers hand-rolled by the rollers of the São Félix factory (Terra Dannemann, Bahia), according to the house. The name of this line, its formats and its notes appear on no page read; they have been removed.","vitolas":["Robusto","Toro"],"wrapper":"Bahia (Fazenda San Antônio)"}]',
  `gamme_es` = '[{"name":"Dannemann Premium","color":"#8B5A2B","force":null,"story":"Puros de tripa larga liados a mano por los torcedores de la fábrica de São Félix (Terra Dannemann, Bahía), según la casa. El nombre de esta línea, sus formatos y sus notas no figuran en ninguna página leída; se retiran.","vitolas":["Robusto","Toro"],"wrapper":"Bahía (Fazenda San Antônio)"}]',
  `gamme_de` = '[{"name":"Dannemann Premium","color":"#8B5A2B","force":null,"story":"Longfiller, von den Zigarrenrollern der Fabrik in São Félix (Terra Dannemann, Bahia) von Hand gerollt, laut dem Haus. Der Name dieser Linie, ihre Formate und ihre Noten stehen auf keiner gelesenen Seite; sie werden gestrichen.","vitolas":["Robusto","Toro"],"wrapper":"Bahia (Fazenda San Antônio)"}]',
  `gamme_zh` = '[{"name":"Dannemann Premium","color":"#8B5A2B","force":null,"story":"由圣费利克斯工厂（Terra Dannemann，巴伊亚）的卷烟师手工卷制的长填料雪茄，此为公司之说。这条系列的名称、规格和风味，在所读的任何页面上都没有出现，故予撤去。","vitolas":["Robusto","Toro"],"wrapper":"巴伊亚（Fazenda San Antônio）"}]',
  `gamme_ar` = '[{"name":"Dannemann Premium","color":"#8B5A2B","force":null,"story":"سيجار بحشوة طويلة يلفّه باليد لفّافو مصنع ساو فيليكس (Terra Dannemann، باهيا)، بحسب الدار. واسم هذا الخط وقياساته ونكهاته لا يرد في أي صفحة قُرئت؛ ولذلك سُحبت.","vitolas":["Robusto","Toro"],"wrapper":"باهيا (Fazenda San Antônio)"}]',
  `celebrities` = '[{"name":"Gerhard Dannemann","anecdote":"Immigrant allemand, fondateur de la maison à São Félix da Cachoeira (1872 selon la maison, 1873 selon Wikipédia). Selon Wikipédia, l''ancienne mairie de São Félix, le Paço Municipal, fut achetée par Geraldo Dannemann puis adaptée à l''usage municipal."}]',
  `celebrities_en` = '[{"name":"Gerhard Dannemann","anecdote":"German immigrant, founder of the house at São Félix da Cachoeira (1872 according to the house, 1873 according to Wikipedia). According to Wikipedia, the former town hall of São Félix, the Paço Municipal, was bought by Geraldo Dannemann and then adapted for municipal use."}]',
  `celebrities_es` = '[{"name":"Gerhard Dannemann","anecdote":"Inmigrante alemán, fundador de la casa en São Félix da Cachoeira (1872 según la casa, 1873 según Wikipedia). Según Wikipedia, el antiguo ayuntamiento de São Félix, el Paço Municipal, fue comprado por Geraldo Dannemann y luego adaptado para uso municipal."}]',
  `celebrities_de` = '[{"name":"Gerhard Dannemann","anecdote":"Deutscher Einwanderer, Gründer des Hauses in São Félix da Cachoeira (1872 laut dem Haus, 1873 laut Wikipedia). Laut Wikipedia wurde das alte Rathaus von São Félix, das Paço Municipal, von Geraldo Dannemann gekauft und dann für den städtischen Gebrauch hergerichtet."}]',
  `celebrities_zh` = '[{"name":"Gerhard Dannemann","anecdote":"德国移民，公司在圣费利克斯-达卡绍埃拉的创办人（公司称1872年，Wikipedia 称1873年）。据 Wikipedia 记载，圣费利克斯的旧市政厅 Paço Municipal 由 Geraldo Dannemann 买下，后改作市政之用。"}]',
  `celebrities_ar` = '[{"name":"Gerhard Dannemann","anecdote":"مهاجر ألماني، مؤسس الدار في ساو فيليكس دا كاشويرا (سنة 1872 بحسب الدار، وسنة 1873 بحسب Wikipedia). وتذكر Wikipedia أنّ بلدية ساو فيليكس القديمة، Paço Municipal، اشتراها جيرالدو دانيمان ثم هُيّئت للاستعمال البلدي."}]',
  `pairings` = '[{"type":"Caipirinha","name":"Caipirinha classique","notes":"Accord de goût, sans page : la canne à sucre de la caipirinha pour un tabac de Bahia."},{"type":"Café","name":"Café brasileiro coado","notes":"Accord de goût : un café filtre brésilien, léger."}]',
  `pairings_en` = '[{"type":"Caipirinha","name":"Classic Caipirinha","notes":"A pairing by taste, no page: the sugarcane of the caipirinha for a Bahia tobacco."},{"type":"Coffee","name":"Brazilian coado coffee","notes":"A pairing by taste: a Brazilian filter coffee, light."}]',
  `pairings_es` = '[{"type":"Caipirinha","name":"Caipirinha clásica","notes":"Maridaje de gusto, sin página: la caña de azúcar de la caipirinha para un tabaco de Bahía."},{"type":"Café","name":"Café brasileiro coado","notes":"Maridaje de gusto: un café de filtro brasileño, ligero."}]',
  `pairings_de` = '[{"type":"Caipirinha","name":"Klassische Caipirinha","notes":"Paarung nach Geschmack, ohne Seite: das Zuckerrohr der Caipirinha zu einem Tabak aus Bahia."},{"type":"Kaffee","name":"Café brasileiro coado","notes":"Paarung nach Geschmack: ein brasilianischer Filterkaffee, leicht."}]',
  `pairings_zh` = '[{"type":"Caipirinha","name":"经典 Caipirinha","notes":"凭口味的搭配，没有页面依据：Caipirinha 的甘蔗味配巴伊亚的烟叶。"},{"type":"咖啡","name":"巴西滤泡咖啡（coado）","notes":"凭口味的搭配：一杯巴西滤泡咖啡，清淡。"}]',
  `pairings_ar` = '[{"type":"Caipirinha","name":"Caipirinha كلاسيكية","notes":"مرافقة بالذوق، دون صفحة: قصب السكر في الكايبيرينيا لتبغ من باهيا."},{"type":"القهوة","name":"قهوة برازيلية مُرشَّحة (coado)","notes":"مرافقة بالذوق: قهوة ترشيح برازيلية، خفيفة."}]',
  `source` = IF(LOCATE(CAST('dannemann-group.com « Our Company » (les trois sites de production et leurs rôles)' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, 'dannemann-group.com « Our Company » (les trois sites de production et leurs rôles)', 'dannemann-group.com « Our Company » (octobre 2026 : dix sites ; São Félix, première fabrique de longfillers, fabrique établie en 1872 selon la maison ; Fazenda San Antônio ; groupe familial suisse) ; dannemann-group.com « Our Brands » (la marque Dannemann : cigarillos et short filler, cultivés au Brésil, fabriqués en Europe) ; dannemann-group.com « Our Tobacco » (Mata Fina, 200 fermes partenaires)'), `source`),
  `source` = IF(LOCATE(CAST('; www.fortenoreconcavo.com.br (23 juillet 2026 : quatre fabricants pour 85 % du segment artisanal, selon l''Apcab)' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, '; www.fortenoreconcavo.com.br (23 juillet 2026 : quatre fabricants pour 85 % du segment artisanal, selon l''Apcab)', '; braziljournal.com « Viva el patron : a volta por cima dos charutos baianos » (4 octobre 2020 : ligne Elementum, Festival Origem)'), `source`),
  `updated_at` = NOW()
 WHERE `name` = 'Dannemann';

-- ── Te Amo ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Te-Amo est le cigare mexicain que l''Amérique a fumé avant de savoir qu''il était mexicain. Dans les années 1970, il était partout — un cigare d''ouvrier, vendu quatre-vingts cents, qui a donné son nom au format toro et fait vivre cent soixante-dix points de vente autour de New York, d''où venaient six ventes sur dix.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Te-Amo est le cigare mexicain que l''Amérique a fumé avant de savoir qu''il était mexicain. Dans les années 1970, il était partout — un cigare d''ouvrier, vendu quatre-vingts cents, qui a donné son nom au format toro et fait vivre cent soixante-dix points de vente autour de New York, d''où venaient six ventes sur dix.', 'Te-Amo est le cigare mexicain que l''Amérique a fumé avant de savoir qu''il était mexicain. Dans les années 1970, il était partout — un cigare d''ouvrier qui, selon Alberto Turrent (2009), se vendait quatre-vingts cents, comptait cent soixante-dix points de vente autour de New York et y réalisait environ soixante pour cent des ventes de la marque dans les années 1970.'), `history`),
  `history_en` = IF(LOCATE(CAST('Te-Amo is the Mexican cigar that America smoked before it knew it was Mexican. In the 1970s it was everywhere — a working man''s cigar, sold for eighty cents, which gave its name to the toro size and kept a hundred and seventy shops around New York alive, where six sales in ten came from.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'Te-Amo is the Mexican cigar that America smoked before it knew it was Mexican. In the 1970s it was everywhere — a working man''s cigar, sold for eighty cents, which gave its name to the toro size and kept a hundred and seventy shops around New York alive, where six sales in ten came from.', 'Te-Amo is the Mexican cigar that America smoked before it knew it was Mexican. In the 1970s it was everywhere — a working man''s cigar which, according to Alberto Turrent (2009), sold for eighty cents, had a hundred and seventy points of sale around New York and made about sixty per cent of the brand''s sales there in the 1970s.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Te-Amo es el puro mexicano que Estados Unidos fumó antes de saber que era mexicano. En los años setenta estaba en todas partes — un puro de obrero, vendido a ochenta centavos, que dio su nombre al formato toro y mantuvo ciento setenta puntos de venta alrededor de Nueva York, de donde salían seis ventas de cada diez.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Te-Amo es el puro mexicano que Estados Unidos fumó antes de saber que era mexicano. En los años setenta estaba en todas partes — un puro de obrero, vendido a ochenta centavos, que dio su nombre al formato toro y mantuvo ciento setenta puntos de venta alrededor de Nueva York, de donde salían seis ventas de cada diez.', 'Te-Amo es el puro mexicano que Estados Unidos fumó antes de saber que era mexicano. En los años setenta estaba en todas partes — un puro de obrero que, según Alberto Turrent (2009), se vendía a ochenta centavos, contaba con ciento setenta puntos de venta alrededor de Nueva York y allí realizaba cerca del sesenta por ciento de las ventas de la marca en los años setenta.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Te-Amo ist die mexikanische Zigarre, die Amerika rauchte, bevor es wusste, dass sie mexikanisch ist. In den 1970er-Jahren war sie überall — eine Arbeiterzigarre, für achtzig Cent verkauft, die dem Format Toro seinen Namen gab und hundertsiebzig Verkaufsstellen rund um New York am Leben hielt, woher sechs von zehn Verkäufen kamen.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Te-Amo ist die mexikanische Zigarre, die Amerika rauchte, bevor es wusste, dass sie mexikanisch ist. In den 1970er-Jahren war sie überall — eine Arbeiterzigarre, für achtzig Cent verkauft, die dem Format Toro seinen Namen gab und hundertsiebzig Verkaufsstellen rund um New York am Leben hielt, woher sechs von zehn Verkäufen kamen.', 'Te-Amo ist die mexikanische Zigarre, die Amerika rauchte, bevor es wusste, dass sie mexikanisch ist. In den 1970er-Jahren war sie überall — eine Arbeiterzigarre, die laut Alberto Turrent (2009) für achtzig Cent verkauft wurde, hundertsiebzig Verkaufsstellen rund um New York hatte und dort in den 1970er-Jahren rund sechzig Prozent der Verkäufe der Marke erzielte.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('Te-Amo 是美国在知道它来自墨西哥之前就已抽起的墨西哥雪茄。1970年代它无处不在——工人的雪茄，售价八十美分，「toro」这一尺寸因它得名，纽约周边一百七十家销售点靠它维持，六成销量出自那里。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, 'Te-Amo 是美国在知道它来自墨西哥之前就已抽起的墨西哥雪茄。1970年代它无处不在——工人的雪茄，售价八十美分，「toro」这一尺寸因它得名，纽约周边一百七十家销售点靠它维持，六成销量出自那里。', 'Te-Amo 是美国在知道它来自墨西哥之前就已抽起的墨西哥雪茄。1970年代它无处不在——工人的雪茄，据阿尔贝托·图伦特（2009）所述，售价八十美分，在纽约周边有一百七十家销售点，并在1970年代于当地实现了该品牌约百分之六十的销量。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('تي-آمو هو السيجار المكسيكي الذي دخّنته أمريكا قبل أن تعرف أنّه مكسيكي. في السبعينيات كان في كلّ مكان — سيجار عامل، يُباع بثمانين سنتًا، أعطى اسمه لقياس «تورو» وأبقى مئة وسبعين نقطة بيع حول نيويورك على قيد الحياة، ومنها كانت تأتي ستّ مبيعات من كلّ عشر.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'تي-آمو هو السيجار المكسيكي الذي دخّنته أمريكا قبل أن تعرف أنّه مكسيكي. في السبعينيات كان في كلّ مكان — سيجار عامل، يُباع بثمانين سنتًا، أعطى اسمه لقياس «تورو» وأبقى مئة وسبعين نقطة بيع حول نيويورك على قيد الحياة، ومنها كانت تأتي ستّ مبيعات من كلّ عشر.', 'تي-آمو هو السيجار المكسيكي الذي دخّنته أمريكا قبل أن تعرف أنّه مكسيكي. في السبعينيات كان في كلّ مكان — سيجار عامل، كان يُباع، بحسب ألبرتو تورينت (2009)، بثمانين سنتًا، وله مئة وسبعون نقطة بيع حول نيويورك، وكان يحقّق هناك نحو ستين في المئة من مبيعات العلامة في السبعينيات.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Te Amo';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('La famille qui le fait est dans le tabac de San Andrés depuis 1880. Alberto Turrent y entre en 1960, à vingt-deux ans, comme chauffeur de camion. La marque naît en 1966 — halfwheel dit 1963, l''atlas retient la date qu''Alberto Turrent a donnée lui-même — et commence par un échec : deux millions de cigares emballés et invendus, un essai à Miami qui ne prend pas, puis New York. En 1972, à la mort de l''associé new-yorkais, la famille rachète la société Te-Amo.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'La famille qui le fait est dans le tabac de San Andrés depuis 1880. Alberto Turrent y entre en 1960, à vingt-deux ans, comme chauffeur de camion. La marque naît en 1966 — halfwheel dit 1963, l''atlas retient la date qu''Alberto Turrent a donnée lui-même — et commence par un échec : deux millions de cigares emballés et invendus, un essai à Miami qui ne prend pas, puis New York. En 1972, à la mort de l''associé new-yorkais, la famille rachète la société Te-Amo.', 'La famille qui le fait est dans le tabac de San Andrés depuis 1880. Alberto Turrent y entre en 1960, à vingt-deux ans, comme chauffeur de camion. La marque naît en 1966 selon Alberto Turrent ; d''autres sources donnent 1963 ou 1964, et la date n''est pas tranchée. Elle commence par un échec : deux millions de cigares emballés et invendus, un essai à Miami qui ne prend pas, puis New York. En 1972, à la mort de l''associé new-yorkais, la famille rachète la société Te-Amo.'), `history`),
  `history_en` = IF(LOCATE(CAST('The family that makes it has been in San Andrés tobacco since 1880. Alberto Turrent entered in 1960, at twenty-two, as a truck driver. The brand was born in 1966 — halfwheel says 1963; this atlas keeps the date Alberto Turrent gave himself — and began with a failure: two million cigars packed and unsold, a try in Miami that did not take, then New York. In 1972, when the New York partner died, the family bought the Te-Amo company.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The family that makes it has been in San Andrés tobacco since 1880. Alberto Turrent entered in 1960, at twenty-two, as a truck driver. The brand was born in 1966 — halfwheel says 1963; this atlas keeps the date Alberto Turrent gave himself — and began with a failure: two million cigars packed and unsold, a try in Miami that did not take, then New York. In 1972, when the New York partner died, the family bought the Te-Amo company.', 'The family that makes it has been in San Andrés tobacco since 1880. Alberto Turrent entered in 1960, at twenty-two, as a truck driver. The brand was born in 1966 according to Alberto Turrent; other sources give 1963 or 1964, and the date is not settled. It began with a failure: two million cigars packed and unsold, a try in Miami that did not take, then New York. In 1972, when the New York partner died, the family bought the Te-Amo company.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La familia que lo hace está en el tabaco de San Andrés desde 1880. Alberto Turrent entra en 1960, a los veintidós años, como chofer de camión. La marca nace en 1966 — halfwheel dice 1963; este atlas retiene la fecha que el propio Alberto Turrent dio — y empieza con un fracaso: dos millones de puros empacados y sin vender, un intento en Miami que no cuaja, luego Nueva York. En 1972, a la muerte del socio neoyorquino, la familia compra la sociedad Te-Amo.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La familia que lo hace está en el tabaco de San Andrés desde 1880. Alberto Turrent entra en 1960, a los veintidós años, como chofer de camión. La marca nace en 1966 — halfwheel dice 1963; este atlas retiene la fecha que el propio Alberto Turrent dio — y empieza con un fracaso: dos millones de puros empacados y sin vender, un intento en Miami que no cuaja, luego Nueva York. En 1972, a la muerte del socio neoyorquino, la familia compra la sociedad Te-Amo.', 'La familia que lo hace está en el tabaco de San Andrés desde 1880. Alberto Turrent entra en 1960, a los veintidós años, como chofer de camión. La marca nace en 1966 según Alberto Turrent; otras fuentes dan 1963 o 1964, y la fecha no está zanjada. Empieza con un fracaso: dos millones de puros empacados y sin vender, un intento en Miami que no cuaja, luego Nueva York. En 1972, a la muerte del socio neoyorquino, la familia compra la sociedad Te-Amo.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die Familie, die sie macht, ist seit 1880 im Tabak von San Andrés. Alberto Turrent stieg 1960 ein, mit zweiundzwanzig, als Lastwagenfahrer. Die Marke entstand 1966 — halfwheel sagt 1963; dieser Atlas behält das Datum, das Alberto Turrent selbst nannte — und begann mit einem Fehlschlag: zwei Millionen Zigarren verpackt und unverkauft, ein Versuch in Miami, der nicht zündete, dann New York. 1972, beim Tod des New Yorker Partners, kaufte die Familie die Firma Te-Amo.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die Familie, die sie macht, ist seit 1880 im Tabak von San Andrés. Alberto Turrent stieg 1960 ein, mit zweiundzwanzig, als Lastwagenfahrer. Die Marke entstand 1966 — halfwheel sagt 1963; dieser Atlas behält das Datum, das Alberto Turrent selbst nannte — und begann mit einem Fehlschlag: zwei Millionen Zigarren verpackt und unverkauft, ein Versuch in Miami, der nicht zündete, dann New York. 1972, beim Tod des New Yorker Partners, kaufte die Familie die Firma Te-Amo.', 'Die Familie, die sie macht, ist seit 1880 im Tabak von San Andrés. Alberto Turrent stieg 1960 ein, mit zweiundzwanzig, als Lastwagenfahrer. Die Marke entstand 1966 laut Alberto Turrent; andere Quellen nennen 1963 oder 1964, und das Datum ist nicht geklärt. Sie begann mit einem Fehlschlag: zwei Millionen Zigarren verpackt und unverkauft, ein Versuch in Miami, der nicht zündete, dann New York. 1972, beim Tod des New Yorker Partners, kaufte die Familie die Firma Te-Amo.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('制作它的家族自1880年起就在圣安德烈斯种烟。阿尔贝托·图伦特1960年二十二岁入行，从卡车司机做起。品牌诞生于1966年——halfwheel 说1963年；本图集采用阿尔贝托·图伦特本人给出的日期——起步即失败：两百万支雪茄装好却卖不出去，迈阿密试水不成，转往纽约。1972年纽约合伙人去世，家族买下 Te-Amo 公司。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '制作它的家族自1880年起就在圣安德烈斯种烟。阿尔贝托·图伦特1960年二十二岁入行，从卡车司机做起。品牌诞生于1966年——halfwheel 说1963年；本图集采用阿尔贝托·图伦特本人给出的日期——起步即失败：两百万支雪茄装好却卖不出去，迈阿密试水不成，转往纽约。1972年纽约合伙人去世，家族买下 Te-Amo 公司。', '制作它的家族自1880年起就在圣安德烈斯种烟。阿尔贝托·图伦特1960年二十二岁入行，从卡车司机做起。品牌诞生于1966年，据阿尔贝托·图伦特所述；其他来源给出1963年或1964年，日期尚无定论。起步即失败：两百万支雪茄装好却卖不出去，迈阿密试水不成，转往纽约。1972年纽约合伙人去世，家族买下 Te-Amo 公司。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('العائلة التي تصنعه في تبغ سان أندريس منذ 1880. دخل ألبرتو تورينت العمل سنة 1960، في الثانية والعشرين، سائقَ شاحنة. وُلدت العلامة سنة 1966 — تقول halfwheel 1963؛ ويحتفظ هذا الأطلس بالتاريخ الذي أعطاه ألبرتو تورينت بنفسه — وبدأت بإخفاق: مليونا سيجار مُعبّأة لم تُبَع، ومحاولة في ميامي لم تنجح، ثم نيويورك. وفي 1972، عند وفاة الشريك النيويوركي، اشترت العائلة شركة تي-آمو.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'العائلة التي تصنعه في تبغ سان أندريس منذ 1880. دخل ألبرتو تورينت العمل سنة 1960، في الثانية والعشرين، سائقَ شاحنة. وُلدت العلامة سنة 1966 — تقول halfwheel 1963؛ ويحتفظ هذا الأطلس بالتاريخ الذي أعطاه ألبرتو تورينت بنفسه — وبدأت بإخفاق: مليونا سيجار مُعبّأة لم تُبَع، ومحاولة في ميامي لم تنجح، ثم نيويورك. وفي 1972، عند وفاة الشريك النيويوركي، اشترت العائلة شركة تي-آمو.', 'العائلة التي تصنعه في تبغ سان أندريس منذ 1880. دخل ألبرتو تورينت العمل سنة 1960، في الثانية والعشرين، سائقَ شاحنة. وُلدت العلامة سنة 1966 بحسب ألبرتو تورينت؛ وتذكر مصادر أخرى 1963 أو 1964، والتاريخ لم يُحسم. وبدأت بإخفاق: مليونا سيجار مُعبّأة لم تُبَع، ومحاولة في ميامي لم تنجح، ثم نيويورك. وفي 1972، عند وفاة الشريك النيويوركي، اشترت العائلة شركة تي-آمو.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Te Amo';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Depuis 2000 et la fusion de Consolidated Cigar dans Altadis, la marque appartient au groupe. Elle est toujours faite par les Turrent, dans leur fabrique de San Andrés Tuxtla, Nueva Matacapan de Tabacos, sur deux mille acres de terre volcanique où poussent le San Andrés Negro, de semence Criollo, et le Sumatra. C''est le premier producteur de tabac à cigares du Mexique, et l''atlas porte déjà la fiche de la famille sous le nom de Casa Turrent. Une marque de groupe faite dans l''usine d''une famille qui a sa propre fiche : même cas que Bolívar Honduras chez Scandinavian Tobacco.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Depuis 2000 et la fusion de Consolidated Cigar dans Altadis, la marque appartient au groupe. Elle est toujours faite par les Turrent, dans leur fabrique de San Andrés Tuxtla, Nueva Matacapan de Tabacos, sur deux mille acres de terre volcanique où poussent le San Andrés Negro, de semence Criollo, et le Sumatra. C''est le premier producteur de tabac à cigares du Mexique, et l''atlas porte déjà la fiche de la famille sous le nom de Casa Turrent. Une marque de groupe faite dans l''usine d''une famille qui a sa propre fiche : même cas que Bolívar Honduras chez Scandinavian Tobacco.', 'En février 2024, la presse du métier écrit qu''Altadis U.S.A. possède la marque aux États-Unis et que les Turrent la possèdent dans le reste du monde. Les cigares sont toujours faits au Mexique par les Turrent ; Alberto Turrent (2009) donne Nueva Matacapan de Tabacos, à San Andrés Tuxtla, comme leur fabrique, et la décrit comme un producteur de tabac à cigares du pays. L''atlas porte la fiche de la famille sous le nom de Casa Turrent ; Te-Amo (Mexique) n''est ni un homonyme New World ni une marque dominicaine.'), `history`),
  `history_en` = IF(LOCATE(CAST('Since 2000 and the merger of Consolidated Cigar into Altadis, the brand belongs to the group. It is still made by the Turrents, in their San Andrés Tuxtla factory, Nueva Matacapan de Tabacos, on two thousand acres of volcanic land growing San Andrés Negro, of Criollo seed, and Sumatra. It is Mexico''s largest cigar-tobacco producer, and this atlas already carries the family''s entry under the name Casa Turrent. A group brand made in the factory of a family that has its own entry: the same case as Bolívar Honduras at Scandinavian Tobacco.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'Since 2000 and the merger of Consolidated Cigar into Altadis, the brand belongs to the group. It is still made by the Turrents, in their San Andrés Tuxtla factory, Nueva Matacapan de Tabacos, on two thousand acres of volcanic land growing San Andrés Negro, of Criollo seed, and Sumatra. It is Mexico''s largest cigar-tobacco producer, and this atlas already carries the family''s entry under the name Casa Turrent. A group brand made in the factory of a family that has its own entry: the same case as Bolívar Honduras at Scandinavian Tobacco.', 'In February 2024, the trade press writes that Altadis U.S.A. owns the brand in the United States and that the Turrents own it in the rest of the world. The cigars are still made in Mexico by the Turrents; Alberto Turrent (2009) gives Nueva Matacapan de Tabacos, in San Andrés Tuxtla, as their factory, and describes it as a cigar-tobacco producer in the country. The atlas carries the family''s entry under the name Casa Turrent; Te-Amo (Mexico) is neither a New World namesake nor a Dominican brand.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Desde 2000 y la fusión de Consolidated Cigar en Altadis, la marca pertenece al grupo. La siguen haciendo los Turrent, en su fábrica de San Andrés Tuxtla, Nueva Matacapan de Tabacos, sobre dos mil acres de tierra volcánica donde crecen el San Andrés Negro, de semilla Criollo, y el Sumatra. Es el mayor productor de tabaco para puros de México, y este atlas ya lleva la ficha de la familia bajo el nombre de Casa Turrent. Una marca de grupo hecha en la fábrica de una familia que tiene su propia ficha: el mismo caso que Bolívar Honduras en Scandinavian Tobacco.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Desde 2000 y la fusión de Consolidated Cigar en Altadis, la marca pertenece al grupo. La siguen haciendo los Turrent, en su fábrica de San Andrés Tuxtla, Nueva Matacapan de Tabacos, sobre dos mil acres de tierra volcánica donde crecen el San Andrés Negro, de semilla Criollo, y el Sumatra. Es el mayor productor de tabaco para puros de México, y este atlas ya lleva la ficha de la familia bajo el nombre de Casa Turrent. Una marca de grupo hecha en la fábrica de una familia que tiene su propia ficha: el mismo caso que Bolívar Honduras en Scandinavian Tobacco.', 'En febrero de 2024, la prensa del sector escribe que Altadis U.S.A. posee la marca en Estados Unidos y que los Turrent la poseen en el resto del mundo. Los puros se siguen haciendo en México por los Turrent; Alberto Turrent (2009) da Nueva Matacapan de Tabacos, en San Andrés Tuxtla, como su fábrica, y la describe como un productor de tabaco para puros del país. El atlas lleva la ficha de la familia bajo el nombre de Casa Turrent; Te-Amo (México) no es ni un homónimo New World ni una marca dominicana.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Seit 2000 und der Fusion von Consolidated Cigar in Altadis gehört die Marke dem Konzern. Gemacht wird sie weiterhin von den Turrents, in ihrer Fabrik in San Andrés Tuxtla, Nueva Matacapan de Tabacos, auf zweitausend Acres vulkanischen Bodens, auf denen San Andrés Negro aus Criollo-Saat und Sumatra wachsen. Es ist der größte Zigarrentabakproduzent Mexikos, und dieser Atlas führt den Eintrag der Familie bereits unter dem Namen Casa Turrent. Eine Konzernmarke, gefertigt in der Fabrik einer Familie, die ihren eigenen Eintrag hat: derselbe Fall wie Bolívar Honduras bei Scandinavian Tobacco.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Seit 2000 und der Fusion von Consolidated Cigar in Altadis gehört die Marke dem Konzern. Gemacht wird sie weiterhin von den Turrents, in ihrer Fabrik in San Andrés Tuxtla, Nueva Matacapan de Tabacos, auf zweitausend Acres vulkanischen Bodens, auf denen San Andrés Negro aus Criollo-Saat und Sumatra wachsen. Es ist der größte Zigarrentabakproduzent Mexikos, und dieser Atlas führt den Eintrag der Familie bereits unter dem Namen Casa Turrent. Eine Konzernmarke, gefertigt in der Fabrik einer Familie, die ihren eigenen Eintrag hat: derselbe Fall wie Bolívar Honduras bei Scandinavian Tobacco.', 'Im Februar 2024 schreibt die Fachpresse, Altadis U.S.A. besitze die Marke in den Vereinigten Staaten und die Turrents besäßen sie im Rest der Welt. Die Zigarren werden weiterhin in Mexiko von den Turrents gemacht; Alberto Turrent (2009) nennt Nueva Matacapan de Tabacos in San Andrés Tuxtla als ihre Fabrik und beschreibt sie als einen Zigarrentabakproduzenten des Landes. Der Atlas führt den Eintrag der Familie unter dem Namen Casa Turrent; Te-Amo (Mexiko) ist weder ein Namensvetter von New World noch eine dominikanische Marke.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('自2000年 Consolidated Cigar 并入 Altadis 起，品牌归集团所有。它仍由图伦特家族在圣安德烈斯图斯特拉的工厂 Nueva Matacapan de Tabacos 制作，两千英亩火山土上种着克里奥约种的 San Andrés Negro 与苏门答腊种。这是墨西哥最大的雪茄烟草生产者，本图集已以 Casa Turrent 之名载有该家族的词条。集团品牌在一个已有自己词条的家族的工厂里制作：与斯堪的纳维亚烟草集团的 Bolívar Honduras 同理。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '自2000年 Consolidated Cigar 并入 Altadis 起，品牌归集团所有。它仍由图伦特家族在圣安德烈斯图斯特拉的工厂 Nueva Matacapan de Tabacos 制作，两千英亩火山土上种着克里奥约种的 San Andrés Negro 与苏门答腊种。这是墨西哥最大的雪茄烟草生产者，本图集已以 Casa Turrent 之名载有该家族的词条。集团品牌在一个已有自己词条的家族的工厂里制作：与斯堪的纳维亚烟草集团的 Bolívar Honduras 同理。', '2024年2月，行业媒体写道，Altadis U.S.A. 在美国拥有该品牌，图伦特家族在世界其他地区拥有该品牌。雪茄仍由图伦特家族在墨西哥制作；阿尔贝托·图伦特（2009）称 Nueva Matacapan de Tabacos（位于圣安德烈斯图斯特拉）是他们的工厂，并称其是该国的一家雪茄烟草生产者。本图集以 Casa Turrent 之名载有该家族的词条；Te-Amo（墨西哥）既不是 New World 的同名品牌，也不是多米尼加品牌。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('منذ 2000 واندماج Consolidated Cigar في ألتاديس، العلامة ملك المجموعة. وما زال آل تورينت يصنعونها في مصنعهم بسان أندريس توكستلا، Nueva Matacapan de Tabacos، على ألفي فدّان من الأرض البركانية ينمو فيها San Andrés Negro من بذرة كريوّو، والسومطرة. إنّه أكبر منتج لتبغ السيجار في المكسيك، ويحمل هذا الأطلس بطاقة العائلة أصلًا باسم Casa Turrent. علامةُ مجموعةٍ تُصنع في مصنع عائلة لها بطاقتها الخاصة: الحالة نفسها لِـBolívar Honduras لدى مجموعة التبغ الإسكندنافية.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'منذ 2000 واندماج Consolidated Cigar في ألتاديس، العلامة ملك المجموعة. وما زال آل تورينت يصنعونها في مصنعهم بسان أندريس توكستلا، Nueva Matacapan de Tabacos، على ألفي فدّان من الأرض البركانية ينمو فيها San Andrés Negro من بذرة كريوّو، والسومطرة. إنّه أكبر منتج لتبغ السيجار في المكسيك، ويحمل هذا الأطلس بطاقة العائلة أصلًا باسم Casa Turrent. علامةُ مجموعةٍ تُصنع في مصنع عائلة لها بطاقتها الخاصة: الحالة نفسها لِـBolívar Honduras لدى مجموعة التبغ الإسكندنافية.', 'في شباط/فبراير 2024، تكتب الصحافة المتخصصة أنّ Altadis U.S.A. تملك العلامة في الولايات المتحدة وأنّ آل تورينت يملكونها في بقية العالم. ولا يزال السيجار يُصنع في المكسيك على يد آل تورينت؛ ويذكر ألبرتو تورينت (2009) أنّ Nueva Matacapan de Tabacos في سان أندريس توكستلا هي مصنعهم، ويصفها بأنها منتج لتبغ السيجار في البلاد. ويحمل الأطلس بطاقة العائلة باسم Casa Turrent؛ و Te-Amo (المكسيك) ليست اسمًا مماثلًا لعلامة New World ولا علامة دومينيكانية.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Te Amo';

UPDATE `brands` SET
  `country_id` = 'mexico',
  `founded` = '1966 selon Alberto Turrent ; San Andrés Tuxtla',
  `factory` = 'Nueva Matacapan de Tabacos, San Andrés Tuxtla (Mexique), fabrique des Turrent ; marque à Altadis U.S.A. aux États-Unis',
  `gamme` = '[{"name":"The Original San Andrés Valley Cigar","color":"#4A6B3A","force":"Medium","story":"La relance de février 2024 : trois formats (Robusto, Toro, Magnum), bagues or, blanc et vert, puro mexicain, robe Habano Mexico San Andrés de trois ans.","vitolas":[],"wrapper":"San Andrés"},{"name":"Te-Amo Revolution","color":"#7A2E1E","force":null,"story":"La précédente tentative de relance de la marque, dont la dernière sortie date de 2012.","vitolas":[],"wrapper":"Non divulguée"}]',
  `gamme_en` = '[{"name":"The Original San Andrés Valley Cigar","color":"#4A6B3A","force":"Medium","story":"The February 2024 relaunch: three sizes (Robusto, Toro, Magnum), gold, white and green bands, Mexican puro, three-year-old Habano Mexico San Andrés wrapper.","vitolas":[],"wrapper":"San Andrés"},{"name":"Te-Amo Revolution","color":"#7A2E1E","force":null,"story":"The brand''s previous relaunch attempt, whose last release dates from 2012.","vitolas":[],"wrapper":"Undisclosed"}]',
  `gamme_es` = '[{"name":"The Original San Andrés Valley Cigar","color":"#4A6B3A","force":"Medium","story":"El relanzamiento de febrero de 2024: tres formatos (Robusto, Toro, Magnum), anillas oro, blanco y verde, puro mexicano, capa Habano Mexico San Andrés de tres años.","vitolas":[],"wrapper":"San Andrés"},{"name":"Te-Amo Revolution","color":"#7A2E1E","force":null,"story":"El intento anterior de relanzamiento de la marca, cuya última salida data de 2012.","vitolas":[],"wrapper":"No divulgada"}]',
  `gamme_de` = '[{"name":"The Original San Andrés Valley Cigar","color":"#4A6B3A","force":"Medium","story":"Der Neustart vom Februar 2024: drei Formate (Robusto, Toro, Magnum), Banderolen in Gold, Weiß und Grün, mexikanischer Puro, Deckblatt Habano Mexico San Andrés, drei Jahre alt.","vitolas":[],"wrapper":"San Andrés"},{"name":"Te-Amo Revolution","color":"#7A2E1E","force":null,"story":"Der frühere Neustartversuch der Marke, dessen letzte Veröffentlichung aus dem Jahr 2012 stammt.","vitolas":[],"wrapper":"Nicht angegeben"}]',
  `gamme_zh` = '[{"name":"The Original San Andrés Valley Cigar","color":"#4A6B3A","force":"Medium","story":"2024年2月的重振：三种尺寸（Robusto、Toro、Magnum），金、白、绿烟标，全墨西哥烟叶的雪茄，茄衣为三年期的 Habano Mexico San Andrés。","vitolas":[],"wrapper":"圣安德烈斯"},{"name":"Te-Amo Revolution","color":"#7A2E1E","force":null,"story":"该品牌此前的一次重振尝试，上一次推出是在2012年。","vitolas":[],"wrapper":"未公开"}]',
  `gamme_ar` = '[{"name":"The Original San Andrés Valley Cigar","color":"#4A6B3A","force":"Medium","story":"إعادة الإطلاق في شباط/فبراير 2024: ثلاثة قياسات (Robusto وToro وMagnum)، وأطواق ذهبية وبيضاء وخضراء، سيجار مكسيكي خالص، وغلاف Habano Mexico San Andrés عمره ثلاث سنوات.","vitolas":[],"wrapper":"سان أندريس"},{"name":"Te-Amo Revolution","color":"#7A2E1E","force":null,"story":"محاولة إعادة الإطلاق السابقة للعلامة، وآخر إصدار لها يعود إلى 2012.","vitolas":[],"wrapper":"غير معلن"}]',
  `celebrities` = '[{"name":"Aztèques et Totonacs","anecdote":"Le tabac a une longue histoire dans la région de San Andrés Tuxtla ; aucune page lue ne relie les cérémonies aztèques à la marque, l''anecdote est donc ramenée à la région."}]',
  `celebrities_en` = '[{"name":"Aztecs and Totonacs","anecdote":"Tobacco has a long history in the San Andrés Tuxtla region; no page read links Aztec ceremonies to the brand, so the anecdote is brought back to the region."}]',
  `celebrities_es` = '[{"name":"Aztecas y totonacas","anecdote":"El tabaco tiene una larga historia en la región de San Andrés Tuxtla; ninguna página leída vincula las ceremonias aztecas con la marca, por lo que la anécdota se limita a la región."}]',
  `celebrities_de` = '[{"name":"Azteken und Totonaken","anecdote":"Tabak hat in der Region San Andrés Tuxtla eine lange Geschichte; keine gelesene Seite verbindet die aztekischen Zeremonien mit der Marke, die Anekdote wird daher auf die Region beschränkt."}]',
  `celebrities_zh` = '[{"name":"阿兹特克人与托托纳克人","anecdote":"烟草在圣安德烈斯图斯特拉地区有悠久的历史；所读页面均未把阿兹特克的仪式与该品牌联系起来，因此这则轶事只限于该地区。"}]',
  `celebrities_ar` = '[{"name":"الأزتيك والتوتوناك","anecdote":"للتبغ تاريخ طويل في منطقة سان أندريس توكستلا؛ ولا تربط أي صفحة قُرئت بين الطقوس الأزتيكية والعلامة، ولذلك حُصرت الحكاية في المنطقة."}]',
  `source` = IF(LOCATE(CAST('halfwheel.com (1963 selon halfwheel — l''atlas retient 1966, la date donnée par Alberto Turrent lui-même)' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, 'halfwheel.com (1963 selon halfwheel — l''atlas retient 1966, la date donnée par Alberto Turrent lui-même)', 'halfwheel.com (page non lue ; 1963 non vérifié)'), `source`),
  `source` = IF(LOCATE(CAST('cigar-coop.com « Altadis USA to reintroduce Te Amo at TPE 20' AS BINARY), CAST(`source` AS BINARY)) > 0, `source`, CONCAT(`source`, ' ; ', 'cigar-coop.com « Altadis USA to reintroduce Te Amo at TPE 2024 » (janvier 2024 : puro mexicain, Turrent pour Altadis U.S.A.) ; cigarjournal.com « A. Turrent Cigars - Te Amo Cigars » (21 octobre 2024 : mélange San Andrés, Intertabac 2024)')),
  `updated_at` = NOW()
 WHERE `name` = 'Te Amo';

-- ── Tabacalera ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('L''histoire de Tabacalera de Filipinas commence non par une décision d''entrepreneur mais par une décision administrative coloniale. En 1881, la Couronne espagnole dissout la Real Compañía de Filipinas — le monopole d''État qui contrôlait la production, la distribution et l''exportation du tabac philippin depuis le XVIIIe siècle — et autorise la création de manufactures privées pour lui succéder. Le passage du monopole à la production concurrentielle visait à moderniser une industrie devenue bureaucratiquement rigide ; Tabacalera sortit de cette réorganisation comme la plus grande et la mieux capitalisée des nouvelles maisons privées.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'L''histoire de Tabacalera de Filipinas commence non par une décision d''entrepreneur mais par une décision administrative coloniale. En 1881, la Couronne espagnole dissout la Real Compañía de Filipinas — le monopole d''État qui contrôlait la production, la distribution et l''exportation du tabac philippin depuis le XVIIIe siècle — et autorise la création de manufactures privées pour lui succéder. Le passage du monopole à la production concurrentielle visait à moderniser une industrie devenue bureaucratiquement rigide ; Tabacalera sortit de cette réorganisation comme la plus grande et la mieux capitalisée des nouvelles maisons privées.', 'Tabacalera naît d''une décision administrative coloniale. Le monopole espagnol du tabac aux Philippines, imposé en 1780 selon Philstar (2011), est aboli le 5 juin 1881 ; la Compañía General de Tabacos de Filipinas est fondée la même année par le marquis de Comillas, Antonio López y López, le 11 novembre selon Philstar, le 26 novembre selon Verafiles (2014). Elle rachète des fabriques de cigares, uniformise la qualité et exporte les « cigares de Manille ».'), `history`),
  `history_en` = IF(LOCATE(CAST('The history of Tabacalera de Filipinas begins not with an entrepreneurial decision but with a colonial administrative one. In 1881, the Spanish crown dissolved the Real Compañía de Filipinas — the state tobacco monopoly that had controlled Philippine tobacco production, distribution, and export since the eighteenth century — and authorized the creation of private manufacturers to operate in its place. The transition from monopoly to competitive production was designed to modernize an industry that had grown bureaucratically rigid, and Tabacalera emerged from this reorganization as the largest and best-capitalized of the new private manufacturers.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The history of Tabacalera de Filipinas begins not with an entrepreneurial decision but with a colonial administrative one. In 1881, the Spanish crown dissolved the Real Compañía de Filipinas — the state tobacco monopoly that had controlled Philippine tobacco production, distribution, and export since the eighteenth century — and authorized the creation of private manufacturers to operate in its place. The transition from monopoly to competitive production was designed to modernize an industry that had grown bureaucratically rigid, and Tabacalera emerged from this reorganization as the largest and best-capitalized of the new private manufacturers.', 'Tabacalera was born of a colonial administrative decision. The Spanish tobacco monopoly in the Philippines, imposed in 1780 according to Philstar (2011), is abolished on 5 June 1881; the Compañía General de Tabacos de Filipinas is founded the same year by the Marquis of Comillas, Antonio López y López, on 11 November according to Philstar, on 26 November according to Verafiles (2014). It buys cigar factories, standardises quality and exports “Manila cigars”.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La historia de Tabacalera de Filipinas empieza no por una decisión de empresario sino por una decisión administrativa colonial. En 1881, la Corona española disuelve la Real Compañía de Filipinas —el monopolio de Estado que controlaba la producción, la distribución y la exportación del tabaco filipino desde el siglo XVIII— y autoriza la creación de manufacturas privadas para sucederle. El paso del monopolio a la producción competitiva buscaba modernizar una industria vuelta burocráticamente rígida; Tabacalera salió de esa reorganización como la mayor y la mejor capitalizada de las nuevas casas privadas.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La historia de Tabacalera de Filipinas empieza no por una decisión de empresario sino por una decisión administrativa colonial. En 1881, la Corona española disuelve la Real Compañía de Filipinas —el monopolio de Estado que controlaba la producción, la distribución y la exportación del tabaco filipino desde el siglo XVIII— y autoriza la creación de manufacturas privadas para sucederle. El paso del monopolio a la producción competitiva buscaba modernizar una industria vuelta burocráticamente rígida; Tabacalera salió de esa reorganización como la mayor y la mejor capitalizada de las nuevas casas privadas.', 'Tabacalera nace de una decisión administrativa colonial. El monopolio español del tabaco en Filipinas, impuesto en 1780 según Philstar (2011), se abole el 5 de junio de 1881; la Compañía General de Tabacos de Filipinas se funda ese mismo año por el marqués de Comillas, Antonio López y López, el 11 de noviembre según Philstar, el 26 de noviembre según Verafiles (2014). Compra fábricas de puros, uniformiza la calidad y exporta los «puros de Manila».'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die Geschichte von Tabacalera de Filipinas beginnt nicht mit einer unternehmerischen, sondern mit einer kolonialen Verwaltungsentscheidung. 1881 löste die spanische Krone die Real Compañía de Filipinas auf — das Staatsmonopol, das Erzeugung, Vertrieb und Ausfuhr des philippinischen Tabaks seit dem 18. Jahrhundert lenkte — und erlaubte die Gründung privater Manufakturen als Nachfolge. Der Übergang vom Monopol zur wettbewerblichen Erzeugung sollte eine bürokratisch erstarrte Industrie erneuern; Tabacalera ging aus dieser Neuordnung als das größte und bestausgestattete der neuen privaten Häuser hervor.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die Geschichte von Tabacalera de Filipinas beginnt nicht mit einer unternehmerischen, sondern mit einer kolonialen Verwaltungsentscheidung. 1881 löste die spanische Krone die Real Compañía de Filipinas auf — das Staatsmonopol, das Erzeugung, Vertrieb und Ausfuhr des philippinischen Tabaks seit dem 18. Jahrhundert lenkte — und erlaubte die Gründung privater Manufakturen als Nachfolge. Der Übergang vom Monopol zur wettbewerblichen Erzeugung sollte eine bürokratisch erstarrte Industrie erneuern; Tabacalera ging aus dieser Neuordnung als das größte und bestausgestattete der neuen privaten Häuser hervor.', 'Tabacalera entsteht aus einer kolonialen Verwaltungsentscheidung. Das spanische Tabakmonopol auf den Philippinen, nach Philstar (2011) 1780 eingeführt, wird am 5. Juni 1881 abgeschafft; die Compañía General de Tabacos de Filipinas wird im selben Jahr vom Marquis von Comillas, Antonio López y López, gegründet, am 11. November laut Philstar, am 26. November laut Verafiles (2014). Sie kauft Zigarrenfabriken, vereinheitlicht die Qualität und exportiert die „Manila-Zigarren“.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('菲律宾塔巴卡莱拉的历史，起点不是一个企业家的决定，而是一项殖民行政决定。1881年，西班牙王室解散了菲律宾皇家公司——这个自18世纪起掌控菲律宾烟草生产、分销与出口的国家专营——并批准设立私人工厂来接替它。从专营转向竞争性生产，本意是让一个官僚化到僵硬的产业现代化；塔巴卡莱拉就是从这次重组中脱颖而出的：在那些新的私人字号里，它规模最大、资本最厚。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '菲律宾塔巴卡莱拉的历史，起点不是一个企业家的决定，而是一项殖民行政决定。1881年，西班牙王室解散了菲律宾皇家公司——这个自18世纪起掌控菲律宾烟草生产、分销与出口的国家专营——并批准设立私人工厂来接替它。从专营转向竞争性生产，本意是让一个官僚化到僵硬的产业现代化；塔巴卡莱拉就是从这次重组中脱颖而出的：在那些新的私人字号里，它规模最大、资本最厚。', 'Tabacalera 诞生于一项殖民行政决定。据 Philstar（2011），西班牙在菲律宾的烟草专营于1780年强制推行，1881年6月5日被废除；同年，Compañía General de Tabacos de Filipinas 由科米利亚斯侯爵安东尼奥·洛佩斯·伊·洛佩斯创立，Philstar 称在11月11日，Verafiles（2014）称在11月26日。它收购雪茄工厂，统一品质，并出口「马尼拉雪茄」。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('لا يبدأ تاريخ «تاباكاليرا دي فيليبيناس» بقرار من رجل أعمال، بل بقرار إداري استعماري. ففي 1881، حلّ التاج الإسباني «الشركة الملكية للفلبين» — الاحتكار الحكومي الذي كان يضبط إنتاج التبغ الفلبيني وتوزيعه وتصديره منذ القرن الثامن عشر — وأذن بإنشاء مصانع خاصة تخلفه. وكان الانتقال من الاحتكار إلى الإنتاج التنافسي يرمي إلى تحديث صناعة تصلّبت بيروقراطيًّا؛ وخرجت «تاباكاليرا» من هذا التنظيم الجديد بوصفها الأكبر والأوفر رأسمالًا بين الدور الخاصة الجديدة.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'لا يبدأ تاريخ «تاباكاليرا دي فيليبيناس» بقرار من رجل أعمال، بل بقرار إداري استعماري. ففي 1881، حلّ التاج الإسباني «الشركة الملكية للفلبين» — الاحتكار الحكومي الذي كان يضبط إنتاج التبغ الفلبيني وتوزيعه وتصديره منذ القرن الثامن عشر — وأذن بإنشاء مصانع خاصة تخلفه. وكان الانتقال من الاحتكار إلى الإنتاج التنافسي يرمي إلى تحديث صناعة تصلّبت بيروقراطيًّا؛ وخرجت «تاباكاليرا» من هذا التنظيم الجديد بوصفها الأكبر والأوفر رأسمالًا بين الدور الخاصة الجديدة.', 'تنشأ Tabacalera من قرار إداري استعماري. فالاحتكار الإسباني للتبغ في الفلبين، الذي فُرض سنة 1780 بحسب Philstar (2011)، يُلغى في 5 حزيران/يونيو 1881؛ وتُؤسَّس Compañía General de Tabacos de Filipinas في السنة نفسها على يد ماركيز كوميّاس أنطونيو لوبيز إي لوبيز، في 11 تشرين الثاني/نوفمبر بحسب Philstar، وفي 26 تشرين الثاني/نوفمبر بحسب Verafiles (2014). وتشتري مصانع سيجار، وتوحّد الجودة، وتصدّر «سيجار مانيلا».'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Tabacalera';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('L''administration coloniale espagnole avait cultivé le tabac philippin pour l''exportation vers l''Espagne pendant plus de deux siècles avant ce moment. La vallée de Cagayan, dans le nord de Luzon — région de culture principale alors comme aujourd''hui — avait été cartographiée, ses tabacs classés, ses pratiques systématisées par des décennies de gestion monopolistique. La feuille de la région d''Ilocos, cultivée dans d''autres conditions sur la côte nord-ouest, fournissait une variété complémentaire dont les assembleurs se servaient pour ajuster les profils. Le savoir technique accumulé était considérable, même s''il restait contraint par la bureaucratie.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'L''administration coloniale espagnole avait cultivé le tabac philippin pour l''exportation vers l''Espagne pendant plus de deux siècles avant ce moment. La vallée de Cagayan, dans le nord de Luzon — région de culture principale alors comme aujourd''hui — avait été cartographiée, ses tabacs classés, ses pratiques systématisées par des décennies de gestion monopolistique. La feuille de la région d''Ilocos, cultivée dans d''autres conditions sur la côte nord-ouest, fournissait une variété complémentaire dont les assembleurs se servaient pour ajuster les profils. Le savoir technique accumulé était considérable, même s''il restait contraint par la bureaucratie.', 'La maison Tabacalera Incorporada se présente aujourd''hui comme une fabrique de cigares d''Asie qui date son travail à la main de 1881 (tabacalera.com.ph, octobre 2026), avec un tabac d''Isabela et d''ailleurs. La marque phare de la Compañía, La Flor de la Isabela, a été rebaptisée Tabacalera en l''honneur de la société fondatrice (Philstar, 2011) ; La Flor de la Isabela a sa propre fiche dans l''atlas.'), `history`),
  `history_en` = IF(LOCATE(CAST('The Spanish colonial administration had cultivated Philippine tobacco specifically for export to Spain for over two centuries before this moment. The Cagayan Valley in northern Luzon — the primary growing region then and now — had been mapped, its tobaccos classified, and its cultivation practices systematized through decades of monopoly management. The Ilocos region''s leaf, grown under different conditions on the northwestern coast, provided a complementary variety that blenders used to adjust profiles. The technical knowledge embedded in the industry was substantial, if bureaucratically constrained.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The Spanish colonial administration had cultivated Philippine tobacco specifically for export to Spain for over two centuries before this moment. The Cagayan Valley in northern Luzon — the primary growing region then and now — had been mapped, its tobaccos classified, and its cultivation practices systematized through decades of monopoly management. The Ilocos region''s leaf, grown under different conditions on the northwestern coast, provided a complementary variety that blenders used to adjust profiles. The technical knowledge embedded in the industry was substantial, if bureaucratically constrained.', 'The house Tabacalera Incorporada now presents itself as a cigar factory in Asia that dates its hand production to 1881 (tabacalera.com.ph, October 2026), with tobacco from Isabela and elsewhere. The Compañía''s flagship brand, La Flor de la Isabela, was renamed Tabacalera in honour of the founding company (Philstar, 2011); La Flor de la Isabela has its own entry in the atlas.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La administración colonial española había cultivado el tabaco filipino para la exportación hacia España durante más de dos siglos antes de ese momento. El valle de Cagayán, en el norte de Luzón —región de cultivo principal entonces como hoy—, había sido cartografiado, sus tabacos clasificados, sus prácticas sistematizadas por décadas de gestión monopolística. La hoja de la región de Ilocos, cultivada en otras condiciones en la costa noroeste, proporcionaba una variedad complementaria que los ligadores empleaban para ajustar los perfiles. El saber técnico acumulado era considerable, aunque siguiera constreñido por la burocracia.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La administración colonial española había cultivado el tabaco filipino para la exportación hacia España durante más de dos siglos antes de ese momento. El valle de Cagayán, en el norte de Luzón —región de cultivo principal entonces como hoy—, había sido cartografiado, sus tabacos clasificados, sus prácticas sistematizadas por décadas de gestión monopolística. La hoja de la región de Ilocos, cultivada en otras condiciones en la costa noroeste, proporcionaba una variedad complementaria que los ligadores empleaban para ajustar los perfiles. El saber técnico acumulado era considerable, aunque siguiera constreñido por la burocracia.', 'La casa Tabacalera Incorporada se presenta hoy como una fábrica de puros de Asia que fecha su trabajo a mano en 1881 (tabacalera.com.ph, octubre de 2026), con tabaco de Isabela y de otros lugares. La marca insignia de la Compañía, La Flor de la Isabela, fue rebautizada Tabacalera en honor de la sociedad fundadora (Philstar, 2011); La Flor de la Isabela tiene su propia ficha en el atlas.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die spanische Kolonialverwaltung hatte den philippinischen Tabak vor diesem Zeitpunkt über zwei Jahrhunderte lang für die Ausfuhr nach Spanien angebaut. Das Cagayán-Tal im Norden Luzons — damals wie heute das wichtigste Anbaugebiet — war vermessen, seine Tabake waren eingeteilt, seine Verfahren durch Jahrzehnte monopolistischer Verwaltung geordnet. Das Blatt aus der Gegend von Ilocos, unter anderen Bedingungen an der Nordwestküste gezogen, lieferte eine ergänzende Sorte, mit der die Mischer die Profile abstimmten. Das angesammelte technische Wissen war beträchtlich, auch wenn es von der Bürokratie eingeengt blieb.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die spanische Kolonialverwaltung hatte den philippinischen Tabak vor diesem Zeitpunkt über zwei Jahrhunderte lang für die Ausfuhr nach Spanien angebaut. Das Cagayán-Tal im Norden Luzons — damals wie heute das wichtigste Anbaugebiet — war vermessen, seine Tabake waren eingeteilt, seine Verfahren durch Jahrzehnte monopolistischer Verwaltung geordnet. Das Blatt aus der Gegend von Ilocos, unter anderen Bedingungen an der Nordwestküste gezogen, lieferte eine ergänzende Sorte, mit der die Mischer die Profile abstimmten. Das angesammelte technische Wissen war beträchtlich, auch wenn es von der Bürokratie eingeengt blieb.', 'Das Haus Tabacalera Incorporada stellt sich heute als eine Zigarrenfabrik in Asien dar, die ihre Handarbeit auf 1881 datiert (tabacalera.com.ph, Oktober 2026), mit Tabak aus Isabela und von anderswo. Die Flaggschiffmarke der Compañía, La Flor de la Isabela, wurde zu Ehren der Gründungsgesellschaft in Tabacalera umbenannt (Philstar, 2011); La Flor de la Isabela hat im Atlas einen eigenen Eintrag.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('在此之前，西班牙殖民当局已为向西班牙出口而种植菲律宾烟草两百多年。吕宋岛北部的卡加延河谷——当时与今天同样是主要产区——早已被测绘，其烟草被分类，其做法在数十年的专营管理中被系统化。西北海岸另一种条件下培育的伊罗戈斯产区叶片，提供了一个互补的品种，调配师用它来微调风格。积累下来的技术知识相当可观，尽管始终被官僚体制束着。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '在此之前，西班牙殖民当局已为向西班牙出口而种植菲律宾烟草两百多年。吕宋岛北部的卡加延河谷——当时与今天同样是主要产区——早已被测绘，其烟草被分类，其做法在数十年的专营管理中被系统化。西北海岸另一种条件下培育的伊罗戈斯产区叶片，提供了一个互补的品种，调配师用它来微调风格。积累下来的技术知识相当可观，尽管始终被官僚体制束着。', 'Tabacalera Incorporada 公司如今自称为亚洲的一家雪茄工厂，并把手工制作的起点定在1881年（tabacalera.com.ph，2026年10月），用的是伊莎贝拉及其他地方的烟叶。该公司的旗舰品牌 La Flor de la Isabela 为纪念创立公司而改名为 Tabacalera（Philstar，2011）；La Flor de la Isabela 在本图集中另有词条。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('كانت الإدارة الاستعمارية الإسبانية قد زرعت التبغ الفلبيني للتصدير إلى إسبانيا أكثر من قرنين قبل تلك اللحظة. فوادي كاغايان، في شمال لوزون — منطقة الزراعة الرئيسة يومها كما اليوم — كان قد رُسم على الخرائط، وصُنّفت تبوغه، ونُظّمت ممارساته عبر عقود من الإدارة الاحتكارية. أما ورقة منطقة إيلوكوس، المزروعة في ظروف أخرى على الساحل الشمالي الغربي، فكانت تقدّم صنفًا مكمّلًا يستعمله الخلّاطون لضبط الطوابع. وكانت المعرفة التقنية المتراكمة كبيرة، وإن ظلّت مقيّدة بالبيروقراطية.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'كانت الإدارة الاستعمارية الإسبانية قد زرعت التبغ الفلبيني للتصدير إلى إسبانيا أكثر من قرنين قبل تلك اللحظة. فوادي كاغايان، في شمال لوزون — منطقة الزراعة الرئيسة يومها كما اليوم — كان قد رُسم على الخرائط، وصُنّفت تبوغه، ونُظّمت ممارساته عبر عقود من الإدارة الاحتكارية. أما ورقة منطقة إيلوكوس، المزروعة في ظروف أخرى على الساحل الشمالي الغربي، فكانت تقدّم صنفًا مكمّلًا يستعمله الخلّاطون لضبط الطوابع. وكانت المعرفة التقنية المتراكمة كبيرة، وإن ظلّت مقيّدة بالبيروقراطية.', 'تقدّم دار Tabacalera Incorporada نفسها اليوم بوصفها مصنع سيجار في آسيا يؤرّخ عمله اليدوي بسنة 1881 (tabacalera.com.ph، تشرين الأول/أكتوبر 2026)، بتبغ من إيزابيلا ومن مواضع أخرى. أما العلامة الرائدة للشركة، La Flor de la Isabela، فقد أُعيدت تسميتها Tabacalera تكريمًا للشركة المؤسِّسة (Philstar، 2011)؛ ولـLa Flor de la Isabela بطاقتها الخاصة في الأطلس.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Tabacalera';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Ce qui distingue vraiment le tabac philippin est difficile à dire sans le vocabulaire de la dégustation, mais c''est réel et constant. La rétro-olfaction — le retour aromatique par les fosses nasales à l''expiration — porte des notes que les dégustateurs expérimentés décrivent comme mentholées, fraîches, légèrement florales. Ce n''est ni une caractéristique variétale ni un artefact de fermentation, mais l''expression de la chimie du sol de Cagayan et de la façon particulière dont ce tabac métabolise ses alcaloïdes. Les assembleurs qui cherchent ce caractère se sont historiquement fournis aux Philippines.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Ce qui distingue vraiment le tabac philippin est difficile à dire sans le vocabulaire de la dégustation, mais c''est réel et constant. La rétro-olfaction — le retour aromatique par les fosses nasales à l''expiration — porte des notes que les dégustateurs expérimentés décrivent comme mentholées, fraîches, légèrement florales. Ce n''est ni une caractéristique variétale ni un artefact de fermentation, mais l''expression de la chimie du sol de Cagayan et de la façon particulière dont ce tabac métabolise ses alcaloïdes. Les assembleurs qui cherchent ce caractère se sont historiquement fournis aux Philippines.', 'Le groupe a connu plusieurs propriétaires. Verafiles (2014) décrit une société espagnole vendue par morceaux des années 1950 aux années 1990, marque La Flor de la Isabela comprise, puis une suite de rachats étrangers de 1997 à 2007 jusqu''à CDF International, société néerlandaise. Philstar (2011) écrit qu''après un siècle la Compañía vend son activité cigares et que la fabrique passe en mains philippines. La fabrique est à Dasmariñas, dans la province de Cavite, sur environ 2 700 m², où les cigares sont faits à la main, avec des presses en bois de plus d''un siècle (Philstar, 2011).'), `history`),
  `history_en` = IF(LOCATE(CAST('What makes Philippine tobacco genuinely distinct in the world context is difficult to describe without the vocabulary of tasting, but it is real and consistent. The retrohale — the aromatic return through the nasal passage when exhaling — carries notes that experienced tasters describe as mentholated, cooling, slightly floral. This is not a variety characteristic or a fermentation artifact but an expression of the Cagayan soil''s chemistry and the particular way Philippine tobacco metabolizes its alkaloids. Blenders who seek that character have historically sourced from the Philippines.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'What makes Philippine tobacco genuinely distinct in the world context is difficult to describe without the vocabulary of tasting, but it is real and consistent. The retrohale — the aromatic return through the nasal passage when exhaling — carries notes that experienced tasters describe as mentholated, cooling, slightly floral. This is not a variety characteristic or a fermentation artifact but an expression of the Cagayan soil''s chemistry and the particular way Philippine tobacco metabolizes its alkaloids. Blenders who seek that character have historically sourced from the Philippines.', 'The group has had several owners. Verafiles (2014) describes a Spanish company sold off piece by piece from the 1950s to the 1990s, the La Flor de la Isabela brand included, then a series of foreign buyouts from 1997 to 2007 up to CDF International, a Dutch company. Philstar (2011) writes that after a century the Compañía sells its cigar business and that the factory passes into Philippine hands. The factory is in Dasmariñas, in Cavite province, on about 2,700 m², where the cigars are made by hand, with wooden presses more than a century old (Philstar, 2011).'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Lo que distingue verdaderamente al tabaco filipino es difícil de decir sin el vocabulario de la cata, pero es real y constante. La retronasal —el retorno aromático por las fosas nasales al espirar— lleva notas que los catadores experimentados describen como mentoladas, frescas, ligeramente florales. No es una característica varietal ni un artefacto de fermentación, sino la expresión de la química del suelo de Cagayán y de la manera particular en que ese tabaco metaboliza sus alcaloides. Los ligadores que buscan ese carácter se han abastecido históricamente en Filipinas.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Lo que distingue verdaderamente al tabaco filipino es difícil de decir sin el vocabulario de la cata, pero es real y constante. La retronasal —el retorno aromático por las fosas nasales al espirar— lleva notas que los catadores experimentados describen como mentoladas, frescas, ligeramente florales. No es una característica varietal ni un artefacto de fermentación, sino la expresión de la química del suelo de Cagayán y de la manera particular en que ese tabaco metaboliza sus alcaloides. Los ligadores que buscan ese carácter se han abastecido históricamente en Filipinas.', 'El grupo ha tenido varios propietarios. Verafiles (2014) describe una sociedad española vendida por partes de los años cincuenta a los noventa, con la marca La Flor de la Isabela incluida, y luego una serie de compras extranjeras de 1997 a 2007 hasta CDF International, sociedad neerlandesa. Philstar (2011) escribe que tras un siglo la Compañía vende su actividad de puros y que la fábrica pasa a manos filipinas. La fábrica está en Dasmariñas, en la provincia de Cavite, sobre unos 2 700 m², donde los puros se hacen a mano, con prensas de madera de más de un siglo (Philstar, 2011).'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Was den philippinischen Tabak wirklich auszeichnet, ist ohne das Vokabular der Verkostung schwer zu sagen, aber es ist wirklich und beständig. Der retronasale Eindruck — die aromatische Rückkehr durch die Nasenhöhlen beim Ausatmen — trägt Noten, die erfahrene Verkoster als mentholartig, frisch, leicht blumig beschreiben. Das ist weder ein Sortenmerkmal noch ein Nebenerzeugnis der Fermentation, sondern der Ausdruck der Bodenchemie von Cagayán und der besonderen Art, wie dieser Tabak seine Alkaloide umsetzt. Mischer, die diesen Charakter suchen, haben sich geschichtlich auf den Philippinen versorgt.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Was den philippinischen Tabak wirklich auszeichnet, ist ohne das Vokabular der Verkostung schwer zu sagen, aber es ist wirklich und beständig. Der retronasale Eindruck — die aromatische Rückkehr durch die Nasenhöhlen beim Ausatmen — trägt Noten, die erfahrene Verkoster als mentholartig, frisch, leicht blumig beschreiben. Das ist weder ein Sortenmerkmal noch ein Nebenerzeugnis der Fermentation, sondern der Ausdruck der Bodenchemie von Cagayán und der besonderen Art, wie dieser Tabak seine Alkaloide umsetzt. Mischer, die diesen Charakter suchen, haben sich geschichtlich auf den Philippinen versorgt.', 'Die Gruppe hatte mehrere Eigentümer. Verafiles (2014) beschreibt ein spanisches Unternehmen, das von den 1950er- bis zu den 1990er-Jahren stückweise verkauft wurde, die Marke La Flor de la Isabela eingeschlossen, danach eine Reihe ausländischer Übernahmen von 1997 bis 2007 bis zu CDF International, einem niederländischen Unternehmen. Philstar (2011) schreibt, dass die Compañía nach einem Jahrhundert ihr Zigarrengeschäft verkauft und die Fabrik in philippinische Hände übergeht. Die Fabrik liegt in Dasmariñas in der Provinz Cavite auf rund 2 700 m², wo die Zigarren von Hand gefertigt werden, mit Holzpressen, die mehr als hundert Jahre alt sind (Philstar, 2011).'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('菲律宾烟草真正的独特之处，不借助品鉴的词汇很难说清，但它真实而稳定。鼻后回味——呼气时经由鼻腔返回的香气——带着老练品鉴者形容为薄荷感、清新、略带花香的气息。这既不是品种特征，也不是发酵的副产物，而是卡加延土壤化学与这种烟草代谢生物碱的特殊方式的表达。历史上，寻找这种性格的调配师都从菲律宾进货。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '菲律宾烟草真正的独特之处，不借助品鉴的词汇很难说清，但它真实而稳定。鼻后回味——呼气时经由鼻腔返回的香气——带着老练品鉴者形容为薄荷感、清新、略带花香的气息。这既不是品种特征，也不是发酵的副产物，而是卡加延土壤化学与这种烟草代谢生物碱的特殊方式的表达。历史上，寻找这种性格的调配师都从菲律宾进货。', '该集团几易其主。Verafiles（2014）描述了一家西班牙公司：从1950年代到1990年代被分块出售，La Flor de la Isabela 品牌也在其中；随后1997年至2007年间是一连串外国收购，直至荷兰公司 CDF International。Philstar（2011）写道，一个世纪之后，Compañía 出售其雪茄业务，工厂转入菲律宾人手中。工厂位于甲米地省的达斯马里尼亚斯，占地约2700平方米，雪茄在此手工制作，使用已有一百多年历史的木制压床（Philstar，2011）。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('وما يميّز التبغ الفلبيني حقًّا يصعب قوله بغير مفردات التذوّق، لكنه حقيقي وثابت. فالشمّ الرجعي — عودة العطر عبر الأنف عند الزفير — يحمل نكهات يصفها الذوّاقة المتمرّسون بأنها نعناعية، منعشة، زهرية قليلًا. وليس ذلك سمة صنفية ولا أثرًا جانبيًّا للتخمير، بل تعبيرٌ عن كيمياء تربة كاغايان وعن الطريقة الخاصة التي يستقلب بها هذا التبغ قلويّاته. والخلّاطون الذين يقصدون هذا الطابع تزوّدوا تاريخيًّا من الفلبين.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'وما يميّز التبغ الفلبيني حقًّا يصعب قوله بغير مفردات التذوّق، لكنه حقيقي وثابت. فالشمّ الرجعي — عودة العطر عبر الأنف عند الزفير — يحمل نكهات يصفها الذوّاقة المتمرّسون بأنها نعناعية، منعشة، زهرية قليلًا. وليس ذلك سمة صنفية ولا أثرًا جانبيًّا للتخمير، بل تعبيرٌ عن كيمياء تربة كاغايان وعن الطريقة الخاصة التي يستقلب بها هذا التبغ قلويّاته. والخلّاطون الذين يقصدون هذا الطابع تزوّدوا تاريخيًّا من الفلبين.', 'عرفت المجموعة عدة مالكين. تصف Verafiles (2014) شركة إسبانية بيعت قطعةً قطعةً من خمسينيات القرن الماضي إلى تسعينياته، بما فيها علامة La Flor de la Isabela، ثم سلسلة من عمليات الشراء الأجنبية من 1997 إلى 2007 حتى CDF International، وهي شركة هولندية. وتكتب Philstar (2011) أنّه بعد قرن تبيع الـCompañía نشاطها في السيجار وأنّ المصنع ينتقل إلى أيدٍ فلبينية. ويقع المصنع في داسماريناس بمقاطعة كافيتي على نحو 2700 متر مربع، حيث تُصنع السيجار يدويًّا، بمكابس خشبية يزيد عمرها على قرن (Philstar، 2011).'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Tabacalera';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('La propriété a changé plusieurs fois depuis l''indépendance : les intérêts espagnols ont cédé la place à des actionnaires philippins après 1946, et la structure a continué d''évoluer. La matière première de Cagayan et les pratiques de fabrication d''origine, à Agoo dans la province de La Union, sont restées continues à travers ces transitions. Tabacalera est un livre d''histoire fumable.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'La propriété a changé plusieurs fois depuis l''indépendance : les intérêts espagnols ont cédé la place à des actionnaires philippins après 1946, et la structure a continué d''évoluer. La matière première de Cagayan et les pratiques de fabrication d''origine, à Agoo dans la province de La Union, sont restées continues à travers ces transitions. Tabacalera est un livre d''histoire fumable.', 'Homonymes : cette fiche est celle de Tabacalera Incorporada (Philippines). Elle n''a rien à voir avec Tabacalera, S.A., la société espagnole (monopole espagnol, Altadis, copropriétaire de Habanos), ni avec Tabacalera del Oriente, Palma, Paxtián ou William Ventura.'), `history`),
  `history_en` = IF(LOCATE(CAST('The company''s ownership has changed several times since independence — Spanish interests were replaced by Filipino shareholders after 1946, and the ownership structure has evolved through the subsequent decades. The Cagayan Valley source material and the original manufacturing practices in Agoo, La Union, have remained continuous throughout these transitions.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The company''s ownership has changed several times since independence — Spanish interests were replaced by Filipino shareholders after 1946, and the ownership structure has evolved through the subsequent decades. The Cagayan Valley source material and the original manufacturing practices in Agoo, La Union, have remained continuous throughout these transitions.', 'Namesakes: this entry is that of Tabacalera Incorporada (Philippines). It has nothing to do with Tabacalera, S.A., the Spanish company (Spanish monopoly, Altadis, co-owner of Habanos), nor with Tabacalera del Oriente, Palma, Paxtián or William Ventura.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La propiedad ha cambiado varias veces desde la independencia: los intereses españoles cedieron el sitio a accionistas filipinos después de 1946, y la estructura ha seguido evolucionando. La materia prima de Cagayán y las prácticas de fabricación de origen, en Agoo, en la provincia de La Unión, se han mantenido continuas a través de esas transiciones. Tabacalera es un libro de historia fumable.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La propiedad ha cambiado varias veces desde la independencia: los intereses españoles cedieron el sitio a accionistas filipinos después de 1946, y la estructura ha seguido evolucionando. La materia prima de Cagayán y las prácticas de fabricación de origen, en Agoo, en la provincia de La Unión, se han mantenido continuas a través de esas transiciones. Tabacalera es un libro de historia fumable.', 'Homónimos: esta ficha es la de Tabacalera Incorporada (Filipinas). No tiene nada que ver con Tabacalera, S.A., la sociedad española (monopolio español, Altadis, copropietaria de Habanos), ni con Tabacalera del Oriente, Palma, Paxtián o William Ventura.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die Eigentümerschaft hat seit der Unabhängigkeit mehrfach gewechselt: Spanische Interessen wichen nach 1946 philippinischen Anteilseignern, und die Struktur hat sich weiter gewandelt. Der Rohstoff aus Cagayán und die ursprünglichen Fertigungsverfahren in Agoo in der Provinz La Unión sind durch diese Übergänge hindurch fortgeführt worden. Tabacalera ist ein rauchbares Geschichtsbuch.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die Eigentümerschaft hat seit der Unabhängigkeit mehrfach gewechselt: Spanische Interessen wichen nach 1946 philippinischen Anteilseignern, und die Struktur hat sich weiter gewandelt. Der Rohstoff aus Cagayán und die ursprünglichen Fertigungsverfahren in Agoo in der Provinz La Unión sind durch diese Übergänge hindurch fortgeführt worden. Tabacalera ist ein rauchbares Geschichtsbuch.', 'Namensvettern: Dieser Eintrag ist der von Tabacalera Incorporada (Philippinen). Er hat nichts mit Tabacalera, S.A., dem spanischen Unternehmen (spanisches Monopol, Altadis, Miteigentümerin von Habanos), zu tun, auch nicht mit Tabacalera del Oriente, Palma, Paxtián oder William Ventura.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('独立以来所有权几度更迭：1946年之后，西班牙方面的权益让位于菲律宾股东，其结构也继续演变。而卡加延的原料，以及拉乌尼翁省阿古最初的制作方法，穿过这些更替一直延续了下来。塔巴卡莱拉是一本可以点燃的历史书。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '独立以来所有权几度更迭：1946年之后，西班牙方面的权益让位于菲律宾股东，其结构也继续演变。而卡加延的原料，以及拉乌尼翁省阿古最初的制作方法，穿过这些更替一直延续了下来。塔巴卡莱拉是一本可以点燃的历史书。', '同名者：本词条是 Tabacalera Incorporada（菲律宾）的词条。它与西班牙公司 Tabacalera, S.A.（西班牙专营、Altadis、Habanos 的共同所有者）无关，也与 Tabacalera del Oriente、Palma、Paxtián 或 William Ventura 无关。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('وقد تبدّلت الملكية مرات منذ الاستقلال: تراجعت المصالح الإسبانية أمام مساهمين فلبينيين بعد 1946، وظلّ الهيكل يتطوّر. أما المادة الأولية من كاغايان وأساليب الصناعة الأصلية، في أغوو بمقاطعة لا أونيون، فبقيت متّصلة عبر هذه التحوّلات. «تاباكاليرا» كتاب تاريخ يمكن تدخينه.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'وقد تبدّلت الملكية مرات منذ الاستقلال: تراجعت المصالح الإسبانية أمام مساهمين فلبينيين بعد 1946، وظلّ الهيكل يتطوّر. أما المادة الأولية من كاغايان وأساليب الصناعة الأصلية، في أغوو بمقاطعة لا أونيون، فبقيت متّصلة عبر هذه التحوّلات. «تاباكاليرا» كتاب تاريخ يمكن تدخينه.', 'أسماء مشابهة: هذه البطاقة هي بطاقة Tabacalera Incorporada (الفلبين). ولا صلة لها بـTabacalera, S.A.، الشركة الإسبانية (الاحتكار الإسباني، وAltadis، الشريكة في ملكية Habanos)، ولا بـTabacalera del Oriente أو Palma أو Paxtián أو William Ventura.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Tabacalera';

