  `source` = IF(LOCATE(CAST('generalcigar.com et en.wikipedia.org « General Cigar Company » (1906 ; Macanudo, Punch et Partagás non cubains ; Santiago, Danlí et Estelí ; propriété de Swedish Match depuis 2005, puis du Scandinavian Tobacco Group depuis la réunion de 2010)' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, 'generalcigar.com et en.wikipedia.org « General Cigar Company » (1906 ; Macanudo, Punch et Partagás non cubains ; Santiago, Danlí et Estelí ; propriété de Swedish Match depuis 2005, puis du Scandinavian Tobacco Group depuis la réunion de 2010)', 'en.wikipedia.org « General Cigar Company » (fondée en 1906 à Evansville selon l''infobox ; Cullman 1961 ; Swedish Match 2005 ; STG 2010 ; Forged 2021 ; Cohiba, Punch, Partagas non cubains) ; fundinguniverse.com « General Cigar Holdings, Inc. History » (1906 : United Cigar Manufacturers Company ; Temple Hall et Macanudo 1968 ; Swedish Match 64 % en janvier 2000)'), `source`),
  `source` = IF(LOCATE(CAST('cigaraficionado.com « Cigar Profiles : an interview with Edg' AS BINARY), CAST(`source` AS BINARY)) > 0, `source`, CONCAT(`source`, ' ; ', 'cigaraficionado.com « Cigar Profiles : an interview with Edgar M. Cullman Sr. » (automne 1994 : 1961, Temple Hall 1969, Partagás dominicaine fin des années 1970) ; en.wikipedia.org « Macanudo (cigar) » (République dominicaine, octobre 2000 ; Café : cape Connecticut shade) ; st-group.com « ST Cigar Group has acquired CAO International » (1er janvier 2007, titre vu en résultat de recherche) ; cigar-coop.com « General Cigar to release CAO Flathead Speed Shop Habano » (janvier 2026 : STG Estelí, Nicaragua, cape Habano d''Équateur) ; coronacigar.com « Macanudo Cafe Hyde Park », « Duke of York », « Duke of Devon » (tailles, résultats de recherche)')),
