-- ── Villiger ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Jean Villiger fonda son atelier de cigares à Pfeffikon, dans le canton de Lucerne, en 1888. La Suisse n''est pas un pays producteur de tabac — mais sa position géographique au cœur de l''Europe, ses réseaux commerciaux et sa tradition d''artisanat de précision firent de Pfeffikon un lieu logique pour une manufacture premium orientée vers l''exportation.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Jean Villiger fonda son atelier de cigares à Pfeffikon, dans le canton de Lucerne, en 1888. La Suisse n''est pas un pays producteur de tabac — mais sa position géographique au cœur de l''Europe, ses réseaux commerciaux et sa tradition d''artisanat de précision firent de Pfeffikon un lieu logique pour une manufacture premium orientée vers l''exportation.', 'Jean Villiger fonda sa fabrique de cigares en 1888, chez lui à Pfeffikon, à 28 ans, dit la page d''histoire de la maison (villigercigars.com, octobre 2026). Il mourut en 1902 et sa veuve Louise poursuivit l''affaire : elle lança en 1907 le Villiger Kiel, présenté comme un cigare à embout en plume d''oie, et fonda en 1910 la filiale allemande, aujourd''hui Villiger Söhne GmbH à Waldshut-Tiengen. En 1918, Hans et Max Villiger reprirent l''entreprise sous le nom de Villiger Söhne. Heinrich, fils de Max, y entra en 1950 et succéda à Hans en 1954 ; il présidait encore le conseil à sa mort, le 25 juillet 2025, à 95 ans, et la maison reste familiale, Jvo Grundler lui ayant succédé à la présidence.'), `history`),
  `history_en` = IF(LOCATE(CAST('Jean Villiger founded his cigar workshop in Pfeffikon, in the canton of Lucerne, in 1888. Switzerland is not a tobacco-producing country — but its geographic position at the heart of Europe, its commercial networks, and its tradition of precision craftsmanship made Pfeffikon a logical location for a premium manufacture oriented toward export.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'Jean Villiger founded his cigar workshop in Pfeffikon, in the canton of Lucerne, in 1888. Switzerland is not a tobacco-producing country — but its geographic position at the heart of Europe, its commercial networks, and its tradition of precision craftsmanship made Pfeffikon a logical location for a premium manufacture oriented toward export.', 'Jean Villiger founded his cigar factory in 1888, at home in Pfeffikon, aged 28, says the company''s history page (villigercigars.com, October 2026). He died in 1902 and his widow Louise carried on the business: in 1907 she launched the Villiger Kiel, presented as a cigar with a goose-quill mouthpiece, and in 1910 founded the German subsidiary, today Villiger Söhne GmbH in Waldshut-Tiengen. In 1918 Hans and Max Villiger took over the company under the name Villiger Söhne. Heinrich, Max''s son, joined it in 1950 and succeeded Hans in 1954; he was still chairman of the board when he died on 25 July 2025, aged 95, and the company remains family-owned, Jvo Grundler having succeeded him as chairman.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Jean Villiger fundó su taller de puros en Pfeffikon, en el cantón de Lucerna, en 1888. Suiza no es un país productor de tabaco, pero su posición geográfica en el centro de Europa, sus redes comerciales y su tradición de artesanía de precisión hicieron de Pfeffikon un lugar lógico para una manufactura premium orientada a la exportación.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Jean Villiger fundó su taller de puros en Pfeffikon, en el cantón de Lucerna, en 1888. Suiza no es un país productor de tabaco, pero su posición geográfica en el centro de Europa, sus redes comerciales y su tradición de artesanía de precisión hicieron de Pfeffikon un lugar lógico para una manufactura premium orientada a la exportación.', 'Jean Villiger fundó su fábrica de puros en 1888, en su propia casa de Pfeffikon, a los 28 años, dice la página de historia de la casa (villigercigars.com, octubre de 2026). Murió en 1902 y su viuda Louise continuó el negocio: lanzó en 1907 el Villiger Kiel, presentado como el puro con boquilla de pluma de ganso, y fundó en 1910 la filial alemana, hoy Villiger Söhne GmbH en Waldshut-Tiengen. En 1918, Hans y Max Villiger se hicieron cargo de la empresa con el nombre de Villiger Söhne. Heinrich, hijo de Max, entró en ella en 1950 y sucedió a Hans en 1954; aún presidía el consejo cuando murió, el 25 de julio de 2025, a los 95 años, y la casa sigue siendo familiar, pues Jvo Grundler le sucedió en la presidencia.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Jean Villiger gründete seine Zigarrenwerkstatt 1888 in Pfeffikon im Kanton Luzern. Die Schweiz ist kein Tabakanbauland — doch ihre geografische Lage mitten in Europa, ihre Handelsnetze und ihre Tradition präziser Handwerkskunst machten Pfeffikon zum naheliegenden Ort für eine auf den Export ausgerichtete Premium-Manufaktur.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Jean Villiger gründete seine Zigarrenwerkstatt 1888 in Pfeffikon im Kanton Luzern. Die Schweiz ist kein Tabakanbauland — doch ihre geografische Lage mitten in Europa, ihre Handelsnetze und ihre Tradition präziser Handwerkskunst machten Pfeffikon zum naheliegenden Ort für eine auf den Export ausgerichtete Premium-Manufaktur.', 'Jean Villiger gründete seine Zigarrenfabrik 1888 bei sich zu Hause in Pfeffikon, mit 28 Jahren, sagt die Geschichtsseite des Hauses (villigercigars.com, Oktober 2026). Er starb 1902, und seine Witwe Louise führte das Geschäft weiter: 1907 brachte sie den Villiger Kiel auf den Markt, vorgestellt als Zigarre mit Federkiel-Mundstück, und gründete 1910 die deutsche Tochtergesellschaft, heute Villiger Söhne GmbH in Waldshut-Tiengen. 1918 übernahmen Hans und Max Villiger das Unternehmen unter dem Namen Villiger Söhne. Heinrich, Max'' Sohn, trat 1950 ein und folgte 1954 auf Hans; er stand dem Verwaltungsrat bei seinem Tod am 25. Juli 2025 mit 95 Jahren noch vor, und das Haus bleibt in Familienhand, da Jvo Grundler ihm im Vorsitz nachgefolgt ist.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('1888 年，Jean Villiger 在琉森州的 Pfeffikon 创办了自己的雪茄作坊。瑞士并非烟草产地，但它地处欧洲中心的位置、发达的贸易网络以及精密手工艺传统，使 Pfeffikon 成为一家面向出口的高端制造厂顺理成章的落脚点。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '1888 年，Jean Villiger 在琉森州的 Pfeffikon 创办了自己的雪茄作坊。瑞士并非烟草产地，但它地处欧洲中心的位置、发达的贸易网络以及精密手工艺传统，使 Pfeffikon 成为一家面向出口的高端制造厂顺理成章的落脚点。', 'Jean Villiger 于1888年在 Pfeffikon 的自宅中创办雪茄工厂，时年28岁，据公司历史页面（villigercigars.com，2026年10月）所述。他于1902年去世，遗孀 Louise 继续经营：1907年她推出 Villiger Kiel，被介绍为一款带鹅毛管嘴的雪茄，1910年又创办德国子公司，即今天位于 Waldshut-Tiengen 的 Villiger Söhne GmbH。1918年，Hans 与 Max Villiger 以 Villiger Söhne 之名接手公司。Max 之子 Heinrich 于1950年入职，1954年接替 Hans；他于2025年7月25日去世，享年95岁，去世时仍担任董事会主席，公司依然是家族企业，由 Jvo Grundler 接任主席一职。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('أسّس Jean Villiger ورشته لصناعة السيجار في Pfeffikon بمقاطعة لوتسرن عام 1888. وسويسرا ليست بلداً منتجاً للتبغ، غير أن موقعها في وسط أوروبا وشبكاتها التجارية وتقاليدها في الحرف الدقيقة جعلت من Pfeffikon مكاناً منطقياً لمصنع فاخر موجّه إلى التصدير.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'أسّس Jean Villiger ورشته لصناعة السيجار في Pfeffikon بمقاطعة لوتسرن عام 1888. وسويسرا ليست بلداً منتجاً للتبغ، غير أن موقعها في وسط أوروبا وشبكاتها التجارية وتقاليدها في الحرف الدقيقة جعلت من Pfeffikon مكاناً منطقياً لمصنع فاخر موجّه إلى التصدير.', 'أسّس Jean Villiger مصنعه للسيجار عام 1888 في بيته في Pfeffikon وهو في الثامنة والعشرين، بحسب صفحة تاريخ الدار (villigercigars.com، أكتوبر 2026). وتوفي عام 1902، فواصلت أرملته Louise العمل: أطلقت عام 1907 سيجار Villiger Kiel، الذي يُقدَّم على أنه سيجار بفوهة من ريشة الإوز، وأسّست عام 1910 الفرع الألماني، وهو اليوم Villiger Söhne GmbH في Waldshut-Tiengen. وفي عام 1918 تولّى Hans وMax Villiger الشركة باسم Villiger Söhne. أما Heinrich، ابن Max، فانضم إليها عام 1950 وخلف Hans عام 1954؛ وكان لا يزال يرأس مجلس الإدارة عند وفاته في 25 يوليو 2025 عن 95 عامًا، وتبقى الدار عائلية، إذ خلفه Jvo Grundler في الرئاسة.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Villiger';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('L''originalité de Villiger dans l''industrie européenne tient à une polyvalence rare : la maison maîtrise aussi bien la production de petit format (cigarillos) que les grands formats premium, et couvre un spectre allant du mass-market accessible au haut de gamme de collection. Cette gamme étendue résulte d''une stratégie d''acquisition patiente — Villiger a absorbé plusieurs manufactures européennes au fil des décennies, intégrant savoir-faire et marques.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'L''originalité de Villiger dans l''industrie européenne tient à une polyvalence rare : la maison maîtrise aussi bien la production de petit format (cigarillos) que les grands formats premium, et couvre un spectre allant du mass-market accessible au haut de gamme de collection. Cette gamme étendue résulte d''une stratégie d''acquisition patiente — Villiger a absorbé plusieurs manufactures européennes au fil des décennies, intégrant savoir-faire et marques.', 'La maison a aussi un volet d''importation : 5th Avenue, coentreprise germano-cubaine de 1989 pour les cigares cubains, Intertabak en 1995 pour la Suisse et le Liechtenstein, et El Mundo del Tabaco en 1997 pour les cigares premium non cubains, intégré à Villiger Söhne une dizaine d''années plus tard (même page). Villiger Söhne, le groupe, ne se réduit donc pas à cette fiche : celle-ci ne porte que ses cigares premium faits à la main, et laisse de côté ses cigarillos et cigares de machine, comme l''Export ou le Premium No. 6, pour lesquels aucune page lue n''établit un roulage à la main.'), `history`),
  `history_en` = IF(LOCATE(CAST('Villiger''s originality in the European cigar industry lies in rare versatility: the house masters both small-format production (cigarillos) and large premium formats, covering a spectrum from accessible mass-market to high-end collectibles. This extended range results from a patient acquisition strategy — Villiger has absorbed several European manufacturers over the decades, integrating their expertise and brands.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'Villiger''s originality in the European cigar industry lies in rare versatility: the house masters both small-format production (cigarillos) and large premium formats, covering a spectrum from accessible mass-market to high-end collectibles. This extended range results from a patient acquisition strategy — Villiger has absorbed several European manufacturers over the decades, integrating their expertise and brands.', 'The company also has an importing side: 5th Avenue, a German-Cuban joint venture of 1989 for Cuban cigars, Intertabak in 1995 for Switzerland and Liechtenstein, and El Mundo del Tabaco in 1997 for non-Cuban premium cigars, integrated into Villiger Söhne about ten years later (same page). Villiger Söhne, the group, is therefore not confined to this entry: this one covers only its handmade premium cigars, and leaves aside its cigarillos and machine-made cigars, such as the Export or the Premium No. 6, for which no page read establishes hand-rolling.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La originalidad de Villiger en la industria europea reside en una polivalencia poco común: la casa domina tanto la producción de formatos pequeños (cigarritos) como los grandes formatos premium, y cubre un espectro que va del mercado masivo asequible a la alta gama de coleccionista. Esa amplitud es fruto de una estrategia de adquisiciones paciente: Villiger ha absorbido varias manufacturas europeas a lo largo de las décadas, integrando saber hacer y marcas.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La originalidad de Villiger en la industria europea reside en una polivalencia poco común: la casa domina tanto la producción de formatos pequeños (cigarritos) como los grandes formatos premium, y cubre un espectro que va del mercado masivo asequible a la alta gama de coleccionista. Esa amplitud es fruto de una estrategia de adquisiciones paciente: Villiger ha absorbido varias manufacturas europeas a lo largo de las décadas, integrando saber hacer y marcas.', 'La casa tiene además una vertiente de importación: 5th Avenue, empresa conjunta germano-cubana de 1989 para los puros cubanos, Intertabak en 1995 para Suiza y Liechtenstein, y El Mundo del Tabaco en 1997 para los puros premium no cubanos, integrada en Villiger Söhne una decena de años después (misma página). Villiger Söhne, el grupo, no se reduce por tanto a esta ficha: esta solo recoge sus puros premium hechos a mano y deja de lado sus cigarritos y puros de máquina, como el Export o el Premium No. 6, para los que ninguna página leída establece un liado a mano.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Villigers Eigenart in der europäischen Branche liegt in einer seltenen Vielseitigkeit: Das Haus beherrscht die Herstellung kleiner Formate (Cigarillos) ebenso wie die großen Premiumformate und deckt ein Spektrum vom erschwinglichen Massenmarkt bis zur Sammlerspitze ab. Diese Breite ist das Ergebnis einer geduldigen Zukaufstrategie — über die Jahrzehnte hat Villiger mehrere europäische Manufakturen übernommen und dabei Können wie Marken eingegliedert.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Villigers Eigenart in der europäischen Branche liegt in einer seltenen Vielseitigkeit: Das Haus beherrscht die Herstellung kleiner Formate (Cigarillos) ebenso wie die großen Premiumformate und deckt ein Spektrum vom erschwinglichen Massenmarkt bis zur Sammlerspitze ab. Diese Breite ist das Ergebnis einer geduldigen Zukaufstrategie — über die Jahrzehnte hat Villiger mehrere europäische Manufakturen übernommen und dabei Können wie Marken eingegliedert.', 'Das Haus hat auch ein Importgeschäft: 5th Avenue, ein deutsch-kubanisches Gemeinschaftsunternehmen von 1989 für kubanische Zigarren, Intertabak 1995 für die Schweiz und Liechtenstein und El Mundo del Tabaco 1997 für nichtkubanische Premiumzigarren, rund zehn Jahre später in Villiger Söhne eingegliedert (dieselbe Seite). Villiger Söhne, die Gruppe, geht also nicht in diesem Eintrag auf: Er behandelt nur die handgefertigten Premiumzigarren und lässt die Cigarillos und maschinengefertigten Zigarren aus, wie den Export oder den Premium No. 6, für die keine gelesene Seite Handarbeit belegt.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('Villiger 在欧洲同业中的独特之处，在于罕见的全能：这家老号既精于小规格（小雪茄）的生产，也擅长高端大规格，覆盖从平价大众市场到收藏级顶端的完整区间。如此宽广的产品线源自耐心的收购策略——数十年间，Villiger 陆续并入多家欧洲制造厂，把技艺与品牌一并纳入。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, 'Villiger 在欧洲同业中的独特之处，在于罕见的全能：这家老号既精于小规格（小雪茄）的生产，也擅长高端大规格，覆盖从平价大众市场到收藏级顶端的完整区间。如此宽广的产品线源自耐心的收购策略——数十年间，Villiger 陆续并入多家欧洲制造厂，把技艺与品牌一并纳入。', '公司还有进口业务：5th Avenue，1989年的德古合资企业，经营古巴雪茄；Intertabak，1995年成立，面向瑞士与列支敦士登；El Mundo del Tabaco，1997年成立，经营非古巴高端雪茄，约十年后并入 Villiger Söhne（同一页面）。因此，集团 Villiger Söhne 并不局限于本条目：本条目只收录其手工制作的高端雪茄，不涉及其小雪茄和机制雪茄，例如 Export 或 Premium No. 6，因为已读页面均未证实这些产品为手工卷制。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('تكمن خصوصية Villiger في الصناعة الأوروبية في تنوّع نادر: فالدار تتقن إنتاج الأحجام الصغيرة (السيجارلّو) كما تتقن الأحجام الفاخرة الكبيرة، وتغطي مدى يمتد من السوق الواسعة الميسورة إلى الفئة العليا الموجّهة للجامعين. وهذا الاتساع ثمرة استراتيجية استحواذ متأنّية: فقد ضمّت Villiger على مدى العقود عدة مصانع أوروبية، مستوعبةً خبراتها وعلاماتها.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'تكمن خصوصية Villiger في الصناعة الأوروبية في تنوّع نادر: فالدار تتقن إنتاج الأحجام الصغيرة (السيجارلّو) كما تتقن الأحجام الفاخرة الكبيرة، وتغطي مدى يمتد من السوق الواسعة الميسورة إلى الفئة العليا الموجّهة للجامعين. وهذا الاتساع ثمرة استراتيجية استحواذ متأنّية: فقد ضمّت Villiger على مدى العقود عدة مصانع أوروبية، مستوعبةً خبراتها وعلاماتها.', 'وللدار كذلك جانب استيراد: 5th Avenue، شركة مشتركة ألمانية كوبية من عام 1989 للسيجار الكوبي، وIntertabak عام 1995 لسويسرا وليختنشتاين، وEl Mundo del Tabaco عام 1997 للسيجار الفاخر غير الكوبي، ودُمجت في Villiger Söhne بعد نحو عشر سنوات (الصفحة نفسها). فمجموعة Villiger Söhne لا تنحصر إذن في هذه الصفحة: فهذه الصفحة لا تتناول إلا سيجارها الفاخر المصنوع يدويًا، وتترك جانبًا السيجارلّو والسيجار المصنوع آليًا، مثل Export أو Premium No. 6، إذ لا تثبت أي صفحة قُرئت أنها تُلفّ يدويًا.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Villiger';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('La gamme Premium est la raison pour laquelle les collectionneurs sérieux s''intéressent à Villiger. Utilisant du tabac brésilien, équatorien et indonésien dans des assemblages supervisés personnellement par Heinrich Villiger (quatrième génération) jusqu''à sa retraite en 2020, les cigares Premium incarnent une approche suisse de la cigariculture : précision, régularité, élégance discrète.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'La gamme Premium est la raison pour laquelle les collectionneurs sérieux s''intéressent à Villiger. Utilisant du tabac brésilien, équatorien et indonésien dans des assemblages supervisés personnellement par Heinrich Villiger (quatrième génération) jusqu''à sa retraite en 2020, les cigares Premium incarnent une approche suisse de la cigariculture : précision, régularité, élégance discrète.', 'En 2021, Villiger a ouvert sa propre usine à Estelí, au Nicaragua, avec environ 150 spécialistes et une quinzaine de marques ; c''est là que le classement de la fiche s''appuie, des lignes de la gamme se roulant aussi en République dominicaine, chez ABAM et chez Tabacalera Palma. L''état de la maison se lit en octobre 2026 sur sa page d''histoire.'), `history`),
  `history_en` = IF(LOCATE(CAST('The Premium range is the reason serious collectors take notice of Villiger. Using Brazilian, Ecuadorian, and Indonesian tobacco in blends personally supervised by Heinrich Villiger (fourth generation) until his retirement in 2020, the Premium cigars embody a Swiss approach to cigariculture: precision, consistency, discreet elegance.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The Premium range is the reason serious collectors take notice of Villiger. Using Brazilian, Ecuadorian, and Indonesian tobacco in blends personally supervised by Heinrich Villiger (fourth generation) until his retirement in 2020, the Premium cigars embody a Swiss approach to cigariculture: precision, consistency, discreet elegance.', 'In 2021, Villiger opened its own factory in Estelí, Nicaragua, with about 150 specialists and some fifteen brands; this is where the entry''s classification rests, some lines of the range also being rolled in the Dominican Republic, at ABAM and at Tabacalera Palma. The state of the company can be read in October 2026 on its history page.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La gama Premium es la razón por la que los coleccionistas serios se interesan por Villiger. Con tabaco brasileño, ecuatoriano e indonesio en ligadas supervisadas personalmente por Heinrich Villiger (cuarta generación) hasta su retirada en 2020, los puros Premium encarnan un enfoque suizo del arte del puro: precisión, regularidad, elegancia discreta.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La gama Premium es la razón por la que los coleccionistas serios se interesan por Villiger. Con tabaco brasileño, ecuatoriano e indonesio en ligadas supervisadas personalmente por Heinrich Villiger (cuarta generación) hasta su retirada en 2020, los puros Premium encarnan un enfoque suizo del arte del puro: precisión, regularidad, elegancia discreta.', 'En 2021, Villiger abrió su propia fábrica en Estelí, Nicaragua, con unos 150 especialistas y una quincena de marcas; en ella se apoya la clasificación de la ficha, ya que algunas líneas de la gama también se lían en la República Dominicana, en ABAM y en Tabacalera Palma. El estado de la casa se lee en octubre de 2026 en su página de historia.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die Premium-Linie ist der Grund, weshalb ernsthafte Sammler sich für Villiger interessieren. Mit brasilianischem, ecuadorianischem und indonesischem Tabak in Mischungen, die Heinrich Villiger (vierte Generation) bis zu seinem Rückzug 2020 persönlich überwachte, verkörpern die Premium-Zigarren eine schweizerische Auffassung der Zigarrenkunst: Präzision, Gleichmäßigkeit, unaufdringliche Eleganz.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die Premium-Linie ist der Grund, weshalb ernsthafte Sammler sich für Villiger interessieren. Mit brasilianischem, ecuadorianischem und indonesischem Tabak in Mischungen, die Heinrich Villiger (vierte Generation) bis zu seinem Rückzug 2020 persönlich überwachte, verkörpern die Premium-Zigarren eine schweizerische Auffassung der Zigarrenkunst: Präzision, Gleichmäßigkeit, unaufdringliche Eleganz.', '2021 eröffnete Villiger in Estelí, Nicaragua, eine eigene Fabrik mit rund 150 Fachkräften und etwa fünfzehn Marken; auf sie stützt sich die Einordnung des Eintrags, wobei einzelne Linien der Reihe auch in der Dominikanischen Republik gerollt werden, bei ABAM und bei Tabacalera Palma. Der Stand des Hauses lässt sich im Oktober 2026 auf seiner Geschichtsseite ablesen.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('认真的收藏者之所以关注 Villiger，正是因为 Premium 系列。它以巴西、厄瓜多尔与印尼烟叶配制，直到 2020 年退休为止，配方一直由第四代的 Heinrich Villiger 亲自把关。Premium 雪茄体现的是一种瑞士式的制茄理念：精准、稳定、含蓄的优雅。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '认真的收藏者之所以关注 Villiger，正是因为 Premium 系列。它以巴西、厄瓜多尔与印尼烟叶配制，直到 2020 年退休为止，配方一直由第四代的 Heinrich Villiger 亲自把关。Premium 雪茄体现的是一种瑞士式的制茄理念：精准、稳定、含蓄的优雅。', '2021年，Villiger 在尼加拉瓜埃斯特利开设了自己的工厂，约有150名专业人员和十五个左右的品牌；本条目的归类即以此为依据，产品线中也有一些在多米尼加共和国的 ABAM 和 Tabacalera Palma 卷制。该公司的现状可于2026年10月在其历史页面上读到。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('تشكيلة Premium هي سبب اهتمام كبار الجامعين بـ Villiger. فهي تعتمد تبغاً برازيلياً وإكوادورياً وإندونيسياً في خلطات أشرف عليها شخصياً Heinrich Villiger (الجيل الرابع) حتى تقاعده عام 2020، وتجسّد رؤية سويسرية لصناعة السيجار: دقة وانتظام وأناقة هادئة.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'تشكيلة Premium هي سبب اهتمام كبار الجامعين بـ Villiger. فهي تعتمد تبغاً برازيلياً وإكوادورياً وإندونيسياً في خلطات أشرف عليها شخصياً Heinrich Villiger (الجيل الرابع) حتى تقاعده عام 2020، وتجسّد رؤية سويسرية لصناعة السيجار: دقة وانتظام وأناقة هادئة.', 'في عام 2021 افتتحت Villiger مصنعها الخاص في إستيلي بنيكاراغوا، بنحو 150 متخصصًا ونحو خمس عشرة علامة؛ وعليه يستند تصنيف هذه الصفحة، علمًا أن بعض خطوط التشكيلة تُلفّ أيضًا في جمهورية الدومينيكان، لدى ABAM ولدى Tabacalera Palma. ويمكن الاطلاع على حال الدار في أكتوبر 2026 في صفحة تاريخها.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Villiger';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST(CONCAT('', CHAR(13), '
', CHAR(13), '
L''Export — le cigarillo brun à l''arôme café distinctif — est probablement le cigare suisse le plus vendu de l''histoire. Sa forme tubulaire, son bandeau rouge reconnaissable et son prix accessible en ont fait l''introduction au tabac premium pour des millions de fumeurs européens depuis 1946. Ce n''est pas le produit le plus ambitieux de Villiger — c''est celui qui a financé tout le reste et construit la marque sur deux générations.') AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, CONCAT('', CHAR(13), '
', CHAR(13), '
L''Export — le cigarillo brun à l''arôme café distinctif — est probablement le cigare suisse le plus vendu de l''histoire. Sa forme tubulaire, son bandeau rouge reconnaissable et son prix accessible en ont fait l''introduction au tabac premium pour des millions de fumeurs européens depuis 1946. Ce n''est pas le produit le plus ambitieux de Villiger — c''est celui qui a financé tout le reste et construit la marque sur deux générations.'), ''), `history`),
  `history_en` = IF(LOCATE(CAST(CONCAT('', CHAR(13), '
', CHAR(13), '
The Export — the brown cigarillo with its distinctive coffee aroma — is probably the best-selling Swiss cigar in history. Its tubular form, recognizable red band, and accessible price made it the introduction to premium tobacco for millions of European smokers since 1946. It is not Villiger''s most ambitious product — it is the one that funded everything else and built the brand over two generations.') AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, CONCAT('', CHAR(13), '
', CHAR(13), '
The Export — the brown cigarillo with its distinctive coffee aroma — is probably the best-selling Swiss cigar in history. Its tubular form, recognizable red band, and accessible price made it the introduction to premium tobacco for millions of European smokers since 1946. It is not Villiger''s most ambitious product — it is the one that funded everything else and built the brand over two generations.'), ''), `history_en`),
  `history_es` = IF(LOCATE(CAST('

El Export —el cigarrito marrón de característico aroma a café— es probablemente el puro suizo más vendido de la historia. Su forma tubular, su reconocible anilla roja y su precio asequible lo convirtieron desde 1946 en la puerta de entrada al tabaco premium para millones de fumadores europeos. No es el producto más ambicioso de Villiger: es el que ha financiado todo lo demás y ha construido la marca a lo largo de dos generaciones.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, '

El Export —el cigarrito marrón de característico aroma a café— es probablemente el puro suizo más vendido de la historia. Su forma tubular, su reconocible anilla roja y su precio asequible lo convirtieron desde 1946 en la puerta de entrada al tabaco premium para millones de fumadores europeos. No es el producto más ambicioso de Villiger: es el que ha financiado todo lo demás y ha construido la marca a lo largo de dos generaciones.', ''), `history_es`),
  `history_de` = IF(LOCATE(CAST('

Der Export — das braune Cigarillo mit dem unverwechselbaren Kaffeearoma — ist wohl die meistverkaufte Schweizer Zigarre der Geschichte. Seine röhrenförmige Gestalt, sein wiedererkennbarer roter Ring und sein erschwinglicher Preis machten ihn seit 1946 für Millionen europäischer Raucher zum Einstieg in den Premiumtabak. Es ist nicht das ehrgeizigste Erzeugnis Villigers — es ist jenes, das alles Übrige finanziert und die Marke über zwei Generationen aufgebaut hat.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, '

Der Export — das braune Cigarillo mit dem unverwechselbaren Kaffeearoma — ist wohl die meistverkaufte Schweizer Zigarre der Geschichte. Seine röhrenförmige Gestalt, sein wiedererkennbarer roter Ring und sein erschwinglicher Preis machten ihn seit 1946 für Millionen europäischer Raucher zum Einstieg in den Premiumtabak. Es ist nicht das ehrgeizigste Erzeugnis Villigers — es ist jenes, das alles Übrige finanziert und die Marke über zwei Generationen aufgebaut hat.', ''), `history_de`),
  `history_zh` = IF(LOCATE(CAST('

Export——那支带独特咖啡香气的棕色小雪茄——很可能是历史上销量最高的瑞士雪茄。管状外形、辨识度极高的红色茄标与亲民价格，使它自 1946 年起成为数百万欧洲烟民进入高端烟草的入口。它不是 Villiger 最具野心的产品，却是养活了其余一切、并用两代人时间铸就品牌的那一支。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '

Export——那支带独特咖啡香气的棕色小雪茄——很可能是历史上销量最高的瑞士雪茄。管状外形、辨识度极高的红色茄标与亲民价格，使它自 1946 年起成为数百万欧洲烟民进入高端烟草的入口。它不是 Villiger 最具野心的产品，却是养活了其余一切、并用两代人时间铸就品牌的那一支。', ''), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('

أما Export — ذلك السيجارلّو البنّي ذو رائحة القهوة المميّزة — فهو على الأرجح أكثر سيجار سويسري مبيعاً في التاريخ. شكله الأنبوبي وطوقه الأحمر سهل التمييز وسعره المتناول جعلته منذ 1946 باب الدخول إلى التبغ الفاخر لملايين المدخّنين الأوروبيين. ليس أطمح منتجات Villiger، لكنه المنتج الذي موّل كل ما عداه وبنى العلامة على مدى جيلين.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, '

أما Export — ذلك السيجارلّو البنّي ذو رائحة القهوة المميّزة — فهو على الأرجح أكثر سيجار سويسري مبيعاً في التاريخ. شكله الأنبوبي وطوقه الأحمر سهل التمييز وسعره المتناول جعلته منذ 1946 باب الدخول إلى التبغ الفاخر لملايين المدخّنين الأوروبيين. ليس أطمح منتجات Villiger، لكنه المنتج الذي موّل كل ما عداه وبنى العلامة على مدى جيلين.', ''), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Villiger';

UPDATE `brands` SET
  `country_id` = 'nicaragua',
  `gamme` = '[{"name":"Villiger La Meridiana","color":"#2C1A0E","story":"Puro entièrement nicaraguayen sorti en Europe en 1998, qui reprend le nom d''une fabrique havanaise du XIXe siècle, disent Cigar Coop et Blind Man''s Puff en mars 2019 ; Cigar Coop le dit alors roulé chez Joya de Nicaragua, à Estelí. Cigarworld.de, détaillant allemand, donne en octobre 2026 une cape H-2000, un liant Connecticut et une tripe, tous du Nicaragua, en longfiller. Villiger la compte parmi les marques de son usine d''Estelí, achevée fin septembre 2021.","wrapper":"Nicaragua (H-2000)","force":null},{"name":"Cuéllar","color":"#5C3317","story":"Série de trois cigares dominicains, Connecticut Krēmē, Black Forest et Caribe, produite par Tabacalera Palma, la fabrique de Jochy Blanco en République dominicaine, disent Cigar Coop en 2019, en janvier 2025 et en mai 2025. Black Forest, annoncé en octobre 2019, a une cape maduro sur liant et tripe dominicains ; Caribe, annoncé le 31 janvier 2025, une cape habano d''Équateur sur liant et tripe dominicains, que Neptune Cigar, détaillant, dit en octobre 2026 fait chez Tabacalera La Palma.","wrapper":"Connecticut / Maduro / Habano","force":null},{"name":"Havana Club","color":"#7A2E1E","force":"Medium","story":"Un nom de vieille marque cubaine, relancé par Villiger en 2007 comme cigare dominicain, roulé à l''ABAM, la fabrique de Santo Domingo que Cigar Coop dit en mars 2018 propriété de José « Matias » Maragoto et chargée de rouler les cigares dominicains de Villiger.","vitolas":[],"wrapper":"Non divulguée"},{"name":"Dominico","color":"#C9A96E","force":"Mild-Medium","story":"Ligne de République dominicaine que la page de la maison, en octobre 2026, dit légère à moyenne et abordable, de niveau 2 sur 5 sur l''échelle de Villiger, en cinq formats : Perla, Corona, Robusto, Torpedo et Churchill. Cigarworld.de, détaillant allemand, la dit roulée à la main en longfiller à ABAM Cigars, en bundles, sous une cape Connecticut Shade d''Équateur, avec un liant d''Indonésie et une tripe Piloto de République dominicaine et du Nicaragua ; la marque date du début des années 2000 selon ce détaillant, qui la tient à son catalogue, pour la Corona, depuis le 7 décembre 2010.","vitolas":[],"wrapper":"Connecticut Shade (Équateur)"},{"name":"Casa de Nicaragua","color":"#8B5A2B","force":"Medium-Full","story":"Présentée en 2014 par Villiger selon Cigarworld.de, qui la tient à son catalogue depuis le 12 août 2014 et la dit roulée à la main en mediumfiller, sous une cape H-2000 d''Équateur, avec un liant d''Indonésie et une tripe du Nicaragua. Villiger la compte parmi les marques de son usine d''Estelí, achevée fin septembre 2021 ; en octobre 2026, la page de la maison donne cinq formats d''origine Nicaragua (Perla, Corona, Robusto, Torpedo, Churchill), de niveau 4 sur 5 sur son échelle.","vitolas":[],"wrapper":"Équateur (H-2000)"},{"name":"La Libertad","color":"#8B5A2B","force":"Medium-Full","story":"Apparue au début des années 2000 chez Liberty Cigar Company, en Allemagne, puis entrée dans le groupe Villiger, elle a quitté le Honduras, où Plasencia la roulait, puis la République dominicaine, où ABAM la roulait, pour Estelí : un nouveau mélange, cape criollo du Nicaragua, liant du Cibao dominicain, tripe nicaraguayenne de Jalapa et d''Estelí, est montré en janvier 2022 au salon TPE de Las Vegas, en Corona, Robusto et Gran Toro. En octobre 2026, la page de la maison la range parmi ses cigares faits à la main, en quatre formats (Gordito, Robusto, Corona, Gran Toro) de niveau 4 sur 5 sur son échelle.","vitolas":[],"wrapper":"Criollo (Nicaragua)"},{"name":"La Capitana","color":"#C9A96E","force":"Mild-Medium","story":"Relancée en 2025 avec un nouveau mélange, cape Connecticut Shade d''Équateur, liant du Nicaragua, tripe du Nicaragua et de République dominicaine, annoncée au salon PCA en avril 2025 en Lonsdale (6 x 43), Robusto (5 x 50), Toro (6 x 50) et Churchill (7 x 50) ; la version précédente avait une cape habano, dit un compte rendu de juillet 2026. Cigarworld.de la dit roulée à la main en longfiller à Estelí par Tabacalera Villiger de Nicaragua, dans les locaux de Joya de Nicaragua, et la tient à son catalogue depuis le 28 août 2025 ; en octobre 2026, la page de la maison donne Robusto, Toro et Churchill, de niveau 2 sur 5 sur son échelle.","vitolas":[],"wrapper":"Connecticut (Équateur)"},{"name":"Corrida","color":"#8B5A2B","force":null,"story":"Lancée en Europe en mai 2017 en deux versions, Honduras (roulée à Danlí par Nestor A. Plasencia, dit un compte rendu de lancement) et République dominicaine (faite à ABAM, dit un autre compte rendu), en Robusto+ (5 x 56) et Toro+ (6 x 52). En octobre 2026, la page de la maison la présente en quatre origines, Honduras, République dominicaine, Nicaragua et Brésil, de niveau 4, 2,5, 5 et 3,5 sur 5 sur son échelle, et la destine aux amateurs de cigares roulés à la main ; Villiger compte Corrida parmi les marques de son usine d''Estelí, achevée fin septembre 2021.","vitolas":[],"wrapper":"Non divulguée"},{"name":"Nicaroma","color":"#8B5A2B","force":"Medium-Full","story":"Série présentée à InterTabac 2023, à Dortmund, selon Cigarworld.de, qui la dit roulée à la main en longfiller à Estelí en partenariat avec Joya de Nicaragua, cape et tripe du Nicaragua sur un liant d''Indonésie, et la tient à son catalogue depuis le 25 septembre 2023 pour le 5 x 52. En octobre 2026, la page de la maison donne trois formats nommés par leurs dimensions, 4 x 56, 5 x 52 et 6 x 54, de niveau 4 sur 5 sur son échelle ; un aperçu d''avril 2013 présentait déjà sous ce nom une ligne à trois capes.","vitolas":[],"wrapper":"Nicaragua"}]',
  `gamme_en` = '[{"name":"Villiger La Meridiana","color":"#2C1A0E","story":"An entirely Nicaraguan puro released in Europe in 1998, taking the name of a nineteenth-century Havana factory, say Cigar Coop and Blind Man''s Puff in March 2019; Cigar Coop then says it is rolled at Joya de Nicaragua, in Estelí. Cigarworld.de, a German retailer, gives in October 2026 an H-2000 wrapper, a Connecticut binder and a filler, all from Nicaragua, in longfiller. Villiger counts it among the brands of its factory in Estelí, completed at the end of September 2021.","wrapper":"Nicaragua (H-2000)","force":null},{"name":"Cuéllar","color":"#5C3317","story":"A series of three Dominican cigars, Connecticut Krēmē, Black Forest and Caribe, produced by Tabacalera Palma, Jochy Blanco''s factory in the Dominican Republic, say Cigar Coop in 2019, in January 2025 and in May 2025. Black Forest, announced in October 2019, has a maduro wrapper over a Dominican binder and filler; Caribe, announced on 31 January 2025, an Ecuadorian habano wrapper over a Dominican binder and filler, which Neptune Cigar, a retailer, says in October 2026 is made at Tabacalera La Palma.","wrapper":"Connecticut / Maduro / Habano","force":null},{"name":"Havana Club","color":"#7A2E1E","force":"Medium","story":"An old Cuban brand name, relaunched by Villiger in 2007 as a Dominican cigar, rolled at ABAM, the Santo Domingo factory that Cigar Coop, in March 2018, says is owned by José “Matias” Maragoto and tasked with rolling Villiger''s Dominican cigars.","vitolas":[],"wrapper":"Undisclosed"},{"name":"Dominico","color":"#C9A96E","force":"Mild-Medium","story":"A line from the Dominican Republic that the company''s page, in October 2026, calls light to medium and affordable, at level 2 of 5 on Villiger''s scale, in five sizes: Perla, Corona, Robusto, Torpedo and Churchill. Cigarworld.de, a German retailer, says it is hand-rolled longfiller at ABAM Cigars, in bundles, under a Connecticut Shade wrapper from Ecuador, with a binder from Indonesia and a Piloto filler from the Dominican Republic and Nicaragua; the brand dates from the early 2000s according to that retailer, which has carried it in its catalogue, for the Corona, since 7 December 2010.","vitolas":[],"wrapper":"Connecticut Shade (Ecuador)"},{"name":"Casa de Nicaragua","color":"#8B5A2B","force":"Medium-Full","story":"Presented in 2014 by Villiger, according to Cigarworld.de, which has carried it in its catalogue since 12 August 2014 and says it is hand-rolled mediumfiller, under an H-2000 wrapper from Ecuador, with a binder from Indonesia and a filler from Nicaragua. Villiger counts it among the brands of its factory in Estelí, completed at the end of September 2021; in October 2026, the company''s page gives five sizes of Nicaraguan origin (Perla, Corona, Robusto, Torpedo, Churchill), at level 4 of 5 on its scale.","vitolas":[],"wrapper":"Ecuador (H-2000)"},{"name":"La Libertad","color":"#8B5A2B","force":"Medium-Full","story":"It appeared in the early 2000s at Liberty Cigar Company, in Germany, then joined the Villiger group, and it left Honduras, where Plasencia rolled it, then the Dominican Republic, where ABAM rolled it, for Estelí: a new blend, with a criollo wrapper from Nicaragua, a binder from the Dominican Cibao and a Nicaraguan filler from Jalapa and Estelí, was shown in January 2022 at the TPE show in Las Vegas, in Corona, Robusto and Gran Toro. In October 2026, the company''s page places it among its handmade cigars, in four sizes (Gordito, Robusto, Corona, Gran Toro), at level 4 of 5 on its scale.","vitolas":[],"wrapper":"Criollo (Nicaragua)"},{"name":"La Capitana","color":"#C9A96E","force":"Mild-Medium","story":"Relaunched in 2025 with a new blend, a Connecticut Shade wrapper from Ecuador, a binder from Nicaragua and a filler from Nicaragua and the Dominican Republic, it was announced at the PCA show in April 2025 in Lonsdale (6 x 43), Robusto (5 x 50), Toro (6 x 50) and Churchill (7 x 50); the previous version had a habano wrapper, says a report from July 2026. Cigarworld.de says it is hand-rolled longfiller in Estelí by Tabacalera Villiger de Nicaragua, on the premises of Joya de Nicaragua, and has carried it in its catalogue since 28 August 2025; in October 2026, the company''s page gives Robusto, Toro and Churchill, at level 2 of 5 on its scale.","vitolas":[],"wrapper":"Connecticut (Ecuador)"},{"name":"Corrida","color":"#8B5A2B","force":null,"story":"Launched in Europe in May 2017 in two versions, Honduras (rolled in Danlí by Nestor A. Plasencia, says a launch report) and Dominican Republic (made at ABAM, says another report), in Robusto+ (5 x 56) and Toro+ (6 x 52). In October 2026, the company''s page presents it in four origins, Honduras, the Dominican Republic, Nicaragua and Brazil, at levels 4, 2.5, 5 and 3.5 of 5 on its scale, and aims it at enthusiasts of hand-rolled cigars; Villiger counts Corrida among the brands of its factory in Estelí, completed at the end of September 2021.","vitolas":[],"wrapper":"Undisclosed"},{"name":"Nicaroma","color":"#8B5A2B","force":"Medium-Full","story":"A series presented at InterTabac 2023, in Dortmund, according to Cigarworld.de, which says it is hand-rolled longfiller in Estelí in partnership with Joya de Nicaragua, with wrapper and filler from Nicaragua and a binder from Indonesia, and has carried it in its catalogue since 25 September 2023 for the 5 x 52. In October 2026, the company''s page gives three sizes named by their dimensions, 4 x 56, 5 x 52 and 6 x 54, at level 4 of 5 on its scale; a preview from April 2013 already presented a three-wrapper line under this name.","vitolas":[],"wrapper":"Nicaragua"}]',
  `gamme_es` = '[{"name":"Villiger La Meridiana","color":"#2C1A0E","story":"Puro enteramente nicaragüense salido en Europa en 1998, que retoma el nombre de una fábrica habanera del siglo XIX, dicen Cigar Coop y Blind Man''s Puff en marzo de 2019; Cigar Coop lo dice entonces liado en Joya de Nicaragua, en Estelí. Cigarworld.de, minorista alemán, da en octubre de 2026 una capa H-2000, un capote Connecticut y una tripa, todos de Nicaragua, en longfiller. Villiger la cuenta entre las marcas de su fábrica de Estelí, terminada a finales de septiembre de 2021.","wrapper":"Nicaragua (H-2000)","force":null},{"name":"Cuéllar","color":"#5C3317","story":"Serie de tres puros dominicanos, Connecticut Krēmē, Black Forest y Caribe, producida por Tabacalera Palma, la fábrica de Jochy Blanco en la República Dominicana, dice Cigar Coop en 2019, en enero de 2025 y en mayo de 2025. Black Forest, anunciado en octubre de 2019, tiene una capa maduro sobre capote y tripa dominicanos; Caribe, anunciado el 31 de enero de 2025, una capa habano de Ecuador sobre capote y tripa dominicanos, que Neptune Cigar, minorista, dice en octubre de 2026 que se hace en Tabacalera La Palma.","wrapper":"Connecticut / Maduro / Habano","force":null},{"name":"Havana Club","color":"#7A2E1E","force":"Medium","story":"Un nombre de vieja marca cubana, relanzado por Villiger en 2007 como puro dominicano, liado en ABAM, la fábrica de Santo Domingo que Cigar Coop dice en marzo de 2018 propiedad de José «Matias» Maragoto y encargada de liar los puros dominicanos de Villiger.","vitolas":[],"wrapper":"No divulgada"},{"name":"Dominico","color":"#C9A96E","force":"Mild-Medium","story":"Línea de la República Dominicana que la página de la casa, en octubre de 2026, califica de ligera a media y asequible, de nivel 2 sobre 5 en la escala de Villiger, en cinco formatos: Perla, Corona, Robusto, Torpedo y Churchill. Cigarworld.de, minorista alemán, indica que está enrollada a mano en longfiller en ABAM Cigars, en bundles, con capa Connecticut Shade de Ecuador, capote de Indonesia y tripa Piloto de la República Dominicana y de Nicaragua; la marca data de principios de los años 2000 según ese minorista, que la tiene en su catálogo, para la Corona, desde el 7 de diciembre de 2010.","vitolas":[],"wrapper":"Connecticut Shade (Ecuador)"},{"name":"Casa de Nicaragua","color":"#8B5A2B","force":"Medium-Full","story":"Presentada en 2014 por Villiger según Cigarworld.de, que la tiene en su catálogo desde el 12 de agosto de 2014 e indica que está enrollada a mano en mediumfiller, con capa H-2000 de Ecuador, capote de Indonesia y tripa de Nicaragua. Villiger la cuenta entre las marcas de su fábrica de Estelí, terminada a finales de septiembre de 2021; en octubre de 2026, la página de la casa ofrece cinco formatos de origen Nicaragua (Perla, Corona, Robusto, Torpedo, Churchill), de nivel 4 sobre 5 en su escala.","vitolas":[],"wrapper":"Ecuador (H-2000)"},{"name":"La Libertad","color":"#8B5A2B","force":"Medium-Full","story":"Surgida a principios de los años 2000 en Liberty Cigar Company, en Alemania, y después integrada en el grupo Villiger, dejó Honduras, donde la enrollaba Plasencia, y luego la República Dominicana, donde la enrollaba ABAM, para pasar a Estelí: una nueva mezcla, con capa criollo de Nicaragua, capote del Cibao dominicano y tripa nicaragüense de Jalapa y de Estelí, se mostró en enero de 2022 en el salón TPE de Las Vegas, en Corona, Robusto y Gran Toro. En octubre de 2026, la página de la casa la sitúa entre sus puros hechos a mano, en cuatro formatos (Gordito, Robusto, Corona, Gran Toro), de nivel 4 sobre 5 en su escala.","vitolas":[],"wrapper":"Criollo (Nicaragua)"},{"name":"La Capitana","color":"#C9A96E","force":"Mild-Medium","story":"Relanzada en 2025 con una nueva mezcla, capa Connecticut Shade de Ecuador, capote de Nicaragua, tripa de Nicaragua y de la República Dominicana, anunciada en el salón PCA en abril de 2025 en Lonsdale (6 x 43), Robusto (5 x 50), Toro (6 x 50) y Churchill (7 x 50); la versión anterior tenía una capa habano, dice una crónica de julio de 2026. Cigarworld.de indica que está enrollada a mano en longfiller en Estelí por Tabacalera Villiger de Nicaragua, en las instalaciones de Joya de Nicaragua, y la tiene en su catálogo desde el 28 de agosto de 2025; en octubre de 2026, la página de la casa ofrece Robusto, Toro y Churchill, de nivel 2 sobre 5 en su escala.","vitolas":[],"wrapper":"Connecticut (Ecuador)"},{"name":"Corrida","color":"#8B5A2B","force":null,"story":"Lanzada en Europa en mayo de 2017 en dos versiones, Honduras (enrollada en Danlí por Nestor A. Plasencia, dice una crónica del lanzamiento) y República Dominicana (hecha en ABAM, dice otra crónica), en Robusto+ (5 x 56) y Toro+ (6 x 52). En octubre de 2026, la página de la casa la presenta en cuatro orígenes, Honduras, República Dominicana, Nicaragua y Brasil, de nivel 4, 2,5, 5 y 3,5 sobre 5 en su escala, y la destina a los aficionados a los puros enrollados a mano; Villiger cuenta Corrida entre las marcas de su fábrica de Estelí, terminada a finales de septiembre de 2021.","vitolas":[],"wrapper":"No divulgada"},{"name":"Nicaroma","color":"#8B5A2B","force":"Medium-Full","story":"Serie presentada en InterTabac 2023, en Dortmund, según Cigarworld.de, que indica que está enrollada a mano en longfiller en Estelí en colaboración con Joya de Nicaragua, con capa y tripa de Nicaragua sobre un capote de Indonesia, y la tiene en su catálogo desde el 25 de septiembre de 2023 para el 5 x 52. En octubre de 2026, la página de la casa ofrece tres formatos designados por sus dimensiones, 4 x 56, 5 x 52 y 6 x 54, de nivel 4 sobre 5 en su escala; un avance de abril de 2013 presentaba ya con ese nombre una línea de tres capas.","vitolas":[],"wrapper":"Nicaragua"}]',
  `gamme_de` = '[{"name":"Villiger La Meridiana","color":"#2C1A0E","story":"Vollständig nicaraguanische Puro-Zigarre, 1998 in Europa erschienen, die den Namen einer Havanner Fabrik des 19. Jahrhunderts übernimmt, sagen Cigar Coop und Blind Man''s Puff im März 2019; Cigar Coop sagt, sie werde damals bei Joya de Nicaragua in Estelí gerollt. Cigarworld.de, ein deutscher Händler, nennt im Oktober 2026 ein H-2000-Deckblatt, ein Connecticut-Umblatt und eine Einlage, alle aus Nicaragua, als Longfiller. Villiger zählt sie zu den Marken seiner Fabrik in Estelí, Ende September 2021 fertiggestellt.","wrapper":"Nicaragua (H-2000)","force":null},{"name":"Cuéllar","color":"#5C3317","story":"Serie aus drei dominikanischen Zigarren, Connecticut Krēmē, Black Forest und Caribe, hergestellt von Tabacalera Palma, der Fabrik von Jochy Blanco in der Dominikanischen Republik, so Cigar Coop 2019, im Januar 2025 und im Mai 2025. Black Forest, im Oktober 2019 angekündigt, hat ein Maduro-Deckblatt auf dominikanischem Umblatt und dominikanischer Einlage; Caribe, am 31. Januar 2025 angekündigt, ein Habano-Deckblatt aus Ecuador auf dominikanischem Umblatt und dominikanischer Einlage, die laut Neptune Cigar, einem Händler, im Oktober 2026 bei Tabacalera La Palma gefertigt wird.","wrapper":"Connecticut / Maduro / Habano","force":null},{"name":"Havana Club","color":"#7A2E1E","force":"Medium","story":"Ein alter kubanischer Markenname, 2007 von Villiger als dominikanische Zigarre neu lanciert, gerollt bei ABAM, der Fabrik in Santo Domingo, die nach Angabe von Cigar Coop im März 2018 José „Matias“ Maragoto gehört und damit beauftragt ist, die dominikanischen Zigarren von Villiger zu rollen.","vitolas":[],"wrapper":"Nicht angegeben"},{"name":"Dominico","color":"#C9A96E","force":"Mild-Medium","story":"Eine Linie aus der Dominikanischen Republik; die Seite des Hauses nennt sie im Oktober 2026 leicht bis mittelkräftig und erschwinglich, auf Stufe 2 von 5 der Villiger-Skala, in fünf Formaten: Perla, Corona, Robusto, Torpedo und Churchill. Cigarworld.de, ein deutscher Händler, gibt an, sie sei bei ABAM Cigars als Longfiller von Hand gerollt, in Bundles, mit einem Deckblatt Connecticut Shade aus Ecuador, einem Umblatt aus Indonesien und einer Einlage Piloto aus der Dominikanischen Republik und aus Nicaragua; die Marke stammt laut diesem Händler aus dem Anfang der 2000er-Jahre, und er führt sie, für die Corona, seit dem 7. Dezember 2010 in seinem Katalog.","vitolas":[],"wrapper":"Connecticut Shade (Ecuador)"},{"name":"Casa de Nicaragua","color":"#8B5A2B","force":"Medium-Full","story":"Laut Cigarworld.de wurde sie 2014 von Villiger vorgestellt; der Händler führt sie seit dem 12. August 2014 in seinem Katalog und gibt an, sie sei als Mediumfiller von Hand gerollt, mit einem Deckblatt H-2000 aus Ecuador, einem Umblatt aus Indonesien und einer Einlage aus Nicaragua. Villiger zählt sie zu den Marken seiner Fabrik in Estelí, die Ende September 2021 fertiggestellt wurde; im Oktober 2026 nennt die Seite des Hauses fünf Formate nicaraguanischer Herkunft (Perla, Corona, Robusto, Torpedo, Churchill), auf Stufe 4 von 5 der Skala des Hauses.","vitolas":[],"wrapper":"Ecuador (H-2000)"},{"name":"La Libertad","color":"#8B5A2B","force":"Medium-Full","story":"Anfang der 2000er-Jahre bei der Liberty Cigar Company in Deutschland entstanden und dann zur Villiger-Gruppe gekommen, hat sie Honduras verlassen, wo Plasencia sie rollte, danach die Dominikanische Republik, wo ABAM sie rollte, und ist nach Estelí gezogen: Eine neue Mischung, mit einem Deckblatt criollo aus Nicaragua, einem Umblatt aus dem dominikanischen Cibao und einer nicaraguanischen Einlage aus Jalapa und Estelí, wurde im Januar 2022 auf der Messe TPE in Las Vegas gezeigt, als Corona, Robusto und Gran Toro. Im Oktober 2026 führt die Seite des Hauses sie unter ihren handgefertigten Zigarren auf, in vier Formaten (Gordito, Robusto, Corona, Gran Toro), auf Stufe 4 von 5 der Skala des Hauses.","vitolas":[],"wrapper":"Criollo (Nicaragua)"},{"name":"La Capitana","color":"#C9A96E","force":"Mild-Medium","story":"2025 mit einer neuen Mischung neu aufgelegt, Deckblatt Connecticut Shade aus Ecuador, Umblatt aus Nicaragua, Einlage aus Nicaragua und der Dominikanischen Republik, auf der Messe PCA im April 2025 angekündigt als Lonsdale (6 x 43), Robusto (5 x 50), Toro (6 x 50) und Churchill (7 x 50); die vorherige Version hatte ein Deckblatt habano, sagt ein Bericht vom Juli 2026. Cigarworld.de gibt an, sie sei in Estelí von Tabacalera Villiger de Nicaragua als Longfiller von Hand gerollt worden, in den Räumen von Joya de Nicaragua, und führt sie seit dem 28. August 2025 in seinem Katalog; im Oktober 2026 nennt die Seite des Hauses Robusto, Toro und Churchill, auf Stufe 2 von 5 der Skala des Hauses.","vitolas":[],"wrapper":"Connecticut (Ecuador)"},{"name":"Corrida","color":"#8B5A2B","force":null,"story":"Im Mai 2017 in Europa in zwei Versionen eingeführt, Honduras (in Danlí von Nestor A. Plasencia gerollt, sagt ein Bericht zur Markteinführung) und Dominikanische Republik (bei ABAM gefertigt, sagt ein anderer Bericht), als Robusto+ (5 x 56) und Toro+ (6 x 52). Im Oktober 2026 stellt die Seite des Hauses sie in vier Herkünften vor, Honduras, Dominikanische Republik, Nicaragua und Brasilien, auf den Stufen 4, 2,5, 5 und 3,5 von 5 der Skala des Hauses, und richtet sie an Liebhaber von handgerollten Zigarren; Villiger zählt Corrida zu den Marken seiner Fabrik in Estelí, die Ende September 2021 fertiggestellt wurde.","vitolas":[],"wrapper":"Nicht angegeben"},{"name":"Nicaroma","color":"#8B5A2B","force":"Medium-Full","story":"Eine Serie, laut Cigarworld.de auf der InterTabac 2023 in Dortmund vorgestellt; der Händler gibt an, sie sei in Estelí in Partnerschaft mit Joya de Nicaragua als Longfiller von Hand gerollt, mit Deckblatt und Einlage aus Nicaragua und einem Umblatt aus Indonesien, und führt sie seit dem 25. September 2023 für das 5 x 52 in seinem Katalog. Im Oktober 2026 nennt die Seite des Hauses drei nach ihren Maßen benannte Formate, 4 x 56, 5 x 52 und 6 x 54, auf Stufe 4 von 5 der Skala des Hauses; eine Vorschau vom April 2013 stellte unter diesem Namen bereits eine Linie mit drei Deckblättern vor.","vitolas":[],"wrapper":"Nicaragua"}]',
  `gamme_zh` = '[{"name":"Villiger La Meridiana","color":"#2C1A0E","story":"完全产自尼加拉瓜的 puro 雪茄，1998年在欧洲面世，沿用了十九世纪一家哈瓦那工厂的名字，据 Cigar Coop 与 Blind Man''s Puff 2019年3月所述；Cigar Coop 当时称其在埃斯特利的 Joya de Nicaragua 卷制。德国零售商 Cigarworld.de 在2026年10月给出的是 H-2000 茄衣、Connecticut 茄套和茄芯，全部产自尼加拉瓜，属 longfiller。Villiger 把它列入其埃斯特利工厂（2021年9月底竣工）的品牌之中。","wrapper":"尼加拉瓜（H-2000）","force":null},{"name":"Cuéllar","color":"#5C3317","story":"由三支多米尼加雪茄组成的系列，即 Connecticut Krēmē、Black Forest 与 Caribe，由 Jochy Blanco 在多米尼加共和国的工厂 Tabacalera Palma 生产，据 Cigar Coop 在2019年、2025年1月和2025年5月所述。Black Forest 于2019年10月宣布，茄衣为 maduro，茄套与茄芯均为多米尼加产；Caribe 于2025年1月31日宣布，茄衣为厄瓜多尔 habano，茄套与茄芯均为多米尼加产，零售商 Neptune Cigar 在2026年10月称其由 Tabacalera La Palma 制造。","wrapper":"Connecticut、Maduro、Habano","force":null},{"name":"Havana Club","color":"#7A2E1E","force":"Medium","story":"一个古巴老牌名，2007年由 Villiger 以多米尼加雪茄的身份重启，在 ABAM 卷制——据 Cigar Coop 2018年3月所述，这家位于圣多明各的工厂归 José「Matias」Maragoto 所有，负责卷制 Villiger 的多米尼加雪茄。","vitolas":[],"wrapper":"未公开"},{"name":"Dominico","color":"#C9A96E","force":"Mild-Medium","story":"来自多米尼加共和国的系列，公司页面在2026年十月称其强度为轻至中等、价格实惠，在Villiger的等级表上为2级（共5级），共有五种规格：Perla、Corona、Robusto、Torpedo和Churchill。德国零售商Cigarworld.de称其在ABAM Cigars手工卷制，采用longfiller，以bundles形式销售，茄衣为厄瓜多尔Connecticut Shade，茄套来自印尼，茄芯为多米尼加共和国与尼加拉瓜的Piloto；据该零售商称，该品牌可追溯至2000年代初，该零售商自2010年十二月七日起将Corona收入目录。","vitolas":[],"wrapper":"Connecticut Shade（厄瓜多尔）"},{"name":"Casa de Nicaragua","color":"#8B5A2B","force":"Medium-Full","story":"据Cigarworld.de称，该系列由Villiger于2014年发布；该零售商自2014年八月十二日起将其收入目录，称其手工卷制，采用mediumfiller，茄衣为厄瓜多尔H-2000，茄套来自印尼，茄芯来自尼加拉瓜。Villiger将其列入位于Estelí的工厂所产品牌之列，该工厂于2021年九月底竣工；2026年十月，公司页面列出五种产地为尼加拉瓜的规格（Perla、Corona、Robusto、Torpedo、Churchill），在其等级表上为4级（共5级）。","vitolas":[],"wrapper":"厄瓜多尔（H-2000）"},{"name":"La Libertad","color":"#8B5A2B","force":"Medium-Full","story":"该系列于2000年代初出现在德国的Liberty Cigar Company，后并入Villiger集团；它先离开洪都拉斯（Plasencia曾在那里卷制），再离开多米尼加共和国（ABAM曾在那里卷制），转至Estelí：一款新配方（茄衣为尼加拉瓜criollo，茄套来自多米尼加的Cibao，茄芯来自尼加拉瓜的Jalapa与Estelí）于2022年一月在Las Vegas的TPE展会上亮相，规格为Corona、Robusto和Gran Toro。2026年十月，公司页面将其列入手工制作雪茄之列，共四种规格（Gordito、Robusto、Corona、Gran Toro），在其等级表上为4级（共5级）。","vitolas":[],"wrapper":"Criollo（尼加拉瓜）"},{"name":"La Capitana","color":"#C9A96E","force":"Mild-Medium","story":"该系列于2025年以新配方重新推出，茄衣为厄瓜多尔Connecticut Shade，茄套来自尼加拉瓜，茄芯来自尼加拉瓜与多米尼加共和国，2025年四月在PCA展会上宣布，规格为Lonsdale（6 x 43）、Robusto（5 x 50）、Toro（6 x 50）和Churchill（7 x 50）；2026年七月的一篇报道称，此前的版本使用habano茄衣。Cigarworld.de称其在Estelí由Tabacalera Villiger de Nicaragua手工卷制，采用longfiller，在Joya de Nicaragua的场地内进行，并自2025年八月二十八日起将其收入目录；2026年十月，公司页面列出Robusto、Toro和Churchill，在其等级表上为2级（共5级）。","vitolas":[],"wrapper":"Connecticut（厄瓜多尔）"},{"name":"Corrida","color":"#8B5A2B","force":null,"story":"该系列于2017年五月在欧洲推出，有两个版本：洪都拉斯版（据一篇发布报道，由Nestor A. Plasencia在Danlí卷制）与多米尼加共和国版（据另一篇报道，在ABAM制作），规格为Robusto+（5 x 56）和Toro+（6 x 52）。2026年十月，公司页面将其列为四种产地：洪都拉斯、多米尼加共和国、尼加拉瓜和巴西，在其等级表上依次为4级、2.5级、5级和3.5级（共5级），并将其面向手工卷制雪茄的爱好者；Villiger将Corrida列入其位于Estelí的工厂所产品牌之列，该工厂于2021年九月底竣工。","vitolas":[],"wrapper":"未公开"},{"name":"Nicaroma","color":"#8B5A2B","force":"Medium-Full","story":"该系列据Cigarworld.de称在Dortmund举行的InterTabac 2023上发布；该零售商称其在Estelí与Joya de Nicaragua合作手工卷制，采用longfiller，茄衣与茄芯来自尼加拉瓜，茄套来自印尼，并自2023年九月二十五日起将5 x 52规格收入目录。2026年十月，公司页面列出三种以尺寸命名的规格：4 x 56、5 x 52和6 x 54，在其等级表上为4级（共5级）；2013年四月的一篇预览报道已经以此名称介绍了一个使用三种茄衣的系列。","vitolas":[],"wrapper":"尼加拉瓜"}]',
  `gamme_ar` = '[{"name":"Villiger La Meridiana","color":"#2C1A0E","story":"سيجار puro نيكاراغوي بالكامل صدر في أوروبا عام 1998، ويستعيد اسم مصنع هافاني من القرن التاسع عشر، بحسب Cigar Coop وBlind Man''s Puff في مارس 2019؛ وتقول Cigar Coop حينئذٍ إنه يُلفّ لدى Joya de Nicaragua في إستيلي. ويذكر Cigarworld.de، وهو تاجر تجزئة ألماني، في أكتوبر 2026 غلافًا H-2000 ورباطًا Connecticut وحشوة، كلّها من نيكاراغوا، من نوع longfiller. وتعدّه Villiger من علامات مصنعها في إستيلي، الذي اكتمل بناؤه في نهاية سبتمبر 2021.","wrapper":"نيكاراغوا (H-2000)","force":null},{"name":"Cuéllar","color":"#5C3317","story":"سلسلة من ثلاث سيجارات دومينيكية، Connecticut Krēmē وBlack Forest وCaribe، تنتجها Tabacalera Palma، مصنع Jochy Blanco في جمهورية الدومينيكان، بحسب Cigar Coop في 2019 وفي يناير 2025 وفي مايو 2025. وBlack Forest، المعلن عنه في أكتوبر 2019، له غلاف maduro على رباط وحشوة دومينيكيين؛ وCaribe، المعلن عنه في 31 يناير 2025، له غلاف habano من الإكوادور على رباط وحشوة دومينيكيين، ويقول تاجر التجزئة Neptune Cigar في أكتوبر 2026 إنه يُصنع لدى Tabacalera La Palma.","wrapper":"Connecticut وMaduro وHabano","force":null},{"name":"Havana Club","color":"#7A2E1E","force":"Medium","story":"اسمُ علامة كوبية قديمة، أعادت Villiger إطلاقه سنة 2007 سيجارًا دومينيكيًّا، يُلفّ في ABAM، مصنع سانتو دومينغو الذي تقول Cigar Coop في مارس 2018 إنه مملوك لـJosé «Matias» Maragoto ومكلَّف بلفّ سيجارات Villiger الدومينيكية.","vitolas":[],"wrapper":"غير معلن"},{"name":"Dominico","color":"#C9A96E","force":"Mild-Medium","story":"خط من جمهورية الدومينيكان، تصفه صفحة الشركة في أكتوبر 2026 بأنه خفيف إلى متوسط وبسعر ميسور، عند المستوى 2 من 5 على سلّم Villiger، بخمسة مقاسات: Perla وCorona وRobusto وTorpedo وChurchill. ويذكر Cigarworld.de، وهو تاجر تجزئة ألماني، أنه ملفوف يدويًا من نوع longfiller لدى ABAM Cigars، ضمن bundles، بغلاف خارجي Connecticut Shade من إكوادور ورابط من إندونيسيا وحشوة Piloto من جمهورية الدومينيكان ومن نيكاراغوا؛ وتعود العلامة إلى مطلع سنوات 2000 بحسب هذا التاجر، الذي يُدرجها في فهرسه، بالنسبة إلى Corona، منذ 7 ديسمبر 2010.","vitolas":[],"wrapper":"Connecticut Shade (إكوادور)"},{"name":"Casa de Nicaragua","color":"#8B5A2B","force":"Medium-Full","story":"قُدّمت في 2014 على يد Villiger بحسب Cigarworld.de، الذي يُدرجها في فهرسه منذ 12 أغسطس 2014 ويقول إنها ملفوفة يدويًا من نوع mediumfiller، بغلاف خارجي H-2000 من إكوادور ورابط من إندونيسيا وحشوة من نيكاراغوا. وتعدّها Villiger من علامات مصنعها في Estelí، الذي اكتمل في أواخر سبتمبر 2021؛ وفي أكتوبر 2026 تذكر صفحة الشركة خمسة مقاسات من أصل نيكاراغوا (Perla وCorona وRobusto وTorpedo وChurchill)، عند المستوى 4 من 5 على سلّمها.","vitolas":[],"wrapper":"إكوادور (H-2000)"},{"name":"La Libertad","color":"#8B5A2B","force":"Medium-Full","story":"ظهرت في مطلع سنوات 2000 لدى Liberty Cigar Company في ألمانيا، ثم انضمّت إلى مجموعة Villiger، وغادرت هندوراس، حيث كانت Plasencia تلفّها، ثم جمهورية الدومينيكان، حيث كانت ABAM تلفّها، إلى Estelí: مزيج جديد بغلاف خارجي criollo من نيكاراغوا ورابط من Cibao الدومينيكي وحشوة نيكاراغوية من Jalapa وEstelí عُرض في يناير 2022 في معرض TPE في Las Vegas بمقاسات Corona وRobusto وGran Toro. وفي أكتوبر 2026 تُدرجها صفحة الشركة ضمن سيجاراتها المصنوعة يدويًا، بأربعة مقاسات (Gordito وRobusto وCorona وGran Toro)، عند المستوى 4 من 5 على سلّمها.","vitolas":[],"wrapper":"Criollo (نيكاراغوا)"},{"name":"La Capitana","color":"#C9A96E","force":"Mild-Medium","story":"أُعيد إطلاقها في 2025 بمزيج جديد، بغلاف خارجي Connecticut Shade من إكوادور ورابط من نيكاراغوا وحشوة من نيكاراغوا ومن جمهورية الدومينيكان، وأُعلن عنها في معرض PCA في أبريل 2025 بمقاسات Lonsdale (6 x 43) وRobusto (5 x 50) وToro (6 x 50) وChurchill (7 x 50)؛ وكانت النسخة السابقة بغلاف خارجي habano، بحسب تقرير في يوليو 2026. ويقول Cigarworld.de إنها ملفوفة يدويًا من نوع longfiller في Estelí لدى Tabacalera Villiger de Nicaragua، في مباني Joya de Nicaragua، ويُدرجها في فهرسه منذ 28 أغسطس 2025؛ وفي أكتوبر 2026 تذكر صفحة الشركة Robusto وToro وChurchill، عند المستوى 2 من 5 على سلّمها.","vitolas":[],"wrapper":"Connecticut (إكوادور)"},{"name":"Corrida","color":"#8B5A2B","force":null,"story":"أُطلقت في أوروبا في مايو 2017 بنسختين: هندوراس (ملفوفة في Danlí على يد Nestor A. Plasencia، بحسب تقرير عن الإطلاق) وجمهورية الدومينيكان (صُنعت لدى ABAM، بحسب تقرير آخر)، بمقاسي Robusto+ (5 x 56) وToro+ (6 x 52). وفي أكتوبر 2026 تعرضها صفحة الشركة بأربعة بلدان منشأ هي هندوراس وجمهورية الدومينيكان ونيكاراغوا والبرازيل، عند المستويات 4 و2,5 و5 و3,5 من 5 على سلّمها، وتوجّهها إلى هواة السيجار الملفوف يدويًا؛ وتعدّ Villiger علامة Corrida من علامات مصنعها في Estelí، الذي اكتمل في أواخر سبتمبر 2021.","vitolas":[],"wrapper":"غير معلن"},{"name":"Nicaroma","color":"#8B5A2B","force":"Medium-Full","story":"سلسلة قُدّمت في InterTabac 2023 في Dortmund بحسب Cigarworld.de، الذي يقول إنها ملفوفة يدويًا من نوع longfiller في Estelí بالشراكة مع Joya de Nicaragua، بغلاف خارجي وحشوة من نيكاراغوا ورابط من إندونيسيا، ويُدرجها في فهرسه منذ 25 سبتمبر 2023 للمقاس 5 x 52. وفي أكتوبر 2026 تذكر صفحة الشركة ثلاثة مقاسات مسمّاة بأبعادها: 4 x 56 و5 x 52 و6 x 54، عند المستوى 4 من 5 على سلّمها؛ وكان عرض تمهيدي في أبريل 2013 قد قدّم بالفعل تحت هذا الاسم خطًا بثلاثة أغلفة خارجية.","vitolas":[],"wrapper":"نيكاراغوا"}]',
  `celebrities` = '[{"name":"Heinrich Villiger","anecdote":"Entré dans la maison familiale en 1950, il succéda à Hans en 1954 et présida le conseil de Villiger Söhne jusqu''à sa mort, le 25 juillet 2025, à 95 ans (page d''histoire de la maison ; zigarren.zone)."}]',
  `celebrities_en` = '[{"name":"Heinrich Villiger","anecdote":"Joined the family house in 1950, succeeded Hans in 1954 and chaired the board of Villiger Söhne until his death on 25 July 2025, aged 95 (the company''s history page; zigarren.zone)."}]',
  `celebrities_es` = '[{"name":"Heinrich Villiger","anecdote":"Entró en la casa familiar en 1950, sucedió a Hans en 1954 y presidió el consejo de Villiger Söhne hasta su muerte, el 25 de julio de 2025, a los 95 años (página de historia de la casa; zigarren.zone)."}]',
  `celebrities_de` = '[{"name":"Heinrich Villiger","anecdote":"1950 in das Familienhaus eingetreten, folgte er 1954 auf Hans und stand dem Verwaltungsrat von Villiger Söhne bis zu seinem Tod am 25. Juli 2025 im Alter von 95 Jahren vor (Geschichtsseite des Hauses; zigarren.zone)."}]',
  `celebrities_zh` = '[{"name":"海因里希·维利格","anecdote":"1950年进入家族企业，1954年接替 Hans，直至2025年7月25日去世（享年95岁）一直担任 Villiger Söhne 董事会主席（公司历史页面；zigarren.zone）。"}]',
  `celebrities_ar` = '[{"name":"هاينريش فيليغر","anecdote":"انضم إلى الدار العائلية عام 1950، وخلف Hans عام 1954، وترأس مجلس إدارة Villiger Söhne حتى وفاته في 25 يوليو 2025 عن 95 عامًا (صفحة تاريخ الدار؛ zigarren.zone)."}]',
  `pairings` = '[]',
  `pairings_en` = '[]',
  `pairings_es` = '[]',
