-- ── Les sceaux des champs réécrits, calculés depuis les colonnes françaises ──
INSERT INTO `translation_status` (`entite`, `entite_id`, `champ`, `lang`, `source_hash`, `statut`, `relecteur`, `maj`)
SELECT 'brands', b.`name`, c.champ, l.lang,
       SHA1(CASE c.champ WHEN 'history' THEN b.`history` WHEN 'celebrities' THEN b.`celebrities` WHEN 'pairings' THEN b.`pairings` ELSE b.`gamme` END), 'machine', NULL, NOW()
  FROM `brands` b
  JOIN (SELECT 'Partagás USA' hote, 'celebrities' champ
        UNION ALL SELECT 'Partagás USA' hote, 'gamme' champ
        UNION ALL SELECT 'Partagás USA' hote, 'history' champ
        UNION ALL SELECT 'Romeo y Julieta USA' hote, 'celebrities' champ
        UNION ALL SELECT 'Romeo y Julieta USA' hote, 'gamme' champ
        UNION ALL SELECT 'Romeo y Julieta USA' hote, 'history' champ
        UNION ALL SELECT 'Romeo y Julieta USA' hote, 'pairings' champ
        UNION ALL SELECT 'Dannemann' hote, 'celebrities' champ
        UNION ALL SELECT 'Dannemann' hote, 'gamme' champ
        UNION ALL SELECT 'Dannemann' hote, 'history' champ
        UNION ALL SELECT 'Dannemann' hote, 'pairings' champ
        UNION ALL SELECT 'Te Amo' hote, 'celebrities' champ
        UNION ALL SELECT 'Te Amo' hote, 'gamme' champ
        UNION ALL SELECT 'Te Amo' hote, 'history' champ
        UNION ALL SELECT 'Tabacalera' hote, 'celebrities' champ
        UNION ALL SELECT 'Tabacalera' hote, 'gamme' champ
        UNION ALL SELECT 'Tabacalera' hote, 'history' champ
        UNION ALL SELECT 'Tabacalera' hote, 'pairings' champ
        UNION ALL SELECT 'General Cigar' hote, 'celebrities' champ
        UNION ALL SELECT 'General Cigar' hote, 'gamme' champ
        UNION ALL SELECT 'General Cigar' hote, 'history' champ
        UNION ALL SELECT 'General Cigar' hote, 'pairings' champ
        UNION ALL SELECT 'Villiger' hote, 'celebrities' champ
        UNION ALL SELECT 'Villiger' hote, 'gamme' champ
        UNION ALL SELECT 'Villiger' hote, 'history' champ
        UNION ALL SELECT 'Villiger' hote, 'pairings' champ) c
  JOIN (SELECT 'en' lang UNION ALL SELECT 'es' UNION ALL SELECT 'de' UNION ALL SELECT 'zh' UNION ALL SELECT 'ar') l
 WHERE c.hote = b.`name`
    ON DUPLICATE KEY UPDATE `source_hash` = VALUES(`source_hash`), `statut` = 'machine', `relecteur` = NULL, `maj` = NOW();

