SELECT 'Partagás USA' AS hote, 'fr' AS lang, 'limited_eds : Partagás Aniversario 170 (2015)' AS quoi, (JSON_CONTAINS(`limited_eds`, '"Partagás Aniversario 170 (2015)"')) AS ok FROM `brands` WHERE `name` = 'Partagás USA'
