UNION ALL SELECT 'Partagás USA', 'fr', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Partagás est un nom porté par deux marques distinctes : le Partagás cubain de Habanos S.A., roulé à La Havane, et le Partagás des États-Unis, sans tabac cubain, que cet atlas classe en République dominicaine, là où il est roulé. Les deux ne partagent que le nom, l''année 1845 de la fondation havanaise et un décor de bague rouge et or.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Partagás USA'
UNION ALL SELECT 'Partagás USA', 'fr', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('La situation de Partagás aux États-Unis illustre le même phénomène juridique que Cohiba USA : l''embargo américain contre Cuba créa un vide de propriété intellectuelle que General Cigar occupa rapidement et légalement.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Partagás USA'
UNION ALL SELECT 'Partagás USA', 'en', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Partagás is a name borne by two distinct brands: the Cuban Partagás of Habanos S.A., rolled in Havana, and the Partagás of the United States, with no Cuban tobacco, which this atlas files under the Dominican Republic, where it is rolled. The two share only the name, the year 1845 of the Havana foundation and a red-and-gold band design.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Partagás USA'
UNION ALL SELECT 'Partagás USA', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('The American Partagás situation illustrates the same legal phenomenon as Cohiba USA: the American embargo against Cuba created an intellectual property vacuum that General Cigar quickly and legally occupied.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Partagás USA'
UNION ALL SELECT 'Partagás USA', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Partagás es un nombre que llevan dos marcas distintas: el Partagás cubano de Habanos S.A., torcido en La Habana, y el Partagás de Estados Unidos, sin tabaco cubano, que este atlas clasifica en la República Dominicana, donde se tuerce. Las dos comparten solo el nombre, el año 1845 de la fundación habanera y un diseño de vitola roja y dorada.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Partagás USA'
UNION ALL SELECT 'Partagás USA', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('La situación de Partagás en Estados Unidos ilustra el mismo fenómeno jurídico que Cohiba USA: el embargo estadounidense contra Cuba creó un vacío de propiedad intelectual que General Cigar ocupó con rapidez y legalidad.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Partagás USA'
UNION ALL SELECT 'Partagás USA', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Partagás ist ein Name, den zwei verschiedene Marken tragen: das kubanische Partagás von Habanos S.A., in Havanna gerollt, und das Partagás der Vereinigten Staaten, ohne kubanischen Tabak, das dieser Atlas unter der Dominikanischen Republik einordnet, wo es gerollt wird. Beide teilen nur den Namen, das Jahr 1845 der Havanna-Gründung und ein rot-goldenes Bandmotiv.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Partagás USA'
UNION ALL SELECT 'Partagás USA', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Die Lage von Partagás in den Vereinigten Staaten veranschaulicht dasselbe rechtliche Phänomen wie Cohiba USA: Das amerikanische Embargo gegen Kuba schuf eine Lücke im geistigen Eigentum, die General Cigar rasch und legal besetzte.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Partagás USA'
UNION ALL SELECT 'Partagás USA', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Partagás 是两个不同品牌共用的名字：一是 Habanos S.A. 旗下的古巴 Partagás，在哈瓦那手工卷制；二是美国的 Partagás，不含古巴烟叶，本图鉴将其归入多米尼加共和国，因为它在那里卷制。两者只共享名字、哈瓦那创立的 1845年，以及红金相间的烟标设计。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Partagás USA'
UNION ALL SELECT 'Partagás USA', 'zh', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Partagás 在美国的处境，说明的是与 Cohiba USA 相同的法律现象：美国对古巴的禁运造成了知识产权真空，而 General Cigar 迅速且合法地填补了它。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Partagás USA'
UNION ALL SELECT 'Partagás USA', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Partagás اسم تحمله علامتان مختلفتان: Partagás الكوبية التابعة لـ Habanos S.A. وتُلَفّ في هافانا، وPartagás الخاصة بالولايات المتحدة، بلا تبغ كوبي، وهي التي يصنّفها هذا الأطلس ضمن جمهورية الدومينيكان لأنها تُلَفّ هناك. ولا يجمع بينهما إلا الاسم وسنة 1845 لتأسيس الدار في هافانا وتصميم خاتم أحمر وذهبي.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Partagás USA'
UNION ALL SELECT 'Partagás USA', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('يوضّح وضع Partagás في الولايات المتحدة الظاهرة القانونية نفسها التي عرفتها Cohiba USA: فالحظر الأمريكي على كوبا خلق فراغاً في الملكية الفكرية شغلته General Cigar سريعاً وبصورة قانونية.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Partagás USA'
UNION ALL SELECT 'Partagás USA', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('General Cigar a la marque aux États-Unis depuis 1978 (Wikipédia) ; la production a commencé en Jamaïque, puis a gagné l''usine de Santiago de los Caballeros, en République dominicaine, un an plus tard (Wikipédia ; presse du métier, hiver 1995-1996). En 1995, l''usine de la zone franche comptait environ 600 employés, dont 200 rouleurs. General Cigar appartient à Scandinavian Tobacco Group (STG) ; la bague porte « 1845 » à la place de « Habana ».' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Partagás USA'
UNION ALL SELECT 'Partagás USA', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('General Cigar détient les droits sur la marque Partagás aux États-Unis, indépendamment du Partagás cubain de Habanos S.A. La version américaine est fabriquée en République Dominicaine depuis les années 1980, utilisant des tabacs dominicains et mexicains dans un profil intentionnellement évocateur — mais distinct — de l''original havanais.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Partagás USA'
UNION ALL SELECT 'Partagás USA', 'en', 'histoire 2 (nouveau texte)', (LOCATE(CAST('General Cigar has held the brand in the United States since 1978 (Wikipedia); production began in Jamaica, then moved a year later to the factory in Santiago de los Caballeros, in the Dominican Republic (Wikipedia; trade press, winter 1995-1996). In 1995 the free-zone factory had about 600 employees, 200 of them rollers. General Cigar belongs to Scandinavian Tobacco Group (STG); the band reads "1845" in place of "Habana".' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Partagás USA'
UNION ALL SELECT 'Partagás USA', 'en', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('General Cigar holds the Partagás trademark rights in the United States, independently of the Cuban Partagás owned by Habanos S.A. The American version has been manufactured in the Dominican Republic since the 1980s, using Dominican and Mexican tobaccos in an intentionally evocative — yet distinct — profile from the original Havana house.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Partagás USA'
UNION ALL SELECT 'Partagás USA', 'es', 'histoire 2 (nouveau texte)', (LOCATE(CAST('General Cigar posee la marca en Estados Unidos desde 1978 (Wikipedia); la producción empezó en Jamaica y un año después pasó a la fábrica de Santiago de los Caballeros, en la República Dominicana (Wikipedia; prensa del sector, invierno de 1995-1996). En 1995, la fábrica de la zona franca contaba con unos 600 empleados, 200 de ellos torcedores. General Cigar pertenece a Scandinavian Tobacco Group (STG); la vitola lleva «1845» en lugar de «Habana».' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Partagás USA'
UNION ALL SELECT 'Partagás USA', 'es', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('General Cigar posee los derechos de la marca Partagás en Estados Unidos, con independencia del Partagás cubano de Habanos S.A. La versión estadounidense se fabrica en la República Dominicana desde los años ochenta, con tabacos dominicanos y mexicanos en un perfil deliberadamente evocador —pero distinto— del original habanero.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Partagás USA'
UNION ALL SELECT 'Partagás USA', 'de', 'histoire 2 (nouveau texte)', (LOCATE(CAST('General Cigar hält die Marke in den Vereinigten Staaten seit 1978 (Wikipedia); die Produktion begann in Jamaika und wechselte ein Jahr später in die Fabrik in Santiago de los Caballeros in der Dominikanischen Republik (Wikipedia; Fachpresse, Winter 1995-1996). 1995 zählte die Fabrik in der Freizone etwa 600 Beschäftigte, davon 200 Roller. General Cigar gehört zu Scandinavian Tobacco Group (STG); das Band trägt „1845“ statt „Habana“.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Partagás USA'
UNION ALL SELECT 'Partagás USA', 'de', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('General Cigar hält die Rechte an der Marke Partagás in den Vereinigten Staaten, unabhängig vom kubanischen Partagás der Habanos S.A. Die amerikanische Version wird seit den 1980er Jahren in der Dominikanischen Republik hergestellt, aus dominikanischen und mexikanischen Tabaken, in einem Profil, das das havannesische Original bewusst anklingen lässt — und sich doch davon unterscheidet.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Partagás USA'
UNION ALL SELECT 'Partagás USA', 'zh', 'histoire 2 (nouveau texte)', (LOCATE(CAST('General Cigar 自 1978年起在美国持有该品牌（维基百科）；生产最初在牙买加，一年后转到多米尼加共和国圣地亚哥-德洛斯卡瓦列罗斯的工厂（维基百科；行业媒体，1995—1996年冬季）。1995年，自由区的这家工厂约有 600 名员工，其中 200 名是卷烟师。General Cigar 隶属于 Scandinavian Tobacco Group（STG）；烟标上印的是“1845”，而不是“Habana”。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Partagás USA'
UNION ALL SELECT 'Partagás USA', 'zh', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('General Cigar 拥有 Partagás 商标在美国的权利，与 Habanos S.A. 旗下的古巴 Partagás 互不相干。美国版自 1980 年代起在多米尼加共和国生产，采用多米尼加与墨西哥烟叶，风格刻意让人联想到哈瓦那原版，却又与之不同。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Partagás USA'
UNION ALL SELECT 'Partagás USA', 'ar', 'histoire 2 (nouveau texte)', (LOCATE(CAST('تملك General Cigar العلامة في الولايات المتحدة منذ 1978 (ويكيبيديا)؛ وبدأ الإنتاج في جامايكا، ثم انتقل بعد عام إلى مصنع سانتياغو دي لوس كاباليروس في جمهورية الدومينيكان (ويكيبيديا؛ صحافة المهنة، شتاء 1995-1996). وفي 1995 كان في مصنع المنطقة الحرة نحو 600 موظف، منهم 200 لفّاف. وتتبع General Cigar مجموعة Scandinavian Tobacco Group (STG)؛ ويحمل الخاتم «1845» بدل «Habana».' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Partagás USA'
UNION ALL SELECT 'Partagás USA', 'ar', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('تملك General Cigar حقوق علامة Partagás في الولايات المتحدة، بمعزل عن Partagás الكوبية التابعة لـ Habanos S.A. وتُصنع النسخة الأمريكية في جمهورية الدومينيكان منذ الثمانينيات، من تبغ دومينيكي ومكسيكي، بطابع يستحضر الأصل الهافاني عن قصد — ويظل مختلفاً عنه.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Partagás USA'
UNION ALL SELECT 'Partagás USA', 'fr', 'histoire 3 (nouveau texte)', (LOCATE(CAST('La presse du métier relevait en 1995 environ huit millions de Partagás par an sortis de cet atelier. Ce Partagás s''est installé comme la version que l''amateur américain, privé du cubain par l''embargo, trouve sur son marché.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Partagás USA'
UNION ALL SELECT 'Partagás USA', 'fr', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('L''impact commercial de cette version américaine est substantiel : Partagás est l''une des marques premium les plus vendues aux États-Unis depuis trois décennies. La fidélité de consommateurs qui ne peuvent accéder au Partagás cubain — et qui ont développé leur palais sur la version dominicaine — crée une base d''acheteurs récurrents solide.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Partagás USA'
UNION ALL SELECT 'Partagás USA', 'en', 'histoire 3 (nouveau texte)', (LOCATE(CAST('In 1995 the trade press noted about eight million Partagás a year coming out of this factory. This Partagás has established itself as the version that the American smoker, deprived of the Cuban by the embargo, finds on his market.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Partagás USA'
UNION ALL SELECT 'Partagás USA', 'en', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('The commercial impact of this American version is substantial: Partagás is one of the best-selling premium brands in the United States over three decades. The loyalty of consumers who cannot access the Cuban Partagás — and who developed their palates on the Dominican version — creates a solid base of recurring buyers.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Partagás USA'
UNION ALL SELECT 'Partagás USA', 'es', 'histoire 3 (nouveau texte)', (LOCATE(CAST('La prensa del sector contabilizaba en 1995 unos ocho millones de Partagás al año salidos de esta fábrica. Este Partagás se ha asentado como la versión que el aficionado estadounidense, privado del cubano por el embargo, encuentra en su mercado.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Partagás USA'
UNION ALL SELECT 'Partagás USA', 'es', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('El impacto comercial de esta versión estadounidense es notable: Partagás figura desde hace tres décadas entre las marcas premium más vendidas en Estados Unidos. La fidelidad de unos consumidores que no pueden acceder al Partagás cubano —y que han formado su paladar con la versión dominicana— sostiene una base sólida de compradores recurrentes.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Partagás USA'
UNION ALL SELECT 'Partagás USA', 'de', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Die Fachpresse verzeichnete 1995 etwa acht Millionen Partagás pro Jahr aus dieser Fabrik. Dieses Partagás hat sich als die Version etabliert, die der amerikanische Liebhaber, dem das Embargo das kubanische vorenthält, auf seinem Markt findet.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Partagás USA'
UNION ALL SELECT 'Partagás USA', 'de', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Der kommerzielle Erfolg dieser amerikanischen Version ist beträchtlich: Partagás gehört seit drei Jahrzehnten zu den meistverkauften Premiummarken der Vereinigten Staaten. Die Treue von Verbrauchern, die keinen Zugang zum kubanischen Partagás haben und ihren Gaumen an der dominikanischen Version geschult haben, trägt einen soliden Stamm an Wiederkäufern.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Partagás USA'
UNION ALL SELECT 'Partagás USA', 'zh', 'histoire 3 (nouveau texte)', (LOCATE(CAST('行业媒体在 1995年记录到，这家工厂每年出产约八百万支 Partagás。这款 Partagás 已成为美国爱好者的选择：他们因禁运而买不到古巴版，只能在自己的市场上找到它。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Partagás USA'
UNION ALL SELECT 'Partagás USA', 'zh', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('这一美国版的商业影响相当可观：三十年来，Partagás 一直是美国销量最高的高端品牌之一。那些无缘古巴 Partagás、并以多米尼加版养成味觉的消费者，形成了稳固的回头客基础。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Partagás USA'
UNION ALL SELECT 'Partagás USA', 'ar', 'histoire 3 (nouveau texte)', (LOCATE(CAST('سجّلت صحافة المهنة في 1995 نحو ثمانية ملايين سيجار Partagás في العام يخرج من هذا المصنع. وقد استقرت هذه Partagás بوصفها النسخة التي يجدها الهاوي الأمريكي في سوقه، وقد حرمه الحظر من الكوبية.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Partagás USA'
UNION ALL SELECT 'Partagás USA', 'ar', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('وأثر هذه النسخة الأمريكية تجارياً كبير: فـ Partagás من أكثر العلامات الفاخرة مبيعاً في الولايات المتحدة منذ ثلاثة عقود. ووفاء مستهلكين لا سبيل لهم إلى Partagás الكوبية، وقد تربّت أذواقهم على النسخة الدومينيكية، يصنع قاعدة متينة من المشترين الدائمين.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Partagás USA'
UNION ALL SELECT 'Partagás USA', 'fr', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Parmi les lignes actuelles, la presse du métier cite la 1845, lancée en 2012 avec une cape Habano d''Équateur, comme une rupture avec les Partagás à cape Cameroun, et la Black Label, à cape Connecticut Broadleaf maduro selon les détaillants. En 2015, l''Aniversario 170 est sortie avec une cape Cameroun cultivée au soleil (revue du 20 novembre 2015). En 2025, STG a confié une édition, la Y Nada Más Santiago, à Tabacalera William Ventura à Tamboril, près de Santiago (titre vu).' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Partagás USA'
UNION ALL SELECT 'Partagás USA', 'fr', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('La gamme 1845, lancée pour commémorer l''année de fondation de la maison havanaise originale, est la proposition la plus ambitieuse de la version américaine : un assemblage à dominante San Andrés du Mexique qui cherche explicitement à reproduire l''intensité terreuse du Partagás cubain. Certains amateurs américains le préfèrent à l''original pour sa régularité ; d''autres le trouvent trop linéaire. Les deux positions sont défendables et reflètent simplement des préférences différentes de style.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Partagás USA'
UNION ALL SELECT 'Partagás USA', 'en', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Among the current lines, the trade press cites the 1845, launched in 2012 with an Ecuadorian Habano wrapper, as a break from the Cameroon-wrapped Partagás, and the Black Label, with a Connecticut Broadleaf maduro wrapper according to retailers. In 2015 the Aniversario 170 came out with a sun-grown Cameroon wrapper (issue of 20 November 2015). In 2025 STG entrusted one edition, the Y Nada Más Santiago, to Tabacalera William Ventura in Tamboril, near Santiago (headline seen).' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Partagás USA'
UNION ALL SELECT 'Partagás USA', 'en', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('The 1845 range, launched to commemorate the founding year of the original Havana house, is the most ambitious proposition of the American version: a Mexican San Andrés-dominant blend that explicitly seeks to reproduce the earthy intensity of the Cuban Partagás. Some American enthusiasts prefer it to the original for its consistency; others find it too linear in its intensity. Both positions are defensible and simply reflect different stylistic preferences.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Partagás USA'
UNION ALL SELECT 'Partagás USA', 'es', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Entre las líneas actuales, la prensa del sector cita la 1845, lanzada en 2012 con capa Habano de Ecuador, como una ruptura con los Partagás de capa Camerún, y la Black Label, de capa Connecticut Broadleaf maduro según los minoristas. En 2015 salió el Aniversario 170 con una capa Camerún cultivada al sol (número del 20 de noviembre de 2015). En 2025, STG encargó una edición, la Y Nada Más Santiago, a Tabacalera William Ventura, en Tamboril, cerca de Santiago (titular visto).' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Partagás USA'
UNION ALL SELECT 'Partagás USA', 'es', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('La gama 1845, lanzada para conmemorar el año de fundación de la casa habanera original, es la propuesta más ambiciosa de la versión estadounidense: una ligada de predominio mexicano San Andrés que busca explícitamente reproducir la intensidad terrosa del Partagás cubano. Algunos aficionados estadounidenses la prefieren al original por su regularidad; otros la encuentran demasiado lineal. Ambas posturas son defendibles y solo reflejan preferencias de estilo distintas.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Partagás USA'
