UNION ALL SELECT 'Partagás USA', 'de', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('Die Linie 1845, benannt nach dem Gründungsjahr des ursprünglichen Havanna-Hauses, ist der ehrgeizigste Vorschlag der amerikanischen Version: eine Mischung mit Übergewicht des mexikanischen San Andrés, die ausdrücklich die erdige Intensität des kubanischen Partagás nachbilden will. Manche amerikanischen Liebhaber ziehen sie wegen ihrer Gleichmäßigkeit dem Original vor, andere finden sie zu geradlinig. Beide Haltungen lassen sich vertreten und spiegeln schlicht unterschiedliche Stilvorlieben.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Partagás USA'
