UNION ALL SELECT 'Dannemann', 'fr', 'factory', (CAST(`factory` AS BINARY) = CAST('Terra Dannemann, São Félix da Cachoeira, Bahia, Brésil — première fabrique de longfillers du groupe, en activité en octobre 2026' AS BINARY)) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'fr', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Dannemann naît à São Félix da Cachoeira, dans le Recôncavo de Bahia, au Brésil, avec Gerhard (devenu Geraldo) Dannemann, immigrant allemand. La date de la fabrique diverge : 1872 selon la maison (dannemann-group.com, qui la nomme sa fabrique de longfillers), 1873 selon Wikipédia, qui lui compte six employés au départ. Les deux versions sont données, non tranchées.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'fr', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Gerhard Dannemann arriva au Brésil en 1873, à vingt-trois ans, parmi des milliers d''immigrants allemands installés dans les États du sud au cours du XIXe siècle. À la différence de la plupart, venus pour l''agriculture ou la petite industrie, Dannemann visait le tabac : il en connaissait le commerce par ses origines allemandes, et celui qu''il découvrit dans le bassin du Recôncavo, à Bahia, ne ressemblait à rien de ce qu''il attendait.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'en', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Dannemann was born in São Félix da Cachoeira, in the Recôncavo of Bahia, Brazil, with Gerhard (later Geraldo) Dannemann, a German immigrant. The date of the factory diverges: 1872 according to the house (dannemann-group.com, which calls it its long filler factory), 1873 according to Wikipedia, which gives it six employees at the start. Both versions are given, neither settled.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Gerhard Dannemann arrived in Brazil in 1873 at the age of 23, one of thousands of German immigrants who had settled in the southern Brazilian states during the nineteenth century. Unlike most who came for agriculture or light industry, Dannemann was drawn specifically to tobacco — he had knowledge of the trade from his German background, and the tobacco he encountered in Bahia''s Recôncavo basin was unlike anything he had expected.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Dannemann nace en São Félix da Cachoeira, en el Recôncavo de Bahía, en Brasil, con Gerhard (llamado luego Geraldo) Dannemann, inmigrante alemán. La fecha de la fábrica diverge: 1872 según la casa (dannemann-group.com, que la nombra su fábrica de puros de tripa larga), 1873 según Wikipedia, que le cuenta seis empleados al comienzo. Se dan las dos versiones, sin zanjar.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Gerhard Dannemann llegó a Brasil en 1873, a los veintitrés años, entre miles de inmigrantes alemanes instalados en los estados del sur a lo largo del siglo XIX. A diferencia de la mayoría, venidos para la agricultura o la pequeña industria, Dannemann apuntaba al tabaco: conocía su comercio por sus orígenes alemanes, y el que descubrió en la cuenca del Recôncavo, en Bahía, no se parecía a nada de lo que esperaba.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Dannemann entsteht in São Félix da Cachoeira, im Recôncavo von Bahia in Brasilien, mit Gerhard (später Geraldo) Dannemann, einem deutschen Einwanderer. Das Datum der Fabrik weicht ab: 1872 laut dem Haus (dannemann-group.com, das sie seine Longfiller-Fabrik nennt), 1873 laut Wikipedia, das ihr zu Beginn sechs Beschäftigte zuschreibt. Beide Fassungen werden genannt, nicht entschieden.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Gerhard Dannemann kam 1873 mit dreiundzwanzig Jahren nach Brasilien, unter Tausenden deutscher Einwanderer, die sich im Lauf des 19. Jahrhunderts in den südlichen Staaten niederließen. Anders als die meisten, die für die Landwirtschaft oder das Kleingewerbe kamen, zielte Dannemann auf den Tabak: Er kannte dessen Handel aus seiner deutschen Herkunft, und was er im Becken des Recôncavo in Bahia vorfand, glich nichts von dem, was er erwartet hatte.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Dannemann 诞生于巴西巴伊亚雷孔卡沃的圣费利克斯-达卡绍埃拉，创办人是德国移民 Gerhard（后来称 Geraldo）Dannemann。工厂的创办日期存在分歧：公司称为1872年（dannemann-group.com，称其为公司的长填料工厂），Wikipedia 则称为1873年，并说开办时有六名员工。两种说法都列出，不作定论。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'zh', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('1873年，二十三岁的格哈德·丹尼曼来到巴西，与19世纪里成千上万定居南部各州的德国移民同行。与多数为农业或小工业而来的人不同，丹尼曼冲着烟草：凭德国出身，他懂这门生意；而他在巴伊亚的雷孔卡沃盆地所见到的烟草，与他预想的毫无相似之处。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('تنشأ Dannemann في ساو فيليكس دا كاشويرا، في ريكونكافو بولاية باهيا بالبرازيل، مع غيرهارد (الذي صار يُدعى جيرالدو) دانيمان، وهو مهاجر ألماني. وتاريخ المصنع مختلف عليه: سنة 1872 بحسب الدار (dannemann-group.com، التي تسمّيه مصنعها للسيجار بحشوة طويلة)، وسنة 1873 بحسب Wikipedia، التي تنسب إليه ستة عاملين في البداية. وتُعرض الروايتان دون ترجيح.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('وصل غيرهارد دانيمان إلى البرازيل عام 1873، في الثالثة والعشرين، بين آلاف المهاجرين الألمان الذين استقرّوا في الولايات الجنوبية خلال القرن التاسع عشر. وخلافًا لمعظمهم، ممن جاؤوا للزراعة أو للصناعة الصغيرة، كان دانيمان يقصد التبغ: عرف تجارته من أصوله الألمانية، لكنّ ما اكتشفه في حوض ريكونكافو بولاية باهيا لم يشبه شيئًا مما توقّعه.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Le tabac vient de la région de Mata Fina, à Bahia : selon la maison, plus de 200 fermes partenaires y cultivent la tripe, et la ferme Fazenda San Antônio, de 1 000 hectares, fournit toutes les capes des gammes de cigares premium. Les balles de tabac y vieillissent avant la fabrication.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Le tabac bahianais se cultive dans les vallées fertiles au sud du Rio Paraguaçu depuis le XVIIe siècle — d''abord par le travail d''esclaves africains, sous administration coloniale portugaise. Le sol y est sombre, alluvial, enrichi par des siècles de crues et de dépôts, et il donne une feuille d''une douceur naturelle qui n''a rien du caractère abrupt du tabac cubain ni de l''intensité poivrée du nicaraguayen. Elle est plus proche d''un bon Sumatra indonésien que d''aucune variété caribéenne : souple, légèrement épicée, avec une finale de noix de cajou et de miel qui la destine aux petits formats accessibles.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'en', 'histoire 2 (nouveau texte)', (LOCATE(CAST('The tobacco comes from the Mata Fina region in Bahia: according to the house, more than 200 partner farms grow the filler there, and the 1,000-hectare Fazenda San Antônio farm supplies all the wrappers of the premium cigar ranges. The tobacco bales age there before manufacture.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'en', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Bahian tobacco has been cultivated in the fertile valleys south of the Rio Paraguaçu since the seventeenth century, originally by enslaved African labor under Portuguese colonial administration. The soil there — dark, alluvial, rich in organic matter from centuries of flooding and deposit — produces a leaf of natural softness and mild sweetness that bears no resemblance to the aggressive character of Cuban tobacco or the peppery intensity of Nicaraguan. It is closer in profile to good Indonesian Sumatra than to any Caribbean variety: gentle, slightly spiced, with a finish of cashew and honey that makes it uniquely suitable for accessible cigar formats.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'es', 'histoire 2 (nouveau texte)', (LOCATE(CAST('El tabaco viene de la región de Mata Fina, en Bahía: según la casa, más de 200 fincas asociadas cultivan allí la tripa, y la finca Fazenda San Antônio, de 1000 hectáreas, suministra todas las capas de las gamas de puros premium. Las pacas de tabaco envejecen allí antes de la fabricación.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'es', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('El tabaco bahiano se cultiva en los valles fértiles al sur del Río Paraguaçu desde el siglo XVII —primero mediante el trabajo de esclavos africanos, bajo administración colonial portuguesa. El suelo es allí oscuro, aluvial, enriquecido por siglos de crecidas y de depósitos, y da una hoja de una dulzura natural que nada tiene del carácter abrupto del tabaco cubano ni de la intensidad apimentada del nicaragüense. Está más cerca de un buen Sumatra indonesio que de ninguna variedad caribeña: flexible, ligeramente especiada, con un final de anacardo y de miel que la destina a los formatos pequeños y accesibles.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'de', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Der Tabak stammt aus der Region Mata Fina in Bahia: Laut dem Haus bauen dort mehr als 200 Partnerfarmen die Einlage an, und die 1000 Hektar große Farm Fazenda San Antônio liefert alle Deckblätter der Premium-Zigarrenlinien. Die Tabakballen reifen dort vor der Herstellung.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'de', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Der bahianische Tabak wird in den fruchtbaren Tälern südlich des Rio Paraguaçu seit dem 17. Jahrhundert angebaut — zuerst durch die Arbeit afrikanischer Sklaven, unter portugiesischer Kolonialverwaltung. Der Boden ist dort dunkel, angeschwemmt, von Jahrhunderten der Überflutungen und Ablagerungen angereichert, und er gibt ein Blatt von natürlicher Milde, das nichts vom schroffen Wesen des kubanischen Tabaks und nichts von der pfeffrigen Intensität des nicaraguanischen hat. Es steht einem guten indonesischen Sumatra näher als irgendeiner karibischen Sorte: geschmeidig, leicht gewürzt, mit einem Abgang aus Cashew und Honig, der es für die kleinen, zugänglichen Formate bestimmt.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'zh', 'histoire 2 (nouveau texte)', (LOCATE(CAST('烟草产自巴伊亚的 Mata Fina 地区：公司称，那里有200多家合作农场种植茄芯烟叶，面积1000公顷的 Fazenda San Antônio 农场供应高端雪茄系列的全部茄衣。烟叶包在那里陈放，然后才进入生产。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'zh', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('巴伊亚烟草自17世纪起就种在帕拉瓜苏河以南的肥沃谷地里——起初依靠非洲奴隶的劳动，处在葡萄牙殖民当局的管理之下。那里的土壤深色、冲积而成，由数百年的泛滥与沉积淤积得深厚，长出的叶子带着一种天然的柔和，既没有古巴烟草的硬朗，也没有尼加拉瓜烟草的胡椒式强度。它更接近一片好的印尼苏门答腊叶，而不像任何加勒比品种：柔韧、微带香料，收尾是腰果与蜂蜜，正合适做小而可及的规格。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'ar', 'histoire 2 (nouveau texte)', (LOCATE(CAST('يأتي التبغ من منطقة Mata Fina في باهيا: تقول الدار إنّ ما يزيد على 200 مزرعة شريكة تزرع فيها الحشوة، وإنّ مزرعة Fazenda San Antônio، ومساحتها 1000 هكتار، تمدّ بجميع الأغلفة الخارجية لسلاسل السيجار الفاخرة. وتُعتَّق بالات التبغ هناك قبل التصنيع.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'ar', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('يُزرع تبغ باهيا في الوديان الخصبة جنوب نهر باراغواسو منذ القرن السابع عشر — بعمل العبيد الأفارقة في البداية، تحت الإدارة الاستعمارية البرتغالية. والتربة هناك داكنة، غرينية، أغنتها قرون من الفيضانات والرواسب، وهي تعطي ورقة ذات لطف طبيعي لا شيء فيه من حدّة التبغ الكوبي ولا من شدّة النيكاراغوي الفلفلية. إنها أقرب إلى سومطرة إندونيسية جيدة منها إلى أي صنف كاريبي: ليّنة، متبّلة قليلًا، بنهاية من الكاجو والعسل تجعلها للقياسات الصغيرة الميسورة.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'fr', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Dannemann comprit le potentiel commercial de ce tabac pour le marché européen, à un moment où la classe moyenne allemande prenait goût aux petits cigares et aux cigarillos comme habitude quotidienne abordable. Il fonda sa manufacture à São Félix da Cachoeira — bourg colonial situé sur l''autre rive du Rio Paraguaçu, face au marché plus important de Cachoeira — et consacra sa première décennie à établir à la fois son approvisionnement et ses réseaux de distribution européens.

' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'en', 'histoire 3 (ancien texte parti)', (LOCATE(CAST(CONCAT('Dannemann recognized the commercial potential of Bahian tobacco for the European market at a moment when the German middle class was developing a taste for small cigars and cigarillos as an affordable daily habit. He founded his factory in São Félix da Cachoeira — a colonial town directly across the Rio Paraguaçu from the larger market of Cachoeira — and spent his first decade establishing both his tobacco sourcing and his European distribution relationships.', CHAR(13), '
', CHAR(13), '
') AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'es', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Dannemann comprendió el potencial comercial de ese tabaco para el mercado europeo, en un momento en que la clase media alemana tomaba gusto a los cigarros pequeños y a los cigarrillos puros como hábito cotidiano asequible. Fundó su manufactura en São Félix da Cachoeira —villa colonial situada en la otra orilla del Río Paraguaçu, frente al mercado más importante de Cachoeira— y dedicó su primera década a establecer a la vez su abastecimiento y sus redes de distribución europeas.

' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'de', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Dannemann erkannte das kaufmännische Vermögen dieses Tabaks für den europäischen Markt, zu einer Zeit, als die deutsche Mittelschicht Gefallen an kleinen Zigarren und Zigarillos als erschwinglicher täglicher Gewohnheit fand. Er gründete seine Manufaktur in São Félix da Cachoeira — einem Kolonialstädtchen am anderen Ufer des Rio Paraguaçu, gegenüber dem größeren Markt von Cachoeira — und verwandte sein erstes Jahrzehnt darauf, zugleich seine Beschaffung und seine europäischen Vertriebsnetze aufzubauen.

' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'zh', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('丹尼曼看出了这种烟草对欧洲市场的商业潜力：那时德国中产阶级正开始把小雪茄与迷你雪茄当作负担得起的日常习惯。他在圣费利克斯-达卡绍埃拉建起工厂——那是帕拉瓜苏河对岸的一座殖民时期小镇，隔水面对更大的市镇卡绍埃拉——并把最初十年用在同时建立货源与欧洲的分销网络上。

' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'ar', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('أدرك دانيمان ما لهذا التبغ من إمكان تجاري في السوق الأوروبية، في لحظة كانت فيها الطبقة الوسطى الألمانية تستطيب السيجار الصغير والسيجارلّو عادةً يومية في المتناول. فأسّس مصنعه في ساو فيليكس دا كاشويرا — بلدة استعمارية على الضفة الأخرى من نهر باراغواسو، قبالة سوق كاشويرا الأكبر — وكرّس عقده الأول لبناء تزوّده وشبكات توزيعه الأوروبية معًا.

' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'fr', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Selon Wikipédia, Dannemann fusionne en 1922 avec la maison Stender pour former la Companhia de Charutos Dannemann ; pendant la guerre, l''affaire brésilienne est expropriée et gérée par le Banco do Brasil ; en 1988, le groupe suisse Burger rachète les droits de marque allemands et reprend Dannemann GmbH, à Lübbecke. En octobre 2026, le groupe DANNEMANN se dit familial et suisse, holding à Rotkreuz, et compte dix sites de production ; la fabrique de São Félix, qu''il nomme Terra Dannemann, est toujours en activité.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'fr', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('L''entreprise est restée à São Félix pendant cent cinquante ans. L''entrepôt colonial que Dannemann fit convertir en 1873 a été agrandi et modernisé, jamais déplacé. La maison demeura dans la famille pendant quatre générations avant que le groupe suisse Burger Söhne ne rachète Dannemann GmbH, en 1988 — mais le lieu de production, l''approvisionnement auprès des fermes bahianaises voisines et la proposition même du produit n''ont pas bougé. Peu de produits de consommation soignés peuvent en dire autant sur un siècle et demi.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'en', 'histoire 4 (nouveau texte)', (LOCATE(CAST('According to Wikipedia, Dannemann merged in 1922 with the Stender company to form the Companhia de Charutos Dannemann; during the war, the Brazilian business was expropriated and run by the Banco do Brasil; in 1988, the Swiss Burger group bought the German trademark rights and took over Dannemann GmbH, in Lübbecke. In October 2026, the DANNEMANN group describes itself as family-owned and Swiss, a holding company in Rotkreuz, and counts ten production sites; the São Félix factory, which it calls Terra Dannemann, is still in operation.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'en', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('The operation has remained in São Félix for 150 years. The colonial warehouse that Dannemann converted in 1873 has been expanded and updated but never relocated. The company passed through the Dannemann family for four generations before the Swiss group Burger Söhne bought Dannemann GmbH, in 1988 — but the production location, the tobacco sourcing from surrounding Bahian farms, and the fundamental proposition of the product have remained constant. Dannemann cigarillos are one of the few luxury consumer products whose manufacturing context has genuinely not moved in a century and a half.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'es', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Según Wikipedia, Dannemann se fusiona en 1922 con la casa Stender para formar la Companhia de Charutos Dannemann; durante la guerra, el negocio brasileño es expropiado y gestionado por el Banco do Brasil; en 1988, el grupo suizo Burger compra los derechos de marca alemanes y asume Dannemann GmbH, en Lübbecke. En octubre de 2026, el grupo DANNEMANN se dice familiar y suizo, con holding en Rotkreuz, y cuenta diez centros de producción; la fábrica de São Félix, que llama Terra Dannemann, sigue en actividad.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'es', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('La empresa ha permanecido en São Félix ciento cincuenta años. El almacén colonial que Dannemann hizo convertir en 1873 ha sido ampliado y modernizado, nunca desplazado. La casa siguió en la familia durante cuatro generaciones antes de que el grupo suizo Burger Söhne comprara Dannemann GmbH, en 1988 —pero el lugar de producción, el abastecimiento en las fincas bahianas vecinas y la propuesta misma del producto no se han movido. Pocos productos de consumo cuidados pueden decir otro tanto a lo largo de siglo y medio.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'de', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Laut Wikipedia fusioniert Dannemann 1922 mit dem Haus Stender zur Companhia de Charutos Dannemann; im Krieg wird das brasilianische Geschäft enteignet und vom Banco do Brasil verwaltet; 1988 kauft die Schweizer Gruppe Burger die deutschen Markenrechte und übernimmt die Dannemann GmbH in Lübbecke. Im Oktober 2026 bezeichnet sich die Gruppe DANNEMANN als Familienunternehmen und schweizerisch, mit Holding in Rotkreuz, und zählt zehn Produktionsstandorte; die Fabrik in São Félix, die sie Terra Dannemann nennt, ist weiterhin in Betrieb.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'de', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('Das Unternehmen ist seit hundertfünfzig Jahren in São Félix geblieben. Das koloniale Lagerhaus, das Dannemann 1873 umbauen ließ, wurde erweitert und erneuert, nie verlegt. Das Haus blieb vier Generationen lang in der Familie, ehe die Schweizer Gruppe Burger Söhne 1988 die Dannemann GmbH übernahm — doch der Produktionsort, die Versorgung von den benachbarten bahianischen Farmen und der Vorschlag des Erzeugnisses selbst haben sich nicht bewegt. Wenige sorgfältige Konsumgüter können über anderthalb Jahrhunderte dasselbe von sich sagen.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'zh', 'histoire 4 (nouveau texte)', (LOCATE(CAST('据 Wikipedia 记载，Dannemann 于1922年与 Stender 公司合并，组成 Companhia de Charutos Dannemann；战争期间，巴西的业务被征收，由 Banco do Brasil 管理；1988年，瑞士的 Burger 集团收购德国的商标权，并接手位于 Lübbecke 的 Dannemann GmbH。2026年10月，DANNEMANN 集团自称为家族企业、瑞士集团，控股公司设在 Rotkreuz，拥有十个生产基地；其位于圣费利克斯的工厂被集团称作 Terra Dannemann，仍在运营。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'zh', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('这家企业在圣费利克斯待了一百五十年。丹尼曼1873年改建的那座殖民时期仓库，被扩建过、现代化过，却从未搬迁。在瑞士的 Burger Söhne 集团于 1988 年收购德国的 Dannemann GmbH 之前，这个字号在家族手里传了四代——但生产的地点、来自邻近巴伊亚农场的供应，以及产品本身的主张，都没有动过。在一个半世纪的跨度上，能这样说的讲究消费品并不多。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'ar', 'histoire 4 (nouveau texte)', (LOCATE(CAST('تذكر Wikipedia أنّ Dannemann اندمجت سنة 1922 مع دار Stender لتشكّل Companhia de Charutos Dannemann؛ وفي أثناء الحرب صودر النشاط البرازيلي وأدارته Banco do Brasil؛ وفي سنة 1988 اشترت المجموعة السويسرية Burger حقوق العلامة الألمانية وتولّت Dannemann GmbH في لوبكه. وفي أكتوبر 2026 تصف مجموعة DANNEMANN نفسها بأنها عائلية وسويسرية، شركتها القابضة في Rotkreuz، وتعدّ عشرة مواقع إنتاج؛ ومصنع ساو فيليكس، الذي تسمّيه Terra Dannemann، لا يزال عاملًا.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'ar', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('بقيت الشركة في ساو فيليكس مئة وخمسين عامًا. أما المستودع الاستعماري الذي حوّله دانيمان عام 1873 فقد وُسّع وحُدِّث، ولم يُنقَل قطّ. وظلّت الدار في العائلة أربعة أجيال قبل أن تشتري المجموعة السويسرية «بورغر زونه» شركة دانيمان الألمانية عام 1988 — غير أنّ مكان الإنتاج، والتزوّد من المزارع الباهية المجاورة، وطرح المنتج نفسه، لم تتزحزح. وقليل من منتجات الاستهلاك المتقنة يمكنه قول مثل ذلك على امتداد قرن ونصف.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'fr', 'histoire 5 (nouveau texte)', (LOCATE(CAST('Ce qui place cette maison au Brésil est le lieu de roulage. La marque Dannemann vendue en Europe, des cigarillos et des cigares short filler, est décrite par la maison comme cultivée au Brésil mais fabriquée en Europe ; Lübbecke produit surtout des cigarillos, Reinach des mélanges et des cigarillos, Brissago des cigares spéciaux. Les marques Moods et Al Capone du même groupe sont d''autres marques ; les Al Capone roulés à la main à Danlí, au Honduras, ne sont pas ceux-ci. Seuls les longfillers roulés à São Félix entrent ici.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'fr', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('Une précision décide de la place de cette maison dans cet atlas. Le groupe fait aussi des cigarillos — mais pas ici : ceux-là sortent de Lübbecke, en Allemagne, et des ateliers suisses de Brissago et Reinach. São Félix est la fabrique de longfillers, où des charuteiras roulent à la main. L''atlas ne porte que ce qui sort de São Félix.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'en', 'histoire 5 (nouveau texte)', (LOCATE(CAST('What places this house in Brazil is the place where the cigars are rolled. The Dannemann brand sold in Europe, cigarillos and short filler cigars, is described by the house as grown in Brazil but made in Europe; Lübbecke mainly produces cigarillos, Reinach blends and cigarillos, Brissago special cigars. The Moods and Al Capone brands of the same group are other brands; the Al Capone hand-rolled in Danlí, Honduras, are not these. Only the long fillers hand-rolled at São Félix are included here.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'en', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('One detail settles this house''s place in this atlas. The group also makes cigarillos — but not here: those come out of Lübbecke, in Germany, and the Swiss workshops at Brissago and Reinach. São Félix is the long filler factory, where charuteiras roll by hand. This atlas holds only what comes out of São Félix.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'es', 'histoire 5 (nouveau texte)', (LOCATE(CAST('Lo que sitúa a esta casa en Brasil es el lugar de liado. La marca Dannemann vendida en Europa, cigarritos y puros de tripa corta, la describe la casa como cultivada en Brasil pero fabricada en Europa; Lübbecke produce sobre todo cigarritos, Reinach mezclas y cigarritos, Brissago puros especiales. Las marcas Moods y Al Capone del mismo grupo son otras marcas; los Al Capone liados a mano en Danlí, en Honduras, no son estos. Aquí solo entran los puros de tripa larga liados en São Félix.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'es', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('Una precisión decide el lugar de esta casa en este atlas. El grupo hace también cigarritos, pero no aquí: esos salen de Lübbecke, en Alemania, y de los talleres suizos de Brissago y Reinach. São Félix es la fábrica de tripa larga, donde las charuteiras lían a mano. Este atlas solo recoge lo que sale de São Félix.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'de', 'histoire 5 (nouveau texte)', (LOCATE(CAST('Was dieses Haus in Brasilien verortet, ist der Ort des Rollens. Die in Europa verkaufte Marke Dannemann, Zigarillos und Zigarren mit kurzer Einlage, beschreibt das Haus als in Brasilien angebaut, aber in Europa hergestellt; Lübbecke produziert vor allem Zigarillos, Reinach Mischungen und Zigarillos, Brissago Spezialzigarren. Die Marken Moods und Al Capone derselben Gruppe sind andere Marken; die in Danlí in Honduras von Hand gerollten Al Capone sind nicht diese. Nur die in São Félix von Hand gerollten Longfiller kommen hier vor.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'de', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('Eine Präzisierung entscheidet über den Platz dieses Hauses in diesem Atlas. Die Gruppe stellt auch Zigarillos her — aber nicht hier: Die kommen aus Lübbecke in Deutschland und aus den Schweizer Werkstätten in Brissago und Reinach. São Félix ist die Longfiller-Fabrik, in der Charuteiras von Hand rollen. Dieser Atlas führt nur, was aus São Félix kommt.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'zh', 'histoire 5 (nouveau texte)', (LOCATE(CAST('这家公司之所以归在巴西，是因为卷制地点在这里。Dannemann 品牌在欧洲销售的是小雪茄和短填料雪茄，公司称其烟草种在巴西、制造在欧洲；Lübbecke 主要生产小雪茄，Reinach 生产混合烟丝和小雪茄，Brissago 生产特色雪茄。同一集团的 Moods 和 Al Capone 是另外的品牌；在洪都拉斯 Danlí 手工卷制的 Al Capone 不是这些。这里只收录在圣费利克斯手工卷制的长填料雪茄。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'zh', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('有一点决定了这家在本图集中的位置。集团也生产小雪茄——但不在这里：那些出自德国的吕贝克，以及瑞士布里萨戈与赖纳赫的工坊。圣费利克斯是长填料工厂，由被称作 charuteiras 的女卷烟师手工卷制。本图集只收录出自圣费利克斯的产品。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'ar', 'histoire 5 (nouveau texte)', (LOCATE(CAST('ما يضع هذه الدار في البرازيل هو مكان اللفّ. فعلامة Dannemann المباعة في أوروبا، وهي سيجارات صغيرة (سيجارلّو) وسيجار بحشوة قصيرة، تصفها الدار بأنها مزروعة في البرازيل ومصنوعة في أوروبا؛ وتنتج لوبكه في الغالب السيجارلّو، وتنتج رايناخ خلطات وسيجارلّو، وتنتج بريساغو سيجارًا خاصًا. وعلامتا Moods وAl Capone من المجموعة نفسها علامتان أخريان؛ وسيجار Al Capone المفتول يدويًا في دانلي بهندوراس ليس هذا. ولا يدخل هنا إلا ما لُفّ باليد من سيجار بحشوة طويلة في ساو فيليكس.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'ar', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('ثمّة تفصيل يحسم مكانة هذه الدار في هذا الأطلس. فالمجموعة تصنع أيضًا سيجارات صغيرة — لكن ليس هنا: تلك تخرج من لوبكه في ألمانيا، ومن الورشتين السويسريتين في بريساغو ورايناخ. أمّا ساو فيليكس فهي مصنع الحشوة الطويلة، حيث تلفّ الـ«تشاروتيراس» باليد. ولا يضمّ هذا الأطلس إلا ما يخرج من ساو فيليكس.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'fr', 'histoire 6 (nouveau texte)', (LOCATE(CAST('Le Centro Cultural Dannemann occupe l''ancien bâtiment colonial de la fabrique, à São Félix. Selon la presse économique de 2012, vingt personnes y travaillaient et le premier revenu du groupe à Bahia venait de Danco, son usine de traitement de feuilles ; un reportage de 2017 date le bâtiment de 1892. Une ligne premium, Elementum, qui porte l''année de récolte, a été présentée au Festival Origem du Recôncavo (Brazil Journal, 4 octobre 2020) ; la page ne dit pas qui la fabrique.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'fr', 'histoire 6 (ancien texte parti)', (LOCATE(CAST('La presse économique de 2012 comptait vingt personnes au Centro Dannemann de São Félix, à la fois fabrique et centre culturel tourné vers les visiteurs, et notait que le premier revenu du groupe suisse à Bahia venait de Danco, son usine de traitement de feuilles, non des cigares. Un reportage de 2017 date le bâtiment du Centro de 1892 — la maison, elle, de 1873. En 2026, l''Apcab, l''association des producteurs artisanaux, compte quatre fabricants pour l''essentiel du segment ; la fiche ne sait pas si Dannemann en est.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'en', 'histoire 6 (nouveau texte)', (LOCATE(CAST('The Centro Cultural Dannemann occupies the former colonial building of the factory, in São Félix. According to the business press of 2012, twenty people worked there and the group''s first income in Bahia came from Danco, its leaf-processing plant; a 2017 report dates the building to 1892. A premium line, Elementum, which carries the harvest year, was presented at the Festival Origem of the Recôncavo (Brazil Journal, 4 October 2020); the page does not say who makes it.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'en', 'histoire 6 (ancien texte parti)', (LOCATE(CAST('The business press of 2012 counted twenty people at the Centro Dannemann in São Félix, both factory and cultural centre turned toward visitors, and noted that the Swiss group''s first income in Bahia came from Danco, its leaf-processing plant, not from cigars. A 2017 report dates the Centro''s building to 1892 — the house itself to 1873. In 2026 Apcab, the artisanal producers'' association, counts four manufacturers for the bulk of the segment; the entry does not know whether Dannemann is one of them.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'es', 'histoire 6 (nouveau texte)', (LOCATE(CAST('El Centro Cultural Dannemann ocupa el antiguo edificio colonial de la fábrica, en São Félix. Según la prensa económica de 2012, trabajaban allí veinte personas y el primer ingreso del grupo en Bahía venía de Danco, su planta de procesado de hojas; un reportaje de 2017 fecha el edificio en 1892. Una línea premium, Elementum, que lleva el año de cosecha, se presentó en el Festival Origem del Recôncavo (Brazil Journal, 4 de octubre de 2020); la página no dice quién la fabrica.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'es', 'histoire 6 (ancien texte parti)', (LOCATE(CAST('La prensa económica de 2012 contaba veinte personas en el Centro Dannemann de São Félix, a la vez fábrica y centro cultural vuelto hacia los visitantes, y anotaba que el primer ingreso del grupo suizo en Bahía venía de Danco, su planta de procesado de hojas, no de los puros. Un reportaje de 2017 fecha el edificio del Centro en 1892 — la casa, en 1873. En 2026 la Apcab, la asociación de productores artesanales, cuenta cuatro fabricantes para lo esencial del segmento; la ficha no sabe si Dannemann es uno de ellos.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'de', 'histoire 6 (nouveau texte)', (LOCATE(CAST('Das Centro Cultural Dannemann belegt das ehemalige Kolonialgebäude der Fabrik in São Félix. Laut der Wirtschaftspresse von 2012 arbeiteten dort zwanzig Menschen, und die ersten Einnahmen der Gruppe in Bahia kamen von Danco, ihrem Blattverarbeitungswerk; eine Reportage von 2017 datiert das Gebäude auf 1892. Eine Premium-Linie, Elementum, die das Erntejahr trägt, wurde auf dem Festival Origem des Recôncavo vorgestellt (Brazil Journal, 4. Oktober 2020); die Seite sagt nicht, wer sie herstellt.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'de', 'histoire 6 (ancien texte parti)', (LOCATE(CAST('Die Wirtschaftspresse von 2012 zählte zwanzig Menschen im Centro Dannemann in São Félix, zugleich Fabrik und den Besuchern zugewandtes Kulturzentrum, und vermerkte, dass die ersten Einnahmen der Schweizer Gruppe in Bahia von Danco kamen, ihrem Blattverarbeitungswerk, nicht von Zigarren. Eine Reportage von 2017 datiert das Gebäude des Centro auf 1892 — das Haus selbst auf 1873. 2026 zählt die Apcab, der Verband der handwerklichen Hersteller, vier Fabrikanten für den Großteil des Segments; der Eintrag weiß nicht, ob Dannemann dazugehört.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'zh', 'histoire 6 (nouveau texte)', (LOCATE(CAST('Centro Cultural Dannemann 占用工厂在圣费利克斯的旧殖民时期建筑。据2012年的经济媒体报道，那里有二十人工作，集团在巴伊亚的头一笔收入来自其烟叶加工厂 Danco；2017年的一篇报道把该建筑的年代定在1892年。一条标有收获年份的高端系列 Elementum，曾在雷孔卡沃的 Festival Origem 上亮相（Brazil Journal，2020年10月4日）；该页面没有说明由谁制造。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Dannemann'
UNION ALL SELECT 'Dannemann', 'zh', 'histoire 6 (ancien texte parti)', (LOCATE(CAST('2012年的经济媒体数到圣费利克斯的 Centro Dannemann 有二十人，既是工厂也是面向访客的文化中心，并指出瑞士集团在巴伊亚的第一大收入来自其烟叶加工厂 Danco，而非雪茄。2017年一篇报道把 Centro 的建筑定在1892年——公司本身则是1873年。2026年，手工生产者协会 Apcab 认定四家制造商占该领域主要份额；词条不知道 Dannemann 是否在其中。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Dannemann'
