UNION ALL SELECT 'Te Amo', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('تي-آمو هو السيجار المكسيكي الذي دخّنته أمريكا قبل أن تعرف أنّه مكسيكي. في السبعينيات كان في كلّ مكان — سيجار عامل، كان يُباع، بحسب ألبرتو تورينت (2009)، بثمانين سنتًا، وله مئة وسبعون نقطة بيع حول نيويورك، وكان يحقّق هناك نحو ستين في المئة من مبيعات العلامة في السبعينيات.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Te Amo'
UNION ALL SELECT 'Te Amo', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('تي-آمو هو السيجار المكسيكي الذي دخّنته أمريكا قبل أن تعرف أنّه مكسيكي. في السبعينيات كان في كلّ مكان — سيجار عامل، يُباع بثمانين سنتًا، أعطى اسمه لقياس «تورو» وأبقى مئة وسبعين نقطة بيع حول نيويورك على قيد الحياة، ومنها كانت تأتي ستّ مبيعات من كلّ عشر.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Te Amo'
UNION ALL SELECT 'Te Amo', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('La famille qui le fait est dans le tabac de San Andrés depuis 1880. Alberto Turrent y entre en 1960, à vingt-deux ans, comme chauffeur de camion. La marque naît en 1966 selon Alberto Turrent ; d''autres sources donnent 1963 ou 1964, et la date n''est pas tranchée. Elle commence par un échec : deux millions de cigares emballés et invendus, un essai à Miami qui ne prend pas, puis New York. En 1972, à la mort de l''associé new-yorkais, la famille rachète la société Te-Amo.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Te Amo'
UNION ALL SELECT 'Te Amo', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('La famille qui le fait est dans le tabac de San Andrés depuis 1880. Alberto Turrent y entre en 1960, à vingt-deux ans, comme chauffeur de camion. La marque naît en 1966 — halfwheel dit 1963, l''atlas retient la date qu''Alberto Turrent a donnée lui-même — et commence par un échec : deux millions de cigares emballés et invendus, un essai à Miami qui ne prend pas, puis New York. En 1972, à la mort de l''associé new-yorkais, la famille rachète la société Te-Amo.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Te Amo'
UNION ALL SELECT 'Te Amo', 'en', 'histoire 2 (nouveau texte)', (LOCATE(CAST('The family that makes it has been in San Andrés tobacco since 1880. Alberto Turrent entered in 1960, at twenty-two, as a truck driver. The brand was born in 1966 according to Alberto Turrent; other sources give 1963 or 1964, and the date is not settled. It began with a failure: two million cigars packed and unsold, a try in Miami that did not take, then New York. In 1972, when the New York partner died, the family bought the Te-Amo company.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Te Amo'
UNION ALL SELECT 'Te Amo', 'en', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('The family that makes it has been in San Andrés tobacco since 1880. Alberto Turrent entered in 1960, at twenty-two, as a truck driver. The brand was born in 1966 — halfwheel says 1963; this atlas keeps the date Alberto Turrent gave himself — and began with a failure: two million cigars packed and unsold, a try in Miami that did not take, then New York. In 1972, when the New York partner died, the family bought the Te-Amo company.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Te Amo'
UNION ALL SELECT 'Te Amo', 'es', 'histoire 2 (nouveau texte)', (LOCATE(CAST('La familia que lo hace está en el tabaco de San Andrés desde 1880. Alberto Turrent entra en 1960, a los veintidós años, como chofer de camión. La marca nace en 1966 según Alberto Turrent; otras fuentes dan 1963 o 1964, y la fecha no está zanjada. Empieza con un fracaso: dos millones de puros empacados y sin vender, un intento en Miami que no cuaja, luego Nueva York. En 1972, a la muerte del socio neoyorquino, la familia compra la sociedad Te-Amo.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Te Amo'
UNION ALL SELECT 'Te Amo', 'es', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('La familia que lo hace está en el tabaco de San Andrés desde 1880. Alberto Turrent entra en 1960, a los veintidós años, como chofer de camión. La marca nace en 1966 — halfwheel dice 1963; este atlas retiene la fecha que el propio Alberto Turrent dio — y empieza con un fracaso: dos millones de puros empacados y sin vender, un intento en Miami que no cuaja, luego Nueva York. En 1972, a la muerte del socio neoyorquino, la familia compra la sociedad Te-Amo.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Te Amo'
UNION ALL SELECT 'Te Amo', 'de', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Die Familie, die sie macht, ist seit 1880 im Tabak von San Andrés. Alberto Turrent stieg 1960 ein, mit zweiundzwanzig, als Lastwagenfahrer. Die Marke entstand 1966 laut Alberto Turrent; andere Quellen nennen 1963 oder 1964, und das Datum ist nicht geklärt. Sie begann mit einem Fehlschlag: zwei Millionen Zigarren verpackt und unverkauft, ein Versuch in Miami, der nicht zündete, dann New York. 1972, beim Tod des New Yorker Partners, kaufte die Familie die Firma Te-Amo.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Te Amo'
UNION ALL SELECT 'Te Amo', 'de', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Die Familie, die sie macht, ist seit 1880 im Tabak von San Andrés. Alberto Turrent stieg 1960 ein, mit zweiundzwanzig, als Lastwagenfahrer. Die Marke entstand 1966 — halfwheel sagt 1963; dieser Atlas behält das Datum, das Alberto Turrent selbst nannte — und begann mit einem Fehlschlag: zwei Millionen Zigarren verpackt und unverkauft, ein Versuch in Miami, der nicht zündete, dann New York. 1972, beim Tod des New Yorker Partners, kaufte die Familie die Firma Te-Amo.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Te Amo'
UNION ALL SELECT 'Te Amo', 'zh', 'histoire 2 (nouveau texte)', (LOCATE(CAST('制作它的家族自1880年起就在圣安德烈斯种烟。阿尔贝托·图伦特1960年二十二岁入行，从卡车司机做起。品牌诞生于1966年，据阿尔贝托·图伦特所述；其他来源给出1963年或1964年，日期尚无定论。起步即失败：两百万支雪茄装好却卖不出去，迈阿密试水不成，转往纽约。1972年纽约合伙人去世，家族买下 Te-Amo 公司。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Te Amo'
UNION ALL SELECT 'Te Amo', 'zh', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('制作它的家族自1880年起就在圣安德烈斯种烟。阿尔贝托·图伦特1960年二十二岁入行，从卡车司机做起。品牌诞生于1966年——halfwheel 说1963年；本图集采用阿尔贝托·图伦特本人给出的日期——起步即失败：两百万支雪茄装好却卖不出去，迈阿密试水不成，转往纽约。1972年纽约合伙人去世，家族买下 Te-Amo 公司。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Te Amo'
UNION ALL SELECT 'Te Amo', 'ar', 'histoire 2 (nouveau texte)', (LOCATE(CAST('العائلة التي تصنعه في تبغ سان أندريس منذ 1880. دخل ألبرتو تورينت العمل سنة 1960، في الثانية والعشرين، سائقَ شاحنة. وُلدت العلامة سنة 1966 بحسب ألبرتو تورينت؛ وتذكر مصادر أخرى 1963 أو 1964، والتاريخ لم يُحسم. وبدأت بإخفاق: مليونا سيجار مُعبّأة لم تُبَع، ومحاولة في ميامي لم تنجح، ثم نيويورك. وفي 1972، عند وفاة الشريك النيويوركي، اشترت العائلة شركة تي-آمو.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Te Amo'
UNION ALL SELECT 'Te Amo', 'ar', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('العائلة التي تصنعه في تبغ سان أندريس منذ 1880. دخل ألبرتو تورينت العمل سنة 1960، في الثانية والعشرين، سائقَ شاحنة. وُلدت العلامة سنة 1966 — تقول halfwheel 1963؛ ويحتفظ هذا الأطلس بالتاريخ الذي أعطاه ألبرتو تورينت بنفسه — وبدأت بإخفاق: مليونا سيجار مُعبّأة لم تُبَع، ومحاولة في ميامي لم تنجح، ثم نيويورك. وفي 1972، عند وفاة الشريك النيويوركي، اشترت العائلة شركة تي-آمو.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Te Amo'
UNION ALL SELECT 'Te Amo', 'fr', 'histoire 3 (nouveau texte)', (LOCATE(CAST('En février 2024, la presse du métier écrit qu''Altadis U.S.A. possède la marque aux États-Unis et que les Turrent la possèdent dans le reste du monde. Les cigares sont toujours faits au Mexique par les Turrent ; Alberto Turrent (2009) donne Nueva Matacapan de Tabacos, à San Andrés Tuxtla, comme leur fabrique, et la décrit comme un producteur de tabac à cigares du pays. L''atlas porte la fiche de la famille sous le nom de Casa Turrent ; Te-Amo (Mexique) n''est ni un homonyme New World ni une marque dominicaine.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Te Amo'
UNION ALL SELECT 'Te Amo', 'fr', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Depuis 2000 et la fusion de Consolidated Cigar dans Altadis, la marque appartient au groupe. Elle est toujours faite par les Turrent, dans leur fabrique de San Andrés Tuxtla, Nueva Matacapan de Tabacos, sur deux mille acres de terre volcanique où poussent le San Andrés Negro, de semence Criollo, et le Sumatra. C''est le premier producteur de tabac à cigares du Mexique, et l''atlas porte déjà la fiche de la famille sous le nom de Casa Turrent. Une marque de groupe faite dans l''usine d''une famille qui a sa propre fiche : même cas que Bolívar Honduras chez Scandinavian Tobacco.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Te Amo'
UNION ALL SELECT 'Te Amo', 'en', 'histoire 3 (nouveau texte)', (LOCATE(CAST('In February 2024, the trade press writes that Altadis U.S.A. owns the brand in the United States and that the Turrents own it in the rest of the world. The cigars are still made in Mexico by the Turrents; Alberto Turrent (2009) gives Nueva Matacapan de Tabacos, in San Andrés Tuxtla, as their factory, and describes it as a cigar-tobacco producer in the country. The atlas carries the family''s entry under the name Casa Turrent; Te-Amo (Mexico) is neither a New World namesake nor a Dominican brand.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Te Amo'
UNION ALL SELECT 'Te Amo', 'en', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Since 2000 and the merger of Consolidated Cigar into Altadis, the brand belongs to the group. It is still made by the Turrents, in their San Andrés Tuxtla factory, Nueva Matacapan de Tabacos, on two thousand acres of volcanic land growing San Andrés Negro, of Criollo seed, and Sumatra. It is Mexico''s largest cigar-tobacco producer, and this atlas already carries the family''s entry under the name Casa Turrent. A group brand made in the factory of a family that has its own entry: the same case as Bolívar Honduras at Scandinavian Tobacco.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Te Amo'
UNION ALL SELECT 'Te Amo', 'es', 'histoire 3 (nouveau texte)', (LOCATE(CAST('En febrero de 2024, la prensa del sector escribe que Altadis U.S.A. posee la marca en Estados Unidos y que los Turrent la poseen en el resto del mundo. Los puros se siguen haciendo en México por los Turrent; Alberto Turrent (2009) da Nueva Matacapan de Tabacos, en San Andrés Tuxtla, como su fábrica, y la describe como un productor de tabaco para puros del país. El atlas lleva la ficha de la familia bajo el nombre de Casa Turrent; Te-Amo (México) no es ni un homónimo New World ni una marca dominicana.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Te Amo'
UNION ALL SELECT 'Te Amo', 'es', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Desde 2000 y la fusión de Consolidated Cigar en Altadis, la marca pertenece al grupo. La siguen haciendo los Turrent, en su fábrica de San Andrés Tuxtla, Nueva Matacapan de Tabacos, sobre dos mil acres de tierra volcánica donde crecen el San Andrés Negro, de semilla Criollo, y el Sumatra. Es el mayor productor de tabaco para puros de México, y este atlas ya lleva la ficha de la familia bajo el nombre de Casa Turrent. Una marca de grupo hecha en la fábrica de una familia que tiene su propia ficha: el mismo caso que Bolívar Honduras en Scandinavian Tobacco.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Te Amo'
UNION ALL SELECT 'Te Amo', 'de', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Im Februar 2024 schreibt die Fachpresse, Altadis U.S.A. besitze die Marke in den Vereinigten Staaten und die Turrents besäßen sie im Rest der Welt. Die Zigarren werden weiterhin in Mexiko von den Turrents gemacht; Alberto Turrent (2009) nennt Nueva Matacapan de Tabacos in San Andrés Tuxtla als ihre Fabrik und beschreibt sie als einen Zigarrentabakproduzenten des Landes. Der Atlas führt den Eintrag der Familie unter dem Namen Casa Turrent; Te-Amo (Mexiko) ist weder ein Namensvetter von New World noch eine dominikanische Marke.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Te Amo'
UNION ALL SELECT 'Te Amo', 'de', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Seit 2000 und der Fusion von Consolidated Cigar in Altadis gehört die Marke dem Konzern. Gemacht wird sie weiterhin von den Turrents, in ihrer Fabrik in San Andrés Tuxtla, Nueva Matacapan de Tabacos, auf zweitausend Acres vulkanischen Bodens, auf denen San Andrés Negro aus Criollo-Saat und Sumatra wachsen. Es ist der größte Zigarrentabakproduzent Mexikos, und dieser Atlas führt den Eintrag der Familie bereits unter dem Namen Casa Turrent. Eine Konzernmarke, gefertigt in der Fabrik einer Familie, die ihren eigenen Eintrag hat: derselbe Fall wie Bolívar Honduras bei Scandinavian Tobacco.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Te Amo'
UNION ALL SELECT 'Te Amo', 'zh', 'histoire 3 (nouveau texte)', (LOCATE(CAST('2024年2月，行业媒体写道，Altadis U.S.A. 在美国拥有该品牌，图伦特家族在世界其他地区拥有该品牌。雪茄仍由图伦特家族在墨西哥制作；阿尔贝托·图伦特（2009）称 Nueva Matacapan de Tabacos（位于圣安德烈斯图斯特拉）是他们的工厂，并称其是该国的一家雪茄烟草生产者。本图集以 Casa Turrent 之名载有该家族的词条；Te-Amo（墨西哥）既不是 New World 的同名品牌，也不是多米尼加品牌。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Te Amo'
UNION ALL SELECT 'Te Amo', 'zh', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('自2000年 Consolidated Cigar 并入 Altadis 起，品牌归集团所有。它仍由图伦特家族在圣安德烈斯图斯特拉的工厂 Nueva Matacapan de Tabacos 制作，两千英亩火山土上种着克里奥约种的 San Andrés Negro 与苏门答腊种。这是墨西哥最大的雪茄烟草生产者，本图集已以 Casa Turrent 之名载有该家族的词条。集团品牌在一个已有自己词条的家族的工厂里制作：与斯堪的纳维亚烟草集团的 Bolívar Honduras 同理。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Te Amo'
UNION ALL SELECT 'Te Amo', 'ar', 'histoire 3 (nouveau texte)', (LOCATE(CAST('في شباط/فبراير 2024، تكتب الصحافة المتخصصة أنّ Altadis U.S.A. تملك العلامة في الولايات المتحدة وأنّ آل تورينت يملكونها في بقية العالم. ولا يزال السيجار يُصنع في المكسيك على يد آل تورينت؛ ويذكر ألبرتو تورينت (2009) أنّ Nueva Matacapan de Tabacos في سان أندريس توكستلا هي مصنعهم، ويصفها بأنها منتج لتبغ السيجار في البلاد. ويحمل الأطلس بطاقة العائلة باسم Casa Turrent؛ و Te-Amo (المكسيك) ليست اسمًا مماثلًا لعلامة New World ولا علامة دومينيكانية.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Te Amo'
UNION ALL SELECT 'Te Amo', 'ar', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('منذ 2000 واندماج Consolidated Cigar في ألتاديس، العلامة ملك المجموعة. وما زال آل تورينت يصنعونها في مصنعهم بسان أندريس توكستلا، Nueva Matacapan de Tabacos، على ألفي فدّان من الأرض البركانية ينمو فيها San Andrés Negro من بذرة كريوّو، والسومطرة. إنّه أكبر منتج لتبغ السيجار في المكسيك، ويحمل هذا الأطلس بطاقة العائلة أصلًا باسم Casa Turrent. علامةُ مجموعةٍ تُصنع في مصنع عائلة لها بطاقتها الخاصة: الحالة نفسها لِـBolívar Honduras لدى مجموعة التبغ الإسكندنافية.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Te Amo'
