UNION ALL SELECT 'Tabacalera', 'fr', 'founded', (CAST(`founded` AS BINARY) = CAST('1881 — Compañía General de Tabacos de Filipinas' AS BINARY)) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'fr', 'factory', (CAST(`factory` AS BINARY) = CAST('Dasmariñas (Cavite), Philippines : fabrique d''environ 2 700 m², cigares faits à la main (philstar.com, 2011) ; siège à Makati' AS BINARY)) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'fr', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Tabacalera naît d''une décision administrative coloniale. Le monopole espagnol du tabac aux Philippines, imposé en 1780 selon Philstar (2011), est aboli le 5 juin 1881 ; la Compañía General de Tabacos de Filipinas est fondée la même année par le marquis de Comillas, Antonio López y López, le 11 novembre selon Philstar, le 26 novembre selon Verafiles (2014). Elle rachète des fabriques de cigares, uniformise la qualité et exporte les « cigares de Manille ».' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'fr', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('L''histoire de Tabacalera de Filipinas commence non par une décision d''entrepreneur mais par une décision administrative coloniale. En 1881, la Couronne espagnole dissout la Real Compañía de Filipinas — le monopole d''État qui contrôlait la production, la distribution et l''exportation du tabac philippin depuis le XVIIIe siècle — et autorise la création de manufactures privées pour lui succéder. Le passage du monopole à la production concurrentielle visait à moderniser une industrie devenue bureaucratiquement rigide ; Tabacalera sortit de cette réorganisation comme la plus grande et la mieux capitalisée des nouvelles maisons privées.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'en', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Tabacalera was born of a colonial administrative decision. The Spanish tobacco monopoly in the Philippines, imposed in 1780 according to Philstar (2011), is abolished on 5 June 1881; the Compañía General de Tabacos de Filipinas is founded the same year by the Marquis of Comillas, Antonio López y López, on 11 November according to Philstar, on 26 November according to Verafiles (2014). It buys cigar factories, standardises quality and exports “Manila cigars”.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('The history of Tabacalera de Filipinas begins not with an entrepreneurial decision but with a colonial administrative one. In 1881, the Spanish crown dissolved the Real Compañía de Filipinas — the state tobacco monopoly that had controlled Philippine tobacco production, distribution, and export since the eighteenth century — and authorized the creation of private manufacturers to operate in its place. The transition from monopoly to competitive production was designed to modernize an industry that had grown bureaucratically rigid, and Tabacalera emerged from this reorganization as the largest and best-capitalized of the new private manufacturers.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Tabacalera nace de una decisión administrativa colonial. El monopolio español del tabaco en Filipinas, impuesto en 1780 según Philstar (2011), se abole el 5 de junio de 1881; la Compañía General de Tabacos de Filipinas se funda ese mismo año por el marqués de Comillas, Antonio López y López, el 11 de noviembre según Philstar, el 26 de noviembre según Verafiles (2014). Compra fábricas de puros, uniformiza la calidad y exporta los «puros de Manila».' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('La historia de Tabacalera de Filipinas empieza no por una decisión de empresario sino por una decisión administrativa colonial. En 1881, la Corona española disuelve la Real Compañía de Filipinas —el monopolio de Estado que controlaba la producción, la distribución y la exportación del tabaco filipino desde el siglo XVIII— y autoriza la creación de manufacturas privadas para sucederle. El paso del monopolio a la producción competitiva buscaba modernizar una industria vuelta burocráticamente rígida; Tabacalera salió de esa reorganización como la mayor y la mejor capitalizada de las nuevas casas privadas.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Tabacalera entsteht aus einer kolonialen Verwaltungsentscheidung. Das spanische Tabakmonopol auf den Philippinen, nach Philstar (2011) 1780 eingeführt, wird am 5. Juni 1881 abgeschafft; die Compañía General de Tabacos de Filipinas wird im selben Jahr vom Marquis von Comillas, Antonio López y López, gegründet, am 11. November laut Philstar, am 26. November laut Verafiles (2014). Sie kauft Zigarrenfabriken, vereinheitlicht die Qualität und exportiert die „Manila-Zigarren“.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Die Geschichte von Tabacalera de Filipinas beginnt nicht mit einer unternehmerischen, sondern mit einer kolonialen Verwaltungsentscheidung. 1881 löste die spanische Krone die Real Compañía de Filipinas auf — das Staatsmonopol, das Erzeugung, Vertrieb und Ausfuhr des philippinischen Tabaks seit dem 18. Jahrhundert lenkte — und erlaubte die Gründung privater Manufakturen als Nachfolge. Der Übergang vom Monopol zur wettbewerblichen Erzeugung sollte eine bürokratisch erstarrte Industrie erneuern; Tabacalera ging aus dieser Neuordnung als das größte und bestausgestattete der neuen privaten Häuser hervor.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Tabacalera 诞生于一项殖民行政决定。据 Philstar（2011），西班牙在菲律宾的烟草专营于1780年强制推行，1881年6月5日被废除；同年，Compañía General de Tabacos de Filipinas 由科米利亚斯侯爵安东尼奥·洛佩斯·伊·洛佩斯创立，Philstar 称在11月11日，Verafiles（2014）称在11月26日。它收购雪茄工厂，统一品质，并出口「马尼拉雪茄」。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'zh', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('菲律宾塔巴卡莱拉的历史，起点不是一个企业家的决定，而是一项殖民行政决定。1881年，西班牙王室解散了菲律宾皇家公司——这个自18世纪起掌控菲律宾烟草生产、分销与出口的国家专营——并批准设立私人工厂来接替它。从专营转向竞争性生产，本意是让一个官僚化到僵硬的产业现代化；塔巴卡莱拉就是从这次重组中脱颖而出的：在那些新的私人字号里，它规模最大、资本最厚。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('تنشأ Tabacalera من قرار إداري استعماري. فالاحتكار الإسباني للتبغ في الفلبين، الذي فُرض سنة 1780 بحسب Philstar (2011)، يُلغى في 5 حزيران/يونيو 1881؛ وتُؤسَّس Compañía General de Tabacos de Filipinas في السنة نفسها على يد ماركيز كوميّاس أنطونيو لوبيز إي لوبيز، في 11 تشرين الثاني/نوفمبر بحسب Philstar، وفي 26 تشرين الثاني/نوفمبر بحسب Verafiles (2014). وتشتري مصانع سيجار، وتوحّد الجودة، وتصدّر «سيجار مانيلا».' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('لا يبدأ تاريخ «تاباكاليرا دي فيليبيناس» بقرار من رجل أعمال، بل بقرار إداري استعماري. ففي 1881، حلّ التاج الإسباني «الشركة الملكية للفلبين» — الاحتكار الحكومي الذي كان يضبط إنتاج التبغ الفلبيني وتوزيعه وتصديره منذ القرن الثامن عشر — وأذن بإنشاء مصانع خاصة تخلفه. وكان الانتقال من الاحتكار إلى الإنتاج التنافسي يرمي إلى تحديث صناعة تصلّبت بيروقراطيًّا؛ وخرجت «تاباكاليرا» من هذا التنظيم الجديد بوصفها الأكبر والأوفر رأسمالًا بين الدور الخاصة الجديدة.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('La maison Tabacalera Incorporada se présente aujourd''hui comme une fabrique de cigares d''Asie qui date son travail à la main de 1881 (tabacalera.com.ph, octobre 2026), avec un tabac d''Isabela et d''ailleurs. La marque phare de la Compañía, La Flor de la Isabela, a été rebaptisée Tabacalera en l''honneur de la société fondatrice (Philstar, 2011) ; La Flor de la Isabela a sa propre fiche dans l''atlas.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('L''administration coloniale espagnole avait cultivé le tabac philippin pour l''exportation vers l''Espagne pendant plus de deux siècles avant ce moment. La vallée de Cagayan, dans le nord de Luzon — région de culture principale alors comme aujourd''hui — avait été cartographiée, ses tabacs classés, ses pratiques systématisées par des décennies de gestion monopolistique. La feuille de la région d''Ilocos, cultivée dans d''autres conditions sur la côte nord-ouest, fournissait une variété complémentaire dont les assembleurs se servaient pour ajuster les profils. Le savoir technique accumulé était considérable, même s''il restait contraint par la bureaucratie.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'en', 'histoire 2 (nouveau texte)', (LOCATE(CAST('The house Tabacalera Incorporada now presents itself as a cigar factory in Asia that dates its hand production to 1881 (tabacalera.com.ph, October 2026), with tobacco from Isabela and elsewhere. The Compañía''s flagship brand, La Flor de la Isabela, was renamed Tabacalera in honour of the founding company (Philstar, 2011); La Flor de la Isabela has its own entry in the atlas.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'en', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('The Spanish colonial administration had cultivated Philippine tobacco specifically for export to Spain for over two centuries before this moment. The Cagayan Valley in northern Luzon — the primary growing region then and now — had been mapped, its tobaccos classified, and its cultivation practices systematized through decades of monopoly management. The Ilocos region''s leaf, grown under different conditions on the northwestern coast, provided a complementary variety that blenders used to adjust profiles. The technical knowledge embedded in the industry was substantial, if bureaucratically constrained.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'es', 'histoire 2 (nouveau texte)', (LOCATE(CAST('La casa Tabacalera Incorporada se presenta hoy como una fábrica de puros de Asia que fecha su trabajo a mano en 1881 (tabacalera.com.ph, octubre de 2026), con tabaco de Isabela y de otros lugares. La marca insignia de la Compañía, La Flor de la Isabela, fue rebautizada Tabacalera en honor de la sociedad fundadora (Philstar, 2011); La Flor de la Isabela tiene su propia ficha en el atlas.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'es', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('La administración colonial española había cultivado el tabaco filipino para la exportación hacia España durante más de dos siglos antes de ese momento. El valle de Cagayán, en el norte de Luzón —región de cultivo principal entonces como hoy—, había sido cartografiado, sus tabacos clasificados, sus prácticas sistematizadas por décadas de gestión monopolística. La hoja de la región de Ilocos, cultivada en otras condiciones en la costa noroeste, proporcionaba una variedad complementaria que los ligadores empleaban para ajustar los perfiles. El saber técnico acumulado era considerable, aunque siguiera constreñido por la burocracia.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'de', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Das Haus Tabacalera Incorporada stellt sich heute als eine Zigarrenfabrik in Asien dar, die ihre Handarbeit auf 1881 datiert (tabacalera.com.ph, Oktober 2026), mit Tabak aus Isabela und von anderswo. Die Flaggschiffmarke der Compañía, La Flor de la Isabela, wurde zu Ehren der Gründungsgesellschaft in Tabacalera umbenannt (Philstar, 2011); La Flor de la Isabela hat im Atlas einen eigenen Eintrag.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'de', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Die spanische Kolonialverwaltung hatte den philippinischen Tabak vor diesem Zeitpunkt über zwei Jahrhunderte lang für die Ausfuhr nach Spanien angebaut. Das Cagayán-Tal im Norden Luzons — damals wie heute das wichtigste Anbaugebiet — war vermessen, seine Tabake waren eingeteilt, seine Verfahren durch Jahrzehnte monopolistischer Verwaltung geordnet. Das Blatt aus der Gegend von Ilocos, unter anderen Bedingungen an der Nordwestküste gezogen, lieferte eine ergänzende Sorte, mit der die Mischer die Profile abstimmten. Das angesammelte technische Wissen war beträchtlich, auch wenn es von der Bürokratie eingeengt blieb.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'zh', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Tabacalera Incorporada 公司如今自称为亚洲的一家雪茄工厂，并把手工制作的起点定在1881年（tabacalera.com.ph，2026年10月），用的是伊莎贝拉及其他地方的烟叶。该公司的旗舰品牌 La Flor de la Isabela 为纪念创立公司而改名为 Tabacalera（Philstar，2011）；La Flor de la Isabela 在本图集中另有词条。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'zh', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('在此之前，西班牙殖民当局已为向西班牙出口而种植菲律宾烟草两百多年。吕宋岛北部的卡加延河谷——当时与今天同样是主要产区——早已被测绘，其烟草被分类，其做法在数十年的专营管理中被系统化。西北海岸另一种条件下培育的伊罗戈斯产区叶片，提供了一个互补的品种，调配师用它来微调风格。积累下来的技术知识相当可观，尽管始终被官僚体制束着。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'ar', 'histoire 2 (nouveau texte)', (LOCATE(CAST('تقدّم دار Tabacalera Incorporada نفسها اليوم بوصفها مصنع سيجار في آسيا يؤرّخ عمله اليدوي بسنة 1881 (tabacalera.com.ph، تشرين الأول/أكتوبر 2026)، بتبغ من إيزابيلا ومن مواضع أخرى. أما العلامة الرائدة للشركة، La Flor de la Isabela، فقد أُعيدت تسميتها Tabacalera تكريمًا للشركة المؤسِّسة (Philstar، 2011)؛ ولـLa Flor de la Isabela بطاقتها الخاصة في الأطلس.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'ar', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('كانت الإدارة الاستعمارية الإسبانية قد زرعت التبغ الفلبيني للتصدير إلى إسبانيا أكثر من قرنين قبل تلك اللحظة. فوادي كاغايان، في شمال لوزون — منطقة الزراعة الرئيسة يومها كما اليوم — كان قد رُسم على الخرائط، وصُنّفت تبوغه، ونُظّمت ممارساته عبر عقود من الإدارة الاحتكارية. أما ورقة منطقة إيلوكوس، المزروعة في ظروف أخرى على الساحل الشمالي الغربي، فكانت تقدّم صنفًا مكمّلًا يستعمله الخلّاطون لضبط الطوابع. وكانت المعرفة التقنية المتراكمة كبيرة، وإن ظلّت مقيّدة بالبيروقراطية.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'fr', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Le groupe a connu plusieurs propriétaires. Verafiles (2014) décrit une société espagnole vendue par morceaux des années 1950 aux années 1990, marque La Flor de la Isabela comprise, puis une suite de rachats étrangers de 1997 à 2007 jusqu''à CDF International, société néerlandaise. Philstar (2011) écrit qu''après un siècle la Compañía vend son activité cigares et que la fabrique passe en mains philippines. La fabrique est à Dasmariñas, dans la province de Cavite, sur environ 2 700 m², où les cigares sont faits à la main, avec des presses en bois de plus d''un siècle (Philstar, 2011).' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'fr', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Ce qui distingue vraiment le tabac philippin est difficile à dire sans le vocabulaire de la dégustation, mais c''est réel et constant. La rétro-olfaction — le retour aromatique par les fosses nasales à l''expiration — porte des notes que les dégustateurs expérimentés décrivent comme mentholées, fraîches, légèrement florales. Ce n''est ni une caractéristique variétale ni un artefact de fermentation, mais l''expression de la chimie du sol de Cagayan et de la façon particulière dont ce tabac métabolise ses alcaloïdes. Les assembleurs qui cherchent ce caractère se sont historiquement fournis aux Philippines.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'en', 'histoire 3 (nouveau texte)', (LOCATE(CAST('The group has had several owners. Verafiles (2014) describes a Spanish company sold off piece by piece from the 1950s to the 1990s, the La Flor de la Isabela brand included, then a series of foreign buyouts from 1997 to 2007 up to CDF International, a Dutch company. Philstar (2011) writes that after a century the Compañía sells its cigar business and that the factory passes into Philippine hands. The factory is in Dasmariñas, in Cavite province, on about 2,700 m², where the cigars are made by hand, with wooden presses more than a century old (Philstar, 2011).' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'en', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('What makes Philippine tobacco genuinely distinct in the world context is difficult to describe without the vocabulary of tasting, but it is real and consistent. The retrohale — the aromatic return through the nasal passage when exhaling — carries notes that experienced tasters describe as mentholated, cooling, slightly floral. This is not a variety characteristic or a fermentation artifact but an expression of the Cagayan soil''s chemistry and the particular way Philippine tobacco metabolizes its alkaloids. Blenders who seek that character have historically sourced from the Philippines.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'es', 'histoire 3 (nouveau texte)', (LOCATE(CAST('El grupo ha tenido varios propietarios. Verafiles (2014) describe una sociedad española vendida por partes de los años cincuenta a los noventa, con la marca La Flor de la Isabela incluida, y luego una serie de compras extranjeras de 1997 a 2007 hasta CDF International, sociedad neerlandesa. Philstar (2011) escribe que tras un siglo la Compañía vende su actividad de puros y que la fábrica pasa a manos filipinas. La fábrica está en Dasmariñas, en la provincia de Cavite, sobre unos 2 700 m², donde los puros se hacen a mano, con prensas de madera de más de un siglo (Philstar, 2011).' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'es', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Lo que distingue verdaderamente al tabaco filipino es difícil de decir sin el vocabulario de la cata, pero es real y constante. La retronasal —el retorno aromático por las fosas nasales al espirar— lleva notas que los catadores experimentados describen como mentoladas, frescas, ligeramente florales. No es una característica varietal ni un artefacto de fermentación, sino la expresión de la química del suelo de Cagayán y de la manera particular en que ese tabaco metaboliza sus alcaloides. Los ligadores que buscan ese carácter se han abastecido históricamente en Filipinas.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'de', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Die Gruppe hatte mehrere Eigentümer. Verafiles (2014) beschreibt ein spanisches Unternehmen, das von den 1950er- bis zu den 1990er-Jahren stückweise verkauft wurde, die Marke La Flor de la Isabela eingeschlossen, danach eine Reihe ausländischer Übernahmen von 1997 bis 2007 bis zu CDF International, einem niederländischen Unternehmen. Philstar (2011) schreibt, dass die Compañía nach einem Jahrhundert ihr Zigarrengeschäft verkauft und die Fabrik in philippinische Hände übergeht. Die Fabrik liegt in Dasmariñas in der Provinz Cavite auf rund 2 700 m², wo die Zigarren von Hand gefertigt werden, mit Holzpressen, die mehr als hundert Jahre alt sind (Philstar, 2011).' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'de', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Was den philippinischen Tabak wirklich auszeichnet, ist ohne das Vokabular der Verkostung schwer zu sagen, aber es ist wirklich und beständig. Der retronasale Eindruck — die aromatische Rückkehr durch die Nasenhöhlen beim Ausatmen — trägt Noten, die erfahrene Verkoster als mentholartig, frisch, leicht blumig beschreiben. Das ist weder ein Sortenmerkmal noch ein Nebenerzeugnis der Fermentation, sondern der Ausdruck der Bodenchemie von Cagayán und der besonderen Art, wie dieser Tabak seine Alkaloide umsetzt. Mischer, die diesen Charakter suchen, haben sich geschichtlich auf den Philippinen versorgt.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'zh', 'histoire 3 (nouveau texte)', (LOCATE(CAST('该集团几易其主。Verafiles（2014）描述了一家西班牙公司：从1950年代到1990年代被分块出售，La Flor de la Isabela 品牌也在其中；随后1997年至2007年间是一连串外国收购，直至荷兰公司 CDF International。Philstar（2011）写道，一个世纪之后，Compañía 出售其雪茄业务，工厂转入菲律宾人手中。工厂位于甲米地省的达斯马里尼亚斯，占地约2700平方米，雪茄在此手工制作，使用已有一百多年历史的木制压床（Philstar，2011）。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'zh', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('菲律宾烟草真正的独特之处，不借助品鉴的词汇很难说清，但它真实而稳定。鼻后回味——呼气时经由鼻腔返回的香气——带着老练品鉴者形容为薄荷感、清新、略带花香的气息。这既不是品种特征，也不是发酵的副产物，而是卡加延土壤化学与这种烟草代谢生物碱的特殊方式的表达。历史上，寻找这种性格的调配师都从菲律宾进货。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'ar', 'histoire 3 (nouveau texte)', (LOCATE(CAST('عرفت المجموعة عدة مالكين. تصف Verafiles (2014) شركة إسبانية بيعت قطعةً قطعةً من خمسينيات القرن الماضي إلى تسعينياته، بما فيها علامة La Flor de la Isabela، ثم سلسلة من عمليات الشراء الأجنبية من 1997 إلى 2007 حتى CDF International، وهي شركة هولندية. وتكتب Philstar (2011) أنّه بعد قرن تبيع الـCompañía نشاطها في السيجار وأنّ المصنع ينتقل إلى أيدٍ فلبينية. ويقع المصنع في داسماريناس بمقاطعة كافيتي على نحو 2700 متر مربع، حيث تُصنع السيجار يدويًّا، بمكابس خشبية يزيد عمرها على قرن (Philstar، 2011).' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'ar', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('وما يميّز التبغ الفلبيني حقًّا يصعب قوله بغير مفردات التذوّق، لكنه حقيقي وثابت. فالشمّ الرجعي — عودة العطر عبر الأنف عند الزفير — يحمل نكهات يصفها الذوّاقة المتمرّسون بأنها نعناعية، منعشة، زهرية قليلًا. وليس ذلك سمة صنفية ولا أثرًا جانبيًّا للتخمير، بل تعبيرٌ عن كيمياء تربة كاغايان وعن الطريقة الخاصة التي يستقلب بها هذا التبغ قلويّاته. والخلّاطون الذين يقصدون هذا الطابع تزوّدوا تاريخيًّا من الفلبين.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'fr', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Homonymes : cette fiche est celle de Tabacalera Incorporada (Philippines). Elle n''a rien à voir avec Tabacalera, S.A., la société espagnole (monopole espagnol, Altadis, copropriétaire de Habanos), ni avec Tabacalera del Oriente, Palma, Paxtián ou William Ventura.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'fr', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('La propriété a changé plusieurs fois depuis l''indépendance : les intérêts espagnols ont cédé la place à des actionnaires philippins après 1946, et la structure a continué d''évoluer. La matière première de Cagayan et les pratiques de fabrication d''origine, à Agoo dans la province de La Union, sont restées continues à travers ces transitions. Tabacalera est un livre d''histoire fumable.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'en', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Namesakes: this entry is that of Tabacalera Incorporada (Philippines). It has nothing to do with Tabacalera, S.A., the Spanish company (Spanish monopoly, Altadis, co-owner of Habanos), nor with Tabacalera del Oriente, Palma, Paxtián or William Ventura.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'en', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('The company''s ownership has changed several times since independence — Spanish interests were replaced by Filipino shareholders after 1946, and the ownership structure has evolved through the subsequent decades. The Cagayan Valley source material and the original manufacturing practices in Agoo, La Union, have remained continuous throughout these transitions.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'es', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Homónimos: esta ficha es la de Tabacalera Incorporada (Filipinas). No tiene nada que ver con Tabacalera, S.A., la sociedad española (monopolio español, Altadis, copropietaria de Habanos), ni con Tabacalera del Oriente, Palma, Paxtián o William Ventura.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'es', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('La propiedad ha cambiado varias veces desde la independencia: los intereses españoles cedieron el sitio a accionistas filipinos después de 1946, y la estructura ha seguido evolucionando. La materia prima de Cagayán y las prácticas de fabricación de origen, en Agoo, en la provincia de La Unión, se han mantenido continuas a través de esas transiciones. Tabacalera es un libro de historia fumable.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'de', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Namensvettern: Dieser Eintrag ist der von Tabacalera Incorporada (Philippinen). Er hat nichts mit Tabacalera, S.A., dem spanischen Unternehmen (spanisches Monopol, Altadis, Miteigentümerin von Habanos), zu tun, auch nicht mit Tabacalera del Oriente, Palma, Paxtián oder William Ventura.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'de', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('Die Eigentümerschaft hat seit der Unabhängigkeit mehrfach gewechselt: Spanische Interessen wichen nach 1946 philippinischen Anteilseignern, und die Struktur hat sich weiter gewandelt. Der Rohstoff aus Cagayán und die ursprünglichen Fertigungsverfahren in Agoo in der Provinz La Unión sind durch diese Übergänge hindurch fortgeführt worden. Tabacalera ist ein rauchbares Geschichtsbuch.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'zh', 'histoire 4 (nouveau texte)', (LOCATE(CAST('同名者：本词条是 Tabacalera Incorporada（菲律宾）的词条。它与西班牙公司 Tabacalera, S.A.（西班牙专营、Altadis、Habanos 的共同所有者）无关，也与 Tabacalera del Oriente、Palma、Paxtián 或 William Ventura 无关。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'zh', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('独立以来所有权几度更迭：1946年之后，西班牙方面的权益让位于菲律宾股东，其结构也继续演变。而卡加延的原料，以及拉乌尼翁省阿古最初的制作方法，穿过这些更替一直延续了下来。塔巴卡莱拉是一本可以点燃的历史书。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'ar', 'histoire 4 (nouveau texte)', (LOCATE(CAST('أسماء مشابهة: هذه البطاقة هي بطاقة Tabacalera Incorporada (الفلبين). ولا صلة لها بـTabacalera, S.A.، الشركة الإسبانية (الاحتكار الإسباني، وAltadis، الشريكة في ملكية Habanos)، ولا بـTabacalera del Oriente أو Palma أو Paxtián أو William Ventura.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'ar', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('وقد تبدّلت الملكية مرات منذ الاستقلال: تراجعت المصالح الإسبانية أمام مساهمين فلبينيين بعد 1946، وظلّ الهيكل يتطوّر. أما المادة الأولية من كاغايان وأساليب الصناعة الأصلية، في أغوو بمقاطعة لا أونيون، فبقيت متّصلة عبر هذه التحوّلات. «تاباكاليرا» كتاب تاريخ يمكن تدخينه.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'fr', 'gamme Tabacalera', (JSON_CONTAINS(JSON_EXTRACT(`gamme`, '$[*].name'), '"Tabacalera"')) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'fr', 'gamme Tabacalera (vitolas)', (JSON_LENGTH(JSON_EXTRACT(`gamme`, '$[0].vitolas')) = 4) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'Tabacalera', 'fr', 'gamme Tabacalera (texte)', (CAST(JSON_UNQUOTE(JSON_EXTRACT(`gamme`, '$[0].story')) AS BINARY) = CAST('Ligne portant le nom de la maison, avec une édition Maduro (tabacalera.com.ph, octobre 2026). La page lue n''indique ni cape, ni force, ni formats.' AS BINARY)) FROM `brands` WHERE `name` = 'Tabacalera'
