UNION ALL SELECT 'Tabacalera', 'fr', 'source (correction)', (LOCATE(CAST('tabacalera.com.ph « Tabacalera Incorporada » (octobre 2026 : lignes, « Handcrafted Since 1881 ») ; philstar.com « Tabacalera: 130 years of cigars and Philippine history » (5 décembre 2011 : fondation le 11 novembre 1881, fabrique de Dasmariñas, cigares à la main) ; verafiles.org « Cigar company bridges PH and Spain past and present » (25 mai 2014 : fondation le 26 novembre 1881, propriétaires successifs, CDF International)' AS BINARY), CAST(`source` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Tabacalera'
UNION ALL SELECT 'General Cigar', 'fr', 'limited_eds : Macanudo Estate Reserve (2014, tabac de Jamaïque)', (JSON_CONTAINS(`limited_eds`, '"Macanudo Estate Reserve (2014, tabac de Jamaïque)"')) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'fr', 'pays', (CAST(`country_id` AS BINARY) = CAST('dominican' AS BINARY)) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'fr', 'founded', (CAST(`founded` AS BINARY) = CAST('1906 (lieu divergent selon les sources)' AS BINARY)) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'fr', 'factory', (CAST(`factory` AS BINARY) = CAST('General Cigar Dominicana, Santiago (République dominicaine) pour Macanudo ; CAO Flathead à STG Estelí (Nicaragua) ; Punch Upper Cut faite au Honduras (2014)' AS BINARY)) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'fr', 'histoire 1 (nouveau texte)', (LOCATE(CAST('General Cigar Company date de 1906, mais les sources ne s''accordent pas sur le lieu. Selon FundingUniverse, la famille Cullman réunit cette année-là ses activités de cigares dans la United Cigar Manufacturers Company, cotée à New York ; selon Wikipédia, la société naît à Evansville (Indiana), comme successeur de Cullman Brothers. Aucune page lue ne parle de Tampa ni d''Ybor City, que l''ancien texte donnait pour berceau.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'fr', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('L''histoire de General Cigar commence à Tampa en 1906, dans les manufactures d''Ybor City — le quartier de l''exil cubain qui avait fait de Tampa la capitale américaine du cigare dans les années 1880. La société d''origine fut, dès ses premières années, un véhicule de consolidation : elle rachetait de plus petits fabricants de Tampa dont les activités individuelles tenaient de moins en moins face aux grandes maisons. La croissance par acquisition a été établie à la fondation, et elle définit l''entreprise depuis.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'en', 'histoire 1 (nouveau texte)', (LOCATE(CAST('General Cigar Company dates from 1906, but sources disagree on the place. According to FundingUniverse, the Cullman family that year brought its cigar businesses together in the United Cigar Manufacturers Company, listed in New York; according to Wikipedia, the company was born in Evansville (Indiana), as successor to Cullman Brothers. No page read mentions Tampa or Ybor City, which the earlier text gave as its cradle.

In 1961, a group led by Edgar M. Cullman bought General Cigar, then known mainly for mass-market cigars such as White Owl (Wikipedia; 1994 interview with Edgar Cullman). Macanudo came next: the Temple Hall factory in Jamaica, which owned the name, was bought in 1968 according to FundingUniverse, in 1969 according to the 1994 interview; General launched its own Macanudo in 1971. Partagás has been made in the Dominican Republic since the late 1970s, says Edgar Cullman. Jamaica stopped in 2000: Macanudo has since been rolled in the Dominican Republic.

CAO was not bought by General: it was ST Cigar Group, the cigar arm of the Scandinavian Tobacco Group, that took control of it on 1 January 2007, according to the group''s press release; the brand joined General Cigar''s portfolio with the 2010 merger. The CAO Flathead Speed Shop Habano, released in 2026, is rolled at STG Estelí, in Nicaragua, according to Cigar Coop.

General Cigar''s cigars are not all rolled in the same place. Macanudo is rolled in the Dominican Republic; General Cigar Dominicana, STG''s Dominican factory, also rolls part of the non-Cuban Cohiba (Cigar Coop, February 2026); the CAO Flathead, in Estelí; the Punch Upper Cut was made in Honduras in 2014, the latest dated trace read. No cigar of the house is rolled in Jamaica today.

On ownership, the date diverges: Swedish Match took 64% of General Cigar in January 2000 according to FundingUniverse, whereas Wikipedia places its acquisition of the company in 2005. In 2010, Swedish Match merged its premium cigars with the Scandinavian Tobacco Group (STG), listed on the stock exchange since 2016; Swedish Match left STG''s capital in 2017 (Cigar Coop). In January 2026, STG entrusted to the sales team of Forged Cigar Company the Cohiba (non-Cuban), Punch and Havana Honeys brands, until then sold by that of General Cigar, and returned Partagás and Room101 to the latter; manufacturing does not change, says Cigar Coop.

Not to be confused: Cohiba, Punch, Partagás and Hoyo de Monterrey, in General Cigar''s portfolio according to Wikipedia, are non-Cuban brands, distinct from the Habanos S.A. brands that carry the same names.

Buffalo Trace is the name of a Kentucky distillery, which partnered in June 2021 with Cigars International for a cigar series sold wholesale by Meier & Dutch, the retailer''s distribution arm. Rolled at General Cigar Dominicana, in Santiago, it combines an Ecuadorian Sumatra wrapper with an arapiraca binder from Brazil. A limited edition, Special F, followed in September 2022, with a binder aged in barrels from the distillery; in October 2026, retailers still offer the series.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST(CONCAT('The General Cigar story begins in Tampa in 1906, in the cigar factories of Ybor City — the Cuban exile neighborhood that had made Tampa the American cigar capital in the 1880s. The original General Cigar Company was a consolidation vehicle from its first years, acquiring smaller Tampa manufacturers whose individual operations were increasingly uncompetitive against the larger houses. The pattern of growth through acquisition was established at the founding and has defined the company ever since.', CHAR(13), '
', CHAR(13), '
The mid-century transformation moved General Cigar from Tampa manufacturer to national distributor and brand manager. The acquisition of Macanudo in the 1970s provided the brand that would drive the company through the cigar boom of the 1990s — a brand positioned for accessibility and consistency, whose commercial success funded the acquisitions that followed.', CHAR(13), '
', CHAR(13), '
The CAO acquisition in 2007 added the premium innovative brand that General Cigar''s portfolio required. Where Macanudo sold reliability, CAO sold discovery — new formats, unexpected blends, releases that enthusiasts anticipated rather than took for granted. The two brands operate in the same general price tier but target different psychological needs, allowing General Cigar to capture a broader segment of the premium market than either brand could reach alone.', CHAR(13), '
', CHAR(13), '
The company''s portfolio now includes cigars under over twenty brand names, produced across manufacturing facilities in the Dominican Republic, Honduras, Jamaica, and Nicaragua. The management challenge — maintaining the distinctive identity and quality standard of each brand while pooling sourcing, logistics, and distribution resources — is the central operational problem of managing a multi-brand cigar company, and General Cigar''s performance across decades suggests it has developed approaches to this problem that smaller competitors have not.', CHAR(13), '
', CHAR(13), '
The Scandinavian Tobacco Group, formed in 2010 by the merger of its cigar activities with those of Swedish Match, owner of General Cigar since 2005, and listed on the stock exchange since 2016, added European distribution and manufacturing capabilities that have extended the company''s reach into markets where American cigar brands had previously operated at a disadvantage. In January 2026, the group entrusted to the sales team of Forged Cigar Company the Cohiba (non-Cuban), Punch and Havana Honeys brands, until then sold by that of General Cigar, and returned Partagás and Room101 to the latter; manufacturing does not change, says Cigar Coop.

Buffalo Trace is the name of a Kentucky distillery, which partnered in June 2021 with Cigars International for a cigar series sold wholesale by Meier & Dutch, the retailer''s distribution arm. Rolled at General Cigar Dominicana, in Santiago, it combines an Ecuadorian Sumatra wrapper with an arapiraca binder from Brazil. A limited edition, Special F, followed in September 2022, with a binder aged in barrels from the distillery; in October 2026, retailers still offer the series.') AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('General Cigar Company data de 1906, pero las fuentes no coinciden en el lugar. Según FundingUniverse, la familia Cullman reunió ese año sus actividades de puros en la United Cigar Manufacturers Company, cotizada en Nueva York; según Wikipedia, la sociedad nace en Evansville (Indiana), como sucesora de Cullman Brothers. Ninguna página leída habla de Tampa ni de Ybor City, que el texto anterior daba por cuna.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('La historia de General Cigar empieza en Tampa en 1906, en las manufacturas de Ybor City —el barrio del exilio cubano que había hecho de Tampa la capital estadounidense del puro en los años ochenta del siglo XIX. La sociedad de origen fue, desde sus primeros años, un vehículo de consolidación: compraba fabricantes más pequeños de Tampa cuyas actividades individuales resistían cada vez menos frente a las grandes casas. El crecimiento por adquisición quedó establecido en la fundación, y define a la empresa desde entonces.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('General Cigar Company stammt aus dem Jahr 1906, doch die Quellen sind sich über den Ort nicht einig. Laut FundingUniverse führte die Familie Cullman in jenem Jahr ihre Zigarrengeschäfte in der United Cigar Manufacturers Company zusammen, die in New York notiert war; laut Wikipedia entsteht die Gesellschaft in Evansville (Indiana) als Nachfolgerin von Cullman Brothers. Keine gelesene Seite spricht von Tampa oder Ybor City, die der frühere Text als Wiege nannte.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Die Geschichte von General Cigar beginnt 1906 in Tampa, in den Manufakturen von Ybor City — dem Viertel des kubanischen Exils, das Tampa in den 1880er Jahren zur amerikanischen Hauptstadt der Zigarre gemacht hatte. Die ursprüngliche Gesellschaft war von ihren ersten Jahren an ein Werkzeug der Zusammenführung: Sie kaufte kleinere Hersteller aus Tampa auf, deren einzelne Betriebe sich gegen die großen Häuser immer weniger behaupteten. Das Wachstum durch Übernahme war bei der Gründung angelegt, und es bestimmt das Unternehmen seither.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('General Cigar Company 可追溯到1906年，但各来源对地点说法不一。据 FundingUniverse，Cullman 家族这一年把雪茄业务合并进在纽约上市的 United Cigar Manufacturers Company；据 Wikipedia，该公司诞生于 Evansville（印第安纳州），是 Cullman Brothers 的继任者。所读页面均未提及坦帕或伊博城，而旧文本曾把它们当作发源地。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'zh', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('General Cigar 的历史始于1906年的坦帕，起点是伊博城的那些工厂——正是这个古巴流亡者聚居的街区，让坦帕在1880年代成为美国的雪茄之都。这家公司从最初几年起就是一个整合的载体：它收购坦帕那些规模较小的厂商，后者单打独斗越来越难与大字号抗衡。以并购求增长，在创立之初就已写下，此后一直定义着这家企业。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('يعود تاريخ General Cigar Company إلى عام 1906، لكنّ المصادر لا تتفق على المكان. بحسب FundingUniverse، جمعت عائلة Cullman في تلك السنة أنشطتها في السيجار ضمن United Cigar Manufacturers Company المدرجة في نيويورك؛ وبحسب Wikipedia، نشأت الشركة في Evansville (إنديانا) كخليفة لـ Cullman Brothers. ولا تذكر أي صفحة مقروءة تامبا ولا إيبور سيتي اللتين نسبهما النص القديم مهدًا.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('يبدأ تاريخ «جنرال سيغار» في تامبا عام 1906، في مصانع إيبور سيتي — حيّ المنفى الكوبي الذي جعل تامبا عاصمة السيجار الأمريكية في ثمانينيات القرن التاسع عشر. وكانت الشركة الأصلية، منذ سنواتها الأولى، أداةً للدمج: تشتري صنّاعًا أصغر في تامبا لم تعد أعمالهم الفردية تصمد أمام الدور الكبرى. فالنمو بالاستحواذ تأسّس مع التأسيس، وهو يحدّد الشركة منذ ذلك الحين.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('En 1961, un groupe mené par Edgar M. Cullman rachète General Cigar, alors connue surtout pour des cigares de grande diffusion comme White Owl (Wikipédia ; entretien de 1994 avec Edgar Cullman). Vient ensuite Macanudo : la fabrique de Temple Hall, en Jamaïque, qui possédait le nom, est achetée en 1968 selon FundingUniverse, en 1969 selon l''entretien de 1994 ; General lance sa propre Macanudo en 1971. Partagás est produite en République dominicaine à partir de la fin des années 1970, dit Edgar Cullman. La Jamaïque cesse en 2000 : Macanudo est depuis roulée en République dominicaine.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('La transformation du milieu du siècle fit passer General Cigar du statut de fabricant de Tampa à celui de distributeur national et de gestionnaire de marques. Le rachat de Macanudo dans les années 1970 apporta la marque qui allait porter l''entreprise à travers l''engouement des années 1990 — une marque positionnée sur l''accessibilité et la régularité, et dont le succès commercial finança les acquisitions suivantes.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'es', 'histoire 2 (nouveau texte)', (LOCATE(CAST('En 1961, un grupo dirigido por Edgar M. Cullman compra General Cigar, entonces conocida sobre todo por puros de gran difusión como White Owl (Wikipedia; entrevista de 1994 con Edgar Cullman). Viene luego Macanudo: la fábrica de Temple Hall, en Jamaica, que poseía el nombre, se compra en 1968 según FundingUniverse y en 1969 según la entrevista de 1994; General lanza su propia Macanudo en 1971. Partagás se produce en la República Dominicana desde finales de los años setenta, dice Edgar Cullman. Jamaica cesa en 2000: desde entonces Macanudo se elabora en la República Dominicana.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'es', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('La transformación de mediados de siglo hizo pasar a General Cigar de fabricante de Tampa a distribuidor nacional y gestor de marcas. La compra de Macanudo en los años setenta aportó la marca que iba a sostener a la empresa a través del entusiasmo de los años noventa —una marca posicionada en la accesibilidad y la regularidad, cuyo éxito comercial financió las adquisiciones siguientes.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'de', 'histoire 2 (nouveau texte)', (LOCATE(CAST('1961 kauft eine Gruppe unter Edgar M. Cullman General Cigar, damals vor allem für massenhaft verbreitete Zigarren wie White Owl bekannt (Wikipedia; Interview von 1994 mit Edgar Cullman). Es folgt Macanudo: Die Fabrik Temple Hall in Jamaika, die den Namen besaß, wird laut FundingUniverse 1968 gekauft, laut dem Interview von 1994 im Jahr 1969; General bringt 1971 eine eigene Macanudo heraus. Partagás wird seit Ende der 1970er Jahre in der Dominikanischen Republik hergestellt, sagt Edgar Cullman. Jamaika endet 2000: Macanudo wird seither in der Dominikanischen Republik gerollt.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'de', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Der Wandel um die Jahrhundertmitte machte aus General Cigar statt eines Herstellers aus Tampa einen landesweiten Vertrieb und Markenverwalter. Der Kauf von Macanudo in den siebziger Jahren brachte jene Marke, die das Unternehmen durch die Begeisterung der neunziger Jahre tragen sollte — eine Marke, die auf Zugänglichkeit und Gleichmäßigkeit gesetzt war und deren kaufmännischer Erfolg die folgenden Übernahmen finanzierte.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'zh', 'histoire 2 (nouveau texte)', (LOCATE(CAST('1961年，由 Edgar M. Cullman 领头的一个集团收购了 General Cigar，当时它主要以 White Owl 这类大众流通的雪茄闻名（Wikipedia；1994年对 Edgar Cullman 的访谈）。随后是 Macanudo：拥有该名称的牙买加 Temple Hall 工厂，据 FundingUniverse 于1968年买下，据1994年访谈则在1969年；General 于1971年推出自己的 Macanudo。据 Edgar Cullman 说，Partagás 自1970年代末起在多米尼加共和国生产。牙买加的生产于2000年停止：此后 Macanudo 在多米尼加共和国卷制。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'zh', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('世纪中叶的转型，让 General Cigar 从坦帕的一家制造商变成全国性的分销商与品牌管理者。七十年代买下马卡努多，带来了那个将在九十年代的热潮中撑起公司的品牌——一个以可及与稳定立身的品牌，其商业上的成功为后续收购提供了资金。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'ar', 'histoire 2 (nouveau texte)', (LOCATE(CAST('في عام 1961 اشترت مجموعة يقودها Edgar M. Cullman شركة General Cigar، وكانت معروفة آنذاك بسيجار واسع الانتشار مثل White Owl (Wikipedia؛ مقابلة عام 1994 مع Edgar Cullman). ثم جاءت Macanudo: فمصنع Temple Hall في جامايكا، الذي كان يملك الاسم، اشتُري عام 1968 بحسب FundingUniverse، وعام 1969 بحسب مقابلة 1994؛ وأطلقت General عام 1971 Macanudo الخاصة بها. وتُنتَج Partagás في الجمهورية الدومينيكية منذ أواخر السبعينيات، بحسب Edgar Cullman. وتتوقف جامايكا عام 2000: ومنذ ذلك الحين تُلَفّ Macanudo في الجمهورية الدومينيكية.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'ar', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('وحوّل تغيّرُ منتصف القرن «جنرال سيغار» من صانع في تامبا إلى موزّع وطني ومدير علامات. وجلب شراء ماكانودو في السبعينيات العلامةَ التي ستحمل الشركة عبر حماسة التسعينيات — علامة موضوعة على التيسّر والانتظام، وموّل نجاحها التجاري الاستحواذات التالية.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'fr', 'histoire 3 (nouveau texte)', (LOCATE(CAST('CAO n''a pas été rachetée par General : c''est ST Cigar Group, la branche cigares du Scandinavian Tobacco Group, qui en prend le contrôle au 1er janvier 2007 selon le communiqué du groupe ; la marque entre dans le portefeuille de General Cigar avec la réunion de 2010. La CAO Flathead Speed Shop Habano, sortie en 2026, est roulée à STG Estelí, au Nicaragua, selon Cigar Coop.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'fr', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Le rachat de CAO en 2007 ajouta la marque premium inventive qui manquait au portefeuille. Là où Macanudo vend la fiabilité, CAO vend la découverte — formats nouveaux, assemblages inattendus, sorties que les amateurs attendent au lieu de les tenir pour acquises. Les deux marques occupent le même étage de prix mais répondent à des besoins différents, ce qui permet au groupe de couvrir un segment plus large que chacune ne pourrait atteindre seule.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'es', 'histoire 3 (nouveau texte)', (LOCATE(CAST('CAO no fue comprada por General: es ST Cigar Group, la rama de puros del Scandinavian Tobacco Group, la que toma su control el 1 de enero de 2007 según el comunicado del grupo; la marca entra en la cartera de General Cigar con la reunión de 2010. La CAO Flathead Speed Shop Habano, aparecida en 2026, se elabora en STG Estelí, en Nicaragua, según Cigar Coop.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'es', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('La compra de CAO en 2007 añadió la marca premium inventiva que faltaba en la cartera. Allí donde Macanudo vende la fiabilidad, CAO vende el descubrimiento —formatos nuevos, ligadas inesperadas, salidas que los aficionados esperan en lugar de darlas por sentadas. Las dos marcas ocupan el mismo escalón de precio pero responden a necesidades distintas, lo que permite al grupo cubrir un segmento más amplio del que cada una alcanzaría sola.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'de', 'histoire 3 (nouveau texte)', (LOCATE(CAST('CAO wurde nicht von General gekauft: Es ist ST Cigar Group, der Zigarrenzweig der Scandinavian Tobacco Group, die laut der Mitteilung der Gruppe zum 1. Januar 2007 die Kontrolle übernimmt; die Marke kommt mit der Zusammenlegung von 2010 ins Portfolio von General Cigar. Die CAO Flathead Speed Shop Habano, 2026 erschienen, wird laut Cigar Coop bei STG Estelí in Nicaragua gerollt.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'de', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Der Kauf von CAO im Jahr 2007 fügte die erfinderische Premiummarke hinzu, die dem Portfolio fehlte. Wo Macanudo Verlässlichkeit verkauft, verkauft CAO Entdeckung — neue Formate, unerwartete Mischungen, Neuheiten, die die Liebhaber erwarten, statt sie vorauszusetzen. Beide Marken liegen auf derselben Preisstufe, bedienen aber verschiedene Bedürfnisse, was dem Konzern erlaubt, ein breiteres Feld abzudecken, als jede allein erreichen könnte.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'zh', 'histoire 3 (nouveau texte)', (LOCATE(CAST('CAO 并非被 General 收购：据该集团的公告，取得其控制权的是 Scandinavian Tobacco Group 的雪茄分支 ST Cigar Group，时间为2007年1月1日；2010年合并后，该品牌进入 General Cigar 的产品组合。据 Cigar Coop，2026年推出的 CAO Flathead Speed Shop Habano 在尼加拉瓜的 STG Estelí 卷制。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'zh', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('2007年收购 CAO，补上了组合里所缺的那个富有创造力的高端品牌。马卡努多卖的是可靠，CAO 卖的是发现——新的规格、意料之外的配方、爱好者会去等待而非视为理所当然的新品。两个品牌处在同一价位层级，回应的却是不同的需求，这让集团覆盖的范围比任何一个单独品牌所能触及的都更宽。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'ar', 'histoire 3 (nouveau texte)', (LOCATE(CAST('لم تشترِ General شركة CAO: بل إن ST Cigar Group، فرع السيجار في Scandinavian Tobacco Group، هي التي تولّت السيطرة عليها في 1 كانون الثاني/يناير 2007 بحسب بيان المجموعة؛ ودخلت العلامة حافظة General Cigar مع اندماج 2010. أما CAO Flathead Speed Shop Habano، الصادرة عام 2026، فتُلَفّ في STG Estelí بنيكاراغوا، بحسب Cigar Coop.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'ar', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('وأضاف شراء CAO عام 2007 العلامة الفاخرة المبتكرة التي كانت تنقص الحافظة. فحيث تبيع ماكانودو الاعتمادية، تبيع CAO الاكتشاف — قياسات جديدة، وخلطات غير متوقّعة، وإصدارات ينتظرها الهواة بدل أن يعدّوها مسلّمة. وتقع العلامتان في الدرجة السعرية نفسها لكنهما تلبّيان حاجتين مختلفتين، مما يتيح للمجموعة تغطية قطاع أوسع مما تبلغه أيّ منهما وحدها.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'fr', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Les cigares de General Cigar ne se roulent pas tous au même endroit. Macanudo l''est en République dominicaine ; General Cigar Dominicana, usine dominicaine de STG, roule aussi une part de la Cohiba non cubaine (Cigar Coop, février 2026) ; la CAO Flathead, à Estelí ; la Punch Upper Cut était faite au Honduras en 2014, dernière trace datée lue. Aucun cigare de la maison n''est roulé en Jamaïque aujourd''hui.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'fr', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('Le portefeuille compte aujourd''hui plus de vingt marques, produites dans des manufactures de République dominicaine, du Honduras, de Jamaïque et du Nicaragua. La difficulté de gestion — tenir l''identité et le niveau de qualité propres à chaque marque tout en mutualisant approvisionnement, logistique et distribution — est le problème central d''un groupe multimarque dans ce métier, et la durée de General Cigar donne à penser qu''il y a trouvé des réponses que de plus petits concurrents n''ont pas.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'es', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Los puros de General Cigar no se elaboran todos en el mismo sitio. Macanudo se elabora en la República Dominicana; General Cigar Dominicana, fábrica dominicana de STG, elabora también una parte de la Cohiba no cubana (Cigar Coop, febrero de 2026); la CAO Flathead, en Estelí; la Punch Upper Cut se hacía en Honduras en 2014, última huella fechada leída. Ningún puro de la casa se elabora hoy en Jamaica.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'es', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('La cartera cuenta hoy con más de veinte marcas, producidas en manufacturas de República Dominicana, de Honduras, de Jamaica y de Nicaragua. La dificultad de gestión —sostener la identidad y el nivel de calidad propios de cada marca mutualizando a la vez abastecimiento, logística y distribución— es el problema central de un grupo multimarca en este oficio, y la duración de General Cigar da a pensar que ha encontrado respuestas que competidores más pequeños no tienen.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'de', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Die Zigarren von General Cigar werden nicht alle am selben Ort gerollt. Macanudo wird in der Dominikanischen Republik gerollt; General Cigar Dominicana, die dominikanische Fabrik von STG, rollt auch einen Teil der nichtkubanischen Cohiba (Cigar Coop, Februar 2026); die CAO Flathead in Estelí; die Punch Upper Cut wurde 2014 in Honduras hergestellt, die letzte gelesene datierte Spur. Keine Zigarre des Hauses wird heute in Jamaika gerollt.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'de', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('Das Portfolio zählt heute mehr als zwanzig Marken, hergestellt in Manufakturen in der Dominikanischen Republik, in Honduras, Jamaika und Nicaragua. Die Führungsaufgabe — die eigene Identität und das Güteniveau jeder Marke zu halten und zugleich Beschaffung, Logistik und Vertrieb zu bündeln — ist das Kernproblem eines Mehrmarkenkonzerns in diesem Fach, und die Dauer von General Cigar legt nahe, dass es dort Antworten gefunden hat, die kleinere Mitbewerber nicht haben.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'zh', 'histoire 4 (nouveau texte)', (LOCATE(CAST('General Cigar 的雪茄并非都在同一地方卷制。Macanudo 在多米尼加共和国卷制；STG 位于多米尼加的工厂 General Cigar Dominicana 也卷制一部分非古巴的 Cohiba（Cigar Coop，2026年2月）；CAO Flathead 在 Estelí；Punch Upper Cut 于2014年在洪都拉斯制造，这是所读到的有日期的末次记录。如今该公司没有任何雪茄在牙买加卷制。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'zh', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('如今这个组合有二十多个品牌，在多米尼加共和国、洪都拉斯、牙买加与尼加拉瓜的工厂里生产。管理上的难处——既要守住每个品牌各自的身份与质量水准，又要把采购、物流与分销统起来——正是这一行里多品牌集团的核心问题；而 General Cigar 存续之久，让人认为它找到了一些更小的对手所没有的答案。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'ar', 'histoire 4 (nouveau texte)', (LOCATE(CAST('لا يُلَفّ سيجار General Cigar كله في المكان نفسه. فتُلَفّ Macanudo في الجمهورية الدومينيكية؛ وتلفّ General Cigar Dominicana، المصنع الدومينيكي التابع لـ STG، جزءًا من Cohiba غير الكوبية أيضًا (Cigar Coop، شباط/فبراير 2026)؛ وتُلَفّ CAO Flathead في Estelí؛ وكانت Punch Upper Cut تُصنع في هندوراس عام 2014، وهو آخر أثر مؤرَّخ مقروء. ولا يُلَفّ اليوم في جامايكا أي سيجار للدار.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'ar', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('وتضمّ الحافظة اليوم أكثر من عشرين علامة، تُنتَج في مصانع بالجمهورية الدومينيكية وهندوراس وجامايكا ونيكاراغوا. أما صعوبة الإدارة — حفظ هوية كل علامة ومستوى جودتها مع توحيد التزوّد واللوجستيات والتوزيع — فهي المشكلة المركزية لأي مجموعة متعدّدة العلامات في هذه المهنة، وطولُ بقاء «جنرال سيغار» يوحي بأنها وجدت إجابات لا يملكها منافسون أصغر.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'fr', 'histoire 5 (nouveau texte)', (LOCATE(CAST('Côté propriété, la date diverge : Swedish Match prend 64 % de General Cigar en janvier 2000 selon FundingUniverse, alors que Wikipédia place en 2005 son acquisition de la société. En 2010, Swedish Match réunit ses cigares premium avec le Scandinavian Tobacco Group (STG), coté en Bourse depuis 2016 ; Swedish Match sort du capital de STG en 2017 (Cigar Coop). En janvier 2026, STG a confié à l''équipe de vente de Forged Cigar Company les marques Cohiba (non cubaine), Punch et Havana Honeys, jusque-là vendues par celle de General Cigar, et lui a rendu Partagás et Room101 ; la fabrication ne change pas, dit Cigar Coop.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'fr', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('Le Scandinavian Tobacco Group, issu en 2010 de la réunion de ses activités cigares avec celles de Swedish Match, propriétaire de General Cigar depuis 2005, et coté en Bourse depuis 2016, y a ajouté des capacités de distribution et de fabrication européennes qui ont étendu la portée du groupe sur des marchés où les marques américaines travaillaient jusque-là en position défavorable. En janvier 2026, il a confié à l''équipe de vente de Forged Cigar Company les marques Cohiba (non cubaine), Punch et Havana Honeys, jusque-là vendues par celle de General Cigar, et lui a rendu Partagás et Room101 ; la fabrication ne change pas, dit Cigar Coop.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'es', 'histoire 5 (nouveau texte)', (LOCATE(CAST('En cuanto a la propiedad, la fecha diverge: Swedish Match toma el 64 % de General Cigar en enero de 2000 según FundingUniverse, mientras que Wikipedia sitúa en 2005 su adquisición de la sociedad. En 2010, Swedish Match reúne sus puros premium con el Scandinavian Tobacco Group (STG), que cotiza en bolsa desde 2016; Swedish Match sale del capital de STG en 2017 (Cigar Coop). En enero de 2026, STG confió al equipo de ventas de Forged Cigar Company las marcas Cohiba (no cubana), Punch y Havana Honeys, hasta entonces vendidas por el de General Cigar, y devolvió a este último Partagás y Room101; la fabricación no cambia, dice Cigar Coop.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'es', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('El Scandinavian Tobacco Group, surgido en 2010 de la reunión de sus actividades de puros con las de Swedish Match, propietaria de General Cigar desde 2005, y que cotiza en bolsa desde 2016, le añadió capacidades de distribución y de fabricación europeas que extendieron el alcance del grupo en mercados donde las marcas estadounidenses trabajaban hasta entonces en posición desfavorable. En enero de 2026, el grupo confió al equipo de ventas de Forged Cigar Company las marcas Cohiba (no cubana), Punch y Havana Honeys, hasta entonces vendidas por el de General Cigar, y devolvió a este último Partagás y Room101; la fabricación no cambia, dice Cigar Coop.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'de', 'histoire 5 (nouveau texte)', (LOCATE(CAST('Beim Eigentum weicht das Datum ab: Swedish Match übernimmt laut FundingUniverse im Januar 2000 64 % von General Cigar, während Wikipedia ihre Übernahme der Gesellschaft auf 2005 legt. 2010 legt Swedish Match seine Premiumzigarren mit der Scandinavian Tobacco Group (STG) zusammen, die seit 2016 börsennotiert ist; Swedish Match scheidet 2017 aus dem Kapital von STG aus (Cigar Coop). Im Januar 2026 vertraute STG dem Vertriebsteam von Forged Cigar Company die Marken Cohiba (nichtkubanisch), Punch und Havana Honeys an, die bis dahin vom Team von General Cigar verkauft wurden, und gab diesem Partagás und Room101 zurück; die Fertigung ändert sich nicht, sagt Cigar Coop.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'de', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('Die Scandinavian Tobacco Group, 2010 durch die Zusammenlegung ihrer Zigarrenaktivitäten mit denen von Swedish Match, Eigentümerin von General Cigar seit 2005, entstanden und seit 2016 börsennotiert, brachte europäische Vertriebs- und Fertigungskapazitäten ein, die die Reichweite des Konzerns auf Märkten erweiterten, in denen amerikanische Marken bis dahin im Nachteil arbeiteten. Im Januar 2026 vertraute der Konzern dem Vertriebsteam von Forged Cigar Company die Marken Cohiba (nichtkubanisch), Punch und Havana Honeys an, die bis dahin vom Team von General Cigar verkauft wurden, und gab diesem Partagás und Room101 zurück; die Fertigung ändert sich nicht, sagt Cigar Coop.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'zh', 'histoire 5 (nouveau texte)', (LOCATE(CAST('产权方面，日期有分歧：据 FundingUniverse，Swedish Match 于2000年1月取得 General Cigar 64%的股份，而 Wikipedia 把它收购该公司的时间定在2005年。2010年，Swedish Match 把旗下高端雪茄与 Scandinavian Tobacco Group（STG）合并，STG 自2016年起在证券交易所上市；Swedish Match 于2017年退出 STG 的股本（Cigar Coop）。2026年1月，STG 把 Cohiba（非古巴）、Punch 与 Havana Honeys 这些品牌交给 Forged Cigar Company 的销售团队，它们此前由 General Cigar 的销售团队销售；并把 Partagás 与 Room101 交还给后者；制造不变，据 Cigar Coop 称。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'zh', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('2010年由其雪茄业务与 Swedish Match 的雪茄业务合并而成（Swedish Match 自2005年起拥有 General Cigar）、自2016年起在证券交易所上市的 Scandinavian Tobacco Group，为它接上了欧洲的分销与制造能力，把集团的触及范围扩展到那些美国品牌此前处于不利位置的市场。2026年1月，该集团把 Cohiba（非古巴）、Punch 与 Havana Honeys 这些品牌交给 Forged Cigar Company 的销售团队，它们此前由 General Cigar 的销售团队销售；并把 Partagás 与 Room101 交还给后者；制造不变，据 Cigar Coop 称。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'ar', 'histoire 5 (nouveau texte)', (LOCATE(CAST('من جهة الملكية، يختلف التاريخ: استحوذت Swedish Match على 64 % من General Cigar في كانون الثاني/يناير 2000 بحسب FundingUniverse، بينما تضع Wikipedia استحواذها على الشركة في عام 2005. وفي عام 2010 ضمّت Swedish Match سيجارها الفاخر إلى Scandinavian Tobacco Group (STG)، المدرجة في البورصة منذ 2016؛ وخرجت Swedish Match من رأسمال STG عام 2017 (Cigar Coop). وفي كانون الثاني/يناير 2026 أوكلت STG إلى فريق مبيعات Forged Cigar Company علامات Cohiba (غير الكوبية) وPunch وHavana Honeys، التي كان يبيعها حتى ذلك الحين فريق General Cigar، وأعادت إليه Partagás وRoom101؛ ولا يتغيّر التصنيع، بحسب Cigar Coop.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'General Cigar'
UNION ALL SELECT 'General Cigar', 'ar', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('وقد أضافت Scandinavian Tobacco Group، التي نشأت عام 2010 من ضمّ أنشطتها في السيجار إلى أنشطة Swedish Match، مالكة General Cigar منذ 2005، والمدرجة في البورصة منذ 2016، قدرات توزيع وتصنيع أوروبية وسّعت مدى المجموعة في أسواق كانت العلامات الأمريكية تعمل فيها حتى ذلك الحين من موقع غير مؤاتٍ. وفي كانون الثاني/يناير 2026 أوكلت المجموعة إلى فريق مبيعات Forged Cigar Company علامات Cohiba (غير الكوبية) وPunch وHavana Honeys، التي كان يبيعها حتى ذلك الحين فريق General Cigar، وأعادت إليه Partagás وRoom101؛ ولا يتغيّر التصنيع، بحسب Cigar Coop.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'General Cigar'
