UNION ALL SELECT 'Villiger', 'fr', 'pays', (CAST(`country_id` AS BINARY) = CAST('nicaragua' AS BINARY)) FROM `brands` WHERE `name` = 'Villiger'
UNION ALL SELECT 'Villiger', 'fr', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Jean Villiger fonda sa fabrique de cigares en 1888, chez lui à Pfeffikon, à 28 ans, dit la page d''histoire de la maison (villigercigars.com, octobre 2026). Il mourut en 1902 et sa veuve Louise poursuivit l''affaire : elle lança en 1907 le Villiger Kiel, présenté comme un cigare à embout en plume d''oie, et fonda en 1910 la filiale allemande, aujourd''hui Villiger Söhne GmbH à Waldshut-Tiengen. En 1918, Hans et Max Villiger reprirent l''entreprise sous le nom de Villiger Söhne. Heinrich, fils de Max, y entra en 1950 et succéda à Hans en 1954 ; il présidait encore le conseil à sa mort, le 25 juillet 2025, à 95 ans, et la maison reste familiale, Jvo Grundler lui ayant succédé à la présidence.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Villiger'
UNION ALL SELECT 'Villiger', 'fr', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Jean Villiger fonda son atelier de cigares à Pfeffikon, dans le canton de Lucerne, en 1888. La Suisse n''est pas un pays producteur de tabac — mais sa position géographique au cœur de l''Europe, ses réseaux commerciaux et sa tradition d''artisanat de précision firent de Pfeffikon un lieu logique pour une manufacture premium orientée vers l''exportation.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Villiger'
UNION ALL SELECT 'Villiger', 'en', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Jean Villiger founded his cigar factory in 1888, at home in Pfeffikon, aged 28, says the company''s history page (villigercigars.com, October 2026). He died in 1902 and his widow Louise carried on the business: in 1907 she launched the Villiger Kiel, presented as a cigar with a goose-quill mouthpiece, and in 1910 founded the German subsidiary, today Villiger Söhne GmbH in Waldshut-Tiengen. In 1918 Hans and Max Villiger took over the company under the name Villiger Söhne. Heinrich, Max''s son, joined it in 1950 and succeeded Hans in 1954; he was still chairman of the board when he died on 25 July 2025, aged 95, and the company remains family-owned, Jvo Grundler having succeeded him as chairman.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Villiger'
UNION ALL SELECT 'Villiger', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Jean Villiger founded his cigar workshop in Pfeffikon, in the canton of Lucerne, in 1888. Switzerland is not a tobacco-producing country — but its geographic position at the heart of Europe, its commercial networks, and its tradition of precision craftsmanship made Pfeffikon a logical location for a premium manufacture oriented toward export.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Villiger'
UNION ALL SELECT 'Villiger', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Jean Villiger fundó su fábrica de puros en 1888, en su propia casa de Pfeffikon, a los 28 años, dice la página de historia de la casa (villigercigars.com, octubre de 2026). Murió en 1902 y su viuda Louise continuó el negocio: lanzó en 1907 el Villiger Kiel, presentado como el puro con boquilla de pluma de ganso, y fundó en 1910 la filial alemana, hoy Villiger Söhne GmbH en Waldshut-Tiengen. En 1918, Hans y Max Villiger se hicieron cargo de la empresa con el nombre de Villiger Söhne. Heinrich, hijo de Max, entró en ella en 1950 y sucedió a Hans en 1954; aún presidía el consejo cuando murió, el 25 de julio de 2025, a los 95 años, y la casa sigue siendo familiar, pues Jvo Grundler le sucedió en la presidencia.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Villiger'
UNION ALL SELECT 'Villiger', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Jean Villiger fundó su taller de puros en Pfeffikon, en el cantón de Lucerna, en 1888. Suiza no es un país productor de tabaco, pero su posición geográfica en el centro de Europa, sus redes comerciales y su tradición de artesanía de precisión hicieron de Pfeffikon un lugar lógico para una manufactura premium orientada a la exportación.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Villiger'
UNION ALL SELECT 'Villiger', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Jean Villiger gründete seine Zigarrenfabrik 1888 bei sich zu Hause in Pfeffikon, mit 28 Jahren, sagt die Geschichtsseite des Hauses (villigercigars.com, Oktober 2026). Er starb 1902, und seine Witwe Louise führte das Geschäft weiter: 1907 brachte sie den Villiger Kiel auf den Markt, vorgestellt als Zigarre mit Federkiel-Mundstück, und gründete 1910 die deutsche Tochtergesellschaft, heute Villiger Söhne GmbH in Waldshut-Tiengen. 1918 übernahmen Hans und Max Villiger das Unternehmen unter dem Namen Villiger Söhne. Heinrich, Max'' Sohn, trat 1950 ein und folgte 1954 auf Hans; er stand dem Verwaltungsrat bei seinem Tod am 25. Juli 2025 mit 95 Jahren noch vor, und das Haus bleibt in Familienhand, da Jvo Grundler ihm im Vorsitz nachgefolgt ist.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Villiger'
UNION ALL SELECT 'Villiger', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Jean Villiger gründete seine Zigarrenwerkstatt 1888 in Pfeffikon im Kanton Luzern. Die Schweiz ist kein Tabakanbauland — doch ihre geografische Lage mitten in Europa, ihre Handelsnetze und ihre Tradition präziser Handwerkskunst machten Pfeffikon zum naheliegenden Ort für eine auf den Export ausgerichtete Premium-Manufaktur.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Villiger'
UNION ALL SELECT 'Villiger', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Jean Villiger 于1888年在 Pfeffikon 的自宅中创办雪茄工厂，时年28岁，据公司历史页面（villigercigars.com，2026年10月）所述。他于1902年去世，遗孀 Louise 继续经营：1907年她推出 Villiger Kiel，被介绍为一款带鹅毛管嘴的雪茄，1910年又创办德国子公司，即今天位于 Waldshut-Tiengen 的 Villiger Söhne GmbH。1918年，Hans 与 Max Villiger 以 Villiger Söhne 之名接手公司。Max 之子 Heinrich 于1950年入职，1954年接替 Hans；他于2025年7月25日去世，享年95岁，去世时仍担任董事会主席，公司依然是家族企业，由 Jvo Grundler 接任主席一职。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Villiger'
UNION ALL SELECT 'Villiger', 'zh', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('1888 年，Jean Villiger 在琉森州的 Pfeffikon 创办了自己的雪茄作坊。瑞士并非烟草产地，但它地处欧洲中心的位置、发达的贸易网络以及精密手工艺传统，使 Pfeffikon 成为一家面向出口的高端制造厂顺理成章的落脚点。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Villiger'
UNION ALL SELECT 'Villiger', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('أسّس Jean Villiger مصنعه للسيجار عام 1888 في بيته في Pfeffikon وهو في الثامنة والعشرين، بحسب صفحة تاريخ الدار (villigercigars.com، أكتوبر 2026). وتوفي عام 1902، فواصلت أرملته Louise العمل: أطلقت عام 1907 سيجار Villiger Kiel، الذي يُقدَّم على أنه سيجار بفوهة من ريشة الإوز، وأسّست عام 1910 الفرع الألماني، وهو اليوم Villiger Söhne GmbH في Waldshut-Tiengen. وفي عام 1918 تولّى Hans وMax Villiger الشركة باسم Villiger Söhne. أما Heinrich، ابن Max، فانضم إليها عام 1950 وخلف Hans عام 1954؛ وكان لا يزال يرأس مجلس الإدارة عند وفاته في 25 يوليو 2025 عن 95 عامًا، وتبقى الدار عائلية، إذ خلفه Jvo Grundler في الرئاسة.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Villiger'
UNION ALL SELECT 'Villiger', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('أسّس Jean Villiger ورشته لصناعة السيجار في Pfeffikon بمقاطعة لوتسرن عام 1888. وسويسرا ليست بلداً منتجاً للتبغ، غير أن موقعها في وسط أوروبا وشبكاتها التجارية وتقاليدها في الحرف الدقيقة جعلت من Pfeffikon مكاناً منطقياً لمصنع فاخر موجّه إلى التصدير.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Villiger'
UNION ALL SELECT 'Villiger', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('La maison a aussi un volet d''importation : 5th Avenue, coentreprise germano-cubaine de 1989 pour les cigares cubains, Intertabak en 1995 pour la Suisse et le Liechtenstein, et El Mundo del Tabaco en 1997 pour les cigares premium non cubains, intégré à Villiger Söhne une dizaine d''années plus tard (même page). Villiger Söhne, le groupe, ne se réduit donc pas à cette fiche : celle-ci ne porte que ses cigares premium faits à la main, et laisse de côté ses cigarillos et cigares de machine, comme l''Export ou le Premium No. 6, pour lesquels aucune page lue n''établit un roulage à la main.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Villiger'
UNION ALL SELECT 'Villiger', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('L''originalité de Villiger dans l''industrie européenne tient à une polyvalence rare : la maison maîtrise aussi bien la production de petit format (cigarillos) que les grands formats premium, et couvre un spectre allant du mass-market accessible au haut de gamme de collection. Cette gamme étendue résulte d''une stratégie d''acquisition patiente — Villiger a absorbé plusieurs manufactures européennes au fil des décennies, intégrant savoir-faire et marques.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Villiger'
UNION ALL SELECT 'Villiger', 'en', 'histoire 2 (nouveau texte)', (LOCATE(CAST('The company also has an importing side: 5th Avenue, a German-Cuban joint venture of 1989 for Cuban cigars, Intertabak in 1995 for Switzerland and Liechtenstein, and El Mundo del Tabaco in 1997 for non-Cuban premium cigars, integrated into Villiger Söhne about ten years later (same page). Villiger Söhne, the group, is therefore not confined to this entry: this one covers only its handmade premium cigars, and leaves aside its cigarillos and machine-made cigars, such as the Export or the Premium No. 6, for which no page read establishes hand-rolling.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Villiger'
UNION ALL SELECT 'Villiger', 'en', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Villiger''s originality in the European cigar industry lies in rare versatility: the house masters both small-format production (cigarillos) and large premium formats, covering a spectrum from accessible mass-market to high-end collectibles. This extended range results from a patient acquisition strategy — Villiger has absorbed several European manufacturers over the decades, integrating their expertise and brands.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Villiger'
UNION ALL SELECT 'Villiger', 'es', 'histoire 2 (nouveau texte)', (LOCATE(CAST('La casa tiene además una vertiente de importación: 5th Avenue, empresa conjunta germano-cubana de 1989 para los puros cubanos, Intertabak en 1995 para Suiza y Liechtenstein, y El Mundo del Tabaco en 1997 para los puros premium no cubanos, integrada en Villiger Söhne una decena de años después (misma página). Villiger Söhne, el grupo, no se reduce por tanto a esta ficha: esta solo recoge sus puros premium hechos a mano y deja de lado sus cigarritos y puros de máquina, como el Export o el Premium No. 6, para los que ninguna página leída establece un liado a mano.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Villiger'
UNION ALL SELECT 'Villiger', 'es', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('La originalidad de Villiger en la industria europea reside en una polivalencia poco común: la casa domina tanto la producción de formatos pequeños (cigarritos) como los grandes formatos premium, y cubre un espectro que va del mercado masivo asequible a la alta gama de coleccionista. Esa amplitud es fruto de una estrategia de adquisiciones paciente: Villiger ha absorbido varias manufacturas europeas a lo largo de las décadas, integrando saber hacer y marcas.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Villiger'
UNION ALL SELECT 'Villiger', 'de', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Das Haus hat auch ein Importgeschäft: 5th Avenue, ein deutsch-kubanisches Gemeinschaftsunternehmen von 1989 für kubanische Zigarren, Intertabak 1995 für die Schweiz und Liechtenstein und El Mundo del Tabaco 1997 für nichtkubanische Premiumzigarren, rund zehn Jahre später in Villiger Söhne eingegliedert (dieselbe Seite). Villiger Söhne, die Gruppe, geht also nicht in diesem Eintrag auf: Er behandelt nur die handgefertigten Premiumzigarren und lässt die Cigarillos und maschinengefertigten Zigarren aus, wie den Export oder den Premium No. 6, für die keine gelesene Seite Handarbeit belegt.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Villiger'
UNION ALL SELECT 'Villiger', 'de', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Villigers Eigenart in der europäischen Branche liegt in einer seltenen Vielseitigkeit: Das Haus beherrscht die Herstellung kleiner Formate (Cigarillos) ebenso wie die großen Premiumformate und deckt ein Spektrum vom erschwinglichen Massenmarkt bis zur Sammlerspitze ab. Diese Breite ist das Ergebnis einer geduldigen Zukaufstrategie — über die Jahrzehnte hat Villiger mehrere europäische Manufakturen übernommen und dabei Können wie Marken eingegliedert.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Villiger'
UNION ALL SELECT 'Villiger', 'zh', 'histoire 2 (nouveau texte)', (LOCATE(CAST('公司还有进口业务：5th Avenue，1989年的德古合资企业，经营古巴雪茄；Intertabak，1995年成立，面向瑞士与列支敦士登；El Mundo del Tabaco，1997年成立，经营非古巴高端雪茄，约十年后并入 Villiger Söhne（同一页面）。因此，集团 Villiger Söhne 并不局限于本条目：本条目只收录其手工制作的高端雪茄，不涉及其小雪茄和机制雪茄，例如 Export 或 Premium No. 6，因为已读页面均未证实这些产品为手工卷制。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Villiger'
UNION ALL SELECT 'Villiger', 'zh', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Villiger 在欧洲同业中的独特之处，在于罕见的全能：这家老号既精于小规格（小雪茄）的生产，也擅长高端大规格，覆盖从平价大众市场到收藏级顶端的完整区间。如此宽广的产品线源自耐心的收购策略——数十年间，Villiger 陆续并入多家欧洲制造厂，把技艺与品牌一并纳入。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Villiger'
UNION ALL SELECT 'Villiger', 'ar', 'histoire 2 (nouveau texte)', (LOCATE(CAST('وللدار كذلك جانب استيراد: 5th Avenue، شركة مشتركة ألمانية كوبية من عام 1989 للسيجار الكوبي، وIntertabak عام 1995 لسويسرا وليختنشتاين، وEl Mundo del Tabaco عام 1997 للسيجار الفاخر غير الكوبي، ودُمجت في Villiger Söhne بعد نحو عشر سنوات (الصفحة نفسها). فمجموعة Villiger Söhne لا تنحصر إذن في هذه الصفحة: فهذه الصفحة لا تتناول إلا سيجارها الفاخر المصنوع يدويًا، وتترك جانبًا السيجارلّو والسيجار المصنوع آليًا، مثل Export أو Premium No. 6، إذ لا تثبت أي صفحة قُرئت أنها تُلفّ يدويًا.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Villiger'
UNION ALL SELECT 'Villiger', 'ar', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('تكمن خصوصية Villiger في الصناعة الأوروبية في تنوّع نادر: فالدار تتقن إنتاج الأحجام الصغيرة (السيجارلّو) كما تتقن الأحجام الفاخرة الكبيرة، وتغطي مدى يمتد من السوق الواسعة الميسورة إلى الفئة العليا الموجّهة للجامعين. وهذا الاتساع ثمرة استراتيجية استحواذ متأنّية: فقد ضمّت Villiger على مدى العقود عدة مصانع أوروبية، مستوعبةً خبراتها وعلاماتها.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Villiger'
UNION ALL SELECT 'Villiger', 'fr', 'histoire 3 (nouveau texte)', (LOCATE(CAST('En 2021, Villiger a ouvert sa propre usine à Estelí, au Nicaragua, avec environ 150 spécialistes et une quinzaine de marques ; c''est là que le classement de la fiche s''appuie, des lignes de la gamme se roulant aussi en République dominicaine, chez ABAM et chez Tabacalera Palma. L''état de la maison se lit en octobre 2026 sur sa page d''histoire.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Villiger'
UNION ALL SELECT 'Villiger', 'fr', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('La gamme Premium est la raison pour laquelle les collectionneurs sérieux s''intéressent à Villiger. Utilisant du tabac brésilien, équatorien et indonésien dans des assemblages supervisés personnellement par Heinrich Villiger (quatrième génération) jusqu''à sa retraite en 2020, les cigares Premium incarnent une approche suisse de la cigariculture : précision, régularité, élégance discrète.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Villiger'
UNION ALL SELECT 'Villiger', 'en', 'histoire 3 (nouveau texte)', (LOCATE(CAST('In 2021, Villiger opened its own factory in Estelí, Nicaragua, with about 150 specialists and some fifteen brands; this is where the entry''s classification rests, some lines of the range also being rolled in the Dominican Republic, at ABAM and at Tabacalera Palma. The state of the company can be read in October 2026 on its history page.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Villiger'
UNION ALL SELECT 'Villiger', 'en', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('The Premium range is the reason serious collectors take notice of Villiger. Using Brazilian, Ecuadorian, and Indonesian tobacco in blends personally supervised by Heinrich Villiger (fourth generation) until his retirement in 2020, the Premium cigars embody a Swiss approach to cigariculture: precision, consistency, discreet elegance.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Villiger'
UNION ALL SELECT 'Villiger', 'es', 'histoire 3 (nouveau texte)', (LOCATE(CAST('En 2021, Villiger abrió su propia fábrica en Estelí, Nicaragua, con unos 150 especialistas y una quincena de marcas; en ella se apoya la clasificación de la ficha, ya que algunas líneas de la gama también se lían en la República Dominicana, en ABAM y en Tabacalera Palma. El estado de la casa se lee en octubre de 2026 en su página de historia.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Villiger'
UNION ALL SELECT 'Villiger', 'es', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('La gama Premium es la razón por la que los coleccionistas serios se interesan por Villiger. Con tabaco brasileño, ecuatoriano e indonesio en ligadas supervisadas personalmente por Heinrich Villiger (cuarta generación) hasta su retirada en 2020, los puros Premium encarnan un enfoque suizo del arte del puro: precisión, regularidad, elegancia discreta.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Villiger'
UNION ALL SELECT 'Villiger', 'de', 'histoire 3 (nouveau texte)', (LOCATE(CAST('2021 eröffnete Villiger in Estelí, Nicaragua, eine eigene Fabrik mit rund 150 Fachkräften und etwa fünfzehn Marken; auf sie stützt sich die Einordnung des Eintrags, wobei einzelne Linien der Reihe auch in der Dominikanischen Republik gerollt werden, bei ABAM und bei Tabacalera Palma. Der Stand des Hauses lässt sich im Oktober 2026 auf seiner Geschichtsseite ablesen.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Villiger'
UNION ALL SELECT 'Villiger', 'de', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Die Premium-Linie ist der Grund, weshalb ernsthafte Sammler sich für Villiger interessieren. Mit brasilianischem, ecuadorianischem und indonesischem Tabak in Mischungen, die Heinrich Villiger (vierte Generation) bis zu seinem Rückzug 2020 persönlich überwachte, verkörpern die Premium-Zigarren eine schweizerische Auffassung der Zigarrenkunst: Präzision, Gleichmäßigkeit, unaufdringliche Eleganz.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Villiger'
UNION ALL SELECT 'Villiger', 'zh', 'histoire 3 (nouveau texte)', (LOCATE(CAST('2021年，Villiger 在尼加拉瓜埃斯特利开设了自己的工厂，约有150名专业人员和十五个左右的品牌；本条目的归类即以此为依据，产品线中也有一些在多米尼加共和国的 ABAM 和 Tabacalera Palma 卷制。该公司的现状可于2026年10月在其历史页面上读到。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Villiger'
UNION ALL SELECT 'Villiger', 'zh', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('认真的收藏者之所以关注 Villiger，正是因为 Premium 系列。它以巴西、厄瓜多尔与印尼烟叶配制，直到 2020 年退休为止，配方一直由第四代的 Heinrich Villiger 亲自把关。Premium 雪茄体现的是一种瑞士式的制茄理念：精准、稳定、含蓄的优雅。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Villiger'
UNION ALL SELECT 'Villiger', 'ar', 'histoire 3 (nouveau texte)', (LOCATE(CAST('في عام 2021 افتتحت Villiger مصنعها الخاص في إستيلي بنيكاراغوا، بنحو 150 متخصصًا ونحو خمس عشرة علامة؛ وعليه يستند تصنيف هذه الصفحة، علمًا أن بعض خطوط التشكيلة تُلفّ أيضًا في جمهورية الدومينيكان، لدى ABAM ولدى Tabacalera Palma. ويمكن الاطلاع على حال الدار في أكتوبر 2026 في صفحة تاريخها.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Villiger'
UNION ALL SELECT 'Villiger', 'ar', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('تشكيلة Premium هي سبب اهتمام كبار الجامعين بـ Villiger. فهي تعتمد تبغاً برازيلياً وإكوادورياً وإندونيسياً في خلطات أشرف عليها شخصياً Heinrich Villiger (الجيل الرابع) حتى تقاعده عام 2020، وتجسّد رؤية سويسرية لصناعة السيجار: دقة وانتظام وأناقة هادئة.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Villiger'
